import importlib.util
import os
import sys
from pathlib import Path


def _detect_colab_runtime() -> bool:
    if 'google.colab' in sys.modules or 'COLAB_GPU' in os.environ:
        return True
    try:
        return Path('/content').exists() and importlib.util.find_spec('google.colab') is not None
    except (ImportError, ModuleNotFoundError, ValueError):
        return False


def _detect_kaggle_runtime() -> bool:
    """Return True inside a Kaggle notebook/script runtime."""
    if os.environ.get('KAGGLE_KERNEL_RUN_TYPE'):
        return True
    return Path('/kaggle/input').is_dir() and Path('/kaggle/working').is_dir()


def _kaggle_input_root() -> Path:
    """Read-only root containing datasets attached to the Kaggle notebook."""
    return Path(os.environ.get('KAGGLE_INPUT_DIR', '/kaggle/input'))


def _kaggle_working_root() -> Path:
    """Writable Kaggle output root retained as notebook output."""
    return Path(os.environ.get('KAGGLE_WORKING_DIR', '/kaggle/working'))


def _detect_cloud_runtime() -> Tuple[bool, bool]:
    """Return mutually exclusive ``(in_colab, in_kaggle)`` runtime flags.

    Some Kaggle images can expose Colab-like modules or paths. Kaggle's
    official runtime marker/input mount is more specific, so it takes priority
    and prevents the later Colab Drive resolver from handling Kaggle inputs.
    """
    in_kaggle = _detect_kaggle_runtime()
    in_colab = False if in_kaggle else _detect_colab_runtime()
    return in_colab, in_kaggle


