import os
import json
import time
import argparse
import warnings
from pathlib import Path
from dataclasses import dataclass, field
from typing import List, Dict, Optional, Tuple, Any
from datetime import datetime
import random
import gc
import inspect

warnings.filterwarnings('ignore')

# Fallbacks for optional dependencies used in type annotations / base classes
# These ensure the module can be imported even if torch is not installed; the
# real objects are populated by calling `check_imports()` at runtime.
try:
    from torch.utils.data import Dataset, DataLoader
except Exception:
    Dataset = object
    DataLoader = object

# Optional dependency: pandas (used for DataFrame handling). Import if available
# to ensure type annotations like `pd.DataFrame` evaluate during module import.
try:
    import pandas as pd
except Exception:
    pd = None

# Optional dependency: numpy. Many comparison/plotting helpers (e.g.
# run_inter_model_comparison) reference a bare `np.` without their own local
# import, relying on this module-level binding.
try:
    import numpy as np
except Exception:
    np = None

# Optional: torch and nn fallbacks to allow import-time class definitions when
# torch is not available. The real torch objects are populated by calling
# `check_imports()` at runtime if needed.
try:
    import torch
    import torch.nn as nn
    # PyTorch 2.6+ uses weights_only=True by default; register pathlib.Path types so
    # checkpoints saved with config.__dict__ (which contains Path objects) load correctly.
    import pathlib as _pathlib
    try:
        _safe_globals = [
            _pathlib.PosixPath, _pathlib.WindowsPath, _pathlib.Path,
            _pathlib.PurePosixPath, _pathlib.PureWindowsPath,
        ]
        # History dicts saved with the flexible-VLM checkpoint contain numpy
        # scalars/dtypes that survive checkpoint_safe_metadata (e.g. inside
        # nested loss-component records). Without these, torch.load under
        # weights_only=True raises "Unsupported global:
        # numpy._core.multiarray.scalar" and the checkpoint is silently
        # discarded and retrained on every run.
        try:
            import numpy as _np_safe
            _safe_globals.extend([_np_safe.dtype, _np_safe.ndarray])
            for _np_scalar_name in (
                'bool_', 'int8', 'int16', 'int32', 'int64',
                'uint8', 'uint16', 'uint32', 'uint64',
                'float16', 'float32', 'float64',
            ):
                _np_scalar = getattr(_np_safe, _np_scalar_name, None)
                if _np_scalar is not None:
                    _safe_globals.append(_np_scalar)
            # The scalar reconstructor lives at numpy._core on NumPy 2.x and
            # numpy.core on 1.x. Try the modern path first; touching .core on
            # 2.x would emit a DeprecationWarning on every import.
            for _np_multiarray_path in (
                'numpy._core.multiarray', 'numpy.core.multiarray',
            ):
                try:
                    import importlib as _importlib_safe
                    _safe_globals.append(_importlib_safe.import_module(
                        _np_multiarray_path
                    ).scalar)
                    break
                except Exception:
                    continue
        except Exception:
            pass
        torch.serialization.add_safe_globals(
            [g for g in _safe_globals if g is not None]
        )
    except AttributeError:
        pass  # PyTorch < 2.6 — no-op
except Exception:
    torch = None
    class _DummyNN:
        class Module: pass
    nn = _DummyNN()

# ============================================================================
# CONFIGURATION
# ============================================================================

@dataclass
class Config:
    # Both derive from the active schema so excluding a class cannot leave a
    # stale count behind. default_factory is evaluated at instantiation, which
    # is after STRESS_LABELS is defined further down this module.
    labels: list = field(default_factory=lambda: list(STRESS_LABELS))
    num_labels: int = field(default_factory=lambda: len(STRESS_LABELS))

    # Training - FIXED v3: Optimized for faster convergence with collapse detection
    batch_size: int = 16
    epochs: int = 15  # FIXED v3: Reduced from 30 to 15 (early abort handles collapse)
    learning_rate: float = 1e-4  # FIXED v3: Higher LR for faster learning (was 1e-5)
    weight_decay: float = 0.01
    early_stopping_patience: int = 6  # FIXED v3: Reduced from 10 to 6 (faster abort)
    warmup_ratio: float = 0.05  # FIXED v3: Shorter warmup (was 0.3)
    gradient_accumulation_steps: int = 2  # Effective batch size = 32
    use_mixed_precision: bool = True  # AMP for faster training

    # Actual transfer-learning backbones. When enabled, the named benchmark
    # runs load pretrained Hugging Face weights instead of scratch look-alikes.
    use_pretrained_backbones: bool = True
    allow_lightweight_fallback: bool = False
    # A full pretrained benchmark on Colab/Kaggle is not a practical CPU job.
    # The historical field name is retained for checkpoint/config compatibility.
    require_colab_gpu_for_pretrained: bool = True
    pretrained_text_tokenizer: str = 'distilbert-base-uncased'
    # Compact text encoders at sequence length 128 fit comfortably on a T4.
    # Activation checkpointing is therefore opt-in: recent PyTorch/transformers
    # combinations can detect divergent BERT recomputation graphs at backward
    # time and raise CheckpointError even though model construction succeeds.
    pretrained_text_gradient_checkpointing: bool = False
    pretrained_epochs: int = 12
    pretrained_text_learning_rate: float = 2e-5
    # Vision uses its own budget and activation-aware learning-rate clocks.
    # Frozen encoder groups no longer decay before they are first unfrozen.
    # The moderate defaults sit between the underfit v17 recipe and the more
    # aggressive legacy 5e-5 full-network schedule.
    pretrained_vision_epochs: int = 15
    pretrained_vision_learning_rate: float = 2e-5
    pretrained_vision_head_learning_rate: float = 1e-4
    pretrained_vision_linear_probe_epochs: int = 1
    pretrained_vision_tail_unfreeze_epochs: int = 2
    pretrained_vision_freeze_batch_norm_stats: bool = True
    # Allow horizontal-flip feature averaging as an inference candidate. It is
    # deployed only when it improves validation macro/micro-F1; the test split
    # never chooses this flag and an exact validation tie keeps original-only.
    pretrained_vision_inference_tta: bool = True

    # One-model flexible VLM. The trained unimodal parents are frozen while the
    # cross-attention adapter learns a bounded correction around whichever
    # parent validation shows is stronger. This avoids destroying either good
    # boundary on the small real-image set while retaining exact text-only and
    # image-only paths.
    flexible_vlm_modality_dropout: float = 0.05
    flexible_vlm_batch_size: int = 16
    flexible_vlm_text_aux_weight: float = 0.0
    flexible_vlm_image_aux_weight: float = 0.0
    # Class-only proxy pairs do not justify instance-alignment supervision.
    # Set this above zero only when annotations are linked to the same image.
    flexible_vlm_alignment_weight: float = 0.0
    flexible_vlm_distillation_weight: float = 0.0
    flexible_vlm_distillation_temperature: float = 2.0
    flexible_vlm_diversity_weight: float = 0.04
    flexible_vlm_gate_supervision_weight: float = 0.15
    flexible_vlm_parent_guard_weight: float = 0.10
    flexible_vlm_parent_guard_margin: float = 0.02
    # NLL-only movement on 30 proxy validation pairs is calibration evidence,
    # not evidence that the adapter improved classification accuracy.
    flexible_vlm_min_validation_f1_gain: float = 1e-4
    flexible_vlm_freeze_backbones: bool = True
    # Both endpoints remain strictly multimodal. The wider interval matters
    # when validation selects text as the stronger parent (as in the v14 run);
    # the old 0.45 ceiling forced every fused result to be image-majority.
    flexible_vlm_min_text_weight: float = 0.05
    flexible_vlm_max_text_weight: float = 0.95
    # Grid spacing for the validation-only fixed-weight calibration sweep. A
    # 0.1 step cannot land inside a productive window narrower than 0.1 (the
    # audited failure mode: a genuine optimum can sit entirely between grid
    # points). 0.01 keeps every point a true validation-only candidate --
    # nothing here reads the test split.
    flexible_vlm_gate_grid_step: float = 0.01
    # Evidence criterion for the proposed model. The point estimate is reported,
    # but the target is accepted only when its Wilson 95% lower bound reaches
    # this value on linked observations with independently verified taxonomy;
    # the measurement is never substituted or clamped.
    proposed_accuracy_target: float = 0.90

    # How the two fusion parents are chosen. 'validation' scores the trained
    # checkpoints on the held-out validation split, which for this project is
    # only ~29 images / ~10 text template groups -- too coarse to separate five
    # architectures, so the selected parent can be materially weaker than an
    # unselected one. 'out_of_fold_cv' instead ranks architectures by pooled
    # grouped cross-validation over the TRAINING rows, raising the selection
    # support to the full training set. Neither setting reads test.
    # Cost: CV retrains every candidate parent_selection_cv_folds times.
    parent_selection_protocol: str = 'out_of_fold_cv'
    parent_selection_cv_folds: int = 3

    # Where the number of training epochs comes from. 'validation' is the
    # historical behaviour: pick the epoch whose checkpoint scores best on the
    # held-out validation split. For text that split collapses to ~8
    # independent template groups and saturates at 1.0 across several
    # architectures, so it cannot rank epochs either -- and ties fall through to
    # an arbitrary tie-break. 'cross_validated' takes the epoch count from the
    # pooled grouped-CV epoch curve (full training-set support) and deploys that
    # epoch's weights directly, with no validation-based checkpoint selection.
    # Requires the CV curve, so it needs parent_selection_protocol=
    # 'out_of_fold_cv'; it falls back to 'validation' per model when no curve
    # is available. Neither setting reads test.
    epoch_selection_protocol: str = 'cross_validated'

    # How the fusion mixing rule is calibrated. 'validation' is the historical
    # behaviour: score candidate weights on the ~30-pair multimodal validation
    # split. On that support every macro/micro-F1 term saturates across a wide
    # band of weights, so the winner is decided by a tie-break rather than by
    # evidence -- and the old tie-break preferred an interior weight, which
    # forced a near-even mix of a strong image parent with a much weaker text
    # parent. 'out_of_fold_cv' calibrates on pooled grouped-CV out-of-fold
    # parent predictions over the training pairs instead, which is several times
    # the support and still fully held out. Neither setting reads test.
    # Cost: retrains both parents gate_calibration_cv_folds times.
    gate_calibration_protocol: str = 'out_of_fold_cv'
    gate_calibration_cv_folds: int = 3
    # Also fit a per-sample gate that mixes by parent reliability (confidence,
    # margin, entropy, agreement) rather than one global constant. It competes
    # against the constant-weight grid on the same support and only deploys if
    # it wins there.
    fit_reliability_gate: bool = True
    # Never deploy a fusion whose calibration-support macro-F1 is below the
    # better parent's by more than this margin. If no genuinely multimodal
    # candidate clears the floor, the stronger parent is deployed and reported
    # as a parent fallback -- not relabelled as a VLM win.
    fusion_no_harm_margin: float = 0.0

    # Federated - IMPROVED: More rounds and higher alpha for better convergence
    num_clients: int = 3
    fed_rounds: int = 8  # Increased from 3 for better convergence
    local_epochs: int = 3  # Increased from 2 for more local training
    dirichlet_alpha: float = 1.0  # Increased from 0.5 for more balanced (IID-like) client data

    # Sensitivity sweep (rounds x clients grid + alpha / local-epochs /
    # participation; feeds plots 46-50 and 53). The matched four-way
    # centralized/FedAvg plots do not require it, but the rounds-vs-performance
    # and clients-vs-performance figures DO. Cheap in the current protocol
    # (139 proxy pairs, tiny models). Disable with --no-fed-sweep.
    run_fed_sweep: bool = True
    fed_sweep_clients: list = field(default_factory=lambda: [2, 3, 5, 10])
    fed_sweep_rounds: int = 10
    fed_sweep_alphas: list = field(default_factory=lambda: [0.1, 0.5, 1.0, 10.0])
    fed_sweep_local_epochs: list = field(default_factory=lambda: [1, 3, 5])
    fed_sweep_participation: list = field(default_factory=lambda: [0.25, 0.5, 1.0])
    fed_sweep_model_types: list = field(default_factory=lambda: ['LLM', 'ViT', 'VLM'])

    # Data + paths
    max_samples_per_class: int = 600
    # 70/15/15 gives the small 200-image real dataset enough independent
    # validation/test examples. Training is still topped up synthetically.
    train_split: float = 0.7
    image_size: int = 224
    max_seq_length: int = 128

    # real_dataset_sorted is small and imbalanced (e.g. LEAF_HOPPERS ~8 imgs).
    # Synthetic-ablation fill target. The default real-data protocol ignores
    # this target and balances online without materializing duplicate tensors;
    # each repeated draw receives a fresh stochastic view. Set
    # image_fill_strategy='synthetic' only for an explicit ablation.
    image_fill_target: int = 200
    image_fill_strategy: str = 'real_oversample'

    # Class-aware training augmentation. The rarest class receives up to this
    # strength multiplier (viewpoint crop depth, brightness/contrast/colour
    # jitter, noise, plus label-preserving flips/90-degree rotations); the
    # largest class always stays at 1.0. This adds genuine per-view diversity to
    # heavily oversampled minority classes (leaf-hoppers) without touching
    # validation/test and without materializing any synthetic image. Set to 1.0
    # to reproduce the previous uniform-strength behaviour exactly.
    minority_augment_max_strength: float = 1.6

    # Paths
    # Image and text roots are intentionally separate. The real images are the
    # 200 sorted field images; their matching observations live in
    # dataset/tea_data/annotations.csv.
    data_dir: Path = field(default_factory=lambda: Path("real_dataset_sorted"))
    text_data_dir: Path = field(default_factory=lambda: Path("dataset/tea_data"))
    data_final_zip: Optional[Path] = None
    data_final_drive_file_id: str = '1PBZJrCGQ8-sxZnKzxMPhA9ySzOZWmMzf'
    output_dir: Path = field(default_factory=lambda: Path("results"))
    checkpoint_dir: Path = field(default_factory=lambda: Path("checkpoints"))
    plots_dir: Path = field(default_factory=lambda: Path("plots"))
    show_plot_previews: bool = False
    plot_preview_limit: int = 12  # 0 means show every generated plot
    plot_preview_width: int = 64

    seed: int = 42


def checkpoint_safe_metadata(value: Any) -> Any:
    """Recursively convert metadata to PyTorch weights-only-safe values.

    PyTorch 2.6 loads checkpoints with ``weights_only=True`` by default.
    NumPy scalar pickles and ``Path`` objects in history/config metadata can
    make an otherwise valid state-dict checkpoint fail to reload. Tensors are
    preserved; metadata is reduced to JSON-like primitives.
    """
    if value is None or isinstance(value, (str, bool, int, float)):
        return value
    if isinstance(value, Path):
        return str(value)
    if torch is not None and isinstance(value, torch.Tensor):
        return value
    if np is not None:
        if isinstance(value, np.generic):
            return checkpoint_safe_metadata(value.item())
        if isinstance(value, np.ndarray):
            return checkpoint_safe_metadata(value.tolist())
    if isinstance(value, dict):
        return {
            str(key): checkpoint_safe_metadata(item)
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple, set)):
        return [checkpoint_safe_metadata(item) for item in value]
    # Checkpoint metadata should remain descriptive rather than executable.
    return str(value)


def discover_kaggle_data_final_zip(input_root: Optional[Path] = None) -> Optional[Path]:
    """Find one uploaded ``data_final.zip`` below Kaggle's input mount.

    Kaggle mounts each attached dataset below ``/kaggle/input/<slug>``. The
    dataset slug is not stable across users, so discovery is content-name based.
    An ambiguous match fails closed instead of silently training on the wrong
    bundle; ``--data-final-zip`` remains the explicit override.
    """
    root = Path(input_root) if input_root is not None else _kaggle_input_root()
    if not root.is_dir():
        return None
    candidates = sorted(
        path for path in root.rglob('*')
        if path.is_file() and path.name.casefold() == 'data_final.zip'
    )
    if len(candidates) > 1:
        rendered = '\n  - '.join(str(path) for path in candidates)
        raise FileExistsError(
            "Multiple data_final.zip files were found in Kaggle inputs. "
            "Keep only one attached bundle or pass --data-final-zip explicitly:\n"
            f"  - {rendered}"
        )
    return candidates[0] if candidates else None


def discover_expanded_kaggle_bundle(
    input_root: Optional[Path] = None,
) -> Tuple[Optional[Path], Optional[Path]]:
    """Locate an already-expanded portable bundle in a Kaggle input mount."""
    root = Path(input_root) if input_root is not None else _kaggle_input_root()
    if not root.is_dir():
        return None, None

    # Only accept the canonical direct-child layout. Downstream schema
    # validation reads the manifest from image_root.parent, so accepting a
    # looser nested layout could trigger a write attempt inside read-only input.
    candidates = []
    for manifest in sorted(root.rglob('label_schema.json')):
        bundle_root = manifest.parent
        image_root = bundle_root / 'real_dataset_sorted'
        text_root = bundle_root / 'text_data'
        if image_root.is_dir() and (text_root / 'annotations.csv').is_file():
            candidates.append((image_root, text_root))

    if len(candidates) > 1:
        rendered = '\n  - '.join(str(image_root.parent) for image_root, _ in candidates)
        raise FileExistsError(
            "Multiple expanded FarmFederate bundles were found in Kaggle inputs. "
            "Keep only one attached dataset or attach a single data_final.zip:\n"
            f"  - {rendered}"
        )
    if candidates:
        return candidates[0]

    # Unversioned expanded inputs are deliberately not accepted: validating or
    # repairing their schema would require writing into read-only /kaggle/input.
    # Upload the versioned data_final.zip or its complete expanded contents.
    return None, None


def prefer_colab_bundle_candidate(
    existing_bundle: Optional[Path],
    mounted_candidates: Optional[List[Path]] = None,
) -> Tuple[Optional[Path], Optional[str]]:
    """Prefer an authenticated Drive bundle without discarding a local upload.

    ``existing_bundle`` is the candidate already discovered in the current
    runtime, commonly ``/content/data_final.zip`` from the Colab Files panel.
    The previous inline logic overwrote that candidate with ``None`` whenever
    the mounted-Drive locations were empty, which incorrectly triggered gdown.
    """
    if mounted_candidates is None:
        mounted_candidates = [
            Path('/content/drive/MyDrive/FarmFederate/data_final.zip'),
            Path('/content/drive/My Drive/FarmFederate/data_final.zip'),
            Path('/content/drive/MyDrive/data_final.zip'),
            Path('/content/drive/My Drive/data_final.zip'),
        ]

    mounted_bundle = next(
        (Path(path) for path in mounted_candidates if Path(path).is_file()),
        None,
    )
    if mounted_bundle is not None:
        return mounted_bundle, 'mounted_drive'

    if existing_bundle is not None:
        existing_bundle = Path(existing_bundle)
        if existing_bundle.is_file():
            return existing_bundle, 'uploaded_or_local'

    return None, None


PORTABLE_EXTRACTION_PROTOCOL = 'farmfederate_portable_extract_v2'
PORTABLE_EXTRACTION_MARKER = '.farmfederate_extraction.json'


def _portable_bundle_sha256(bundle_zip: Path) -> str:
    """Return the full digest used to identify an immutable data bundle."""
    import hashlib

    hasher = hashlib.sha256()
    with open(Path(bundle_zip), 'rb') as bundle_file:
        for chunk in iter(lambda: bundle_file.read(1024 * 1024), b''):
            hasher.update(chunk)
    return hasher.hexdigest()


def portable_bundle_extract_root(bundle_zip: Optional[Path] = None) -> Path:
    """Return a writable, optionally content-addressed extraction directory."""

    if IN_KAGGLE:
        root = _kaggle_working_root() / 'farmfederate_data'
    elif IN_COLAB:
        root = Path('/content/farmfederate_data')
    else:
        root = Path('.farmfederate_data')

    if bundle_zip is None:
        return root

    # The protocol suffix prevents a pre-v14 overlay cache from being reused.
    # Earlier extraction reruns could copy an uncorrected legacy archive over
    # folders that had already undergone the BLIGHT/RUST schema repair.
    return root / f"{_portable_bundle_sha256(bundle_zip)[:16]}-extract-v2"


def extract_portable_bundle(bundle_zip: Path, extract_root: Path) -> Tuple[Path, Path]:
    """Safely extract or reuse one verified portable ZIP extraction.

    A digest-bound completion marker makes repeated notebook executions
    idempotent. In particular, an original legacy archive is never overlaid on
    the in-place BLIGHT/RUST repair performed after the first extraction.
    """
    import json as _bundle_json
    import shutil
    import zipfile
    from pathlib import PurePosixPath

    bundle_zip = Path(bundle_zip)
    extract_root = Path(extract_root)
    if not bundle_zip.is_file():
        raise FileNotFoundError(f"Portable bundle not found: {bundle_zip}")
    bundle_digest = _portable_bundle_sha256(bundle_zip)
    base = extract_root.resolve()
    marker_path = extract_root / PORTABLE_EXTRACTION_MARKER

    if marker_path.is_file():
        try:
            marker = _bundle_json.loads(marker_path.read_text(encoding='utf-8'))
            if (marker.get('extraction_protocol') != PORTABLE_EXTRACTION_PROTOCOL
                    or marker.get('bundle_sha256') != bundle_digest):
                raise ValueError("protocol or bundle digest mismatch")

            def _marked_path(field_name):
                raw_value = marker.get(field_name)
                if not isinstance(raw_value, str) or not raw_value:
                    raise ValueError(f"missing {field_name}")
                relative = Path(raw_value)
                if relative.is_absolute() or '..' in relative.parts:
                    raise ValueError(f"unsafe {field_name}")
                resolved = (extract_root / relative).resolve()
                if base not in resolved.parents and resolved != base:
                    raise ValueError(f"unsafe {field_name}")
                return resolved

            image_root = _marked_path('image_root')
            text_root = _marked_path('text_root')
            if (not image_root.is_dir()
                    or not (text_root / 'annotations.csv').is_file()):
                raise FileNotFoundError("marked bundle contents are incomplete")
        except Exception as marker_error:
            raise ValueError(
                f"Portable extraction cache marker is invalid: {marker_path}. "
                "Remove this content-addressed cache directory and rerun."
            ) from marker_error
        print(f"[Data] Reusing verified portable bundle extraction: {extract_root}")
        return image_root, text_root

    if extract_root.exists() and any(extract_root.iterdir()):
        raise FileExistsError(
            f"Portable extraction root is non-empty but unverified: {extract_root}. "
            "Use portable_bundle_extract_root(bundle_zip) or remove the stale cache."
        )

    extract_root.mkdir(parents=True, exist_ok=True)
    extracted_files = []

    print(f"[Data] Extracting portable bundle: {bundle_zip}")
    with zipfile.ZipFile(bundle_zip, 'r') as archive:
        for member in archive.infolist():
            # Windows-created ZIPs may store backslashes. Normalize to POSIX
            # components before validating and writing on Linux runtimes.
            portable_name = member.filename.replace('\\', '/')
            parts = [
                part for part in PurePosixPath(portable_name).parts
                if part not in ('', '.')
            ]
            if not parts:
                continue
            if any(part == '..' for part in parts):
                raise ValueError(f"Unsafe path in data bundle: {member.filename}")
            target = extract_root.joinpath(*parts).resolve()
            if base not in target.parents and target != base:
                raise ValueError(f"Unsafe path in data bundle: {member.filename}")
            if member.is_dir() or portable_name.endswith('/'):
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(member, 'r') as source, open(target, 'wb') as destination:
                shutil.copyfileobj(source, destination)
            extracted_files.append(target)

    image_roots = sorted({
        parent
        for path in extracted_files
        for parent in path.parents
        if parent.name == 'real_dataset_sorted' and base in parent.parents
    })
    annotation_files = sorted(
        path for path in extracted_files
        if path.name == 'annotations.csv' and path.parent.name == 'text_data'
    )
    bundle_pairs = sorted({
        (annotation.parent.parent / 'real_dataset_sorted', annotation.parent)
        for annotation in annotation_files
        if annotation.parent.parent / 'real_dataset_sorted' in image_roots
    })
    if len(bundle_pairs) != 1:
        members = '\n    '.join(str(path.relative_to(base)) for path in extracted_files)
        if len(bundle_pairs) > 1:
            raise FileExistsError(
                "data_final.zip contains multiple complete portable bundles; "
                "upload an archive with exactly one data_final root. Found:\n    "
                + members
            )
        raise FileNotFoundError(
            "data_final.zip has an invalid layout. It must contain one co-located "
            "real_dataset_sorted/ and text_data/annotations.csv pair. Found:\n    "
            + members
        )
    image_root, text_root = bundle_pairs[0]
    marker = {
        'extraction_protocol': PORTABLE_EXTRACTION_PROTOCOL,
        'bundle_sha256': bundle_digest,
        'image_root': image_root.relative_to(base).as_posix(),
        'text_root': text_root.relative_to(base).as_posix(),
    }
    marker_tmp = marker_path.with_suffix(marker_path.suffix + '.tmp')
    marker_tmp.write_text(
        _bundle_json.dumps(marker, indent=2) + '\n', encoding='utf-8'
    )
    marker_tmp.replace(marker_path)
    return image_root, text_root


# Canonical FarmFederate stress schema. Text CSV class_name/class_id values and
# sorted image folder names must match this exact order before modalities are
# paired. It is distinct from the legacy five-class tea taxonomy below.
# Full taxonomy as it physically exists in the sorted image folders and in
# annotations.csv. The bundle on disk always contains all five; which of them
# the benchmark actually uses is decided by EXCLUDED_STRESS_LABELS below.
FULL_STRESS_LABELS = [
    'LEAF_BLIGHT', 'LEAF_HOPPERS', 'LEAF_RUST',
    'LOOPER_CATERPILLARS', 'MOSQUITO_BUG',
]

# Classes removed from the benchmark, each with its reason.
#
# LEAF_HOPPERS: all 8 field photographs were inspected and none shows
# leafhopper damage - no pale stippling, tip burn, leaf curl or bronzing. The
# class is 6 train / 1 val / 1 test, and every one of the five vision
# backbones scored exactly 0.000 on it. Meanwhile the synthetic text, which is
# generated FROM the label and does spell out those symptoms, scored 1.000.
# Averaging a structurally unlearnable class into macro-F1 both depresses every
# vision score by a fixed 1/K and hands the text branch a free point, which is
# what drove the fusion gate onto text. It is excluded and reported as such,
# not silently dropped.
EXCLUDED_STRESS_LABELS = ['LEAF_HOPPERS']

STRESS_LABELS = [
    label for label in FULL_STRESS_LABELS
    if label not in EXCLUDED_STRESS_LABELS
]
# Active benchmark schema. Bumped whenever the class set changes so stale
# checkpoints and cached fingerprints are invalidated rather than reused.
STRESS_SCHEMA_VERSION = 'farmfederate_stress_v3_excluded_unlearnable_classes'
# Layout of the portable data bundle on disk. This is deliberately NOT bumped
# when a class is excluded: the bundle still contains all five folders, and
# label_schema.json inside an already-published bundle must stay valid.
BUNDLE_SCHEMA_VERSION = 'farmfederate_stress_v2_direct_yolo_ids'
SUPPORTED_IMAGE_SUFFIXES = frozenset({
    '.jpg', '.jpeg', '.png', '.bmp', '.webp',
})
TEA_DISEASE_LABELS = STRESS_LABELS  # backward-compatible alias for the stress schema
ORIGINAL_TEA_CLASSES = [
    'gray_blight', 'helopeltis', 'algal_leaf_spot', 'brown_blight', 'red_leaf_spot'
]
# Ground-truth mapping in the raw YOLO OBB data.yaml, over the FULL taxonomy.
# Always translate raw id -> canonical name -> canonical index; raw IDs are not
# STRESS_LABELS indices, and that is doubly true once a class is excluded.
FULL_RAW_YOLO_ID_TO_STRESS = {
    0: 'LEAF_BLIGHT',
    1: 'LEAF_HOPPERS',
    2: 'LEAF_RUST',
    3: 'LOOPER_CATERPILLARS',
    4: 'MOSQUITO_BUG',
}
# Active mapping. Excluded raw ids are simply absent, so every call site that
# does RAW_YOLO_ID_TO_STRESS.get(raw_id) already skips those annotations.
RAW_YOLO_ID_TO_STRESS = {
    raw_id: name for raw_id, name in FULL_RAW_YOLO_ID_TO_STRESS.items()
    if name in STRESS_LABELS
}


def _ensure_portable_bundle_label_schema(image_root: Path, bundle_root: Path) -> Dict[str, Any]:
    """Validate/repair the one known legacy portable-bundle label swap.

    The first ``data_final.zip`` release was produced with raw YOLO IDs 0 and 2
    reversed, so its LEAF_BLIGHT (35 images) and LEAF_RUST (62 images) folders
    contradicted the text labels. Portable bundles now carry ``label_schema.json``.
    For the exact legacy count signature we repair the extracted working copy;
    unknown unversioned layouts fail closed instead of silently pairing
    semantically contradictory modalities.
    """
    import json as _schema_json

    image_root = Path(image_root)
    bundle_root = Path(bundle_root)
    manifest_path = bundle_root / 'label_schema.json'
    # Validate the bundle against the FULL taxonomy: the manifest describes what
    # is physically on disk, which is independent of how many classes the
    # current benchmark chooses to use. Checking it against the active subset
    # would reject a perfectly valid bundle the moment a class is excluded.
    expected_mapping = {str(k): v for k, v in FULL_RAW_YOLO_ID_TO_STRESS.items()}
    expected_class_order = list(FULL_STRESS_LABELS)
    if manifest_path.is_file():
        manifest = _schema_json.loads(manifest_path.read_text(encoding='utf-8'))
        if (manifest.get('schema_version') != BUNDLE_SCHEMA_VERSION
                or manifest.get('raw_yolo_id_to_stress') != expected_mapping
                or manifest.get('class_order') != expected_class_order):
            raise ValueError(
                f"Portable bundle label schema is incompatible: {manifest_path}. "
                f"Expected {BUNDLE_SCHEMA_VERSION}, mapping {expected_mapping}, "
                f"and class order {expected_class_order}."
            )
        return manifest

    def _image_count(class_name):
        class_dir = image_root / class_name
        return sum(
            1 for path in class_dir.rglob('*')
            if path.is_file() and path.suffix.lower() in SUPPORTED_IMAGE_SUFFIXES
        ) if class_dir.is_dir() else 0

    blight_count = _image_count('LEAF_BLIGHT')
    rust_count = _image_count('LEAF_RUST')
    repaired_legacy_swap = False
    if (blight_count, rust_count) == (35, 62):
        import shutil as _schema_shutil
        blight_dir = image_root / 'LEAF_BLIGHT'
        rust_dir = image_root / 'LEAF_RUST'
        temporary_dir = image_root / '__LABEL_SWAP_TEMP__'
        if temporary_dir.exists():
            raise RuntimeError(f"Cannot repair interrupted label swap: {temporary_dir}")
        print(
            "[Data] Repairing legacy data_final.zip label error: "
            "swapping LEAF_BLIGHT and LEAF_RUST image folders."
        )
        _schema_shutil.move(str(blight_dir), str(temporary_dir))
        _schema_shutil.move(str(rust_dir), str(blight_dir))
        _schema_shutil.move(str(temporary_dir), str(rust_dir))
        repaired_legacy_swap = True
        blight_count, rust_count = rust_count, blight_count
    elif (blight_count, rust_count) != (62, 35):
        raise ValueError(
            "Unversioned portable bundle has an unknown LEAF_BLIGHT/LEAF_RUST "
            f"layout ({blight_count}/{rust_count} images). Rebuild it with the "
            "current script so multimodal labels can be verified."
        )

    manifest = {
        'schema_version': BUNDLE_SCHEMA_VERSION,
        'raw_yolo_id_to_stress': expected_mapping,
        'class_order': list(STRESS_LABELS),
        'legacy_blightrust_swap_repaired': repaired_legacy_swap,
    }
    manifest_path.write_text(
        _schema_json.dumps(manifest, indent=2) + '\n', encoding='utf-8'
    )
    return manifest


