def _is_usable_sorted_dataset(dataset_root: Path) -> bool:
    """Return whether a canonical sorted root contains a supported image."""
    dataset_root = Path(dataset_root)
    if not dataset_root.is_dir():
        return False
    if not all((dataset_root / label).is_dir() for label in STRESS_LABELS):
        return False
    for label in STRESS_LABELS:
        class_root = dataset_root / label
        image_root = (
            class_root / 'images'
            if (class_root / 'images').is_dir() else class_root
        )
        if any(
            path.is_file() and path.suffix.lower() in SUPPORTED_IMAGE_SUFFIXES
            for path in image_root.iterdir()
        ):
            return True
    return False

