# ============================================================================
# REAL TEA LEAF DATASET LOADER (YOLO OBB FORMAT)
# ============================================================================

def load_real_tea_dataset(dataset_dir: str = None, img_size: int = 224) -> Tuple[List, List, List]:
    """Load the real tea leaf disease dataset from YOLO OBB annotation format.

    The dataset has images in <dataset_dir>/images/ and YOLO OBB label files in
    <dataset_dir>/labels/. Each label file contains lines of:
        class_id x1 y1 x2 y2 x3 y3 x4 y4   (oriented bounding box corners)

    Canonical class mapping (5 classes, translated from data.yaml):
        0 = LEAF_BLIGHT
        1 = LEAF_HOPPERS
        2 = LEAF_RUST
        3 = LOOPER_CATERPILLARS
        4 = MOSQUITO_BUG

    For image-level classification the dominant (most frequent) class in the
    annotation file is used as the label for the whole image.

    Args:
        dataset_dir: Path to the dataset root (contains images/ and labels/).
                     Auto-detects common paths if None.
        img_size:    Resize target (default 224).

    Returns:
        (images, labels, texts) — lists of normalised image tensors,
        integer label lists [[class_idx], ...], and synthetic description strings.
    """
    import torch
    import numpy as np
    from pathlib import Path as _Path

    # ── Resolve dataset directory ──
    if dataset_dir is None:
        _candidates = [
            # Sorted per-class structure (Colab gdown target)
            _Path("/content/real_dataset_sorted"),
            _Path("/content/drive/MyDrive/FarmFederate/real_dataset_sorted"),
            _Path("/content/drive/My Drive/FarmFederate/real_dataset_sorted"),
            # Flat YOLO OBB structure (local)
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset"),
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/Real_Dataset"),
            _Path("Real Dataset"),
            _Path("Real_Dataset"),
            _Path("/content/drive/MyDrive/FarmFederate/Real Dataset"),
            _Path("/content/drive/MyDrive/FarmFederate/Real_Dataset"),
            _Path("../Real Dataset"),
            _Path("../Real_Dataset"),
        ]
        dataset_dir = next((p for p in _candidates if p.exists()), None)
        if dataset_dir is None:
            print("  [RealTea] Dataset directory not found — returning empty.")
            return [], [], []

    dataset_dir = _Path(dataset_dir)

    # ── Detect per-class sorted structure (real_dataset_sorted/LEAF_BLIGHT/ ...) ──
    _sorted_cls_dirs = [dataset_dir / lbl for lbl in STRESS_LABELS]
    if all(d.exists() for d in _sorted_cls_dirs) or any(d.exists() for d in _sorted_cls_dirs):
        print(f"  [RealTea] Per-class sorted structure detected in: {dataset_dir}")
        try:
            from PIL import Image as _PILImage
        except ImportError:
            print("  [RealTea] PIL not available — cannot load images.")
            return [], [], []
        mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)
        std  = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)
        images, labels, texts = [], [], []
        class_counts = {i: 0 for i in range(len(STRESS_LABELS))}
        def _sorted_source_dir(folder_name):
            class_dir = dataset_dir / folder_name
            nested = class_dir / 'images'
            return nested if nested.is_dir() else class_dir

        def _sorted_count(folder_name):
            source_dir = _sorted_source_dir(folder_name)
            return sum(
                1 for path in source_dir.iterdir()
                if path.is_file() and path.suffix.lower() in {
                    '.jpg', '.jpeg', '.png', '.bmp', '.webp'
                }
            ) if source_dir.is_dir() else 0

        _legacy_alias = {}
        if (_sorted_count('LEAF_BLIGHT'), _sorted_count('LEAF_RUST')) == (35, 62):
            _legacy_alias = {
                'LEAF_BLIGHT': 'LEAF_RUST',
                'LEAF_RUST': 'LEAF_BLIGHT',
            }
            print("  [RealTea] Repairing known legacy BLIGHT/RUST folder mapping in memory")
        for cls_idx, cls_name in enumerate(STRESS_LABELS):
            cls_dir = _sorted_source_dir(_legacy_alias.get(cls_name, cls_name))
            if not cls_dir.exists():
                continue
            _ipaths = (sorted(cls_dir.glob("*.jpg")) + sorted(cls_dir.glob("*.jpeg")) +
                       sorted(cls_dir.glob("*.png")) + sorted(cls_dir.glob("*.JPG")) +
                       sorted(cls_dir.glob("*.PNG")))
            for img_path in _ipaths:
                try:
                    pil_img = _PILImage.open(img_path).convert("RGB").resize((img_size, img_size))
                    arr = np.array(pil_img, dtype=np.float32) / 255.0
                    img_tensor = torch.from_numpy(arr).permute(2, 0, 1)
                    img_tensor = (img_tensor - mean) / std
                    images.append(img_tensor)
                    labels.append([cls_idx])
                    texts.append(generate_tea_disease_text(cls_name, len(images)))
                    class_counts[cls_idx] += 1
                except Exception:
                    continue
        print(f"  [RealTea] Loaded {len(images)} images from sorted per-class dirs")
        for ci, cnt in class_counts.items():
            print(f"    class {ci} ({STRESS_LABELS[ci]}): {cnt} images")
        return images, labels, texts

    img_dir = dataset_dir / "images"
    lbl_dir = dataset_dir / "labels"

    if not img_dir.exists() or not lbl_dir.exists():
        print(f"  [RealTea] images/ or labels/ not found in {dataset_dir}")
        return [], [], []

    print(f"  [RealTea] Loading real tea leaf dataset from: {dataset_dir}")

    try:
        from PIL import Image as _PILImage
    except ImportError:
        print("  [RealTea] PIL not available — cannot load images.")
        return [], [], []

    mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)
    std  = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)

    images, labels, texts = [], [], []
    skipped = 0
    class_counts = {i: 0 for i in range(len(STRESS_LABELS))}

    img_paths = sorted(img_dir.glob("*.jpg")) + sorted(img_dir.glob("*.png")) + sorted(img_dir.glob("*.jpeg"))

    for img_path in img_paths:
        lbl_path = lbl_dir / (img_path.stem + ".txt")
        if not lbl_path.exists():
            skipped += 1
            continue

        # ── Parse YOLO OBB label file ──
        try:
            cls_ids = []
            with open(lbl_path, "r") as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) >= 1:
                        cls_ids.append(int(parts[0]))
            if not cls_ids:
                skipped += 1
                continue
            # Use dominant (most frequent) class as the image-level label
            from collections import Counter as _Counter
            dominant_raw_cls = _Counter(cls_ids).most_common(1)[0][0]
            canonical_name = RAW_YOLO_ID_TO_STRESS.get(dominant_raw_cls)
            if canonical_name is None:
                skipped += 1
                continue
            dominant_cls = LABEL_TO_IDX[canonical_name]
        except Exception:
            skipped += 1
            continue

        # ── Load and preprocess image ──
        try:
            pil_img = _PILImage.open(img_path).convert("RGB").resize((img_size, img_size))
            arr = np.array(pil_img, dtype=np.float32) / 255.0
            img_tensor = torch.from_numpy(arr).permute(2, 0, 1)          # CHW
            img_tensor = (img_tensor - mean) / std
        except Exception:
            skipped += 1
            continue

        images.append(img_tensor)
        labels.append([dominant_cls])
        texts.append(generate_tea_disease_text(STRESS_LABELS[dominant_cls], len(images)))
        class_counts[dominant_cls] += 1

    total = len(images)
    print(f"  [RealTea] Loaded {total} images (skipped {skipped})")
    for ci, cnt in class_counts.items():
        print(f"    class {ci} ({STRESS_LABELS[ci]}): {cnt} images")
    return images, labels, texts


