def _load_gdrive_image_dataset_disabled(data_dir: str = None, img_size: int = 224) -> Tuple[List, List, List]:
    """Load tea disease images from the tea_data folder structure on Google Drive (or local).

    Expected structure:
        tea_data/
            annotations.csv
            gray_blight/      *.jpg / *.png
            helopeltis/       *.jpg / *.png
            algal_leaf_spot/  *.jpg / *.png
            brown_blight/     *.jpg / *.png
            red_leaf_spot/    *.jpg / *.png

    This is the primary loader for the Google Drive dataset at:
        https://drive.google.com/drive/folders/1cWXvhdtP_ExwjkM29yb8tp1_JQuAwnxp

    Each image is paired with its annotation text from annotations.csv where available;
    falls back to generate_tea_disease_text() if no annotation match is found.

    Returns:
        (images, labels, texts) — normalised image tensors, integer label lists, text strings.
    """
    import torch
    import numpy as np
    from pathlib import Path as _Path

    # ── Resolve base directory ──
    if data_dir is None:
        _candidates = [
            # Highest priority: MyDrive/FarmFederate/tea_data
            _Path("/content/drive/MyDrive/FarmFederate/tea_data"),
            _Path("/content/drive/My Drive/FarmFederate/tea_data"),
            # Fallbacks
            _Path("/content/drive/MyDrive/FarmFederate/data"),
            _Path("/content/drive/My Drive/FarmFederate/data"),
            _Path("/content/drive/MyDrive/tea_data"),
            _Path("/content/drive/My Drive/tea_data"),
            # Local Windows
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/tea_data"),
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/data"),
            _Path("tea_data"),
            _Path("data"),
            _Path("../tea_data"),
        ]
        data_dir = next((str(p) for p in _candidates if p.exists()), None)
        if data_dir is None:
            print("  [GDrive] Dataset directory not found (tried FarmFederate/data and tea_data paths).")
            return [], [], []

    data_dir = _Path(data_dir)
    print(f"  [GDrive] Loading tea disease images from: {data_dir}")

    try:
        from PIL import Image as _PILImage
    except ImportError:
        print("  [GDrive] PIL not available — cannot load images.")
        return [], [], []

    # ── Load annotation text lookup: class_id → [text, ...] ──
    ann_df = _load_annotations_csv_internal()
    ann_by_cls: dict = {}
    ann_lookup: dict = {}  # (image_file_stem, box_idx) → text
    if ann_df is not None:
        for _, row in ann_df.iterrows():
            ci = int(row['class_id'])
            t  = str(row['text']).strip()
            ann_by_cls.setdefault(ci, []).append(t)
            stem = str(row['image_file']).strip().rsplit('.', 1)[0]
            ann_lookup[(stem, int(row['box_idx']))] = t

    mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)
    std  = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)

    images, labels, texts = [], [], []
    class_counts = {i: 0 for i in range(len(STRESS_LABELS))}

    for class_idx, class_name in enumerate(STRESS_LABELS):
        class_dir = data_dir / class_name
        if not class_dir.exists():
            print(f"    [GDrive] Folder not found: {class_dir}")
            continue

        img_paths = (sorted(class_dir.glob("*.jpg")) +
                     sorted(class_dir.glob("*.jpeg")) +
                     sorted(class_dir.glob("*.png")) +
                     sorted(class_dir.glob("*.JPG")) +
                     sorted(class_dir.glob("*.PNG")))

        if not img_paths:
            print(f"    [GDrive] No images in {class_dir}")
            continue

        for img_path in img_paths:
            try:
                pil_img = _PILImage.open(img_path).convert("RGB").resize((img_size, img_size))
                arr = np.array(pil_img, dtype=np.float32) / 255.0
                img_tensor = torch.from_numpy(arr).permute(2, 0, 1)
                noise      = torch.randn_like(img_tensor) * 0.03
                brightness = 0.88 + random.random() * 0.24
                img_tensor = torch.clamp(img_tensor * brightness + noise, 0.0, 1.0)
                img_tensor = (img_tensor - mean) / std
            except Exception:
                continue

            # ── Resolve text: try annotation lookup, then class pool, then template ──
            text = None
            stem = img_path.stem  # e.g. "107_jpg.rf.abc_box0" or just "img_001"
            if '_box' in stem:
                orig_stem, box_part = stem.rsplit('_box', 1)
                try:
                    box_idx = int(box_part)
                    for ext in ('', '.jpg', '.jpeg', '.png'):
                        key = (orig_stem + ext, box_idx)
                        if key in ann_lookup:
                            text = ann_lookup[key]
                            break
                    if text is None:
                        for (img_f, b_idx), t in ann_lookup.items():
                            if b_idx == box_idx and (orig_stem in img_f or img_f in orig_stem):
                                text = t
                                break
                except ValueError:
                    pass

            if text is None and class_idx in ann_by_cls:
                text = random.choice(ann_by_cls[class_idx])

            if text is None:
                text = generate_tea_disease_text(class_name, class_counts[class_idx])

            images.append(img_tensor)
            labels.append([class_idx])
            texts.append(text)
            class_counts[class_idx] += 1

    total = len(images)
    print(f"  [GDrive] Loaded {total} images")
    for ci, cnt in class_counts.items():
        if cnt > 0:
            print(f"    {STRESS_LABELS[ci]}: {cnt}")
    return images, labels, texts


