def _load_classified_crops_dataset_disabled(zip_path: str = None, img_size: int = 224) -> Tuple[List, List, List]:
    """Load cropped tea disease images from Classified_Crops.zip (fallback loader).

    Prefer load_gdrive_image_dataset() which reads directly from the tea_data/ folder
    structure on Google Drive. This zip-based loader is kept as a fallback.

    Zip structure: crops/{class_name}/{filename}.jpg
    Class folders: gray_blight, helopeltis, algal_leaf_spot, brown_blight, red_leaf_spot

    Pairs each image with its text annotation from annotations.csv when available;
    falls back to generate_tea_disease_text() for images with no annotation.

    Returns:
        (images, labels, texts) — normalised image tensors, integer label lists, text strings.
    """
    import torch
    import numpy as np
    import zipfile
    from io import BytesIO
    from pathlib import Path as _Path

    # ── Resolve zip path ──
    if zip_path is None:
        _candidates = [
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/Classified_Crops.zip"),
            _Path("Classified_Crops.zip"),
            _Path("/content/drive/MyDrive/FarmFederate/Classified_Crops.zip"),
            _Path("/content/FarmFederate/Classified_Crops.zip"),
            _Path("../Classified_Crops.zip"),
        ]
        zip_path = next((str(p) for p in _candidates if p.exists()), None)
        if zip_path is None:
            print("  [Crops] Classified_Crops.zip not found — returning empty.")
            return [], [], []

    try:
        from PIL import Image as _PILImage
    except ImportError:
        print("  [Crops] PIL not available — cannot load images.")
        return [], [], []

    # ── Load annotation lookup: (image_file, box_idx) → text ──
    ann_lookup: dict = {}
    ann_df = _load_annotations_csv_internal()
    if ann_df is not None:
        for _, row in ann_df.iterrows():
            key = (str(row['image_file']).strip(), int(row['box_idx']))
            ann_lookup[key] = str(row['text']).strip()

    mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)
    std  = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)

    images, labels, texts = [], [], []
    class_counts = {i: 0 for i in range(len(STRESS_LABELS))}

    print(f"  [Crops] Loading from {zip_path}")
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            all_names = zf.namelist()
            for zname in sorted(all_names):
                # Expect path like: crops/{class_name}/somefile_box{idx}.jpg
                parts = zname.replace('\\', '/').split('/')
                if len(parts) < 3:
                    continue
                class_name = parts[-2]
                filename   = parts[-1]
                if class_name not in LABEL_TO_IDX:
                    continue
                if not filename.lower().endswith(('.jpg', '.jpeg', '.png')):
                    continue

                class_idx = LABEL_TO_IDX[class_name]

                # ── Load image ──
                try:
                    raw = zf.read(zname)
                    pil_img = _PILImage.open(BytesIO(raw)).convert("RGB").resize((img_size, img_size))
                    arr = np.array(pil_img, dtype=np.float32) / 255.0
                    img_tensor = torch.from_numpy(arr).permute(2, 0, 1)
                    noise      = torch.randn_like(img_tensor) * 0.03
                    brightness = 0.88 + random.random() * 0.24
                    img_tensor = torch.clamp(img_tensor * brightness + noise, 0.0, 1.0)
                    img_tensor = (img_tensor - mean) / std
                except Exception:
                    continue

                # ── Resolve text annotation ──
                # Filename pattern: {orig_stem}_box{idx}.jpg  e.g. 12_jpg.rf.abc_box0.jpg
                text = None
                stem = filename.rsplit('.', 1)[0]   # strip extension
                if '_box' in stem:
                    orig_stem, box_part = stem.rsplit('_box', 1)
                    try:
                        box_idx = int(box_part)
                        # Try looking up by stem (without extension suffix) variants
                        for ext in ('.jpg', '.jpeg', '.png', ''):
                            key = (orig_stem + ext, box_idx)
                            if key in ann_lookup:
                                text = ann_lookup[key]
                                break
                        if text is None:
                            # Try partial match: image_file field may be just the base name
                            for (img_f, b_idx), t in ann_lookup.items():
                                if b_idx == box_idx and (orig_stem in img_f or img_f in orig_stem):
                                    text = t
                                    break
                    except ValueError:
                        pass

                if text is None:
                    text = generate_tea_disease_text(class_name, len(images))

                images.append(img_tensor)
                labels.append([class_idx])
                texts.append(text)
                class_counts[class_idx] += 1

    except Exception as e:
        print(f"  [Crops] Error reading zip: {e}")
        return [], [], []

    total = len(images)
    print(f"  [Crops] Loaded {total} crop images from Classified_Crops.zip")
    for ci, cnt in class_counts.items():
        print(f"    class {ci} ({STRESS_LABELS[ci]}): {cnt} images")
    return images, labels, texts


def _load_annotations_csv_internal(csv_path: str = None) -> "Optional[pd.DataFrame]":
    """Internal helper: load annotations.csv into a DataFrame.

    Current schema: text, class_id, class_name. Legacy files may additionally
    contain image_file, box_idx, and disease; those columns remain supported.
    Returns None if CSV not found or unreadable.

    Search order (first found wins):
      1. tea_data/annotations.csv  (Google Drive mounted folder — preferred)
      2. tea_results/annotation/annotations.csv (local legacy path)
    """
    import pandas as pd
    from pathlib import Path as _Path

    if csv_path is None:
        _candidates = [
            # Highest priority: /content/tea_data (downloaded by setup_colab_data)
            _Path("/content/tea_data/annotations.csv"),
            # MyDrive/FarmFederate/tea_data
            _Path("/content/drive/MyDrive/FarmFederate/tea_data/annotations.csv"),
            _Path("/content/drive/My Drive/FarmFederate/tea_data/annotations.csv"),
            # Fallbacks
            _Path("/content/drive/MyDrive/FarmFederate/data/annotations.csv"),
            _Path("/content/drive/My Drive/FarmFederate/data/annotations.csv"),
            _Path("/content/drive/MyDrive/tea_data/annotations.csv"),
            # Local Windows paths
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/tea_data/annotations.csv"),
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/data/annotations.csv"),
            _Path("tea_data/annotations.csv"),
            _Path("data/annotations.csv"),
            # Legacy annotation paths
            _Path("C:/Users/USER_HP/Desktop/FarmFederate/tea_results/annotation/annotations.csv"),
            _Path("tea_results/annotation/annotations.csv"),
            _Path("/content/drive/MyDrive/FarmFederate/tea_results/annotation/annotations.csv"),
            _Path("/content/FarmFederate/tea_results/annotation/annotations.csv"),
            _Path("../tea_results/annotation/annotations.csv"),
        ]
        csv_path = next((str(p) for p in _candidates if p.exists()), None)

    if csv_path is None:
        return None

    try:
        df = pd.read_csv(csv_path)
        # Normalise column names
        df.columns = [c.strip().lower() for c in df.columns]
        required = {'class_id', 'text'}
        if not required.issubset(set(df.columns)):
            print(f"  [Annotations] Missing columns. Found: {list(df.columns)}")
            return None
        df['class_id'] = df['class_id'].astype(int)
        if 'box_idx' in df.columns:
            df['box_idx'] = df['box_idx'].astype(int)
        if 'class_name' in df.columns:
            # class_name is authoritative; class_id is a redundant positional
            # index into the schema. Excluding a class shifts every id above it,
            # so trusting the stored id would silently relabel the corpus.
            # Derive the id from the name instead, and verify the name against
            # the FULL taxonomy so a genuine typo still fails loudly.
            df['class_name'] = df['class_name'].astype(str).str.strip()
            unknown = sorted(set(
                df.loc[~df['class_name'].isin(FULL_STRESS_LABELS), 'class_name']
            ))
            if unknown:
                raise ValueError(
                    f"annotations.csv contains class_name values outside the "
                    f"taxonomy {FULL_STRESS_LABELS}: {unknown}"
                )
            dropped = int((~df['class_name'].isin(STRESS_LABELS)).sum())
            df = df[df['class_name'].isin(STRESS_LABELS)].copy()
            df['class_id'] = df['class_name'].map(LABEL_TO_IDX).astype(int)
            if dropped:
                print(f"  [Annotations] Dropped {dropped} rows for excluded "
                      f"classes {EXCLUDED_STRESS_LABELS}; class_id re-derived "
                      "from class_name.")
        else:
            # No name column to cross-check against. Keep only ids that are
            # valid under the ACTIVE schema rather than guessing at intent.
            df = df[df['class_id'].isin(range(len(STRESS_LABELS)))].copy()
        return df
    except Exception as e:
        print(f"  [Annotations] Failed to load CSV: {e}")
        return None


def load_annotations_text_dataset(csv_path: str = None, n_samples: int = None) -> "pd.DataFrame":
    """Load real tea disease text from annotations.csv.

    Current columns: text, class_id, class_name. Legacy annotation metadata is
    accepted when present. class_id follows the canonical STRESS_LABELS order.

    Args:
        csv_path:  Path to annotations.csv. Auto-detects if None.
        n_samples: If given, oversample/subsample to this total (balanced).

    Returns:
        DataFrame with columns: text, labels, label_name, source
    """
    import pandas as pd

    df = _load_annotations_csv_internal(csv_path)
    if df is None:
        print("  [Annotations] CSV not found — falling back to synthetic text.")
        return generate_synthetic_text_data(n_samples or 500)

    print(f"  [Annotations] Loaded {len(df)} rows from annotations.csv")

    # Build output DataFrame
    out_rows = []
    for _, row in df.iterrows():
        cls_id = int(row['class_id'])
        if not (0 <= cls_id < len(STRESS_LABELS)):
            continue
        out_rows.append({
            'text':       str(row['text']).strip(),
            'labels':     [cls_id],
            'label_name': STRESS_LABELS[cls_id],
            'source':     'annotations_csv',
        })

    result = pd.DataFrame(out_rows)
    counts = result['label_name'].value_counts().to_dict()
    print(f"  [Annotations] Classes: {counts}")

    # Optionally balance/oversample to n_samples
    if n_samples is not None and len(result) < n_samples:
        result = balance_dataset(result, target_per_class=n_samples // len(STRESS_LABELS))

    return result


def generate_tea_disease_text(disease_type: str, idx: int) -> str:
    """Generate neutral field observation text for a tea leaf disease class.

    Uses purely visual symptom descriptions — no scientific genus names, no disease
    labels embedded in the text. This prevents trivial keyword-matching shortcuts
    and ensures models learn genuine symptom patterns.
    """
    templates = {
        'LEAF_BLIGHT': [
            "Brown water-soaked lesions spreading from leaf margins inward. Tissue collapses quickly under humid conditions.",
            "Dark necrotic patches with pale yellow borders on lower canopy leaves. Soft texture at active edge.",
            "Blighted areas starting at tip and progressing along margins. Entire leaf surface browning in advanced cases.",
            "Irregular brown blotches covering large portions of leaf blade. Adjacent tissue appears water-soaked.",
            "Necrotic tan-brown patches with darker outer ring. Spreads rapidly in moist dense canopy sections.",
            "Leaf tissue turning brown from edges inward. Water-soaked translucent border at leading edge of lesion.",
        ],
        'LEAF_HOPPERS': [
            "Pale stippling pattern across upper leaf surface. Leaf margins curling upward. Colour fading to pale yellow.",
            "Uniform whitish flecking on leaf blade. Leaves feel papery and dry. Lower canopy most affected.",
            "Tip burn on young leaves with pale stippled damage spreading toward mid-leaf. Veins still green.",
            "Yellowing and bronzing of leaves with fine speckled texture on upper surface. Curled margins visible.",
            "Leaf tips turning yellow-white with fine pale speckling. Leaf curl on newly emerged growth.",
            "Bleached stippling across leaf surface. Leaves brittle and discoloured. Tip dieback in severe cases.",
        ],
        'LEAF_RUST': [
            "Orange-yellow powdery pustules on lower leaf surface. Corresponding pale spots visible on upper surface.",
            "Rust-coloured spore masses on abaxial surface. Upper leaf shows yellow-orange chlorotic spots.",
            "Bright orange urediniospore pustules scattered on underside of leaves. Spores dust off when touched.",
            "Yellow-orange raised pustules in irregular groups on leaf underside. Upper surface pale yellow above each.",
            "Orange pustules coalescing on lower leaf surface. Leaves yellowing and dropping in severe patches.",
            "Small circular orange-rust coloured spots on adaxial surface. Powdery spore deposits on abaxial side.",
        ],
        'LOOPER_CATERPILLARS': [
            "Irregular holes across leaf blade with ragged edges. Frass pellets visible on remaining tissue.",
            "Skeletonized patches where only veins remain. Leaf edges highly irregular from feeding damage.",
            "Large irregular sections of leaf removed. Frass deposits and silk threads present near damage.",
            "Leaf lamina partially consumed leaving midrib and major veins intact. Feeding damage on multiple leaves.",
            "Notched leaf margins and internal holes. Damage pattern consistent with chewing from leaf edge inward.",
            "Defoliated patches on canopy with only coarse veins remaining. Fine frass scattered beneath affected leaves.",
        ],
        'MOSQUITO_BUG': [
            "Multiple small raised necrotic spots on tender shoots. Each spot has a sunken dark centre. Tips wilted.",
            "Young flush with angular brown lesions at irregular positions. Rough raised texture at wound centres.",
            "New growth showing shoot dieback with scattered corky raised spots. Pale outer ring around each lesion.",
            "Raised angular marks on expanding leaves. Shoot tips bent and discoloured. Lesions not along veins.",
            "Tender leaves with rough brown patches and tip wilting. Scattered wound-like raised lesions throughout.",
            "Young shoots with multiple stipple-like raised spots and tip wilting. Lesion centres sunken and dark.",
        ],
    }
    disease_templates = templates.get(disease_type, templates['LEAF_BLIGHT'])
    base = disease_templates[idx % len(disease_templates)]
    # 35% chance to add ambiguous cross-symptom suffix
    if random.random() < 0.35:
        base += random.choice([
            " Pattern may overlap with adjacent stress factors.",
            " Monitoring across multiple plants recommended.",
            " Further observation needed before definitive assessment.",
            " Environmental conditions may be contributing.",
        ])
    return base


