def setup_environment():
    """Install required packages and setup environment"""
    print("=" * 70)
    print("SETTING UP ENVIRONMENT")
    print("=" * 70)

    packages = {
        'torch': 'torch',
        'torchvision': 'torchvision',
        'transformers': 'transformers',
        'datasets': 'datasets',
        'PIL': 'pillow',
        'pandas': 'pandas',
        'numpy': 'numpy',
        'sklearn': 'scikit-learn',
        'tqdm': 'tqdm',
        'matplotlib': 'matplotlib',
        'seaborn': 'seaborn',
        'sentence_transformers': 'sentence-transformers',
    }

    # Optional packages (don't fail if install fails). Keys are import names;
    # values are pip distribution names.
    optional_packages = {'faiss': 'faiss-cpu'}

    import subprocess
    for module_name, pkg in packages.items():
        try:
            __import__(module_name)
            print(f"  [OK] {pkg}")
        except ImportError:
            print(f"  [Installing] {pkg}...")
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', pkg])

    # Try optional packages
    for module_name, pkg in optional_packages.items():
        try:
            __import__(module_name)
            print(f"  [OK] {pkg}")
        except ImportError:
            try:
                print(f"  [Installing] {pkg}...")
                subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', pkg])
            except Exception:
                print(f"  [SKIP] {pkg} (optional)")

    try:
        import torch
        import transformers as _transformers_version
        print(
            f"\n  [Versions] torch={torch.__version__}, "
            f"transformers={_transformers_version.__version__}, "
            f"python={sys.version.split()[0]}"
        )
        if torch.cuda.is_available():
            print(f"  [GPU] {torch.cuda.get_device_name(0)}")
            print(f"  [Memory] {torch.cuda.get_device_properties(0).total_memory / 1e9:.1f} GB")
        else:
            print("\n  [CPU] No GPU detected, using CPU")
    except Exception as e:
        print(f"\n  [Warning] Could not detect GPU: {e}")

    print("\nSetup complete!")
    return True


