def generate_synthetic_text_data(n_samples: int = 500) -> "pd.DataFrame":
    """Generate LEARNABLE synthetic text data for tea leaf disease classification.

    Creates realistic but ambiguous tea garden field observations so models must
    learn symptom combinations rather than trivial keyword shortcuts.
    - 30% clear class-indicative text, 70% mixed/ambiguous for realistic F1 range.
    - Balanced class distribution across 5 tea leaf disease classes.
    """

    # Per-class symptom vocabulary — no explicit disease names in observations
    class_keywords = {
        0: {  # LEAF_BLIGHT
            'observations': ['brown water-soaked lesions spreading from leaf margins', 'dark necrotic patches with pale yellow borders',
                             'blighted areas from leaf tip progressing along margins', 'irregular brown blotches on leaf blade',
                             'necrotic tan-brown patches with darker outer ring', 'tissue collapsing under humid conditions'],
            'symptoms': ['water-soaked brown necrosis from margins', 'large irregular brown blotches',
                        'soft tissue at active lesion edge', 'blighted leaf tissue collapsing',
                        'pale yellow border around brown necrosis', 'entire leaf browning in advanced cases'],
            'conditions': ['high humidity and wet conditions', 'dense canopy reducing airflow',
                          'rainy season peak', 'poor field drainage', 'warm moist microclimate'],
            'indicators': ['blight coverage exceeding 30% of leaf area', 'new flush most susceptible',
                          'spread confirmed to multiple plants', 'water-soaked margin at active edge'],
        },
        1: {  # LEAF_HOPPERS
            'observations': ['pale stippling pattern across upper leaf surface', 'whitish flecking on leaf blade',
                             'tip burn on young leaves', 'yellowing and bronzing of leaves',
                             'leaf margins curling upward', 'leaves feel papery and dry'],
            'symptoms': ['uniform stippled bleaching on upper surface', 'tip burn and leaf curl',
                        'yellowing with fine speckled texture', 'bronzing of leaf surface',
                        'brittle dry leaf texture', 'tip dieback in severe cases'],
            'conditions': ['dry warm weather favoring hopper build-up', 'open canopy with high light',
                          'new flush actively growing', 'reduced natural enemy pressure'],
            'indicators': ['stippling density increasing per leaf', 'tip burn advancing',
                          'leaf curl confirmed on multiple plants', 'hopper nymphs visible on underside'],
        },
        2: {  # LEAF_RUST
            'observations': ['orange-yellow powdery pustules on lower leaf surface', 'rust-coloured spore masses on abaxial surface',
                             'bright orange urediniospores visible on leaf underside', 'yellow-orange pustules on leaf underside',
                             'pale spots on upper surface corresponding to pustules below', 'spores dust off when touched'],
            'symptoms': ['orange powdery pustules on abaxial surface', 'yellow chlorotic spots on adaxial surface',
                        'coalescing rust pustules on lower leaf', 'leaf yellowing and early drop',
                        'spore masses on lower surface', 'pustule groups in irregular distribution'],
            'conditions': ['moderate humidity with alternating wet-dry cycles', 'warm temperatures',
                          'susceptible growth stage', 'spore dispersal by wind and splash'],
            'indicators': ['pustule count per leaf increasing', 'spore load visible when leaf touched',
                          'yellow spotting on upper surface spreading', 'defoliation in severely affected areas'],
        },
        3: {  # LOOPER_CATERPILLARS
            'observations': ['irregular holes across leaf blade with ragged edges', 'skeletonized patches with only veins remaining',
                             'large sections of leaf tissue removed', 'frass pellets visible on remaining tissue',
                             'notched leaf margins from feeding', 'multiple leaves defoliated in canopy'],
            'symptoms': ['ragged irregular holes in leaf lamina', 'skeletonized leaves with veins intact',
                        'feeding damage from leaf edges inward', 'frass deposits near feeding sites',
                        'silk threads and frass webbing present', 'severe defoliation in patches'],
            'conditions': ['warm season with high caterpillar pressure', 'reduced predator/parasitoid activity',
                          'dense canopy providing shelter', 'susceptible young flush growth'],
            'indicators': ['hole count and size increasing per plant', 'frass deposits confirmed below leaves',
                          'skeletonized patches spreading', 'larvae visible on undersides of leaves'],
        },
        4: {  # MOSQUITO_BUG
            'observations': ['multiple small raised necrotic spots on tender shoots', 'corky raised spots on young flush',
                             'wilting of shoot tips after feeding damage', 'angular brown lesions at irregular positions',
                             'rough raised texture at each wound centre', 'shoot dieback on new growth'],
            'symptoms': ['raised necrotic spots with sunken dark centres', 'shoot tip wilting and dieback',
                        'angular brown lesions not following veins', 'corky wound tissue on tender flush',
                        'scattered wound-like raised lesions', 'young shoot stunting noted'],
            'conditions': ['warm dry spells alternating with humidity', 'new flush actively growing',
                          'unshaded field sections', 'high insect population in adjacent vegetation'],
            'indicators': ['wound lesion count increasing per plant on scout check', 'characteristic raised lesion confirmed',
                          'feeding puncture marks visible under lens', 'shoot damage increasing per plant'],
        },
    }


    # These tables were written against the original five-class order and are
    # indexed by class index. Excluding a class renumbers those indices, which
    # would silently attach one class's symptoms to another's label. Rekey by
    # NAME and project onto the ACTIVE schema before any lookup happens.
    _SOURCE_ORDER = [
        'LEAF_BLIGHT', 'LEAF_HOPPERS', 'LEAF_RUST',
        'LOOPER_CATERPILLARS', 'MOSQUITO_BUG',
    ]
    class_keywords = {
        index: class_keywords[_SOURCE_ORDER.index(name)]
        for index, name in enumerate(STRESS_LABELS)
    }

    templates = [
        "Leaf image shows {symptom1} and {symptom2}. {observation}. Field context: {condition}. Assessment: {indicator}.",
        "Image analysis — leaf surface: {symptom1}. Secondary sign: {symptom2}. Visual observation: {observation}. Status: {indicator}.",
        "Crop photo: {symptom1} visible on leaf. Also shows {symptom2}. {observation}. Conditions: {condition}. Note: {indicator}.",
        "Scouting image: {symptom1} and {symptom2} observed. {observation}. Background: {condition}. Indicator: {indicator}.",
        "Visual record of tea leaf: {symptom1}. Additionally: {symptom2}. {observation}. {indicator}.",
        "Field photograph: leaf displays {symptom1} with {symptom2}. {observation}. {condition}. Note: {indicator}.",
        "Image depicts {symptom1}. Concurrent sign: {symptom2}. {observation}. Environmental: {condition}. Assessment: {indicator}.",
    ]

    texts, labels = [], []

    for i in range(n_samples):
        label_idx = i % len(STRESS_LABELS)
        template = random.choice(templates)
        keywords = class_keywords[label_idx]

        # 3-tier difficulty: 8% clear / 22% slightly mixed / 70% heavily mixed.
        # Heavily mixed rows contain cross-class distractors but retain one
        # class-supporting assessment indicator, so every label remains valid.
        rnd = random.random()
        other_indices = [j for j in range(len(STRESS_LABELS)) if j != label_idx]
        other_idx1 = random.choice(other_indices)
        other_idx2 = random.choice([j for j in other_indices if j != other_idx1] or other_indices)
        other_kw1 = class_keywords[other_idx1]
        other_kw2 = class_keywords[other_idx2]

        if rnd < 0.08:
            # Clear: all fields from true class
            observation = random.choice(keywords['observations'])
            symptom1    = random.choice(keywords['symptoms'])
            symptom2    = random.choice(keywords['symptoms'])
            while symptom2 == symptom1:
                symptom2 = random.choice(keywords['symptoms'])
            condition   = random.choice(keywords['conditions'])
            indicator   = random.choice(keywords['indicators'])
        elif rnd < 0.30:
            # Slightly mixed: primary observation+symptom from true class, rest cross-class
            observation = random.choice(keywords['observations'])
            symptom1    = random.choice(keywords['symptoms'])
            symptom2    = random.choice(other_kw1['symptoms'])
            condition   = random.choice(other_kw2['conditions'])
            indicator   = random.choice(other_kw1['indicators'])
        else:
            # Heavily mixed: symptoms come from two other classes while the
            # assessment indicator remains a weak true-class signal.
            observation = random.choice(other_kw1['observations'])
            symptom1    = random.choice(other_kw2['symptoms'])
            symptom2    = random.choice(other_kw1['symptoms'])
            condition   = random.choice(other_kw2['conditions'])
            # Retain one genuine class-supporting clue. Difficulty comes from
            # cross-class distractors, never from assigning a label unsupported
            # by any part of the generated observation.
            indicator   = random.choice(keywords['indicators'])

        text = template.format(
            observation=observation,
            symptom1=symptom1,
            symptom2=symptom2,
            condition=condition,
            indicator=indicator,
        )
        texts.append(text.strip())
        labels.append([label_idx])

    return pd.DataFrame({'text': texts, 'labels': labels, 'label_name': [STRESS_LABELS[l[0]] for l in labels]})


def generate_synthetic_image_data(n_samples: int = 500, img_size: int = 224, target_labels: list = None) -> Tuple[List, List]:
    """Generate synthetic tea leaf images with subtle per-disease visual patterns.

    All 5 classes share a similar green tea-leaf base colour. Class indices use
    STRESS_LABELS: margin blight, hopper stippling, rust pustules, chewing
    holes, and mosquito-bug corky lesions respectively.

    These generated images are fallback/ablation data and are never substituted
    for the untouched real validation or test images.

    Args:
        target_labels: Optional list of label indices. If provided, images[i] gets
                       the visual pattern for target_labels[i] instead of i % 5.
    """
    import torch
    import numpy as np

    images, labels = [], []

    # Crop leaf green base colours — subtle per-class offset
    base_colors = [
        (0.30, 0.43, 0.14),  # LEAF_BLIGHT          — slightly warmer green (browning)
        (0.28, 0.43, 0.15),  # LEAF_HOPPERS         — normal green (stippling)
        (0.27, 0.43, 0.16),  # LEAF_RUST            — similar green
        (0.26, 0.43, 0.14),  # LOOPER_CATERPILLARS  — normal green
        (0.25, 0.43, 0.14),  # MOSQUITO_BUG         — slightly darker (damaged tissue)
    ]

    # Visual pattern type for each class
    patterns = ['brown_blight', 'gray_diffuse', 'orange_velvet', 'circular_spots', 'dark_lesions']

    # These tables were written against the original five-class order and are
    # indexed by class index. Excluding a class renumbers those indices, which
    # would silently attach one class's symptoms to another's label. Rekey by
    # NAME and project onto the ACTIVE schema before any lookup happens.
    _SOURCE_ORDER = [
        'LEAF_BLIGHT', 'LEAF_HOPPERS', 'LEAF_RUST',
        'LOOPER_CATERPILLARS', 'MOSQUITO_BUG',
    ]
    base_colors = [base_colors[_SOURCE_ORDER.index(n)] for n in STRESS_LABELS]
    patterns = [patterns[_SOURCE_ORDER.index(n)] for n in STRESS_LABELS]

    for i in range(n_samples):
        if target_labels is not None:
            lbl = target_labels[i]
            label_idx = lbl[0] if isinstance(lbl, (list, tuple)) else int(lbl)
        else:
            label_idx = i % len(STRESS_LABELS)

        base_r, base_g, base_b = base_colors[label_idx]
        base_r += (random.random() - 0.5) * 0.12
        base_g += (random.random() - 0.5) * 0.12
        base_b += (random.random() - 0.5) * 0.08

        img = torch.zeros(3, img_size, img_size)
        noise = 0.05 + random.random() * 0.05

        img[0] = base_r + torch.randn(img_size, img_size) * noise
        img[1] = base_g + torch.randn(img_size, img_size) * noise
        img[2] = base_b + torch.randn(img_size, img_size) * noise

        intensity = 0.12 + random.random() * 0.13
        y_grid, x_grid = np.ogrid[:img_size, :img_size]
        primary_pattern = patterns[label_idx]

        # Apply primary pattern 55% of the time
        if random.random() < 0.55:
            if primary_pattern == 'dark_lesions':  # MOSQUITO_BUG — dark corky feeding-wound spots
                for _ in range(random.randint(3, 8)):
                    cx = random.randint(20, img_size - 20)
                    cy = random.randint(20, img_size - 20)
                    r  = random.randint(5, 14)
                    mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < r**2
                    # Very dark necrotic centre
                    img[0, mask] *= (1 - 0.7 * intensity)
                    img[1, mask] *= (1 - 0.7 * intensity)
                    img[2, mask] *= (1 - 0.6 * intensity)

            elif primary_pattern == 'orange_velvet':  # LEAF_RUST — orange-red rust patches
                for _ in range(random.randint(2, 5)):
                    cx = random.randint(30, img_size - 30)
                    cy = random.randint(30, img_size - 30)
                    r  = random.randint(8, 20)
                    mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < r**2
                    # Orange-red rust colour
                    img[0, mask] = img[0, mask] * (1 - 0.5 * intensity) + 0.65 * 0.5 * intensity
                    img[1, mask] = img[1, mask] * (1 - 0.5 * intensity) + 0.30 * 0.5 * intensity
                    img[2, mask] = img[2, mask] * (1 - 0.5 * intensity) + 0.05 * 0.5 * intensity

            elif primary_pattern == 'circular_spots':  # LOOPER_CATERPILLARS — irregular hole patterns
                for _ in range(random.randint(4, 12)):
                    cx = random.randint(15, img_size - 15)
                    cy = random.randint(15, img_size - 15)
                    r_outer = random.randint(5, 12)
                    r_inner = max(2, r_outer // 2)
                    outer = ((x_grid - cx)**2 + (y_grid - cy)**2) < r_outer**2
                    inner = ((x_grid - cx)**2 + (y_grid - cy)**2) < r_inner**2
                    ring  = outer & ~inner
                    # Dark border ring
                    img[0, ring] = img[0, ring] * (1 - 0.5 * intensity) + 0.22 * 0.5 * intensity
                    img[1, ring] = img[1, ring] * (1 - 0.5 * intensity) + 0.10 * 0.5 * intensity
                    # Pale grey-brown centre
                    img[0, inner] = img[0, inner] * (1 - 0.4 * intensity) + 0.55 * 0.4 * intensity
                    img[1, inner] = img[1, inner] * (1 - 0.4 * intensity) + 0.42 * 0.4 * intensity
                    img[2, inner] = img[2, inner] * (1 - 0.4 * intensity) + 0.30 * 0.4 * intensity

            elif primary_pattern == 'brown_blight':  # LEAF_BLIGHT — tip & margin browning
                # Tip blight: top rows
                tip_rows = int(img_size * (0.15 + random.random() * 0.25))
                for row in range(tip_rows):
                    fade = (tip_rows - row) / tip_rows * intensity
                    img[0, row, :] = img[0, row, :] * (1 - fade) + 0.55 * fade
                    img[1, row, :] = img[1, row, :] * (1 - fade) + 0.28 * fade
                    img[2, row, :] = img[2, row, :] * (1 - fade) + 0.08 * fade
                # Margin blight
                margin = int(img_size * (0.08 + random.random() * 0.12))
                for col in range(margin):
                    fade = (margin - col) / margin * intensity * 0.6
                    img[0, :, col]    = img[0, :, col]    * (1 - fade) + 0.50 * fade
                    img[1, :, col]    = img[1, :, col]    * (1 - fade) + 0.25 * fade
                    img[0, :, -col-1] = img[0, :, -col-1] * (1 - fade) + 0.50 * fade
                    img[1, :, -col-1] = img[1, :, -col-1] * (1 - fade) + 0.25 * fade

            elif primary_pattern == 'gray_diffuse':  # LEAF_HOPPERS — pale stippled areas
                for _ in range(random.randint(2, 5)):
                    cx = random.randint(25, img_size - 25)
                    cy = random.randint(25, img_size - 25)
                    r  = random.randint(15, 35)
                    mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < r**2
                    # Pale grey-white blend
                    img[0, mask] = img[0, mask] * (1 - 0.45 * intensity) + 0.62 * 0.45 * intensity
                    img[1, mask] = img[1, mask] * (1 - 0.45 * intensity) + 0.60 * 0.45 * intensity
                    img[2, mask] = img[2, mask] * (1 - 0.45 * intensity) + 0.58 * 0.45 * intensity

        # Cross-class confusion: 60% chance secondary pattern from a different disease
        if random.random() < 0.60:
            sec_idx     = random.choice([j for j in range(len(STRESS_LABELS)) if j != label_idx])
            sec_pattern = patterns[sec_idx]
            sec_int     = 0.08 + random.random() * 0.12

            if sec_pattern == 'dark_lesions':
                cx = random.randint(30, img_size - 30); cy = random.randint(30, img_size - 30)
                mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < (random.randint(4, 9))**2
                img[0, mask] *= (1 - 0.5 * sec_int)
                img[1, mask] *= (1 - 0.5 * sec_int)
            elif sec_pattern == 'orange_velvet':
                cx = random.randint(40, img_size - 40); cy = random.randint(40, img_size - 40)
                mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < (random.randint(5, 12))**2
                img[0, mask] = img[0, mask] * (1 - 0.3 * sec_int) + 0.60 * 0.3 * sec_int
                img[1, mask] = img[1, mask] * (1 - 0.3 * sec_int) + 0.28 * 0.3 * sec_int
            elif sec_pattern == 'circular_spots':
                for _ in range(random.randint(2, 5)):
                    cx = random.randint(20, img_size - 20); cy = random.randint(20, img_size - 20)
                    mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < (random.randint(3, 7))**2
                    img[0, mask] = img[0, mask] * (1 - 0.35 * sec_int) + 0.50 * 0.35 * sec_int
            elif sec_pattern == 'brown_blight':
                tip = int(img_size * 0.08)
                for row in range(tip):
                    fade = (tip - row) / tip * sec_int * 0.4
                    img[0, row, :] = img[0, row, :] * (1 - fade) + 0.50 * fade
            elif sec_pattern == 'gray_diffuse':
                cx = random.randint(35, img_size - 35); cy = random.randint(35, img_size - 35)
                mask = ((x_grid - cx)**2 + (y_grid - cy)**2) < (random.randint(10, 22))**2
                img[0, mask] = img[0, mask] * (1 - 0.3 * sec_int) + 0.60 * 0.3 * sec_int
                img[1, mask] = img[1, mask] * (1 - 0.3 * sec_int) + 0.58 * 0.3 * sec_int

        # Global noise + brightness variation
        img = img + torch.randn_like(img) * 0.06
        brightness = 0.85 + random.random() * 0.30
        img = img * brightness
        img = torch.clamp(img, 0, 1)

        mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)
        std  = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)
        img  = (img - mean) / std

        images.append(img)
        labels.append([label_idx])

    return images, labels


