# Fixed categorical colors per model type (Okabe-Ito, colorblind-safe).
# Same entity always gets the same hue across every figure.
MODEL_TYPE_COLORS = {
    'ViT': '#D55E00',
    'LLM': '#0072B2',
    'VLM': '#CC79A7',
    'FlexibleVLM': '#009E73',
}
MODEL_TYPE_ORDER = ['ViT', 'LLM', 'VLM', 'FlexibleVLM']
FEDERATED_CONDITION_DISPLAY = {
    'ViT': 'Image only (unimodal)',
    'LLM': 'Text only (unimodal)',
    'VLM': 'Standard VLM fusion (concat)',
    'FlexibleVLM': 'Flexible multimodal VLM (matched scratch)',
}


def generate_federated_sweep_plots(results: Dict, plots_dir) -> list:
    """Federated-learning analysis plots (46-50) from run_federated_sweep() data.

    Every point is a measured federated run — no synthetic values. Produces:
      46  rounds vs performance (one line per client count, panel per model type)
      47  number of clients vs performance (final and best round)
      48  data heterogeneity (Dirichlet alpha) vs performance
      49  local epochs per round vs performance
      50  client participation fraction vs performance

    Returns the list of saved file paths (empty if no sweep data present).
    """
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    from pathlib import Path as _Path

    plots_dir = _Path(plots_dir)
    saved = []
    fed_sweep = results.get('fed_sweep', {})
    sweep_types = [mt for mt in MODEL_TYPE_ORDER if fed_sweep.get(mt)]
    if not sweep_types:
        print("  [46-50] Skipped federated analysis plots: no fed_sweep data "
              "(enable config.run_fed_sweep to generate)")
        return saved

    # Plot 46: rounds vs performance, one line per client count, panel per model type
    _has_cr = [mt for mt in sweep_types if fed_sweep[mt].get('clients_rounds')]
    if _has_cr:
        fig, axes = plt.subplots(1, len(_has_cr), figsize=(5.5 * len(_has_cr), 4.6),
                                 sharey=True, squeeze=False)
        for ax, mt in zip(axes[0], _has_cr):
            cr = fed_sweep[mt]['clients_rounds']
            client_counts = sorted(cr.keys(), key=int)
            shades = plt.cm.Blues(np.linspace(0.45, 0.95, len(client_counts)))
            for nc, shade in zip(client_counts, shades):
                h = cr[nc]['history']
                ax.plot(h['rounds'], h['val_f1'], marker='o', ms=4, linewidth=2,
                        color=shade, label=f"{nc} clients")
            ax.set_title(mt, color=MODEL_TYPE_COLORS.get(mt), fontweight='bold')
            ax.set_xlabel('Federated round')
            ax.grid(True, alpha=0.3)
        axes[0][0].set_ylabel('Global Val F1 (micro)')
        axes[0][-1].legend(fontsize=8, loc='lower right')
        fig.suptitle('Plot 46: Rounds vs performance at each client count (FedAvg)',
                     fontweight='bold')
        plt.tight_layout()
        p = plots_dir / 'plot46_fed_rounds_vs_performance.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [46/50] Federated rounds vs performance saved")

        # Plot 47: number of clients vs performance (final and best round)
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 4.6))
        for mt in _has_cr:
            cr = fed_sweep[mt]['clients_rounds']
            client_counts = sorted(cr.keys(), key=int)
            xs = [int(c) for c in client_counts]
            ax1.plot(xs, [cr[c]['final_f1'] for c in client_counts], marker='o',
                     linewidth=2, color=MODEL_TYPE_COLORS.get(mt), label=mt)
            ax2.plot(xs, [cr[c]['best_f1'] for c in client_counts], marker='o',
                     linewidth=2, color=MODEL_TYPE_COLORS.get(mt), label=mt)
        for ax, ttl in ((ax1, 'Final-round F1'), (ax2, 'Best-round F1')):
            ax.set_xlabel('Number of clients (total data fixed)')
            ax.set_ylabel('Global Val F1 (micro)')
            ax.set_title(ttl)
            ax.grid(True, alpha=0.3)
            ax.legend()
        fig.suptitle('Plot 47: Number of clients vs performance', fontweight='bold')
        plt.tight_layout()
        p = plots_dir / 'plot47_fed_clients_vs_performance.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [47/50] Federated clients vs performance saved")

    # Plot 48: data heterogeneity (Dirichlet alpha) vs performance
    _has_a = [mt for mt in sweep_types if fed_sweep[mt].get('alpha')]
    if _has_a:
        plt.figure(figsize=(8, 5))
        for mt in _has_a:
            al = fed_sweep[mt]['alpha']
            alphas = sorted(al.keys(), key=float)
            plt.plot([float(a) for a in alphas], [al[a]['final_f1'] for a in alphas],
                     marker='o', linewidth=2, color=MODEL_TYPE_COLORS.get(mt), label=mt)
        plt.xscale('log')
        plt.xlabel('Dirichlet alpha (smaller = more non-IID)')
        plt.ylabel('Global Val F1 (micro)')
        plt.title('Plot 48: Client data heterogeneity vs performance')
        plt.grid(True, alpha=0.3)
        plt.legend()
        plt.tight_layout()
        p = plots_dir / 'plot48_fed_heterogeneity.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [48/50] Federated heterogeneity saved")

    # Plot 49: local epochs per round vs performance
    _has_le = [mt for mt in sweep_types if fed_sweep[mt].get('local_epochs')]
    if _has_le:
        plt.figure(figsize=(8, 5))
        for mt in _has_le:
            le = fed_sweep[mt]['local_epochs']
            epochs_keys = sorted(le.keys(), key=int)
            plt.plot([int(k) for k in epochs_keys], [le[k]['final_f1'] for k in epochs_keys],
                     marker='o', linewidth=2, color=MODEL_TYPE_COLORS.get(mt), label=mt)
        plt.xlabel('Local epochs per round (E)')
        plt.ylabel('Global Val F1 (micro)')
        plt.title('Plot 49: Local computation vs performance')
        plt.grid(True, alpha=0.3)
        plt.legend()
        plt.tight_layout()
        p = plots_dir / 'plot49_fed_local_epochs.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [49/50] Federated local epochs saved")

    # Plot 50: client participation fraction vs performance
    _has_p = [mt for mt in sweep_types if fed_sweep[mt].get('participation')]
    if _has_p:
        plt.figure(figsize=(8, 5))
        for mt in _has_p:
            pr = fed_sweep[mt]['participation']
            fracs = sorted(pr.keys(), key=float)
            plt.plot([float(k) for k in fracs], [pr[k]['final_f1'] for k in fracs],
                     marker='o', linewidth=2, color=MODEL_TYPE_COLORS.get(mt), label=mt)
        plt.xlabel('Client participation fraction per round (C)')
        plt.ylabel('Global Val F1 (micro)')
        plt.title('Plot 50: Partial client participation vs performance')
        plt.grid(True, alpha=0.3)
        plt.legend()
        plt.tight_layout()
        p = plots_dir / 'plot50_fed_participation.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [50/50] Federated participation saved")

    print(f"\n  Federated analysis plots (46-50) saved to {plots_dir}/")
    return saved


def generate_federated_reviewer_plots(results: Dict, plots_dir, local_epochs: int = 3) -> list:
    """Reviewer-oriented federated plots (53-56). All points are measured.

      53  communication cost vs accuracy (cumulative MB exchanged, per client count)
      54  federated vs centralized convergence on a common axis (passes over data)
      55  per-class F1: centralized vs federated (minority-class behaviour)
      56  client data distribution at the paper config (size + label mix per client)
    """
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    from pathlib import Path as _Path

    plots_dir = _Path(plots_dir)
    saved = []
    # Entity colors reused from plot05: centralized vs federated pair
    CENT_COL, FED_COL = '#56B4E9', '#E69F00'
    # Fixed class colors (Okabe-Ito order by class id)
    CLASS_COLS = ['#0072B2', '#E69F00', '#009E73', '#CC79A7', '#56B4E9']

    fed_sweep = results.get('fed_sweep', {})
    fed_hist = results.get('federated_history', {})
    cent_res = results.get('centralized', {})
    fed_res = results.get('federated', {})
    client_stats = results.get('fed_client_stats', {})

    # Plot 53: cumulative communication vs accuracy (per client count, panels per model)
    _has = [mt for mt in MODEL_TYPE_ORDER
            if fed_sweep.get(mt, {}).get('clients_rounds') and fed_sweep[mt].get('model_params')]
    if _has:
        fig, axes = plt.subplots(1, len(_has), figsize=(5.5 * len(_has), 4.6),
                                 sharey=True, squeeze=False)
        for ax, mt in zip(axes[0], _has):
            cr = fed_sweep[mt]['clients_rounds']
            mb_per_client_round = fed_sweep[mt]['model_params'] * 4 * 2 / 1e6  # fp32, up+down
            client_counts = sorted(cr.keys(), key=int)
            shades = plt.cm.Blues(np.linspace(0.45, 0.95, len(client_counts)))
            for nc, shade in zip(client_counts, shades):
                h = cr[nc]['history']
                mb = [r * int(nc) * mb_per_client_round for r in h['rounds']]
                ax.plot(mb, h['val_f1'], marker='o', ms=4, linewidth=2,
                        color=shade, label=f"{nc} clients")
            ax.set_xscale('log')
            # Minor log labels collide when the panel spans <1 decade
            ax.tick_params(axis='x', which='minor', labelbottom=False)
            ax.set_title(mt, color=MODEL_TYPE_COLORS.get(mt), fontweight='bold')
            ax.set_xlabel('Cumulative communication (MB, fp32 up+down)')
            ax.grid(True, alpha=0.3)
        axes[0][0].set_ylabel('Global Val F1 (micro)')
        axes[0][-1].legend(fontsize=8, loc='lower right')
        fig.suptitle('Plot 53: Accuracy vs communication cost (FedAvg)', fontweight='bold')
        plt.tight_layout()
        p = plots_dir / 'plot53_fed_communication_cost.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [53] Federated communication cost saved")

    # Plot 54: federated vs centralized convergence, common x = passes over training data
    _has = [mt for mt in MODEL_TYPE_ORDER
            if isinstance(cent_res.get(mt), dict) and (cent_res[mt].get('history') or {}).get('val_f1')
            and (fed_hist.get(mt) or {}).get('val_f1')]
    if _has:
        fig, axes = plt.subplots(1, len(_has), figsize=(5.5 * len(_has), 4.6),
                                 sharey=True, squeeze=False)
        for ax, mt in zip(axes[0], _has):
            central_history = cent_res[mt]['history']
            ch = central_history['val_f1']
            fh = fed_hist[mt]
            central_x = central_history.get(
                'passes', list(range(1, len(ch) + 1))
            )
            ax.plot(central_x, ch, marker='s', ms=4, linewidth=2,
                    color=CENT_COL, label='Centralized control (matched block)')
            fed_x = fh.get(
                'passes',
                [r * max(1, local_epochs) for r in fh['rounds']],
            )
            ax.plot(fed_x, fh['val_f1'], marker='o', ms=4, linewidth=2,
                    color=FED_COL, label=f'Federated (round = {local_epochs} local epochs)')
            ax.set_title(
                FEDERATED_CONDITION_DISPLAY.get(mt, mt),
                color=MODEL_TYPE_COLORS.get(mt), fontweight='bold'
            )
            ax.set_xlabel('Equivalent passes over training data')
            ax.grid(True, alpha=0.3)
        axes[0][0].set_ylabel('Val F1 (micro)')
        axes[0][-1].legend(fontsize=8, loc='lower right')
        fig.suptitle('Plot 54: Federated vs centralized convergence (same data-pass axis)',
                     fontweight='bold')
        plt.tight_layout()
        p = plots_dir / 'plot54_fed_vs_centralized_convergence.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [54] Fed vs centralized convergence saved")

    # Plot 55: per-class F1 centralized vs federated (does federation hurt minority classes?)
    _has = [mt for mt in MODEL_TYPE_ORDER
            if isinstance(cent_res.get(mt), dict) and cent_res[mt].get('per_class_f1')
            and isinstance(fed_res.get(mt), dict) and fed_res[mt].get('per_class_f1')]
    if _has:
        n_cls = len(STRESS_LABELS)
        short = [TEA_DISEASE_DISPLAY.get(c, c).replace(' ', '\n') for c in STRESS_LABELS]
        x = np.arange(n_cls)
        w = 0.38
        fig, axes = plt.subplots(1, len(_has), figsize=(5.5 * len(_has), 4.8),
                                 sharey=True, squeeze=False)
        for ax, mt in zip(axes[0], _has):
            cv = list(cent_res[mt]['per_class_f1'])[:n_cls]
            fv = list(fed_res[mt]['per_class_f1'])[:n_cls]
            ax.bar(x - w / 2, cv, w, color=CENT_COL, edgecolor='white', lw=1,
                   label='Centralized')
            ax.bar(x + w / 2, fv, w, color=FED_COL, edgecolor='white', lw=1,
                   label='Federated')
            ax.set_title(
                FEDERATED_CONDITION_DISPLAY.get(mt, mt),
                color=MODEL_TYPE_COLORS.get(mt), fontweight='bold'
            )
            ax.set_xticks(x)
            ax.set_xticklabels(short, fontsize=8)
            ax.grid(True, alpha=0.3, axis='y')
        axes[0][0].set_ylabel('Per-class F1 (common held-out test)')
        axes[0][0].set_ylim(0, 1.05)
        # Bars rise from y=0, so any in-axes legend collides — place at figure level
        _h, _l = axes[0][0].get_legend_handles_labels()
        fig.legend(_h, _l, fontsize=8, loc='upper right', ncol=2, framealpha=0.9)
        fig.suptitle('Plot 55: Per-class F1 — centralized vs federated', fontweight='bold')
        plt.tight_layout(rect=(0, 0, 1, 0.93))
        p = plots_dir / 'plot55_fed_per_class_f1.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [55] Per-class fed vs centralized saved")

    # Plot 56: what each client actually holds (size + label mix), paper config
    _has = [mt for mt in MODEL_TYPE_ORDER
            if client_stats.get(mt, {}).get('client_label_counts')]
    if _has:
        fig, axes = plt.subplots(1, len(_has), figsize=(5.5 * len(_has), 4.8),
                                 squeeze=False)
        for ax, mt in zip(axes[0], _has):
            st = client_stats[mt]
            counts = np.array(st['client_label_counts'], dtype=float)  # [clients, classes]
            xs = np.arange(counts.shape[0])
            bottom = np.zeros(counts.shape[0])
            for cls_i in range(counts.shape[1]):
                col = CLASS_COLS[cls_i % len(CLASS_COLS)]
                ax.bar(xs, counts[:, cls_i], bottom=bottom, color=col,
                       edgecolor='white', lw=1,
                       label=TEA_DISEASE_DISPLAY.get(STRESS_LABELS[cls_i], STRESS_LABELS[cls_i])
                       if mt == _has[0] else None)
                bottom += counts[:, cls_i]
            ax.set_title(
                f"{FEDERATED_CONDITION_DISPLAY.get(mt, mt)}  "
                f"(K={st['num_clients']}, " + r"$\alpha$=" + f"{st['alpha']})",
                color=MODEL_TYPE_COLORS.get(mt), fontweight='bold'
            )
            ax.set_xlabel('Client')
            ax.set_xticks(xs)
            ax.set_xticklabels([str(i + 1) for i in xs])
            ax.grid(True, alpha=0.3, axis='y')
        axes[0][0].set_ylabel('Training samples held (stacked by class)')
        fig.legend(fontsize=8, loc='upper right', ncol=2, framealpha=0.9)
        fig.suptitle('Plot 56: Per-client data distribution under the Dirichlet split',
                     fontweight='bold')
        plt.tight_layout(rect=(0, 0, 1, 0.92))
        p = plots_dir / 'plot56_fed_client_distribution.png'
        plt.savefig(p); plt.close(); saved.append(p)
        print("  [56] Client data distribution saved")

    if saved:
        print(f"\n  Federated reviewer plots (53-56) saved to {plots_dir}/")
    else:
        print("  [53-56] Skipped reviewer plots: missing fed_sweep/history/per-class/client data")
    return saved


def generate_measured_diagnostic_plots(results: Dict, plots_dir,
                                       bootstrap_replicates: int = 2000) -> list:
    """Generate plots 58-64 from measured, paired held-out predictions.

    These diagnostics deliberately fail closed: a plot is skipped if models do
    not share the exact label order/support or if required probabilities are
    absent. Bootstrap intervals quantify held-out sample uncertainty for one
    fitted checkpoint; they are not multi-seed training intervals.
    """
    import csv
    import math
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    from pathlib import Path as _Path

    plots_dir = _Path(plots_dir)
    plots_dir.mkdir(parents=True, exist_ok=True)
    saved = []
    diagnostics = results.setdefault('multimodal_diagnostics', {})
    diagnostics['protocol'] = {
        'evaluation_scope': (
            'same held-out label-aligned proxy pairs; text and image are not '
            'sample-linked observations of the same leaf'
        ),
        'selection_use': 'reporting only; test diagnostics never select models',
        'bootstrap_scope': (
            'paired class-stratified held-out-sample uncertainty conditional '
            'on one fitted checkpoint; not training-seed uncertainty'
        ),
        'bootstrap_replicates': int(bootstrap_replicates),
    }

    def _skip(plot_number, reason):
        print(f"  [{plot_number}] Skipped measured diagnostic: {reason}")

    def _write_csv(filename, rows):
        rows = list(rows)
        if not rows:
            return None
        path = plots_dir / filename
        fieldnames = []
        for row in rows:
            for key in row:
                if key not in fieldnames:
                    fieldnames.append(key)
        with path.open('w', newline='', encoding='utf-8') as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(rows)
        return str(path)

    def _macro_f1(labels, predictions, class_ids):
        values = []
        for class_id in class_ids:
            true_positive = np.sum(
                (labels == class_id) & (predictions == class_id)
            )
            false_positive = np.sum(
                (labels != class_id) & (predictions == class_id)
            )
            false_negative = np.sum(
                (labels == class_id) & (predictions != class_id)
            )
            denominator = 2 * true_positive + false_positive + false_negative
            values.append(
                (2.0 * true_positive / denominator) if denominator else 0.0
            )
        return float(np.mean(values)) if values else 0.0

    def _exact_mcnemar_p(a_only, b_only):
        discordant = int(a_only + b_only)
        if discordant == 0:
            return 1.0
        k = int(min(a_only, b_only))
        logs = [
            math.lgamma(discordant + 1)
            - math.lgamma(index + 1)
            - math.lgamma(discordant - index + 1)
            - discordant * math.log(2.0)
            for index in range(k + 1)
        ]
        maximum = max(logs)
        tail = math.exp(maximum) * sum(
            math.exp(value - maximum) for value in logs
        )
        return float(min(1.0, 2.0 * tail))

    def _holm_adjust(rows, p_key='p_exact'):
        if not rows:
            return rows
        ranked = sorted(range(len(rows)), key=lambda idx: rows[idx][p_key])
        running = 0.0
        count = len(rows)
        for rank, row_index in enumerate(ranked):
            adjusted = min(1.0, (count - rank) * rows[row_index][p_key])
            running = max(running, adjusted)
            rows[row_index]['p_holm'] = float(running)
        return rows

    def _stratified_indices(labels, rng):
        pieces = []
        for class_id in sorted(np.unique(labels).tolist()):
            positions = np.flatnonzero(labels == class_id)
            if len(positions):
                pieces.append(rng.choice(positions, size=len(positions), replace=True))
        return np.concatenate(pieces) if pieces else np.array([], dtype=int)

    display_names = {
        'unimodal_image': 'Image only',
        'unimodal_text': 'Text only',
        'standard_vlm_fusion': 'Concat VLM',
        'proposed_multimodal_vlm': 'Proposed VLM',
    }
    default_order = list(display_names)
    common = results.get('fusion_common_test', {})
    four_way = common.get(
        'four_way_modality_comparison',
        results.get('four_way_modality_comparison', {}),
    )
    metadata = common.get(
        'four_way_metadata',
        results.get('four_way_modality_comparison_metadata', {}),
    )
    for condition_key in default_order:
        condition_row = four_way.get(condition_key, {})
        if isinstance(condition_row, dict) and condition_row.get('plot_label'):
            display_names[condition_key] = str(condition_row['plot_label'])
    order = [key for key in metadata.get('order', default_order) if key in four_way]
    if len(order) != 4 or set(order) != set(default_order):
        order = default_order

    paired_outputs = None
    try:
        if not all(key in four_way for key in default_order):
            raise ValueError('four common-test modality conditions are unavailable')
        paired_outputs = {}
        reference_labels = None
        n_classes = len(STRESS_LABELS)
        for key in order:
            row = four_way[key]
            labels = np.asarray(row.get('labels'), dtype=int).reshape(-1)
            predictions = np.asarray(row.get('predictions'), dtype=int).reshape(-1)
            probabilities = np.asarray(row.get('probabilities'), dtype=float)
            if not len(labels) or predictions.shape != labels.shape:
                raise ValueError(f'{key} has missing or malformed labels/predictions')
            if probabilities.shape != (len(labels), n_classes):
                raise ValueError(
                    f'{key} probability shape {probabilities.shape} is not '
                    f'({len(labels)}, {n_classes})'
                )
            if (not np.isfinite(probabilities).all()
                    or (probabilities < 0.0).any()
                    or not np.allclose(probabilities.sum(axis=1), 1.0, atol=1e-5)):
                raise ValueError(f'{key} probabilities are invalid')
            if not np.array_equal(probabilities.argmax(axis=1), predictions):
                raise ValueError(f'{key} predictions do not match probability argmax')
            if reference_labels is None:
                reference_labels = labels
            elif not np.array_equal(reference_labels, labels):
                raise ValueError(f'{key} label/order differs from the paired reference')
            paired_outputs[key] = {
                'labels': labels,
                'predictions': predictions,
                'probabilities': probabilities,
                'correct': predictions == labels,
            }
        paired_n = int(len(reference_labels))
        class_ids = list(range(n_classes))
        diagnostics['paired_support'] = {
            'n': paired_n,
            'identical_label_order_asserted': True,
            'class_counts': {
                STRESS_LABELS[class_id]: int(np.sum(reference_labels == class_id))
                for class_id in class_ids
            },
        }
    except Exception as paired_error:
        paired_outputs = None
        diagnostics['paired_diagnostics_skipped'] = str(paired_error)

    # Plot 58: paired sample-bootstrap macro-F1 intervals and proposed deltas.
    if paired_outputs is not None and paired_n >= 2:
        rng = np.random.default_rng(58001)
        bootstrap_values = {key: [] for key in order}
        for _ in range(int(bootstrap_replicates)):
            indices = _stratified_indices(reference_labels, rng)
            for key in order:
                bootstrap_values[key].append(_macro_f1(
                    reference_labels[indices],
                    paired_outputs[key]['predictions'][indices],
                    class_ids,
                ))
        bootstrap_values = {
            key: np.asarray(values, dtype=float)
            for key, values in bootstrap_values.items()
        }
        model_intervals = {}
        for key in order:
            estimate = _macro_f1(
                reference_labels, paired_outputs[key]['predictions'], class_ids
            )
            low, high = np.quantile(bootstrap_values[key], [0.025, 0.975])
            model_intervals[key] = {
                'estimate': float(estimate),
                'ci_low': float(low),
                'ci_high': float(high),
            }
        proposed_key = 'proposed_multimodal_vlm'
        delta_intervals = {}
        for baseline_key in order:
            if baseline_key == proposed_key:
                continue
            observed_delta = (
                model_intervals[proposed_key]['estimate']
                - model_intervals[baseline_key]['estimate']
            )
            bootstrap_delta = (
                bootstrap_values[proposed_key] - bootstrap_values[baseline_key]
            )
            low, high = np.quantile(bootstrap_delta, [0.025, 0.975])
            delta_intervals[baseline_key] = {
                'estimate': float(observed_delta),
                'ci_low': float(low),
                'ci_high': float(high),
                'bootstrap_fraction_above_zero': float(
                    np.mean(bootstrap_delta > 0.0)
                ),
            }
        diagnostics['paired_bootstrap'] = {
            'method': 'paired class-stratified percentile bootstrap',
            'confidence_level': 0.95,
            'replicates': int(bootstrap_replicates),
            'uncertainty_scope': diagnostics['protocol']['bootstrap_scope'],
            'models_macro_f1': model_intervals,
            'proposed_minus_baseline_macro_f1': delta_intervals,
        }
        bootstrap_csv_rows = []
        for key, interval in model_intervals.items():
            bootstrap_csv_rows.append({
                'comparison': key,
                'kind': 'model_macro_f1',
                **interval,
            })
        for key, interval in delta_intervals.items():
            bootstrap_csv_rows.append({
                'comparison': f'proposed_minus_{key}',
                'kind': 'paired_macro_f1_delta',
                **interval,
            })
        diagnostics['paired_bootstrap']['csv'] = _write_csv(
            'paired_bootstrap_comparison.csv', bootstrap_csv_rows
        )

        fig, axes = plt.subplots(1, 2, figsize=(14, 5.8))
        y = np.arange(len(order))
        estimates = np.array([model_intervals[key]['estimate'] for key in order])
        lows = np.array([model_intervals[key]['ci_low'] for key in order])
        highs = np.array([model_intervals[key]['ci_high'] for key in order])
        axes[0].errorbar(
            estimates, y, xerr=[
                np.maximum(0.0, estimates - lows),
                np.maximum(0.0, highs - estimates),
            ],
            fmt='o', color='#0072B2', ecolor='#56B4E9', capsize=5,
        )
        axes[0].set_yticks(y)
        axes[0].set_yticklabels([display_names[key] for key in order])
        axes[0].invert_yaxis()
        axes[0].set_xlim(0, 1.02)
        axes[0].set_xlabel('Macro-F1 (95% paired sample-bootstrap CI)')
        axes[0].grid(axis='x', alpha=0.25)
        delta_keys = [key for key in order if key != proposed_key]
        dy = np.arange(len(delta_keys))
        delta_est = np.array([delta_intervals[key]['estimate'] for key in delta_keys])
        delta_low = np.array([delta_intervals[key]['ci_low'] for key in delta_keys])
        delta_high = np.array([delta_intervals[key]['ci_high'] for key in delta_keys])
        axes[1].errorbar(
            delta_est, dy,
            xerr=[
                np.maximum(0.0, delta_est - delta_low),
                np.maximum(0.0, delta_high - delta_est),
            ],
            fmt='o', color='#009E73', ecolor='#E69F00', capsize=5,
        )
        axes[1].axvline(0.0, color='black', linewidth=1)
        axes[1].set_yticks(dy)
        axes[1].set_yticklabels([
            f"Proposed - {display_names[key]}" for key in delta_keys
        ])
        axes[1].invert_yaxis()
        axes[1].set_xlabel('Paired macro-F1 difference (95% CI)')
        axes[1].grid(axis='x', alpha=0.25)
        fig.suptitle(
            f'Plot 58: Paired Held-Out-Sample Uncertainty (N={paired_n})\n'
            'One fitted checkpoint; intervals are not multi-seed uncertainty',
            fontweight='bold',
        )
        plt.tight_layout(rect=(0, 0, 1, 0.90))
        path = plots_dir / 'plot58_paired_bootstrap_ci.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        print('  [58] Paired sample-bootstrap intervals saved')
    else:
        _skip(58, diagnostics.get('paired_diagnostics_skipped', 'N < 2'))

    # Plot 59: exact paired McNemar tests with Holm family-wise correction.
    if paired_outputs is not None:
        pair_rows = []
        for left_index, left_key in enumerate(order):
            for right_key in order[left_index + 1:]:
                left_correct = paired_outputs[left_key]['correct']
                right_correct = paired_outputs[right_key]['correct']
                left_only = int(np.sum(left_correct & ~right_correct))
                right_only = int(np.sum(~left_correct & right_correct))
                pair_rows.append({
                    'model_a': left_key,
                    'model_b': right_key,
                    'a_only_correct': left_only,
                    'b_only_correct': right_only,
                    'discordant': left_only + right_only,
                    'delta_accuracy_a_minus_b': float(
                        (left_only - right_only) / paired_n
                    ),
                    'p_exact': _exact_mcnemar_p(left_only, right_only),
                })
        _holm_adjust(pair_rows)
        diagnostics['mcnemar'] = {
            'method': 'two-sided exact McNemar with Holm correction',
            'tests': pair_rows,
            'csv': _write_csv('mcnemar_pairwise.csv', pair_rows),
        }
        delta_matrix = np.zeros((len(order), len(order)), dtype=float)
        p_matrix = np.ones((len(order), len(order)), dtype=float)
        lookup = {}
        for row in pair_rows:
            lookup[(row['model_a'], row['model_b'])] = row
        annotations = [['' for _ in order] for _ in order]
        for left_index, left_key in enumerate(order):
            for right_index, right_key in enumerate(order):
                if left_index == right_index:
                    annotations[left_index][right_index] = '0.0 pp\np=1.00'
                    continue
                if left_index < right_index:
                    row = lookup[(left_key, right_key)]
                    delta = row['delta_accuracy_a_minus_b']
                    p_value = row['p_holm']
                    discordant = (
                        f"{row['a_only_correct']}/{row['b_only_correct']}"
                    )
                else:
                    row = lookup[(right_key, left_key)]
                    delta = -row['delta_accuracy_a_minus_b']
                    p_value = row['p_holm']
                    discordant = (
                        f"{row['b_only_correct']}/{row['a_only_correct']}"
                    )
                delta_matrix[left_index, right_index] = delta
                p_matrix[left_index, right_index] = p_value
                annotations[left_index][right_index] = (
                    f'{delta * 100:+.1f} pp\n{discordant}\np={p_value:.3f}'
                )
        limit = max(0.05, float(np.abs(delta_matrix).max()))
        fig, ax = plt.subplots(figsize=(9.5, 8))
        image_handle = ax.imshow(
            delta_matrix, cmap='RdBu_r', vmin=-limit, vmax=limit
        )
        ax.set_xticks(np.arange(len(order)))
        ax.set_yticks(np.arange(len(order)))
        ax.set_xticklabels([display_names[key] for key in order], rotation=30,
                           ha='right')
        ax.set_yticklabels([display_names[key] for key in order])
        for row_index in range(len(order)):
            for column_index in range(len(order)):
                ax.text(column_index, row_index,
                        annotations[row_index][column_index],
                        ha='center', va='center', fontsize=8)
        fig.colorbar(image_handle, ax=ax, label='Row - column accuracy')
        ax.set_title(
            'Plot 59: Paired Accuracy Difference and Exact McNemar Test\n'
            'Cell: difference; row-only/column-only correct; Holm-adjusted p',
            fontweight='bold',
        )
        plt.tight_layout()
        path = plots_dir / 'plot59_mcnemar_matrix.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        print('  [59] Exact McNemar matrix saved')
    else:
        _skip(59, diagnostics.get('paired_diagnostics_skipped', 'paired data missing'))

    # Plot 60: unimodal complementarity, fusion rescue/harm, oracles, and gate.
    if paired_outputs is not None:
        text_correct = paired_outputs['unimodal_text']['correct']
        image_correct = paired_outputs['unimodal_image']['correct']
        overlap = {
            'both_correct': int(np.sum(text_correct & image_correct)),
            'text_only_correct': int(np.sum(text_correct & ~image_correct)),
            'image_only_correct': int(np.sum(~text_correct & image_correct)),
            'neither_correct': int(np.sum(~text_correct & ~image_correct)),
        }
        fusion_rows = {}
        for fusion_key in ('standard_vlm_fusion', 'proposed_multimodal_vlm'):
            fusion_correct = paired_outputs[fusion_key]['correct']
            fusion_rows[fusion_key] = {
                'rescues_when_both_unimodal_wrong': int(np.sum(
                    ~text_correct & ~image_correct & fusion_correct
                )),
                'harms_when_either_unimodal_correct': int(np.sum(
                    (text_correct | image_correct) & ~fusion_correct
                )),
                'preserves_either_unimodal_correct': int(np.sum(
                    (text_correct | image_correct) & fusion_correct
                )),
                'all_wrong': int(np.sum(
                    ~text_correct & ~image_correct & ~fusion_correct
                )),
            }
            fusion_rows[fusion_key]['net_rescue'] = (
                fusion_rows[fusion_key]['rescues_when_both_unimodal_wrong']
                - fusion_rows[fusion_key]['harms_when_either_unimodal_correct']
            )
        error_jaccard = {}
        for left_key in order:
            error_jaccard[left_key] = {}
            left_error = ~paired_outputs[left_key]['correct']
            for right_key in order:
                right_error = ~paired_outputs[right_key]['correct']
                union = int(np.sum(left_error | right_error))
                error_jaccard[left_key][right_key] = float(
                    np.sum(left_error & right_error) / union if union else 1.0
                )
        oracle = {
            'text_or_image': float(np.mean(text_correct | image_correct)),
            'all_three_baselines': float(np.mean(
                text_correct | image_correct
                | paired_outputs['standard_vlm_fusion']['correct']
            )),
        }
        proposed_row = four_way['proposed_multimodal_vlm']
        gate = np.asarray(
            proposed_row.get('effective_text_weight', []), dtype=float
        ).reshape(-1)
        gate_valid = len(gate) == paired_n and np.isfinite(gate).all()
        gate_summary = {
            'semantics': 'effective text weight; 1=text, 0=image',
            'interpretation': 'routing behaviour, not causal modality attribution',
            'available': bool(gate_valid),
            'validation_selected_mode': proposed_row.get(
                'validation_selected_fusion_mode', 'unknown'
            ),
            'effective_mode': proposed_row.get('effective_mode', 'unknown'),
        }
        if gate_valid:
            gate_summary.update({
                'mean': float(gate.mean()),
                'std': float(gate.std()),
                'is_constant': bool(np.std(gate) < 1e-8),
                'per_class': {
                    STRESS_LABELS[class_id]: {
                        'n': int(np.sum(reference_labels == class_id)),
                        'mean': float(gate[reference_labels == class_id].mean())
                        if np.any(reference_labels == class_id) else None,
                        'std': float(gate[reference_labels == class_id].std())
                        if np.any(reference_labels == class_id) else None,
                    }
                    for class_id in class_ids
                },
            })
        diagnostics['fusion_complementarity'] = {
            'proxy_pair_caveat': diagnostics['protocol']['evaluation_scope'],
            'unimodal_overlap': overlap,
            'fusion_rescue_harm': fusion_rows,
            'oracle_accuracy': oracle,
            'error_jaccard': error_jaccard,
            'gate': gate_summary,
        }
        sample_rows = []
        for sample_index in range(paired_n):
            sample_row = {
                'sample_index': sample_index,
                'true_label': int(reference_labels[sample_index]),
            }
            for key in order:
                sample_row[f'{key}_prediction'] = int(
                    paired_outputs[key]['predictions'][sample_index]
                )
                sample_row[f'{key}_confidence'] = float(
                    paired_outputs[key]['probabilities'][sample_index].max()
                )
                sample_row[f'{key}_correct'] = int(
                    paired_outputs[key]['correct'][sample_index]
                )
            if gate_valid:
                sample_row['proposed_effective_text_weight'] = float(
                    gate[sample_index]
                )
            sample_rows.append(sample_row)
        diagnostics['fusion_complementarity']['sample_csv'] = _write_csv(
            'fusion_complementarity.csv', sample_rows
        )

        fig, axes = plt.subplots(2, 2, figsize=(15, 10))
        overlap_names = ['Both correct', 'Text only', 'Image only', 'Neither']
        overlap_values = [
            overlap['both_correct'], overlap['text_only_correct'],
            overlap['image_only_correct'], overlap['neither_correct'],
        ]
        axes[0, 0].bar(overlap_names, overlap_values,
                       color=['#009E73', '#0072B2', '#D55E00', '#999999'])
        axes[0, 0].set_ylabel('Held-out samples')
        axes[0, 0].set_title('Unimodal correctness overlap')
        axes[0, 0].tick_params(axis='x', rotation=20)
        fusion_keys = ['standard_vlm_fusion', 'proposed_multimodal_vlm']
        x = np.arange(2)
        width = 0.25
        rescue_values = [fusion_rows[key][
            'rescues_when_both_unimodal_wrong'] for key in fusion_keys]
        harm_values = [-fusion_rows[key][
            'harms_when_either_unimodal_correct'] for key in fusion_keys]
        net_values = [fusion_rows[key]['net_rescue'] for key in fusion_keys]
        axes[0, 1].bar(x - width, rescue_values, width, label='Rescue',
                       color='#009E73')
        axes[0, 1].bar(x, harm_values, width, label='Harm (shown negative)',
                       color='#D55E00')
        axes[0, 1].bar(x + width, net_values, width, label='Net',
                       color='#0072B2')
        axes[0, 1].axhline(0.0, color='black', linewidth=1)
        axes[0, 1].set_xticks(x)
        axes[0, 1].set_xticklabels([
            display_names['standard_vlm_fusion'],
            display_names['proposed_multimodal_vlm'],
        ])
        axes[0, 1].set_ylabel('Sample count')
        axes[0, 1].set_title('Fusion rescue versus harm')
        axes[0, 1].legend(fontsize=8)
        accuracy_labels = [display_names[key] for key in order] + [
            'Text|image oracle', 'All-baseline oracle'
        ]
        accuracy_values = [
            float(np.mean(paired_outputs[key]['correct'])) for key in order
        ] + [oracle['text_or_image'], oracle['all_three_baselines']]
        axes[1, 0].barh(
            accuracy_labels[::-1], accuracy_values[::-1],
            color=['#999999', '#999999', '#009E73', '#CC79A7', '#0072B2', '#D55E00']
        )
        axes[1, 0].set_xlim(0, 1.02)
        axes[1, 0].set_xlabel('Accuracy')
        axes[1, 0].set_title('Observed models and correctness oracles')
        if gate_valid:
            proposed_correct = paired_outputs[
                'proposed_multimodal_vlm'
            ]['correct']
            for class_id in class_ids:
                indices = np.flatnonzero(reference_labels == class_id)
                offsets = (
                    np.linspace(-0.16, 0.16, len(indices))
                    if len(indices) > 1 else np.zeros(len(indices))
                )
                colors = [
                    '#009E73' if proposed_correct[index] else '#D55E00'
                    for index in indices
                ]
                axes[1, 1].scatter(
                    class_id + offsets, gate[indices], c=colors,
                    s=32, alpha=0.8, edgecolors='white', linewidths=0.4,
                )
                if len(indices):
                    axes[1, 1].plot(
                        [class_id - 0.22, class_id + 0.22],
                        [gate[indices].mean()] * 2,
                        color='black', linewidth=2,
                    )
            axes[1, 1].set_ylim(-0.03, 1.03)
            axes[1, 1].set_xticks(class_ids)
            axes[1, 1].set_xticklabels([
                TEA_DISEASE_DISPLAY.get(label, label).replace(' ', '\n')
                for label in STRESS_LABELS
            ], fontsize=8)
            axes[1, 1].set_ylabel('Effective text weight (1=text, 0=image)')
            gate_mode = proposed_row.get(
                'validation_selected_fusion_mode', 'unknown'
            )
            constant_note = ' (constant validation-selected weight)' \
                if gate_summary.get('is_constant') else ''
            axes[1, 1].set_title(
                f'Selected-condition routing weight: {gate_mode}{constant_note}'
            )
        else:
            axes[1, 1].axis('off')
            axes[1, 1].text(
                0.5, 0.5, 'Effective fusion gate was not retained',
                ha='center', va='center'
            )
        fig.suptitle(
            'Plot 60: Fusion/Selected-Model Complementarity on Proxy Pairs\n'
            'Rescue/harm is not evidence of naturally paired sensor complementarity',
            fontweight='bold',
        )
        plt.tight_layout(rect=(0, 0, 1, 0.93))
        path = plots_dir / 'plot60_fusion_complementarity_gate.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        print('  [60] Fusion complementarity and routing gate saved')
    else:
        _skip(60, diagnostics.get('paired_diagnostics_skipped', 'paired data missing'))

    # Plot 61: reliability, risk-coverage, ECE/Brier/NLL/AURC.
    if paired_outputs is not None:
        calibration = {}
        bin_count = min(10, max(2, int(math.sqrt(paired_n))))
        bin_edges = np.linspace(0.0, 1.0, bin_count + 1)
        for key in order:
            probabilities = paired_outputs[key]['probabilities']
            predictions = paired_outputs[key]['predictions']
            confidence = probabilities.max(axis=1)
            correct = (predictions == reference_labels).astype(float)
            bin_rows = []
            ece = 0.0
            for bin_index in range(bin_count):
                lower, upper = bin_edges[bin_index], bin_edges[bin_index + 1]
                in_bin = ((confidence >= lower) & (confidence < upper))
                if bin_index == bin_count - 1:
                    in_bin = ((confidence >= lower) & (confidence <= upper))
                count = int(np.sum(in_bin))
                if not count:
                    continue
                mean_confidence = float(confidence[in_bin].mean())
                empirical_accuracy = float(correct[in_bin].mean())
                ece += count / paired_n * abs(
                    empirical_accuracy - mean_confidence
                )
                bin_rows.append({
                    'lower': float(lower), 'upper': float(upper),
                    'n': count, 'mean_confidence': mean_confidence,
                    'accuracy': empirical_accuracy,
                })
            one_hot = np.eye(n_classes)[reference_labels]
            brier = float(np.mean(np.sum((probabilities - one_hot) ** 2, axis=1)))
            nll = float(-np.mean(np.log(np.clip(
                probabilities[np.arange(paired_n), reference_labels],
                1e-12, 1.0,
            ))))
            sorted_indices = np.argsort(-confidence, kind='mergesort')
            sorted_confidence = confidence[sorted_indices]
            sorted_correct = correct[sorted_indices]
            risk_coverage = []
            cumulative_correct = 0.0
            previous_coverage = 0.0
            aurc = 0.0
            cursor = 0
            while cursor < paired_n:
                end = cursor + 1
                while (end < paired_n
                       and sorted_confidence[end] == sorted_confidence[cursor]):
                    end += 1
                cumulative_correct += float(sorted_correct[cursor:end].sum())
                coverage = end / paired_n
                risk = 1.0 - cumulative_correct / end
                aurc += (coverage - previous_coverage) * risk
                risk_coverage.append({
                    'coverage': float(coverage), 'risk': float(risk),
                    'threshold': float(sorted_confidence[cursor]),
                })
                previous_coverage = coverage
                cursor = end
            calibration[key] = {
                'ece': float(ece),
                'multiclass_brier': brier,
                'nll': nll,
                'grouped_aurc': float(aurc),
                'reliability_bins': bin_rows,
                'risk_coverage': risk_coverage,
            }
        diagnostics['calibration'] = {
            'binning': f'{bin_count} identical equal-width confidence bins',
            'brier_definition': (
                'mean sum_k (p_k-y_k)^2; unnormalized multiclass range [0,2]'
            ),
            'temperature_scaling_on_test': False,
            'models': calibration,
            'csv': _write_csv('calibration_metrics.csv', [
                {
                    'model': key,
                    'ece': calibration[key]['ece'],
                    'multiclass_brier': calibration[key]['multiclass_brier'],
                    'nll': calibration[key]['nll'],
                    'grouped_aurc': calibration[key]['grouped_aurc'],
                }
                for key in order
            ]),
        }
        fig, axes = plt.subplots(1, 3, figsize=(18, 5.8))
        palette = ['#D55E00', '#0072B2', '#CC79A7', '#009E73']
        axes[0].plot([0, 1], [0, 1], '--', color='black', linewidth=1,
                     label='Perfect calibration')
        for key, color in zip(order, palette):
            bins = calibration[key]['reliability_bins']
            axes[0].plot(
                [row['mean_confidence'] for row in bins],
                [row['accuracy'] for row in bins],
                marker='o', linewidth=2, color=color,
                label=f"{display_names[key]} (ECE={calibration[key]['ece']:.3f})",
            )
        axes[0].set_xlim(0, 1)
        axes[0].set_ylim(0, 1)
        axes[0].set_xlabel('Mean confidence')
        axes[0].set_ylabel('Empirical accuracy')
        axes[0].set_title('Reliability diagram')
        axes[0].legend(fontsize=7)
        axes[0].grid(alpha=0.2)
        for key, color in zip(order, palette):
            points = calibration[key]['risk_coverage']
            axes[1].plot(
                [0.0] + [row['coverage'] for row in points],
                [0.0] + [row['risk'] for row in points],
                linewidth=2, color=color,
                label=f"{display_names[key]} (AURC={calibration[key]['grouped_aurc']:.3f})",
            )
        axes[1].set_xlim(0, 1)
        axes[1].set_ylim(bottom=0)
        axes[1].set_xlabel('Coverage')
        axes[1].set_ylabel('Selective risk (error rate)')
        axes[1].set_title('Risk-coverage (lower is better)')
        axes[1].legend(fontsize=7)
        axes[1].grid(alpha=0.2)
        x = np.arange(len(order))
        width = 0.23
        for offset, metric_key, label, color in (
            (-width, 'ece', 'ECE', '#56B4E9'),
            (0.0, 'multiclass_brier', 'Brier', '#E69F00'),
            (width, 'grouped_aurc', 'AURC', '#009E73'),
        ):
            axes[2].bar(
                x + offset,
                [calibration[key][metric_key] for key in order],
                width, label=label, color=color,
            )
        axes[2].set_xticks(x)
        axes[2].set_xticklabels(
            [display_names[key] for key in order], rotation=25, ha='right'
        )
        axes[2].set_ylabel('Calibration/selective metric')
        axes[2].set_title('ECE, multiclass Brier, and grouped AURC')
        axes[2].legend(fontsize=8)
        for index, key in enumerate(order):
            axes[2].text(
                index, max(
                    calibration[key]['ece'],
                    calibration[key]['multiclass_brier'],
                    calibration[key]['grouped_aurc'],
                ) + 0.02,
                f"NLL={calibration[key]['nll']:.2f}",
                ha='center', fontsize=7, rotation=90,
            )
        fig.suptitle(
            f'Plot 61: Confidence Quality and Selective Prediction (N={paired_n})',
            fontweight='bold',
        )
        plt.tight_layout(rect=(0, 0, 1, 0.94))
        path = plots_dir / 'plot61_calibration_risk_coverage.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        print('  [61] Calibration and risk-coverage diagnostics saved')
    else:
        _skip(61, diagnostics.get('paired_diagnostics_skipped', 'paired data missing'))

    # Plot 62: corruption robustness for the two multimodal models.
    robustness = results.get('modality_robustness', {})
    robustness_models = robustness.get('models', {})
    valid_robustness = {}
    for key, value in robustness_models.items():
        if (not isinstance(value, dict)
                or not value.get('text_token_deletion')
                or not value.get('image_gaussian_noise')):
            continue
        clean_reference = value.get('clean_reference', {})
        clean_labels = np.asarray(
            clean_reference.get('labels', []), dtype=int
        ).reshape(-1)
        clean_predictions = np.asarray(
            clean_reference.get('predictions', []), dtype=int
        ).reshape(-1)
        if paired_outputs is not None and key in paired_outputs:
            if (not np.array_equal(clean_labels, reference_labels)
                    or not np.array_equal(
                        clean_predictions,
                        paired_outputs[key]['predictions'],
                    )):
                diagnostics.setdefault('corruption_robustness_skipped_models', {})[
                    key
                ] = 'severity-zero predictions do not reproduce common clean baseline'
                continue
        elif not len(clean_labels) or len(clean_predictions) != len(clean_labels):
            diagnostics.setdefault('corruption_robustness_skipped_models', {})[
                key
            ] = 'clean-reference arrays are absent or malformed'
            continue
        valid_robustness[key] = value
    if valid_robustness:
        fig, axes = plt.subplots(1, 2, figsize=(13, 5.5), sharey=True)
        robustness_colors = {
            'standard_vlm_fusion': '#CC79A7',
            'proposed_multimodal_vlm': '#009E73',
        }
        robustness_names = {
            'standard_vlm_fusion': 'Concat VLM',
            'proposed_multimodal_vlm': display_names[
                'proposed_multimodal_vlm'
            ],
        }
        robustness_csv_rows = []
        for key, value in valid_robustness.items():
            color = robustness_colors.get(key, '#0072B2')
            for axis, curve_key, curve_label in (
                (axes[0], 'text_token_deletion', 'Text token deletion'),
                (axes[1], 'image_gaussian_noise', 'Image Gaussian noise'),
            ):
                curve = value[curve_key]
                axis.plot(
                    [row['severity'] for row in curve],
                    [row['f1_macro'] for row in curve],
                    marker='o', linewidth=2.2, color=color,
                    label=robustness_names.get(key, key),
                )
                for row in curve:
                    robustness_csv_rows.append({
                        'model': key, 'corruption': curve_key, **row,
                    })
                axis.set_xlabel('Corruption severity')
                axis.set_title(curve_label)
                axis.grid(alpha=0.25)
            true_missing = value.get('true_missing_modality', {})
            if true_missing:
                if 'text_missing_image_only' in true_missing:
                    axes[0].scatter(
                        [1.04], [true_missing['text_missing_image_only']['f1_macro']],
                        marker='X', s=80, color=color,
                    )
                if 'image_missing_text_only' in true_missing:
                    axes[1].scatter(
                        [1.04], [true_missing['image_missing_text_only']['f1_macro']],
                        marker='X', s=80, color=color,
                    )
        axes[0].set_ylabel('Macro-F1 on common held-out support')
        axes[0].set_xlim(-0.02, 1.10)
        axes[1].set_xlim(-0.02, 1.10)
        axes[0].set_ylim(0, 1.02)
        axes[0].legend(fontsize=8)
        axes[1].legend(fontsize=8)
        fig.suptitle(
            'Plot 62: Missing/Corrupted-Modality Robustness\n'
            'X at 1.04 = true missing-modality inference (proposed model only)',
            fontweight='bold',
        )
        plt.tight_layout(rect=(0, 0, 1, 0.91))
        path = plots_dir / 'plot62_modality_robustness.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        diagnostics['corruption_robustness'] = {
            'source_key': 'modality_robustness',
            'csv': _write_csv('corruption_robustness.csv', robustness_csv_rows),
            'uncertainty_scope': (
                'one deterministic corruption realization; no confidence band'
            ),
        }
        print('  [62] Missing/corrupted-modality robustness saved')
    else:
        _skip(62, 'no measured robustness curves')

    # Plot 63: class-specific proposed-model gain over each fair baseline.
    if paired_outputs is not None:
        proposed_per_class = np.asarray(
            four_way['proposed_multimodal_vlm'].get('per_class_f1', []),
            dtype=float,
        )
        baseline_keys = [
            'unimodal_image', 'unimodal_text', 'standard_vlm_fusion'
        ]
        baseline_per_class = [
            np.asarray(four_way[key].get('per_class_f1', []), dtype=float)
            for key in baseline_keys
        ]
        if (len(proposed_per_class) == n_classes
                and all(len(values) == n_classes for values in baseline_per_class)):
            gain_matrix = np.vstack([
                proposed_per_class - values for values in baseline_per_class
            ])
            diagnostics['per_class_modality_gain'] = {
                f'proposed_minus_{key}': {
                    STRESS_LABELS[class_id]: float(gain_matrix[row_index, class_id])
                    for class_id in class_ids
                }
                for row_index, key in enumerate(baseline_keys)
            }
            limit = max(0.05, float(np.abs(gain_matrix).max()))
            fig, ax = plt.subplots(figsize=(11, 5.5))
            image_handle = ax.imshow(
                gain_matrix, cmap='RdBu_r', vmin=-limit, vmax=limit,
                aspect='auto',
            )
            ax.set_yticks(np.arange(len(baseline_keys)))
            ax.set_yticklabels([
                f"Proposed - {display_names[key]}" for key in baseline_keys
            ])
            ax.set_xticks(np.arange(n_classes))
            ax.set_xticklabels([
                TEA_DISEASE_DISPLAY.get(label, label).replace(' ', '\n')
                for label in STRESS_LABELS
            ])
            for row_index in range(gain_matrix.shape[0]):
                for class_id in class_ids:
                    ax.text(
                        class_id, row_index,
                        f'{gain_matrix[row_index, class_id]:+.3f}',
                        ha='center', va='center', fontsize=9,
                    )
            fig.colorbar(image_handle, ax=ax, label='Absolute per-class F1 gain')
            ax.set_title(
                'Plot 63: Where the Validation-Selected Proposed Condition Gains or Loses',
                fontweight='bold',
            )
            plt.tight_layout()
            path = plots_dir / 'plot63_per_class_modality_gain.png'
            plt.savefig(path, dpi=300)
            plt.close()
            saved.append(path)
            print('  [63] Per-class modality gain saved')
        else:
            _skip(63, 'per-class F1 arrays are incomplete')
    else:
        _skip(63, diagnostics.get('paired_diagnostics_skipped', 'paired data missing'))

    # Plot 64: paired FedAvg-minus-centralized effect for all four conditions.
    fed_comparison = results.get('four_way_federated_comparison', {})
    fed_conditions = fed_comparison.get('conditions', {})
    expected_fed_condition_order = [
        'unimodal_image',
        'unimodal_text',
        'standard_vlm_fusion',
        'flexible_multimodal_vlm_matched_scratch',
    ]
    fed_rows = []
    try:
        if (not isinstance(fed_conditions, dict)
                or set(fed_conditions) != set(expected_fed_condition_order)):
            raise ValueError(
                'four-way centralized/FedAvg comparison requires exactly the '
                'image, text, concat, and flexible-VLM conditions'
            )
        rng = np.random.default_rng(64001)
        for condition_key in expected_fed_condition_order:
            condition = fed_conditions[condition_key]
            centralized = condition['centralized']
            federated = condition['federated']
            labels = np.asarray(centralized.get('labels'), dtype=int).reshape(-1)
            fed_labels = np.asarray(federated.get('labels'), dtype=int).reshape(-1)
            central_predictions = np.asarray(
                centralized.get('predictions'), dtype=int
            ).reshape(-1)
            fed_predictions = np.asarray(
                federated.get('predictions'), dtype=int
            ).reshape(-1)
            if (not len(labels) or not np.array_equal(labels, fed_labels)
                    or len(central_predictions) != len(labels)
                    or len(fed_predictions) != len(labels)):
                raise ValueError(f'{condition_key} lacks aligned paired outputs')
            class_ids_fed = list(range(len(STRESS_LABELS)))
            observed = (
                _macro_f1(labels, fed_predictions, class_ids_fed)
                - _macro_f1(labels, central_predictions, class_ids_fed)
            )
            bootstrap_delta = []
            for _ in range(int(bootstrap_replicates)):
                indices = _stratified_indices(labels, rng)
                bootstrap_delta.append(
                    _macro_f1(
                        labels[indices], fed_predictions[indices], class_ids_fed
                    )
                    - _macro_f1(
                        labels[indices], central_predictions[indices],
                        class_ids_fed,
                    )
                )
            low, high = np.quantile(bootstrap_delta, [0.025, 0.975])
            central_correct = central_predictions == labels
            fed_correct = fed_predictions == labels
            central_only = int(np.sum(central_correct & ~fed_correct))
            fed_only = int(np.sum(~central_correct & fed_correct))
            fed_rows.append({
                'condition': condition_key,
                'display_name': condition.get('display_name', condition_key),
                'n': int(len(labels)),
                'fed_minus_central_macro_f1': float(observed),
                'ci_low': float(low),
                'ci_high': float(high),
                'central_only_correct': central_only,
                'fed_only_correct': fed_only,
                'p_exact': _exact_mcnemar_p(central_only, fed_only),
            })
        _holm_adjust(fed_rows)
        diagnostics['federated_paired_effect'] = {
            'method': (
                'paired class-stratified sample bootstrap for macro-F1; exact '
                'McNemar with Holm correction for correctness'
            ),
            'uncertainty_scope': diagnostics['protocol']['bootstrap_scope'],
            'conditions': fed_rows,
            'csv': _write_csv('federated_paired_effect.csv', fed_rows),
        }
        y = np.arange(len(fed_rows))
        estimates = np.array([
            row['fed_minus_central_macro_f1'] for row in fed_rows
        ])
        lows = np.array([row['ci_low'] for row in fed_rows])
        highs = np.array([row['ci_high'] for row in fed_rows])
        fig, ax = plt.subplots(figsize=(11, 6))
        ax.errorbar(
            estimates, y, xerr=[
                np.maximum(0.0, estimates - lows),
                np.maximum(0.0, highs - estimates),
            ],
            fmt='o', color='#E69F00', ecolor='#0072B2', capsize=5,
        )
        ax.axvline(0.0, color='black', linewidth=1)
        ax.set_yticks(y)
        ax.set_yticklabels([row['display_name'] for row in fed_rows])
        ax.invert_yaxis()
        ax.set_xlabel('FedAvg - centralized macro-F1 (95% paired sample-bootstrap CI)')
        ax.set_title(
            'Plot 64: Paired Federated Effect on Common Held-Out Support\n'
            'Annotations: Holm-adjusted exact McNemar p',
            fontweight='bold',
        )
        for index, row in enumerate(fed_rows):
            ax.text(
                highs[index] + 0.01, index,
                f"p={row['p_holm']:.3f}", va='center', fontsize=8,
            )
        ax.grid(axis='x', alpha=0.25)
        plt.tight_layout()
        path = plots_dir / 'plot64_federated_paired_effect.png'
        plt.savefig(path, dpi=300)
        plt.close()
        saved.append(path)
        print('  [64] Paired federated effect saved')
    except Exception as fed_diagnostic_error:
        diagnostics['federated_paired_effect_skipped'] = str(fed_diagnostic_error)
        _skip(64, str(fed_diagnostic_error))

    diagnostics['plot_files'] = [str(path) for path in saved]
    return saved


def generate_all_plots(results: Dict, config: Config):
    """Generate the measured comparison, diagnostic, and literature plots."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import seaborn as sns
    import numpy as np
    import ast
    import re

    def safe_array_convert(data, key):
        """Safely convert string representation of array back to numpy array.

        When results are saved to JSON with default=str, numpy arrays become strings.
        This function converts them back to arrays for plotting.
        """
        value = data.get(key)
        if value is None:
            return None

        # Already a numpy array
        if isinstance(value, np.ndarray):
            return value

        # Already a list
        if isinstance(value, list):
            return np.array(value)

        # String representation - need to parse
        if isinstance(value, str):
            try:
                # Remove extra whitespace
                clean = value.strip()

                # Handle numpy array string format like "[1 2 3]" or "[[1 2][3 4]]"
                # Replace multiple spaces with commas for proper list format
                clean = re.sub(r'\s+', ',', clean)
                # Fix edge cases like "[," or ",]"
                clean = clean.replace('[,', '[').replace(',]', ']')
                # Fix consecutive commas
                clean = re.sub(r',+', ',', clean)

                # Try to parse
                parsed = ast.literal_eval(clean)
                return np.array(parsed)
            except Exception as e:
                # If parsing fails, return None
                print(f"    Warning: Could not convert {key} to array: {e}")
                return None

        # Try direct conversion as fallback
        try:
            return np.array(value)
        except:
            return None

    try:
        plt.style.use('seaborn-v0_8-whitegrid')
    except:
        plt.style.use('ggplot')

    plt.rcParams.update({'font.size': 10, 'axes.labelsize': 11, 'axes.titlesize': 12, 'figure.dpi': 150, 'savefig.dpi': 300})

    plots_dir = config.plots_dir
    plots_dir.mkdir(parents=True, exist_ok=True)

    print("\n" + "=" * 70)
    print("GENERATING 25+ COMPARISON PLOTS")
    print("=" * 70)

    llm_results = results.get('llm_models', {})
    vit_results = results.get('vit_models', {})
    vlm_results = results.get('vlm_models', {})
    fed_results = results.get('federated', {})
    cent_results = results.get('centralized', {})

    # Plot 1: LLM Model Comparison
    if llm_results:
        plt.figure(figsize=(12, 6))
        names = list(llm_results.keys())
        macro_scores = [
            llm_results[n].get('f1_macro', llm_results[n].get('f1', 0.0))
            for n in names
        ]
        accuracy_scores = [llm_results[n].get('f1', 0.0) for n in names]
        x = np.arange(len(names))
        width = 0.38
        plt.bar(x - width / 2, macro_scores, width, label='Group macro F1',
                color='#2b6cb0', edgecolor='black')
        plt.bar(x + width / 2, accuracy_scores, width,
                label='Group accuracy (= micro F1)', color='#90cdf4',
                edgecolor='black')
        plt.xlabel('LLM Model')
        plt.ylabel('Held-out score')
        plt.title('Plot 1: LLM Comparison (Macro F1 Primary)')
        plt.xticks(x, names, rotation=45, ha='right')
        plt.legend()
        plt.ylim(0, 1)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot01_llm_comparison.png')
        plt.close()
        print("  [01/25] LLM comparison saved")

    # Plot 2: ViT Model Comparison
    if vit_results:
        plt.figure(figsize=(12, 6))
        names = list(vit_results.keys())
        macro_scores = [
            vit_results[n].get('f1_macro', vit_results[n].get('f1', 0.0))
            for n in names
        ]
        accuracy_scores = [vit_results[n].get('f1', 0.0) for n in names]
        x = np.arange(len(names))
        width = 0.38
        plt.bar(x - width / 2, macro_scores, width, label='Macro F1',
                color='#c05621', edgecolor='black')
        plt.bar(x + width / 2, accuracy_scores, width,
                label='Accuracy (= micro F1)', color='#fbd38d',
                edgecolor='black')
        plt.xlabel('ViT Model')
        plt.ylabel('Held-out score')
        plt.title('Plot 2: Vision Model Comparison (Macro F1 Primary)')
        plt.xticks(x, names, rotation=45, ha='right')
        plt.legend()
        plt.ylim(0, 1)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot02_vit_comparison.png')
        plt.close()
        print("  [02/25] ViT comparison saved")

    # Plot 3: VLM Fusion Architecture Comparison
    if vlm_results:
        plt.figure(figsize=(14, 6))
        names = list(vlm_results.keys())
        display_names = [
            vlm_results[n].get('display_name', n) for n in names
        ]
        macro_scores = [
            vlm_results[n].get('f1_macro', vlm_results[n].get('f1', 0.0))
            for n in names
        ]
        accuracy_scores = [vlm_results[n].get('f1', 0.0) for n in names]
        x = np.arange(len(names))
        width = 0.38
        plt.bar(x - width / 2, macro_scores, width, label='Macro F1',
                color='#2f855a', edgecolor='black')
        plt.bar(x + width / 2, accuracy_scores, width,
                label='Accuracy (= micro F1)', color='#9ae6b4',
                edgecolor='black')
        plt.xlabel('VLM Fusion Architecture')
        plt.ylabel('Held-out score')
        plt.title('Plot 3: VLM Fusion Comparison (Macro F1 Primary)')
        plt.xticks(x, display_names, rotation=45, ha='right')
        plt.legend()
        plt.ylim(0, 1)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot03_vlm_fusion_comparison.png')
        plt.close()
        print("  [03/25] VLM fusion comparison saved")

    # Plot 4: Model Type Overview
    plt.figure(figsize=(10, 6))
    model_types = ['LLM (Best)', 'ViT (Best)', 'VLM (Best)']
    best_scores = [
        max([v.get('f1_macro', v.get('f1', 0.0)) for v in llm_results.values()]) if llm_results else 0,
        max([v.get('f1_macro', v.get('f1', 0.0)) for v in vit_results.values()]) if vit_results else 0,
        max([v.get('f1_macro', v.get('f1', 0.0)) for v in vlm_results.values()]) if vlm_results else 0,
    ]
    colors = ['#3498db', '#e74c3c', '#2ecc71']
    plt.bar(model_types, best_scores, color=colors, edgecolor='black', width=0.6)
    plt.ylabel('Best macro F1 within family')
    plt.title('Plot 4: Family Bests (Descriptive; Held-out Supports Differ)')
    plt.ylim(0, 1)
    plt.tight_layout()
    plt.savefig(plots_dir / 'plot04_model_type_overview.png')
    plt.close()
    print("  [04/25] Model type overview saved")

    # Plot 5: Federated vs Centralized
    if fed_results and cent_results:
        plt.figure(figsize=(12, 6))
        model_types = [
            model_type for model_type in MODEL_TYPE_ORDER
            if model_type in fed_results and model_type in cent_results
        ]
        x = np.arange(len(model_types))
        width = 0.35
        fed_f1 = [fed_results[m]['f1'] for m in model_types]
        cent_f1 = [cent_results[m]['f1'] for m in model_types]
        central_bars = plt.bar(
            x - width/2, cent_f1, width, label='Centralized control',
            color='#56B4E9', edgecolor='black'
        )
        federated_bars = plt.bar(
            x + width/2, fed_f1, width, label='Federated (FedAvg)',
            color='#E69F00', edgecolor='black'
        )
        for bars in (central_bars, federated_bars):
            for bar in bars:
                plt.text(
                    bar.get_x() + bar.get_width()/2,
                    min(1.025, bar.get_height() + 0.015),
                    f"{bar.get_height():.3f}",
                    ha='center', va='bottom', fontsize=8,
                )
        plt.xlabel('Fixed model condition')
        plt.ylabel('Common held-out micro-F1 (= accuracy)')
        plt.title('Plot 5: Matched Centralized Control vs Federated FedAvg')
        plt.xticks(
            x,
            [FEDERATED_CONDITION_DISPLAY.get(model_type, model_type)
             for model_type in model_types],
            rotation=15,
            ha='right',
        )
        plt.legend()
        plt.ylim(0, 1.06)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot05_fed_vs_centralized.png')
        if len(model_types) == 4:
            four_way_micro_plot = (
                plots_dir / 'plot05_four_way_fed_vs_centralized.png'
            )
            plt.savefig(four_way_micro_plot)
            results.setdefault('four_way_federated_plots', {})[
                'micro_f1'
            ] = str(four_way_micro_plot)
        plt.close()
        print("  [05/25] Fed vs Centralized saved")

        # Plot 57: three non-duplicate metric panels for the exact same eight
        # evaluations (four architectures x centralized/FedAvg) on one common
        # test support. Micro-F1 is intentionally omitted here because it is
        # mathematically identical to accuracy for single-label multiclass data.
        if len(model_types) == 4:
            metric_specs = [
                ('accuracy', 'Accuracy'),
                ('f1_macro', 'Macro-F1'),
                ('f1_weighted', 'Weighted-F1'),
            ]
            fig, axes = plt.subplots(1, 3, figsize=(18, 6), sharey=True)
            labels = [
                FEDERATED_CONDITION_DISPLAY.get(model_type, model_type)
                for model_type in model_types
            ]
            for ax, (metric_key, metric_label) in zip(axes, metric_specs):
                central_values = [
                    float(cent_results[m].get(metric_key, cent_results[m]['f1']))
                    for m in model_types
                ]
                fed_values = [
                    float(fed_results[m].get(metric_key, fed_results[m]['f1']))
                    for m in model_types
                ]
                cbars = ax.bar(
                    x - width/2, central_values, width,
                    color='#56B4E9', edgecolor='black',
                    label='Centralized control'
                )
                fbars = ax.bar(
                    x + width/2, fed_values, width,
                    color='#E69F00', edgecolor='black',
                    label='Federated (FedAvg)'
                )
                for bars in (cbars, fbars):
                    for bar in bars:
                        ax.text(
                            bar.get_x() + bar.get_width()/2,
                            min(1.025, bar.get_height() + 0.012),
                            f"{bar.get_height():.2f}",
                            ha='center', va='bottom', fontsize=7,
                        )
                ax.set_title(metric_label)
                ax.set_xticks(x)
                ax.set_xticklabels(labels, rotation=25, ha='right', fontsize=8)
                ax.set_ylim(0, 1.06)
                ax.grid(axis='y', alpha=0.25)
            axes[0].set_ylabel('Common held-out score')
            handles, legend_labels = axes[0].get_legend_handles_labels()
            fig.legend(handles, legend_labels, loc='upper center', ncol=2)
            common_n = results.get('four_way_federated_comparison', {}).get('n')
            accuracy_step = (1.0 / common_n) if common_n else None
            fig.suptitle(
                'Plot 57: Four-Way Centralized vs Federated Comparison'
                + (
                    f' (common N={common_n}; accuracy resolution='
                    f'{accuracy_step:.4f})'
                    if common_n else ''
                ),
                fontweight='bold',
                y=0.99,
            )
            plt.tight_layout(rect=(0, 0, 1, 0.92))
            four_way_metrics_plot = (
                plots_dir / 'plot57_four_way_fed_vs_centralized.png'
            )
            plt.savefig(four_way_metrics_plot, dpi=300)
            results.setdefault('four_way_federated_plots', {})[
                'accuracy_macro_weighted_f1'
            ] = str(four_way_metrics_plot)
            plt.close()
            print("  [57] Four-way centralized vs federated metrics saved")

    # Plot 6-10: Training curves and metrics
    if vlm_results:
        # Plot 6: Training Loss Curves
        plt.figure(figsize=(12, 6))
        for name, data in vlm_results.items():
            if 'history' in data and 'train_loss' in data['history']:
                plt.plot(data['history']['train_loss'], label=name, linewidth=2)
        plt.xlabel('Epoch')
        plt.ylabel('Training Loss')
        plt.title('Plot 6: VLM Training Loss Curves')
        plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot06_training_loss.png')
        plt.close()
        print("  [06/25] Training loss curves saved")

        # Plot 7: Validation macro-F1 curves
        plt.figure(figsize=(12, 6))
        for name, data in vlm_results.items():
            if 'history' in data and 'val_f1' in data['history']:
                validation_history = data['history'].get(
                    'val_f1_macro', data['history']['val_f1']
                )
                plt.plot(validation_history, label=name, linewidth=2, marker='o')
        plt.xlabel('Epoch')
        plt.ylabel('Validation macro F1')
        plt.title('Plot 7: VLM Validation Macro-F1 Curves')
        plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot07_val_f1_curves.png')
        plt.close()
        print("  [07/25] Validation F1 curves saved")

    # Plot 8-10: Parameter count, Precision/Recall
    all_models = {}
    all_models.update({f"LLM-{k}": v for k, v in llm_results.items()})
    all_models.update({f"ViT-{k}": v for k, v in vit_results.items()})
    all_models.update({f"VLM-{k}": v for k, v in vlm_results.items()})

    parameter_models = {
        name: row for name, row in all_models.items()
        if isinstance(row, dict)
        and isinstance(row.get('params'), (int, float, np.number))
        and float(row['params']) > 0
    }
    if parameter_models:
        plt.figure(figsize=(16, 6))
        names = list(parameter_models.keys())
        params = [float(parameter_models[n]['params']) / 1e6 for n in names]
        colors = ['#3498db' if 'LLM' in n else '#e74c3c' if 'ViT' in n else '#2ecc71' for n in names]
        plt.bar(names, params, color=colors, edgecolor='black')
        plt.xlabel('Model')
        plt.ylabel('Parameters (Millions)')
        plt.title('Plot 8: Model Parameter Count')
        plt.xticks(rotation=45, ha='right', fontsize=8)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot08_params.png')
        plt.close()
        print("  [08/25] Parameter count saved")

    # Plot 9: Precision-Recall Curves (proper sklearn curves)
    if vlm_results:
        from sklearn.metrics import precision_recall_curve, average_precision_score
        from sklearn.preprocessing import label_binarize

        plt.figure(figsize=(12, 8))

        # Check if we have probability data for proper PR curves
        has_pr_data = any('probabilities' in vlm_results.get(n, {}) for n in vlm_results.keys())

        if has_pr_data:
            # Plot actual precision-recall curves for models with probability data
            colors = plt.cm.tab10(np.linspace(0, 1, len(vlm_results)))
            for idx, (name, data) in enumerate(vlm_results.items()):
                if 'probabilities' in data and 'labels' in data:
                    # Convert string representations back to arrays
                    y_true = safe_array_convert(data, 'labels')
                    y_probs = safe_array_convert(data, 'probabilities')

                    # Skip if conversion failed
                    if y_true is None or y_probs is None:
                        print(f"    Warning: Skipping {name} - could not convert arrays")
                        continue

                    # Binarize labels for multi-class PR curves
                    n_classes = y_probs.shape[1] if len(y_probs.shape) > 1 else 5
                    y_true_bin = label_binarize(y_true, classes=list(range(n_classes)))

                    # Compute micro-average PR curve
                    precision_avg, recall_avg, _ = precision_recall_curve(
                        y_true_bin.ravel(), y_probs.ravel()
                    )
                    ap = average_precision_score(y_true_bin, y_probs, average='micro')

                    plt.plot(recall_avg, precision_avg, color=colors[idx],
                            linewidth=2, label=f'{name} (AP={ap:.3f})')
            plt.xlabel('Recall')
            plt.ylabel('Precision')
            plt.title('Plot 9: Precision-Recall Curves (Multi-class Micro-Average)')
            plt.legend(loc='lower left', fontsize=8)
        else:
            # Fallback: Plot precision vs recall bar comparison
            names = list(vlm_results.keys())
            precision = [vlm_results[n].get('precision', 0) for n in names]
            recall = [vlm_results[n].get('recall', 0) for n in names]
            x = np.arange(len(names))
            plt.bar(x - 0.2, precision, 0.4, label='Precision', color='blue', alpha=0.7)
            plt.bar(x + 0.2, recall, 0.4, label='Recall', color='red', alpha=0.7)
            plt.xlabel('Fusion Architecture')
            plt.ylabel('Score')
            plt.title('Plot 9: Precision vs Recall by VLM Fusion Type')
            plt.xticks(x, names, rotation=45, ha='right')
            plt.legend()

        plt.xlim(0, 1)
        plt.ylim(0, 1)
        plt.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot09_precision_recall_curves.png')
        plt.close()
        print("  [09/25] Precision-Recall curves saved")

    # Plot 9b: Per-class Precision-Recall curves
    if vlm_results:
        from sklearn.metrics import precision_recall_curve, average_precision_score
        from sklearn.preprocessing import label_binarize

        # Find a model with probability data
        best_model = None
        for name, data in vlm_results.items():
            if 'probabilities' in data and 'labels' in data:
                best_model = (name, data)
                break

        if best_model:
            name, data = best_model
            # Convert string representations back to arrays
            y_true = safe_array_convert(data, 'labels')
            y_probs = safe_array_convert(data, 'probabilities')

            # Only proceed if conversion succeeded
            if y_true is not None and y_probs is not None:
                n_classes = y_probs.shape[1] if len(y_probs.shape) > 1 else 5
                y_true_bin = label_binarize(y_true, classes=list(range(n_classes)))

                plt.figure(figsize=(12, 8))
                colors = plt.cm.Set1(np.linspace(0, 1, n_classes))

                for i in range(min(n_classes, len(STRESS_LABELS))):
                    precision_i, recall_i, _ = precision_recall_curve(y_true_bin[:, i], y_probs[:, i])
                    ap_i = average_precision_score(y_true_bin[:, i], y_probs[:, i])
                    plt.plot(recall_i, precision_i, color=colors[i],
                            linewidth=2, label=f'{STRESS_LABELS[i]} (AP={ap_i:.3f})')

                plt.xlabel('Recall')
                plt.ylabel('Precision')
                plt.title(f'Plot 9b: Per-Class Precision-Recall Curves ({name})')
                plt.legend(loc='lower left')
                plt.xlim(0, 1)
                plt.ylim(0, 1)
                plt.grid(True, alpha=0.3)
                plt.tight_layout()
                plt.savefig(plots_dir / 'plot09b_per_class_pr_curves.png')
                plt.close()
                print("  [09b/25] Per-class PR curves saved")
            else:
                print("  [09b/25] SKIPPED - Could not convert probability data")

        # Plot 10: F1 Micro vs Macro
        plt.figure(figsize=(10, 6))
        names_vlm = list(vlm_results.keys())
        x_vlm = np.arange(len(names_vlm))
        f1_micro = [vlm_results[n]['f1'] for n in names_vlm]
        f1_macro = [vlm_results[n].get('f1_macro', vlm_results[n]['f1']) for n in names_vlm]
        plt.bar(x_vlm - 0.2, f1_micro, 0.4, label='F1 Micro', color='green', alpha=0.7)
        plt.bar(x_vlm + 0.2, f1_macro, 0.4, label='F1 Macro', color='purple', alpha=0.7)
        plt.xlabel('Fusion Architecture')
        plt.ylabel('F1 Score')
        plt.title('Plot 10: F1 Micro vs Macro')
        plt.xticks(x_vlm, names_vlm, rotation=45, ha='right')
        plt.legend()
        plt.ylim(0, 1)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot10_f1_micro_macro.png')
        plt.close()
        print("  [10/25] F1 Micro vs Macro saved")

    # Plot 10b: Confusion Matrix for Best VLM Model
    if vlm_results:
        from sklearn.metrics import confusion_matrix as sk_confusion_matrix

        # Find best model with prediction data
        best_model_data = None
        best_model_name = None
        for name, data in vlm_results.items():
            if 'predictions' in data and data['predictions'] is not None:
                if best_model_data is None or data.get('f1', 0) > best_model_data.get('f1', 0):
                    best_model_data = data
                    best_model_name = name

        if best_model_data and 'predictions' in best_model_data and 'labels' in best_model_data:
            # Convert string representations back to arrays
            y_true = safe_array_convert(best_model_data, 'labels')
            y_pred = safe_array_convert(best_model_data, 'predictions')

            # Only proceed if conversion succeeded
            if y_true is not None and y_pred is not None:
                # FIXED: Always include all 5 stress classes in confusion matrix
                all_class_labels = list(range(len(STRESS_LABELS)))  # [0, 1, 2, 3, 4]

                # Flatten arrays in case they're 2D
                y_true_flat = np.array(y_true).flatten()
                y_pred_flat = np.array(y_pred).flatten()

                # Create confusion matrix with explicit labels to ensure 5x5
                cm = sk_confusion_matrix(y_true_flat, y_pred_flat, labels=all_class_labels)

                # Verify cm is 5x5 (absolute guarantee)
                _n_cls = len(STRESS_LABELS)
                if cm.shape != (_n_cls, _n_cls):
                    # Pad with zeros to the active class count
                    full_cm = np.zeros((_n_cls, _n_cls), dtype=cm.dtype)
                    min_rows = min(cm.shape[0], _n_cls)
                    min_cols = min(cm.shape[1], _n_cls)
                    full_cm[:min_rows, :min_cols] = cm[:min_rows, :min_cols]
                    cm = full_cm

                # Plot 10b: Confusion Matrix
                plt.figure(figsize=(10, 8))
                sns.heatmap(cm, annot=True, fmt='d', cmap='Blues',
                           xticklabels=STRESS_LABELS, yticklabels=STRESS_LABELS,
                           cbar_kws={'label': 'Count'})
                plt.xlabel('Predicted')
                plt.ylabel('True')

                # Add distribution info to title
                total_samples = cm.sum()
                pred_dist = cm.sum(axis=0)  # Column sums (predictions per class)
                true_dist = cm.sum(axis=1)  # Row sums (true labels per class)
                classes_predicted = int((pred_dist > 0).sum())
                classes_in_test = int((true_dist > 0).sum())

                title_str = (f'Plot 10b: Confusion Matrix ({best_model_name})\n'
                            f'Total: {int(total_samples)} samples | '
                            f'Classes in test: {classes_in_test}/5 | '
                            f'Classes predicted: {classes_predicted}/5')
                plt.title(title_str)
                plt.tight_layout()
                plt.savefig(plots_dir / 'plot10b_confusion_matrix.png', dpi=300)
                plt.close()

                # Print status
                if classes_predicted < 5:
                    print(f"  [10b/25] Confusion matrix saved (Warning: Model only predicting {classes_predicted}/5 classes)")
                else:
                    print("  [10b/25] Confusion matrix saved")

                # Plot 10c: Normalized Confusion Matrix (row-wise normalization)
                row_sums = cm.sum(axis=1, keepdims=True)
                row_sums[row_sums == 0] = 1  # Avoid division by zero
                cm_normalized = cm.astype('float32') / row_sums

                plt.figure(figsize=(10, 8))
                sns.heatmap(cm_normalized, annot=True, fmt='.2%', cmap='RdYlGn',
                           xticklabels=STRESS_LABELS, yticklabels=STRESS_LABELS,
                           vmin=0, vmax=1, cbar_kws={'label': 'Normalized Recall'})
                plt.xlabel('Predicted')
                plt.ylabel('True')
                plt.title(f'Plot 10c: Normalized Confusion Matrix ({best_model_name})')
                plt.tight_layout()
                plt.savefig(plots_dir / 'plot10c_confusion_matrix_normalized.png', dpi=300)
                plt.close()
                print("  [10c/25] Normalized confusion matrix saved")
            else:
                print("  [10b/25] SKIPPED - Could not convert prediction/label data")
                print("  [10c/25] SKIPPED - Could not convert prediction/label data")

    # Plot 10d: compare four fixed conditions on the exact same held-out proxy
    # pairs. Never substitute family headline scores from different test sets.
    _ablation = {}
    _fair_common = results.get('fusion_common_test', {})
    _proposed_effective_row = (
        _fair_common.get('four_way_modality_comparison', {}).get(
            'proposed_multimodal_vlm', {}
        ) if isinstance(_fair_common, dict) else {}
    )
    _proposed_plot_label = _proposed_effective_row.get(
        'plot_label', 'Proposed adaptive VLM'
    )
    _proposed_effective_mode = _proposed_effective_row.get(
        'effective_mode', 'adaptive_cross_attention'
    )
    _four_way_entries = [
        ('Image only\n(unimodal)', 'vision_parent',
         _fair_common.get('vision_parent_name', 'vision parent'), '#D55E00'),
        ('Text only\n(unimodal)', 'text_parent',
         _fair_common.get('text_parent_name', 'text parent'), '#0072B2'),
        ('Standard VLM fusion\n(text + image concat)', 'concat_baseline',
         'concat', '#CC79A7'),
        (str(_proposed_plot_label).replace(' ', '\n', 1),
         'flexible_cross_attention', _proposed_effective_mode, '#009E73'),
    ]
    _common_entries = _four_way_entries
    _has_common_test = all(_key in _fair_common for _, _key, _, _ in _common_entries)

    if _has_common_test:
        _comparison_scope = 'common_held_out_proxy_pairs'
        _plot_ylabel = 'Common held-out score'
        _plot_title = 'Four-Way Common-Test Modality Comparison'
        for _label, _key, _model_name, _color in _common_entries:
            _metrics = _fair_common[_key]
            _ablation[_label] = {
                'model': _model_name,
                'f1_micro': float(_metrics.get('f1_micro', 0.0)),
                'f1_macro': float(_metrics.get('f1_macro', _metrics.get('f1_micro', 0.0))),
                'precision': float(_metrics.get('precision', 0.0)),
                'recall': float(_metrics.get('recall', 0.0)),
                'accuracy': float(_metrics.get('accuracy', 0.0)),
                'n': int(_metrics.get('n', 0)),
                'comparison_scope': _comparison_scope,
                'color': _color,
            }
    else:
        _comparison_scope = 'four_way_common_test_unavailable'
    results['modality_ablation'] = {
        key: {k: v for k, v in value.items() if k != 'color'}
        for key, value in _ablation.items()
    }

    if len(_ablation) == 4:
        # Accuracy and micro-F1 are identical for single-label multiclass
        # classification. Plot that quantity once so five bars do not imply
        # five independent metrics.
        _metric_keys = ['f1_macro', 'accuracy', 'precision', 'recall']
        _metric_labels = [
            'Macro F1 (primary)', 'Accuracy (= Micro F1)',
            'Macro Precision', 'Macro Recall',
        ]
        _x = np.arange(len(_metric_keys))
        _series_count = 4
        _width = min(0.24, 0.82 / _series_count)
        plt.figure(figsize=(14 if _series_count == 4 else 12, 7))
        _observed_best_macro_f1 = max(
            entry['f1_macro'] for entry in _ablation.values()
        )
        for _idx, (_label, _entry) in enumerate(_ablation.items()):
            _values = [_entry[m] for m in _metric_keys]
            _offset = (_idx - (_series_count - 1) / 2.0) * _width
            _is_observed_leader = (
                abs(_entry['f1_macro'] - _observed_best_macro_f1) < 1e-12
            )
            _legend_suffix = (
                ' — observed macro-F1 leader' if _is_observed_leader else ''
            )
            _bars = plt.bar(
                _x + _offset, _values, _width,
                label=f"{_label} ({_entry['model']}){_legend_suffix}",
                color=_entry['color'],
                edgecolor='black' if 'Proposed' in _label else 'none',
                linewidth=1.5 if 'Proposed' in _label else 0.0,
                hatch='//' if 'Proposed' in _label else None,
            )
            for _bar, _value in zip(_bars, _values):
                plt.text(
                    _bar.get_x() + _bar.get_width() / 2.0,
                    min(1.025, _value + 0.012),
                    f"{_value:.2f}",
                    ha='center', va='bottom', fontsize=7, rotation=90,
                )
        plt.xticks(_x, _metric_labels)
        plt.ylabel(_plot_ylabel)
        plt.ylim(0, 1.05)
        plt.title(_plot_title)
        plt.legend(fontsize=8)
        plt.grid(axis='y', alpha=0.25)
        plt.tight_layout()
        plt.savefig(plots_dir / 'plot10d_modality_contribution.png', dpi=300)
        plt.savefig(
            plots_dir / 'plot10d_four_way_modality_comparison.png', dpi=300
        )
        plt.close()
        print(f"  [10d/25] Modality comparison saved ({_comparison_scope})")
    else:
        print(
            "  [10d/25] Skipped: all four fixed common-test conditions "
            "(text, image, concat, flexible VLM) are required"
        )

    # Plot 11: Research Paper Comparison (45+ papers) - Enhanced
    plt.figure(figsize=(18, 20))
    paper_names = list(RESEARCH_PAPERS.keys())
    paper_f1 = [RESEARCH_PAPERS[p]['f1'] for p in paper_names]
    paper_cats = [RESEARCH_PAPERS[p]['category'] for p in paper_names]
    paper_years = [RESEARCH_PAPERS[p].get('year', 2020) for p in paper_names]

    # Add our best result
    our_best_f1 = 0
    our_best_name = "FarmFederate"
    if vlm_results:
        best_vlm = max(vlm_results.keys(), key=lambda x: vlm_results[x]['f1'])
        our_best_f1 = vlm_results[best_vlm]['f1']
