def load_linked_crop_observations(annotation_dir, img_size: int = 224):
    """Load genuine crop/text pairs described by annotations.csv.

    Expected files are ``annotations.csv`` and ``crops/<disease>/``.  Every
    returned row retains its original ``image_file`` as a grouping key so all
    boxes from one photograph stay in exactly one split.
    """
    annotation_dir = Path(annotation_dir)
    csv_path = annotation_dir / 'annotations.csv'
    crops_root = annotation_dir / 'crops'
    if not csv_path.is_file() or not crops_root.is_dir():
        return None

    source = pd.read_csv(csv_path)
    required = {'image_file', 'box_idx', 'class_id', 'disease', 'text'}
    if not required.issubset(source.columns):
        return None
    source['class_id'] = pd.to_numeric(
        source['class_id'], errors='raise'
    ).astype(int)
    source['box_idx'] = pd.to_numeric(
        source['box_idx'], errors='raise'
    ).astype(int)
    source = source[source['class_id'].isin(range(len(STRESS_LABELS)))].copy()

    import torchvision.transforms as _T
    from PIL import Image as _PILImage
    transform = _T.Compose([
        _T.Resize((img_size, img_size)),
        _T.ToTensor(),
        _T.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),
    ])
    images, texts, labels, groups, crop_paths, diseases = [], [], [], [], [], []
    for row in source.itertuples(index=False):
        disease = str(row.disease).strip().lower()
        stem = Path(str(row.image_file)).stem
        box_index = int(row.box_idx)
        crop_dir = crops_root / disease
        candidates = [
            crop_dir / f'{stem}_box{box_index:02d}{suffix}'
            for suffix in ('.jpg', '.jpeg', '.png', '.JPG', '.PNG')
        ] + [
            crop_dir / f'{stem}_box{box_index}{suffix}'
            for suffix in ('.jpg', '.jpeg', '.png', '.JPG', '.PNG')
        ]
        crop_path = next((path for path in candidates if path.is_file()), None)
        if crop_path is None:
            continue
        try:
            image = transform(_PILImage.open(crop_path).convert('RGB'))
        except Exception:
            continue
        images.append(image)
        texts.append(str(row.text).strip())
        labels.append([int(row.class_id)])
        groups.append(Path(str(row.image_file)).name)
        crop_paths.append(crop_path)
        diseases.append(disease)

    if len(images) < 50:
        return None
    class_counts = {
        class_id: sum(_single_label_index(label) == class_id for label in labels)
        for class_id in range(len(STRESS_LABELS))
    }
    if any(count == 0 for count in class_counts.values()):
        return None

    # Connected grouping enforces both leakage constraints simultaneously:
    # (1) every crop from one source photo stays together, and (2) repeated
    # annotation text cannot occur across splits even when attached to another
    # photograph.
    source_image_files = list(groups)
    parent = list(range(len(groups)))

    def _find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def _union(left, right):
        left_root, right_root = _find(left), _find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    seen_source, seen_text = {}, {}
    for index, (source_image, text) in enumerate(zip(source_image_files, texts)):
        source_key = Path(source_image).name
        text_key = _normalise_text_for_split(text)
        if source_key in seen_source:
            _union(index, seen_source[source_key])
        else:
            seen_source[source_key] = index
        if text_key in seen_text:
            _union(index, seen_text[text_key])
        else:
            seen_text[text_key] = index
    groups = [f'linked_component_{_find(index)}' for index in range(len(groups))]
    return {
        'images': images,
        'texts': texts,
        'labels': labels,
        'groups': groups,
        'source_image_files': source_image_files,
        'crop_paths': crop_paths,
        'source_diseases': diseases,
        'class_counts': class_counts,
        'annotation_csv': csv_path,
        'crops_root': crops_root,
    }


def grouped_multimodal_split(labels, groups, train_ratio: float = 0.7,
                             val_ratio: float = 0.15, seed: int = 42):
    """Choose a leakage-safe group split with near-stratified class ratios.

    Class-pure source groups use an exact, deterministic apportionment when
    their bundle sizes permit it. This is important for very small classes:
    eight Hopper sources should be allocated 6/1/1, rather than letting one
    random source move training support from six down to five. Mixed-label or
    indivisible group layouts retain the deterministic grouped-search fallback.
    """

    flat_labels = np.asarray([_single_label_index(label) for label in labels])
    groups_array = np.asarray([str(group) for group in groups])
    indices = np.arange(len(flat_labels))
    num_classes = len(STRESS_LABELS)
    independent_groups_per_class = {
        class_id: len(set(groups_array[flat_labels == class_id]))
        for class_id in range(num_classes)
    }
    insufficient = {
        STRESS_LABELS[class_id]: count
        for class_id, count in independent_groups_per_class.items()
        if count < 3
    }
    if insufficient:
        raise ValueError(
            "A leakage-safe train/validation/test split requires at least "
            "three independent source groups per class; found "
            f"{insufficient}."
        )

    # First try exact class-wise apportionment. Most sorted-image benchmarks
    # have class-pure groups, including Roboflow variants that form a size-two
    # bundle. Dynamic programming assigns whole bundles while hitting the
    # requested file counts exactly; no external dependency is needed here.
    group_rows: Dict[str, List[int]] = {}
    for row_index, group in enumerate(groups_array.tolist()):
        group_rows.setdefault(group, []).append(row_index)
    groups_are_class_pure = all(
        len({int(flat_labels[index]) for index in row_indices}) == 1
        for row_indices in group_rows.values()
    )

    def _bounded_apportion(total, ideals, lower, upper):
        import math

        allocation = [
            min(int(upper[index]), max(int(lower[index]), int(math.floor(ideal))))
            for index, ideal in enumerate(ideals)
        ]
        if total < sum(lower) or total > sum(upper):
            return None
        while sum(allocation) < total:
            candidates = [
                index for index in range(len(allocation))
                if allocation[index] < upper[index]
            ]
            if not candidates:
                return None
            chosen = max(
                candidates,
                key=lambda index: (
                    ideals[index] - allocation[index],
                    upper[index] - allocation[index],
                    -index,
                ),
            )
            allocation[chosen] += 1
        while sum(allocation) > total:
            candidates = [
                index for index in range(len(allocation))
                if allocation[index] > lower[index]
            ]
            if not candidates:
                return None
            chosen = max(
                candidates,
                key=lambda index: (
                    allocation[index] - ideals[index],
                    allocation[index] - lower[index],
                    index,
                ),
            )
            allocation[chosen] -= 1
        return allocation

    if groups_are_class_pure:
        class_counts = np.bincount(flat_labels, minlength=num_classes).astype(int)
        train_total = int(round(len(indices) * float(train_ratio)))
        val_total = int(round(len(indices) * float(val_ratio)))
        test_total = len(indices) - train_total - val_total
        test_ratio = 1.0 - float(train_ratio) - float(val_ratio)
        minimum = [1] * num_classes
        val_upper = [max(1, int(count) - 2) for count in class_counts]
        val_targets = _bounded_apportion(
            val_total,
            [float(count) * float(val_ratio) for count in class_counts],
            minimum,
            val_upper,
        )
        if val_targets is not None:
            remaining_counts = [
                int(count) - int(val_targets[class_id])
                for class_id, count in enumerate(class_counts)
            ]
            test_upper = [max(1, count - 1) for count in remaining_counts]
            test_targets = _bounded_apportion(
                test_total,
                [float(count) * test_ratio for count in class_counts],
                minimum,
                test_upper,
            )
        else:
            test_targets = None

        exact_splits = [[], [], []]
        exact_solution = val_targets is not None and test_targets is not None
        if exact_solution:
            for class_id in range(num_classes):
                class_bundles = [
                    (group, row_indices)
                    for group, row_indices in group_rows.items()
                    if int(flat_labels[row_indices[0]]) == class_id
                ]
                class_rng = random.Random(int(seed) + class_id * 1009)
                class_rng.shuffle(class_bundles)
                # Larger export bundles are considered first and preferentially
                # assigned to training, leaving singletons for exact held-out
                # support counts.
                class_bundles.sort(key=lambda item: -len(item[1]))
                train_target = (
                    int(class_counts[class_id])
                    - int(val_targets[class_id])
                    - int(test_targets[class_id])
                )
                val_target = int(val_targets[class_id])
                test_target = int(test_targets[class_id])
                states = {(0, 0): ()}
                processed = 0
                for _, row_indices in class_bundles:
                    bundle_size = len(row_indices)
                    next_states = {}
                    for (train_used, val_used), assignment in states.items():
                        test_used = processed - train_used - val_used
                        options = (
                            (0, train_used + bundle_size, val_used, test_used),
                            (1, train_used, val_used + bundle_size, test_used),
                            (2, train_used, val_used, test_used + bundle_size),
                        )
                        for split_id, new_train, new_val, new_test in options:
                            if (new_train <= train_target
                                    and new_val <= val_target
                                    and new_test <= test_target):
                                next_states.setdefault(
                                    (new_train, new_val),
                                    assignment + (split_id,),
                                )
                    states = next_states
                    processed += bundle_size
                    if not states:
                        break
                assignment = states.get((train_target, val_target))
                if assignment is None:
                    exact_solution = False
                    break
                for split_id, (_, row_indices) in zip(assignment, class_bundles):
                    exact_splits[split_id].extend(row_indices)

        if exact_solution:
            for split_id in range(3):
                random.Random(int(seed) + 7001 + split_id).shuffle(
                    exact_splits[split_id]
                )
            return tuple(exact_splits)

    from sklearn.model_selection import GroupShuffleSplit
    global_distribution = np.bincount(
        flat_labels, minlength=num_classes
    ).astype(float)
    global_distribution /= max(1.0, global_distribution.sum())
    remaining_ratio = 1.0 - float(train_ratio)
    relative_val_ratio = float(val_ratio) / max(remaining_ratio, 1e-8)
    best = None

    for attempt in range(256):
        outer = GroupShuffleSplit(
            n_splits=1, train_size=float(train_ratio),
            random_state=int(seed) + attempt,
        )
        train_index, remaining_index = next(
            outer.split(indices, flat_labels, groups_array)
        )
        inner = GroupShuffleSplit(
            n_splits=1, train_size=relative_val_ratio,
            random_state=int(seed) + 1000 + attempt,
        )
        relative_val, relative_test = next(inner.split(
            remaining_index,
            flat_labels[remaining_index],
            groups_array[remaining_index],
        ))
        val_index = remaining_index[relative_val]
        test_index = remaining_index[relative_test]
        split_indices = (train_index, val_index, test_index)
        score = 0.0
        candidate_has_full_class_support = True
        for split_index, target_ratio in zip(
            split_indices, (train_ratio, val_ratio, 1.0 - train_ratio - val_ratio)
        ):
            counts = np.bincount(
                flat_labels[split_index], minlength=num_classes
            ).astype(float)
            missing = float((counts == 0).sum())
            if missing:
                candidate_has_full_class_support = False
                break
            distribution = counts / max(1.0, counts.sum())
            score += 20.0 * abs(len(split_index) / len(indices) - target_ratio)
            score += float(np.abs(distribution - global_distribution).sum())
        if not candidate_has_full_class_support:
            continue
        candidate = (score, attempt, split_indices)
        if best is None or candidate[:2] < best[:2]:
            best = candidate

    if best is None:
        raise RuntimeError(
            'Could not construct a source-grouped split with every class in '
            'train, validation, and test after 256 deterministic attempts.'
        )
    train_index, val_index, test_index = best[2]
    # This assertion is the leakage boundary for the paired benchmark.
    group_sets = [set(groups_array[index]) for index in best[2]]
    if (group_sets[0] & group_sets[1] or group_sets[0] & group_sets[2]
            or group_sets[1] & group_sets[2]):
        raise RuntimeError('Grouped multimodal split leaked source photographs')
    for split_name, split_index in zip(
        ('train', 'validation', 'test'), best[2]
    ):
        present_classes = set(flat_labels[split_index].tolist())
        if present_classes != set(range(num_classes)):
            raise RuntimeError(
                f'Grouped {split_name} split is missing one or more classes'
            )
    return train_index.tolist(), val_index.tolist(), test_index.tolist()


def _real_image_source_group(image_path: Any) -> str:
    """Return a stable source-photo key for an exported image path.

    Roboflow export names end in ``.rf.<content hash>``. Multiple exported
    variants can therefore describe the same original photograph even though
    their final filenames differ. Splitting on the suffix-bearing filenames
    would leak near-duplicate source content across train/validation/test.
    """
    import re

    stem = Path(image_path).stem
    source_stem = re.sub(r'\.rf\.[0-9a-fA-F]+$', '', stem)
    return source_stem.casefold()


def load_local_images(data_dir, max_per_class: int = 800, img_size: int = 224,
                      seed: int = 42, return_source_groups: bool = False):
    """Load real images from local folders.

    Supports two layouts:
      - tea_data/{stress}/           (flat — Google Drive structure)
      - data/{stress}/images/        (legacy — nested images/ subfolder)

    Returns:
        images: list of normalised tensors [C,H,W]
        labels: list of [int] label lists
        source_groups: optional stable source-photo keys when
            ``return_source_groups=True``
    """
    import torchvision.transforms as _T
    # Loading must be deterministic because this happens before train/val/test
    # splitting. Stochastic views are applied later by training Datasets only.
    transform = _T.Compose([
        _T.Resize((img_size, img_size)),
        _T.ToTensor(),
        _T.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),
    ])
    from PIL import Image as _PILImage
    images, labels, source_groups = [], [], []
    rng = random.Random(seed)
    data_dir = Path(data_dir)
    num_classes = len(STRESS_LABELS)
    image_suffixes = {'.jpg', '.jpeg', '.png', '.bmp', '.webp'}

    def _class_image_count(folder_name):
        class_dir = data_dir / folder_name
        nested_dir = class_dir / 'images'
        source_dir = nested_dir if nested_dir.is_dir() else class_dir
        return sum(
            1 for path in source_dir.iterdir()
            if path.is_file() and path.suffix.lower() in image_suffixes
        ) if source_dir.is_dir() else 0

    # Remap, without mutating the source, the exact known legacy sorted-folder
    # signature created by the old 0<->2 YOLO mapping bug.
    legacy_folder_alias = {}
    if (_class_image_count('LEAF_BLIGHT'), _class_image_count('LEAF_RUST')) == (35, 62):
        legacy_folder_alias = {
            'LEAF_BLIGHT': 'LEAF_RUST',
            'LEAF_RUST': 'LEAF_BLIGHT',
        }
        print(
            "  [Label repair] Legacy LEAF_BLIGHT/LEAF_RUST folders detected; "
            "loading them with corrected canonical labels."
        )
    for idx, stress in enumerate(STRESS_LABELS):
        source_stress = legacy_folder_alias.get(stress, stress)
        # Check flat structure first (GDrive tea_data/), then nested (data/{stress}/images/)
        flat_dir   = data_dir / source_stress
        nested_dir = data_dir / source_stress / "images"
        if nested_dir.exists():
            img_dir = nested_dir
        elif flat_dir.exists():
            img_dir = flat_dir
        else:
            print(f"  [WARN] No image folder found for {stress} under {data_dir}")
            continue
        paths = sorted(
            list(img_dir.glob("*.jpg")) + list(img_dir.glob("*.jpeg"))
            + list(img_dir.glob("*.png")) + list(img_dir.glob("*.JPG"))
            + list(img_dir.glob("*.PNG")),
            key=lambda path: path.name.casefold(),
        )
        rng.shuffle(paths)
        paths = paths[:max_per_class]
        loaded = 0
        for p in paths:
            try:
                img = _PILImage.open(p).convert("RGB")
                images.append(transform(img))
                labels.append([idx])
                source_groups.append(_real_image_source_group(p))
                loaded += 1
            except Exception:
                continue
        print(f"  {stress}: {loaded} images loaded from {img_dir}")
    if return_source_groups:
        return images, labels, source_groups
    return images, labels


def run_training_real_data(config: "Config" = None, allow_short: bool = False):
    """Full training pipeline using real images and a separately supplied text CSV.

    Loads:
      - Text  : annotations.csv or data/{stress}/text.csv (provenance is audited)
      - Images: data/{stress}/images/   (real .jpg/.png files)

    Trains all 26 models: 5 LLM + 5 ViT + 8 early-fusion VLM +
    1 flexible token-level VLM + 1 pretrained late-fusion VLM +
    4 matched centralized controls + 4 federated models (image-only,
    text-only, concat VLM, and flexible cross-attention VLM).
    Generates 45+ plots and saves complete_results.json.

    Colab usage:
        from google.colab import drive
        drive.mount('/content/drive')
        exec(open('FarmFederate_Colab_Complete.py').read())
        run_training_real_data()

    Kaggle usage:
        # Attach a Dataset containing data_final.zip, then:
        !python FarmFederate_Colab_Complete.py --full-kaggle
    """
    if config is None:
        config = Config(epochs=15, batch_size=16, max_samples_per_class=800)

    print(f"[Build] {SCRIPT_BUILD} | label schema: {STRESS_SCHEMA_VERSION}")
    check_imports()
    if not allow_short and config.epochs < 10:
        print(f"[Info] Enforcing minimum epochs=10 (was {config.epochs})")
        config.epochs = 10

    torch.manual_seed(config.seed)
    np.random.seed(config.seed)
    random.seed(config.seed)

    device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    print(f"\n[Device] {device}")
    if ((IN_COLAB or IN_KAGGLE)
            and bool(getattr(config, 'use_pretrained_backbones', True))
            and bool(getattr(config, 'require_colab_gpu_for_pretrained', True))
            and device.type != 'cuda'):
        _runtime_name = 'Kaggle' if IN_KAGGLE else 'Colab'
        _accelerator_help = (
            "In Kaggle open Notebook options/settings and enable a GPU "
            "accelerator, then restart the session."
            if IN_KAGGLE else
            "In Colab choose Runtime > Change runtime type > T4 GPU, "
            "reconnect, and rerun the cell."
        )
        raise RuntimeError(
            f"CUDA GPU is not available in {_runtime_name}. {_accelerator_help} "
            "The script "
            "does not silently run the full pretrained benchmark on CPU."
        )
    if IN_KAGGLE and bool(getattr(config, 'use_pretrained_backbones', True)):
        print(
            "[Kaggle] Pretrained Hugging Face weights require Internet on the "
            "first run unless an equivalent model cache is attached."
        )
    setup_gdrive_output_dirs(config)
    config.output_dir.mkdir(parents=True, exist_ok=True)
    config.plots_dir.mkdir(parents=True, exist_ok=True)
    config.checkpoint_dir.mkdir(parents=True, exist_ok=True)

    # Portable bundle support. Colab reads from mounted Drive (or its configured
    # Drive ID); Kaggle discovers an attached /kaggle/input/**/data_final.zip.
    # Every runtime extracts into a writable work area, never into Kaggle input.
    _bundle_image_dir = None
    _bundle_text_dir = None
    _explicit_bundle_zip = getattr(config, "data_final_zip", None)
    if _explicit_bundle_zip:
        _bundle_zip = Path(_explicit_bundle_zip)
        if not _bundle_zip.is_file():
            raise FileNotFoundError(
                f"The explicit --data-final-zip path does not exist: {_bundle_zip}"
            )
        print(f"[Data] Using explicit portable bundle: {_bundle_zip}")
    else:
        _zip_candidates = []
        if IN_KAGGLE:
            _kaggle_bundle_zip = discover_kaggle_data_final_zip()
            if _kaggle_bundle_zip is not None:
                _zip_candidates.append(_kaggle_bundle_zip)
                print(f"[Data] Kaggle input bundle discovered: {_kaggle_bundle_zip}")
        _zip_candidates.extend([
            Path("/content/drive/MyDrive/FarmFederate/data_final.zip"),
            Path("/content/drive/My Drive/FarmFederate/data_final.zip"),
            Path("/content/drive/MyDrive/data_final.zip"),
            Path("/content/data_final.zip"),
            Path("data_final.zip"),
        ])
        _bundle_zip = next((p for p in _zip_candidates if p.is_file()), None)
    # Prefer the authenticated mounted Drive file. This works even when gdown
    # cannot access a link that is private to the signed-in Google account.
    if IN_COLAB and not IN_KAGGLE and not _explicit_bundle_zip:
        _mounted_candidates = [
            Path("/content/drive/MyDrive/FarmFederate/data_final.zip"),
            Path("/content/drive/My Drive/FarmFederate/data_final.zip"),
            Path("/content/drive/MyDrive/data_final.zip"),
            Path("/content/drive/My Drive/data_final.zip"),
        ]
        _bundle_zip, _colab_bundle_source = prefer_colab_bundle_candidate(
            _bundle_zip, _mounted_candidates
        )
        if _colab_bundle_source == 'mounted_drive':
            print(f"[Data] Using authenticated mounted-Drive bundle: {_bundle_zip}")
        elif _colab_bundle_source == 'uploaded_or_local':
            print(f"[Data] Using uploaded/local Colab bundle: {_bundle_zip}")
        else:
            _file_id = getattr(config, "data_final_drive_file_id", "")
            _download_target = Path("/content/data_final.zip")
            print(f"[Data] Mounted bundle not found; trying public Drive download ({_file_id})...")
            try:
                import gdown as _gdown
                _downloaded = _gdown.download(
                    id=_file_id, output=str(_download_target), quiet=False, fuzzy=True
                )
            except Exception as _download_error:
                _downloaded = None
                print(f"[Data] Public Drive download failed: {_download_error}")
            if _downloaded and _download_target.is_file():
                _bundle_zip = _download_target
            else:
                raise FileNotFoundError(
                    "data_final.zip is not publicly downloadable and was not found in "
                    "the current session or mounted Drive. Upload it to "
                    "/content/data_final.zip, pass --data-final-zip, or copy it to "
                    "MyDrive/data_final.zip or MyDrive/FarmFederate/data_final.zip, "
                    "then rerun the cell."
                )
    if IN_KAGGLE and _bundle_zip is None:
        _bundle_image_dir, _bundle_text_dir = discover_expanded_kaggle_bundle()
        if _bundle_image_dir is not None and _bundle_text_dir is not None:
            print(f"[Data] Expanded Kaggle bundle discovered under {_kaggle_input_root()}")

    if _bundle_zip is not None:
        _extract_root = portable_bundle_extract_root(_bundle_zip)
        _bundle_image_dir, _bundle_text_dir = extract_portable_bundle(
            _bundle_zip, _extract_root
        )
        _bundle_schema = _ensure_portable_bundle_label_schema(
            _bundle_image_dir, _bundle_image_dir.parent
        )
        print(f"[Data] Portable image root: {_bundle_image_dir.resolve()}")
        print(f"[Data] Portable text root:  {_bundle_text_dir.resolve()}")
        print(f"[Data] Portable label schema: {_bundle_schema['schema_version']}")

    elif _bundle_image_dir is not None and _bundle_text_dir is not None:
        _bundle_schema = _ensure_portable_bundle_label_schema(
            _bundle_image_dir, _bundle_image_dir.parent
        )
        print(f"[Data] Portable image root: {_bundle_image_dir.resolve()}")
        print(f"[Data] Portable text root:  {_bundle_text_dir.resolve()}")
        print(f"[Data] Portable label schema: {_bundle_schema['schema_version']}")

    # ── Resolve data directory ──────────────────────────────────────────────
    # Resolve the real image dataset independently from the matching text data.
    _repo_root = (Path(__file__).resolve().parent.parent
                  if '__file__' in globals() else Path.cwd())
    _candidates = [
        Path(config.data_dir),                                  # Config/--data-dir
        Path("C:/Users/USER_HP/Desktop/FarmFederate/real_dataset_sorted"),
        Path("real_dataset_sorted"),
        _repo_root / "real_dataset_sorted",
        Path("/content/real_dataset_sorted"),
        Path("/content/drive/MyDrive/FarmFederate/real_dataset_sorted"),
        Path("/content/drive/My Drive/FarmFederate/real_dataset_sorted"),
        Path("/content/tea_data"),                              # primary — downloaded by setup_colab_data()
        Path("/content/drive/MyDrive/FarmFederate/tea_data"),  # GDrive MyDrive/FarmFederate/tea_data
        Path("/content/drive/My Drive/FarmFederate/tea_data"), # alt Drive path
        Path("/content/drive/MyDrive/FarmFederate/data"),
        Path("/content/drive/My Drive/FarmFederate/data"),
        Path("/content/drive/MyDrive/tea_data"),
        Path("C:/Users/USER_HP/Desktop/FarmFederate/farmfederate_results (1)/dataset/tea_data"),  # real dataset (local)
        Path("C:/Users/USER_HP/Desktop/FarmFederate/tea_data"),
        Path("C:/Users/USER_HP/Desktop/FarmFederate/data"),
        Path("tea_data"),
        Path("/content/FarmFederate/data"),
        Path("/content/drive/MyDrive/data"),
        Path("data"),
    ]
    if _bundle_image_dir is not None:
        _candidates.insert(0, _bundle_image_dir)
    # Env override wins over the built-in candidate list.
    if os.environ.get("DATA_DIR"):
        _candidates.insert(0, Path(os.environ["DATA_DIR"]))

    def _is_usable_dataset(p: Path) -> bool:
        return _is_usable_sorted_dataset(p)

    data_dir = next((p for p in _candidates if _is_usable_dataset(p)), None)
    if data_dir is None:
        if IN_KAGGLE:
            raise FileNotFoundError(
                f"No valid FarmFederate bundle was found under {_kaggle_input_root()}. "
                "Use Add Input/Add Data to attach the Kaggle Dataset containing "
                "data_final.zip, or pass --data-final-zip with its exact path."
            )
        raise FileNotFoundError(
            "Real image dataset not found. Supply --data-dir pointing to "
            "real_dataset_sorted with the five disease class folders."
        )
    data_dir = data_dir.resolve()
    config.data_dir = data_dir
    print(f"[Data] Real image directory: {data_dir}")

    _text_candidates = [
        Path(config.text_data_dir),
        Path("C:/Users/USER_HP/Desktop/FarmFederate/dataset/tea_data"),
        _repo_root / "dataset" / "tea_data",
        Path("dataset/tea_data"),
        Path("/content/dataset/tea_data"),
        Path("/content/drive/MyDrive/FarmFederate/dataset/tea_data"),
    ]
    if _bundle_text_dir is not None:
        _text_candidates.insert(0, _bundle_text_dir)
    text_data_dir = next((p for p in _text_candidates if (p / "annotations.csv").is_file()), None)
    if text_data_dir is None:
        if IN_KAGGLE:
            raise FileNotFoundError(
                "The attached Kaggle input does not contain text_data/annotations.csv. "
                "Attach the complete data_final.zip bundle."
            )
        raise FileNotFoundError(
            "Matching text dataset not found. Supply --text-data-dir pointing "
            "to dataset/tea_data containing annotations.csv."
        )
    text_data_dir = text_data_dir.resolve()
    config.text_data_dir = text_data_dir
    print(f"[Data] Text directory: {text_data_dir}")

    max_per_class = config.max_samples_per_class

    # ── [1/8] Load text data (real CSVs preferred, synthetic fallback) ──────────
    # Priority: per-class text.csv files OR combined annotations.csv in data_dir.
    # Falls back to synthetic text (70% cross-class templates) if no real text found.
    print("\n[1/8] Loading text data...")
    text_df = None
    # A CSV is not necessarily image-linked field text. Preserve that distinction
    # in the console output and saved results.
    text_source_kind = "unknown"

    # Try combined annotations.csv
    _annot_csv = text_data_dir / "annotations.csv"
    if _annot_csv.exists():
        try:
            _df = pd.read_csv(_annot_csv)
            if {"text", "class_id", "class_name"}.issubset(_df.columns) and len(_df) >= len(STRESS_LABELS) * 10:
                _df["class_name"] = _df["class_name"].astype(str).str.strip()
                # class_name is authoritative. class_id is a positional index
                # into the schema, so excluding a class shifts every id above
                # it; trusting the stored id would silently relabel the corpus.
                # Validate the NAME against the full taxonomy (a genuine typo
                # still fails loudly), then re-derive the id from it.
                _unknown_names = sorted(set(
                    _df.loc[~_df["class_name"].isin(FULL_STRESS_LABELS), "class_name"]
                ))
                if _unknown_names:
                    raise ValueError(
                        f"Text schema mismatch in {_annot_csv}: class_name values "
                        f"outside the taxonomy {FULL_STRESS_LABELS}: {_unknown_names}"
                    )
                _dropped_rows = int((~_df["class_name"].isin(STRESS_LABELS)).sum())
                _df = _df[_df["class_name"].isin(STRESS_LABELS)].copy()
                _df["class_id"] = _df["class_name"].map(LABEL_TO_IDX).astype(int)
                if _dropped_rows:
                    print(f"  Dropped {_dropped_rows} text rows for excluded "
                          f"classes {EXCLUDED_STRESS_LABELS}; class_id "
                          "re-derived from class_name.")
                _has_image_link = {"image_file", "box_idx"}.issubset(_df.columns)
                _is_synthetic_template_csv = (
                    "source" in _df.columns
                    and _df["source"].astype(str).str.contains("synthetic", case=False, na=False).all()
                )
                _df = _df.rename(columns={"class_id": "labels", "class_name": "label_name"})
                _df["labels"] = _df["labels"].apply(lambda x: [int(x)])
                _df = _df[_df["label_name"].isin(STRESS_LABELS)].reset_index(drop=True)
                if len(_df) >= len(STRESS_LABELS) * 10:
                    text_df = _df
                    text_source_kind = (
                        "generated synthetic template CSV" if _is_synthetic_template_csv
                        else "image-linked annotations CSV" if _has_image_link
                        else "unlinked annotations CSV"
                    )
                    print(f"  Loaded {len(text_df)} text rows from {_annot_csv} ({text_source_kind})")
                    print("  " + text_df["label_name"].value_counts().to_string().replace("\n", "\n  "))
        except ValueError:
            # Never silently position-map a different disease taxonomy into
            # the image stress labels; that invalidates multimodal training.
            raise
        except Exception as _e:
            print(f"  [WARN] Could not load {_annot_csv}: {_e}")

    # Try per-class text.csv files
    if text_df is None:
        _per_class_rows = []
        for _ci, _cls in enumerate(STRESS_LABELS):
            _csv_path = text_data_dir / _cls / "text.csv"
            if _csv_path.exists():
                try:
                    _cdf = pd.read_csv(_csv_path)
                    if "text" in _cdf.columns:
                        _cdf = _cdf[["text"]].copy()
                        _cdf["labels"] = [[_ci]] * len(_cdf)
                        _cdf["label_name"] = _cls
                        _per_class_rows.append(_cdf)
                except Exception as _e:
                    print(f"  [WARN] Could not load {_csv_path}: {_e}")
        if _per_class_rows and sum(len(d) for d in _per_class_rows) >= len(STRESS_LABELS) * 10:
            text_df = pd.concat(_per_class_rows, ignore_index=True)
            text_source_kind = "unlinked per-class text CSV"
            print(f"  Loaded {len(text_df)} text rows from per-class text.csv files ({text_source_kind})")
            print("  " + text_df["label_name"].value_counts().to_string().replace("\n", "\n  "))

    # Synthetic fallback
    if text_df is None:
        print("  Real text not found — generating synthetic text (60% cross-class templates)...")
        n_text_samples = min(max_per_class * len(STRESS_LABELS), 2000)
        text_df = generate_synthetic_text_data(n_samples=n_text_samples)
        text_source_kind = "generated synthetic template text"
        print(f"  Text generated: {len(text_df)} rows (balanced by construction)")
        print("  " + text_df["label_name"].value_counts().to_string().replace("\n", "\n  "))

    text_labels = text_df["labels"].tolist()
    val_ratio = 1.0 - config.train_split
    (texts_train, label_train_txt), (texts_val, label_val_txt), (texts_test, label_test_txt), text_split_audit = grouped_text_split(
        texts=text_df["text"].tolist(),
        labels=text_labels,
        train_ratio=config.train_split,
        val_ratio=val_ratio * 0.5,
        seed=config.seed,
    )

    # Keep a template-disjoint test set untouched until after early stopping.
    text_train = pd.DataFrame({"text": texts_train, "labels": label_train_txt,
                                "label_name": [STRESS_LABELS[l[0] if isinstance(l, list) else int(l)] for l in label_train_txt]})
    texts_train = text_train["text"].tolist()
    label_train_txt = text_train["labels"].tolist()
    text_val   = pd.DataFrame({"text": texts_val,   "labels": label_val_txt})
    text_test  = pd.DataFrame({"text": texts_test,  "labels": label_test_txt})
    print(
        "  Exact/template-overlap-audited text split: "
        f"{len(text_train)} train, {len(text_val)} val, {len(text_test)} test"
    )
    print(f"  Text deduplication: {text_split_audit['raw_rows']} raw -> "
          f"{text_split_audit['unique_text_rows']} unique "
          f"({text_split_audit['duplicate_rows_removed']} duplicate rows removed)")
    print("  Text overlap audit: "
          f"exact train/val={text_split_audit['exact_overlap_train_val']}, "
          f"exact train/test={text_split_audit['exact_overlap_train_test']}, "
          f"template train/val={text_split_audit['template_overlap_train_val']}, "
          f"template train/test={text_split_audit['template_overlap_train_test']}")
    if (text_split_audit['exact_overlap_train_val'] or text_split_audit['exact_overlap_train_test']
            or text_split_audit['group_overlap_train_val'] or text_split_audit['group_overlap_train_test']):
        raise RuntimeError("Text split leakage audit failed; refusing to train on overlapping groups.")

    # ── [2/8] Load real images ──────────────────────────────────────────────
    # Source: the resolved real image dir (real_dataset_sorted/{CLASS}/*.jpg).
    # load_local_images resolves a nested images/ subfolder if present, else the
    # flat class folder, and assigns label = index of the class in STRESS_LABELS
    # (matching annotations.csv class_id order). Training-only balancing is
    # applied after the real train/validation/test split below.
    print(f"\n[2/8] Loading real images from {data_dir} ...")
    images_all, img_labels_all, image_source_groups = load_local_images(
        data_dir, max_per_class=max_per_class, img_size=config.image_size,
        seed=config.seed, return_source_groups=True,
    )
    print(f"  Loaded {len(images_all)} real images from {data_dir}")

    if len(images_all) < len(STRESS_LABELS):
        from pathlib import Path as _RDPath
        _rd_candidates = [
            "C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset",
            "C:/Users/USER_HP/Desktop/FarmFederate/Real_Dataset",
            "/content/real_dataset_sorted",
            "/content/drive/MyDrive/FarmFederate/real_dataset_sorted",
        ]
        _rd_path = next((p for p in _rd_candidates if _RDPath(p).exists()), None)
        print(f"  [Fallback] too few images in {data_dir} — trying YOLO OBB Real Dataset...")
        if _rd_path:
            images_all, img_labels_all, _ = load_real_tea_dataset(_rd_path, img_size=config.image_size)
        else:
            images_all, img_labels_all, _ = load_real_tea_dataset(img_size=config.image_size)
        # The legacy tensor-only loader does not retain paths. Identity groups
        # preserve the old split without pretending that source-photo leakage
        # was audited.
        image_source_groups = [
            f'legacy_untracked_image_{index}' for index in range(len(images_all))
        ]
        print(
            "  [IMAGE PROVENANCE WARNING] Fallback loader did not retain source "
            "filenames; near-duplicate source grouping could not be verified."
        )
    print(f"  Images loaded: {len(images_all)}")

    # real_dataset_sorted is small and imbalanced. Split the REAL images into
    # train/val/test FIRST so evaluation stays 100% real and untouched, then
    # balance only the TRAIN split according to image_fill_strategy. The default
    # repeats real training images with fresh augmentation on access; synthetic
    # fill is available only as an explicit ablation.
    _cls_counts = {i: sum(1 for l in img_labels_all if (l[0] if isinstance(l, list) else l) == i)
                   for i in range(len(STRESS_LABELS))}
    for cls_idx, cnt in _cls_counts.items():
        if cnt == 0:
            raise ValueError(f"No real images found for required class {STRESS_LABELS[cls_idx]}")
        print(f"    {STRESS_LABELS[cls_idx]}: {cnt} real images")

    image_train_idx, image_val_idx, image_test_idx = grouped_multimodal_split(
        labels=img_labels_all,
        groups=image_source_groups,
        train_ratio=config.train_split,
        val_ratio=val_ratio * 0.5,
        seed=config.seed,
    )

    def _image_values(values, indices):
        return [values[index] for index in indices]

    image_train = _image_values(images_all, image_train_idx)
    image_val = _image_values(images_all, image_val_idx)
    image_test = _image_values(images_all, image_test_idx)
    label_train_img = _image_values(img_labels_all, image_train_idx)
    label_val_img = _image_values(img_labels_all, image_val_idx)
    label_test_img = _image_values(img_labels_all, image_test_idx)
    image_split_groups_train = _image_values(
        image_source_groups, image_train_idx
    )
    image_split_groups_val = _image_values(
        image_source_groups, image_val_idx
    )
    image_split_groups_test = _image_values(
        image_source_groups, image_test_idx
    )

    def _image_split_counts(split_labels):
        return {
            STRESS_LABELS[class_id]: sum(
                _single_label_index(label) == class_id
                for label in split_labels
            )
            for class_id in range(len(STRESS_LABELS))
        }

    image_split_audit = {
        'protocol': 'source_photo_grouped_exact_class_apportionment_v2',
        'source_files': len(image_source_groups),
        'independent_source_groups': len(set(image_source_groups)),
        'duplicate_export_variants': (
            len(image_source_groups) - len(set(image_source_groups))
        ),
        'split_groups': {
            'train': len(set(image_split_groups_train)),
            'val': len(set(image_split_groups_val)),
            'test': len(set(image_split_groups_test)),
        },
        'split_class_counts': {
            'train': _image_split_counts(label_train_img),
            'val': _image_split_counts(label_val_img),
            'test': _image_split_counts(label_test_img),
        },
        'group_overlap_train_val': len(
            set(image_split_groups_train) & set(image_split_groups_val)
        ),
        'group_overlap_train_test': len(
            set(image_split_groups_train) & set(image_split_groups_test)
        ),
        'group_overlap_val_test': len(
            set(image_split_groups_val) & set(image_split_groups_test)
        ),
    }
    # Keep an immutable view of the real training support before balancing.
    real_image_train = list(image_train)
    real_label_train_img = list(label_train_img)
    print(f"  Image split (real only): {len(image_train)} train, {len(image_val)} val, {len(image_test)} test")
    print(
        "  Independent source-photo groups: "
        f"{image_split_audit['split_groups']['train']} train / "
        f"{image_split_audit['split_groups']['val']} val / "
        f"{image_split_audit['split_groups']['test']} test; "
        f"duplicate export variants kept together="
        f"{image_split_audit['duplicate_export_variants']}"
    )
    print(
        "  Image file-row class support by split: "
        f"train={image_split_audit['split_class_counts']['train']}; "
        f"val={image_split_audit['split_class_counts']['val']}; "
        f"test={image_split_audit['split_class_counts']['test']}"
    )

    # Prefer genuine filename-and-box-linked crop/text observations when the
    # repository data are available. This is the only path on which the two
    # modalities describe the same physical lesion. Splitting by image_file
    # prevents different boxes from one photograph crossing split boundaries.
    linked_pair_mode = False
    linked_pair_info = None
    linked_mm_train = linked_mm_val = linked_mm_test = None
    benchmark_image_root = Path(data_dir)
    linked_annotation_candidates = [
        text_data_dir,
        _repo_root / 'tea_results' / 'annotation',
        Path('/content/FarmFederate/tea_results/annotation'),
        Path('/content/drive/MyDrive/FarmFederate/tea_results/annotation'),
    ]
    for linked_annotation_dir in linked_annotation_candidates:
        try:
            linked_pair_info = load_linked_crop_observations(
                linked_annotation_dir, img_size=config.image_size
            )
        except Exception as linked_load_error:
            print(
                f"  [WARN] Linked-pair load failed at {linked_annotation_dir}: "
                f"{linked_load_error}"
            )
            linked_pair_info = None
        if linked_pair_info is not None:
            break

    if linked_pair_info is not None:
        linked_pair_mode = True
        linked_train_idx, linked_val_idx, linked_test_idx = grouped_multimodal_split(
            linked_pair_info['labels'], linked_pair_info['groups'],
            train_ratio=config.train_split,
            val_ratio=val_ratio * 0.5,
            seed=config.seed,
        )

        def _linked_values(key, indices):
            values = linked_pair_info[key]
            return [values[index] for index in indices]

        images_all = list(linked_pair_info['images'])
        img_labels_all = list(linked_pair_info['labels'])
        image_train = _linked_values('images', linked_train_idx)
        image_val = _linked_values('images', linked_val_idx)
        image_test = _linked_values('images', linked_test_idx)
        label_train_img = _linked_values('labels', linked_train_idx)
        label_val_img = _linked_values('labels', linked_val_idx)
        label_test_img = _linked_values('labels', linked_test_idx)
        image_source_groups = list(linked_pair_info['groups'])
        image_split_groups_train = _linked_values('groups', linked_train_idx)
        image_split_groups_val = _linked_values('groups', linked_val_idx)
        image_split_groups_test = _linked_values('groups', linked_test_idx)
        texts_train = _linked_values('texts', linked_train_idx)
        texts_val = _linked_values('texts', linked_val_idx)
        texts_test = _linked_values('texts', linked_test_idx)
        label_train_txt = list(label_train_img)
        label_val_txt = list(label_val_img)
        label_test_txt = list(label_test_img)
        text_train = pd.DataFrame({
            'text': texts_train,
            'labels': label_train_txt,
            'label_name': [STRESS_LABELS[_single_label_index(label)]
                           for label in label_train_txt],
        })
        text_val = pd.DataFrame({'text': texts_val, 'labels': label_val_txt})
        text_test = pd.DataFrame({'text': texts_test, 'labels': label_test_txt})
        text_df = pd.DataFrame({
            'text': linked_pair_info['texts'],
            'labels': linked_pair_info['labels'],
            'label_name': [STRESS_LABELS[_single_label_index(label)]
                           for label in linked_pair_info['labels']],
            'source_disease': linked_pair_info['source_diseases'],
            'image_file': linked_pair_info['source_image_files'],
        })
        text_labels = text_df['labels'].tolist()
        real_image_train = list(image_train)
        real_label_train_img = list(label_train_img)
        linked_mm_train = (list(texts_train), list(image_train), list(label_train_img))
        linked_mm_val = (list(texts_val), list(image_val), list(label_val_img))
        linked_mm_test = (list(texts_test), list(image_test), list(label_test_img))
        benchmark_image_root = Path(linked_pair_info['crops_root'])
        text_source_kind = 'filename-and-box-linked crop observations'
        text_split_audit = {
            'protocol': 'source-image-grouped multimodal split',
            'raw_rows': len(text_df),
            'unique_text_rows': int(text_df['text'].nunique()),
            'duplicate_rows_removed': 0,
            'exact_overlap_train_val': 0,
            'exact_overlap_train_test': 0,
            'template_overlap_train_val': None,
            'template_overlap_train_test': None,
            'group_overlap_train_val': 0,
            'group_overlap_train_test': 0,
            'source_groups': len(set(linked_pair_info['source_image_files'])),
            'connected_split_groups': len(set(linked_pair_info['groups'])),
        }
        image_split_audit = {
            'protocol': 'linked_source_image_and_text_component_grouped_v1',
            'source_files': len(linked_pair_info['source_image_files']),
            'independent_source_groups': len(set(linked_pair_info['groups'])),
            'duplicate_export_variants': None,
            'split_groups': {
                'train': len(set(image_split_groups_train)),
                'val': len(set(image_split_groups_val)),
                'test': len(set(image_split_groups_test)),
            },
            'split_class_counts': {
                'train': _image_split_counts(label_train_img),
                'val': _image_split_counts(label_val_img),
                'test': _image_split_counts(label_test_img),
            },
            'group_overlap_train_val': 0,
            'group_overlap_train_test': 0,
            'group_overlap_val_test': 0,
        }
        print(
            "  [Paired benchmark] Using genuine crop/text observations: "
            f"{len(image_train)} train, {len(image_val)} validation, "
            f"{len(image_test)} test from "
            f"{len(set(linked_pair_info['source_image_files']))} source photographs."
        )
        print(
            "  [Leakage guard] All boxes from a source photograph remain in "
            "one split."
        )

    if linked_pair_mode:
        linked_group_counts = {
            'train': len(set(_linked_values('groups', linked_train_idx))),
            'val': len(set(_linked_values('groups', linked_val_idx))),
            'test': len(set(_linked_values('groups', linked_test_idx))),
        }
        text_split_audit['split_groups'] = dict(linked_group_counts)
        print(f"  Independent source-image groups: {linked_group_counts}")
    else:
        print(
            "  Independent text groups: "
            f"{text_split_audit['split_groups']['train']} train / "
            f"{text_split_audit['split_groups']['val']} val / "
            f"{text_split_audit['split_groups']['test']} test; "
            f"per-class allocation={text_split_audit['split_groups_per_class']}"
        )
        if text_source_kind.startswith('unlinked'):
            print(
                "  [TEXT PROVENANCE WARNING] The CSV has no image links or "
                "declared synthetic/field provenance. Results are an unlinked "
                "text benchmark, not verified field-observation accuracy."
            )
        elif 'synthetic' in text_source_kind:
            print(
                "  [TEXT BENCHMARK] Text is generated from symptom templates; "
                "scores measure held-out-template recognition, not field-text "
                "generalization."
            )

    # Keep one deterministic representative per independent training source.
    # Export variants are distinct files/tensors but not independent evidence.
    source_unique_real_image_train = []
    source_unique_real_label_train_img = []
    source_unique_real_groups_train = []
    _seen_training_source_groups = set()
    for image, label, source_group in zip(
        real_image_train, real_label_train_img, image_split_groups_train
    ):
        source_group = str(source_group)
        # Linked components may contain several genuine lesion crops, including
        # different labels from one source photo. Retain every linked row and
        # keep the component intact later during client partitioning. Only the
        # unlinked Roboflow export path deduplicates near-identical files.
        if (not linked_pair_mode
                and source_group in _seen_training_source_groups):
            continue
        _seen_training_source_groups.add(source_group)
        source_unique_real_image_train.append(image)
        source_unique_real_label_train_img.append(label)
        source_unique_real_groups_train.append(source_group)
    if not source_unique_real_image_train:
        raise RuntimeError("No independent real-image training sources remain")
    source_unique_train_class_counts = _image_split_counts(
        source_unique_real_label_train_img
    )
    image_split_audit[
        'train_linked_row_class_counts'
        if linked_pair_mode else 'train_independent_source_class_counts'
    ] = dict(source_unique_train_class_counts)
    # Filename-and-box linked rows are genuine distinct lesion observations and
    # remain available to the linked benchmark. Unlinked sorted exports use one
    # representative per source to avoid double-weighting near duplicates.
    if linked_pair_mode:
        model_real_image_train = list(real_image_train)
        model_real_label_train_img = list(real_label_train_img)
        model_real_train_groups = list(image_split_groups_train)
    else:
        model_real_image_train = list(source_unique_real_image_train)
        model_real_label_train_img = list(source_unique_real_label_train_img)
        model_real_train_groups = list(source_unique_real_groups_train)
    if len(model_real_train_groups) != len(model_real_image_train):
        raise RuntimeError(
            'Training image rows and source groups are misaligned; grouped '
            'cross-validation cannot be built safely'
        )
    if linked_pair_mode:
        print(
            "  Linked training support retained: "
            f"{len(source_unique_real_image_train)} lesion rows in "
            f"{len(set(source_unique_real_groups_train))} connected source "
            f"groups; row classes={source_unique_train_class_counts}"
        )
    else:
        print(
            "  Independent real-image training support: "
            f"{len(source_unique_real_image_train)} sources from "
            f"{len(real_image_train)} files; classes="
            f"{source_unique_train_class_counts}"
        )

    _fill_target = int(getattr(config, "image_fill_target", 0) or 0)
    _fill_strategy = str(getattr(config, 'image_fill_strategy', 'real_oversample')).lower()
    if _fill_strategy not in {'real_oversample', 'synthetic'}:
        raise ValueError("image_fill_strategy must be 'real_oversample' or 'synthetic'")
    _train_fill_counts = {}
    model_train_synthetic_count = 0
    if _fill_strategy == 'real_oversample':
        # BalancedBatchSampler performs replacement sampling online. The
        # historical fill target is intentionally ignored in the real-data
        # protocol so duplicate tensors are never materialized twice.
        print(
            "  Train balancing: no duplicate tensors materialized; "
            f"BalancedBatchSampler resamples {len(model_real_image_train)} "
            "real training rows online with fresh augmentation."
        )
    elif _fill_target > 0:
        _train_cls_counts = {
            i: sum(
                _single_label_index(label) == i
                for label in model_real_label_train_img
            )
            for i in range(len(STRESS_LABELS))
        }
        for cls_idx, cnt in _train_cls_counts.items():
            need = max(0, _fill_target - cnt)
            if need > 0:
                additions, addition_labels = generate_stress_specific_images(
                    cls_idx, need, img_size=config.image_size
                )
                model_real_image_train.extend(additions)
                model_real_label_train_img.extend(addition_labels)
                # Each synthetic image is its own independent source so the
                # grouped CV splitter keeps treating real photographs, not
                # generated fill, as the correlated unit.
                model_real_train_groups.extend(
                    f'synthetic_fill_{STRESS_LABELS[cls_idx]}_{index}'
                    for index in range(len(additions))
                )
                _train_fill_counts[STRESS_LABELS[cls_idx]] = len(additions)
                model_train_synthetic_count += len(additions)
                print(f"    {STRESS_LABELS[cls_idx]}: train {cnt} real "
                      f"+{len(additions)} {_fill_strategy} -> {cnt + len(additions)}")
        print(
            f"  Explicit synthetic-fill ablation: {len(model_real_image_train)} "
            f"training rows ({model_train_synthetic_count} synthetic); "
            f"val/test stay {len(image_val)}/{len(image_test)} real-only"
        )
    else:
        print(
            f"  Fill disabled; train {len(model_real_image_train)} / val "
            f"{len(image_val)} / test {len(image_test)}, all real"
        )

    # Compute a fingerprint of the loaded dataset so stale checkpoints from different
    # data runs are detected and force-retrained even if their F1 is in a valid range.
    import hashlib as _hl
    _img_cls_c = {
        STRESS_LABELS[i]: sum(1 for l in img_labels_all if (l[0] if isinstance(l, list) else l) == i)
        for i in range(len(STRESS_LABELS))
    }
    _text_cls_c = {
        STRESS_LABELS[i]: sum(
            1 for label in text_labels
            if (label[0] if isinstance(label, list) else label) == i
        ) for i in range(len(STRESS_LABELS))
    }
    # Include text content and the evaluation protocol in the checkpoint identity.
    # The old fingerprint used image class counts only, so a changed/leaky text
    # split could accidentally reuse an incompatible checkpoint.
    _text_fingerprint_rows = "\n".join(
        f"{_normalise_text_for_split(text)}\t{_single_label_index(label)}"
        for text, label in zip(text_df["text"].tolist(), text_labels)
    )
    _text_content_digest = _hl.sha256(_text_fingerprint_rows.encode("utf-8")).hexdigest()[:12]
    _text_split_assignment_rows = []
    for _split_name, _split_texts, _split_labels in (
        ('train', texts_train, label_train_txt),
        ('val', texts_val, label_val_txt),
        ('test', texts_test, label_test_txt),
    ):
        _text_split_assignment_rows.extend(
            f"{_split_name}\t{_normalise_text_for_split(text)}\t"
            f"{_single_label_index(label)}"
            for text, label in zip(_split_texts, _split_labels)
        )
    _text_split_digest = _hl.sha256(
        "\n".join(sorted(_text_split_assignment_rows)).encode('utf-8')
    ).hexdigest()[:12]
    _image_split_assignment_rows = []
    for _split_name, _split_groups, _split_labels in (
        ('train', image_split_groups_train, label_train_img),
        ('val', image_split_groups_val, label_val_img),
        ('test', image_split_groups_test, label_test_img),
    ):
        _image_split_assignment_rows.extend(
            f"{_split_name}\t{group}\t{_single_label_index(label)}"
            for group, label in zip(_split_groups, _split_labels)
        )
    _image_split_digest = _hl.sha256(
        "\n".join(sorted(_image_split_assignment_rows)).encode('utf-8')
    ).hexdigest()[:12]

    # Counts alone cannot identify an image dataset: replacing every image
    # while keeping the same class totals must invalidate vision and fusion
    # checkpoints. Hash stable relative paths plus file bytes from the resolved
    # real-image tree. (Only ~200 source images are used, so this is inexpensive.)
    _image_digest = _hl.sha256()
    _image_file_count = 0
    _image_root = Path(benchmark_image_root).resolve()
    for _image_path in sorted(
        (p for p in _image_root.rglob('*')
         if p.is_file() and p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.bmp', '.webp'}),
        key=lambda p: p.relative_to(_image_root).as_posix(),
    ):
        _relative_image_path = _image_path.relative_to(_image_root).as_posix()
        _image_digest.update(_relative_image_path.encode('utf-8'))
        with _image_path.open('rb') as _image_file:
            for _chunk in iter(lambda: _image_file.read(1024 * 1024), b''):
                _image_digest.update(_chunk)
        _image_file_count += 1
    _image_content_digest = _image_digest.hexdigest()[:12]

    # Audit any filename-linked source annotation that can establish the real
    # taxonomy. A self-authored folder manifest is not evidence that renamed
    # classes still describe the photographed disease.
    taxonomy_audit = {
        'status': 'unverified',
        'claim_eligible': False,
        'source': None,
        'matched_image_files': 0,
        'observed_id_to_name': {},
        'configured_id_to_name': {
            str(index): label for index, label in enumerate(STRESS_LABELS)
        },
        'note': (
            'No independent filename-linked taxonomy source was available; '
            'high scores must not be interpreted as verified disease semantics.'
        ),
    }
    linked_taxonomy_candidates = [
        text_data_dir / 'linked_annotations.csv',
        _repo_root / 'tea_results' / 'annotation' / 'annotations.csv',
    ]
    image_filenames = {
        path.name for path in Path(data_dir).rglob('*')
        if path.is_file() and path.suffix.lower() in {
            '.jpg', '.jpeg', '.png', '.bmp', '.webp'
        }
    }
    for linked_taxonomy_path in linked_taxonomy_candidates:
        if not linked_taxonomy_path.is_file():
            continue
        try:
            linked_df = pd.read_csv(linked_taxonomy_path)
            required_columns = {'image_file', 'class_id', 'disease'}
            if not required_columns.issubset(linked_df.columns):
                continue
            linked_df['class_id'] = pd.to_numeric(
                linked_df['class_id'], errors='raise'
            ).astype(int)
            matched_df = linked_df[
                linked_df['image_file'].astype(str).map(
                    lambda value: Path(value).name in image_filenames
                )
            ].copy()
            if len(matched_df) < len(STRESS_LABELS):
                continue
            observed_mapping = {}
            for class_id, class_rows in matched_df.groupby('class_id'):
                disease_names = class_rows['disease'].astype(str).str.strip().str.lower()
                if len(disease_names):
                    observed_mapping[str(int(class_id))] = disease_names.mode().iloc[0]
            configured_mapping = {
                str(index): label.lower() for index, label in enumerate(STRESS_LABELS)
            }
            mismatches = {
                class_id: {
                    'source': source_name,
                    'configured': configured_mapping.get(class_id),
                }
                for class_id, source_name in observed_mapping.items()
                if configured_mapping.get(class_id) != source_name
            }
            taxonomy_audit.update({
                'status': 'mismatch' if mismatches else 'verified',
                'claim_eligible': not bool(mismatches),
                'source': str(linked_taxonomy_path),
                'matched_image_files': int(
                    matched_df['image_file'].astype(str).nunique()
                ),
                'observed_id_to_name': observed_mapping,
                'mismatches': mismatches,
                'note': (
                    'Filename-linked source taxonomy contradicts configured labels.'
                    if mismatches else
                    'Filename-linked source taxonomy matches configured labels.'
                ),
            })
            break
        except Exception as taxonomy_error:
            taxonomy_audit['note'] = (
                f'Taxonomy audit failed for {linked_taxonomy_path}: {taxonomy_error}'
            )
    if taxonomy_audit['status'] != 'verified':
        print("\n  [DATA INTEGRITY WARNING] Disease taxonomy is not verified.")
        print(f"    Status: {taxonomy_audit['status']}")
        print(f"    {taxonomy_audit['note']}")
        if taxonomy_audit.get('observed_id_to_name'):
            print(
                "    Filename-linked source mapping: "
                f"{taxonomy_audit['observed_id_to_name']}"
            )
        print(
            "    Training may continue as an engineering diagnostic, but the "
            "pipeline will not emit a publication claim that the proposed "
            "disease model is best until this is repaired."
        )

    _fingerprint_parts = [
        "evaluation_protocol:template_group_heldout_v4_diverse_proxy_support",
        f"tokenizer:{config.pretrained_text_tokenizer if config.use_pretrained_backbones else 'stable_blake2b_v1'}",
        "text_encoder:lightweight_transformer_masked_pool_v2",
        "vision_encoder:lightweight_residual_cnn_v2",
        f"label_schema:{STRESS_SCHEMA_VERSION}",
        f"text_digest:{_text_content_digest}",
        f"text_split_digest:{_text_split_digest}",
        f"text_source_kind:{text_source_kind}",
        f"image_digest:{_image_content_digest}",
        f"image_split_protocol:{image_split_audit['protocol']}",
        f"image_split_digest:{_image_split_digest}",
        f"seed:{config.seed}",
        f"train_split:{config.train_split}",
        f"image_size:{int(config.image_size)}",
        f"max_seq_length:{int(config.max_seq_length)}",
        f"image_fill_target:"
        f"{_fill_target if _fill_strategy == 'synthetic' else 'online_only'}",
        f"image_fill_strategy:{_fill_strategy}",
        "checkpoint_selection:validation_macro_micro_nll_v1",
        "balanced_sampler:epoch_scaled_largest_class_v2",
        "vlm_train_support:independent_sources_online_pairing_v2",
        "proxy_text_pairing:template_round_robin_v1",
        "image_loader_order:sorted_then_seeded_shuffle_v1",
        "image_preprocess:deterministic_split_online_crop_color_aug_v3",
        *[f"image_{key}:{value}" for key, value in sorted(_img_cls_c.items())],
    ]
    data_fingerprint = _hl.sha256("|".join(_fingerprint_parts).encode("utf-8")).hexdigest()[:12]

    # Flat int labels for BalancedBatchSampler
    flat_labels_txt = [l[0] if isinstance(l, list) else l for l in label_train_txt]
    flat_labels_img = [l[0] if isinstance(l, list) else l for l in label_train_img]

    # ── [3/8] Pair text+images by label for VLM ─────────────────────────────
    print("\n[3/8] Pairing text + images by label for VLM training...")
    txt_by_lbl = {i: [] for i in range(len(STRESS_LABELS))}
    img_by_lbl = {i: [] for i in range(len(STRESS_LABELS))}
    for t, l in zip(texts_train, label_train_txt):
        li = l[0] if isinstance(l, list) else l
        txt_by_lbl[li].append(t)
    # Carry the image's source-photo group alongside the tensor so each paired
    # row can be assigned a leakage-safe cross-validation group below.
    for img, l, src in zip(
        model_real_image_train, model_real_label_train_img,
        model_real_train_groups,
    ):
        li = l[0] if isinstance(l, list) else l
        img_by_lbl[li].append((img, str(src)))

    mm_texts_tr, mm_images_tr, mm_labels_tr = [], [], []
    mm_image_sources_tr = []
    pairing_rng = random.Random(config.seed + 7301)
    for li in range(len(STRESS_LABELS)):
        text_pool = list(txt_by_lbl[li])
        image_pool = list(img_by_lbl[li])
        if not text_pool or not image_pool:
            raise ValueError(
                f"VLM training requires both modalities for {STRESS_LABELS[li]}"
            )
        pairing_rng.shuffle(image_pool)
        # Keep one row per independent real training image. BalancedBatchSampler
        # and online same-class pairing already provide fresh repeated views;
        # physically expanding five Hopper sources to 200 rows and then
        # resampling them again caused needless double oversampling.
        n = min(len(text_pool), len(image_pool))
        selected_texts = select_template_diverse_texts(
            text_pool, n, seed=config.seed + 7311 + li
        )
        mm_texts_tr.extend(selected_texts)
        mm_images_tr.extend(image for image, _ in image_pool[:n])
        mm_image_sources_tr.extend(source for _, source in image_pool[:n])
        mm_labels_tr.extend([[li]] * n)
    combined = list(zip(
        mm_texts_tr, mm_images_tr, mm_labels_tr, mm_image_sources_tr
    ))
    pairing_rng.shuffle(combined)
    (mm_texts_tr, mm_images_tr, mm_labels_tr,
     mm_image_sources_tr) = map(list, zip(*combined))
    flat_labels_mm = [l[0] for l in mm_labels_tr]

    # Connected grouping over BOTH modalities for paired cross-validation. Two
    # rows must share a fold if they share an image source OR a text template,
    # otherwise a fold boundary could be crossed by two export variants of one
    # photograph or two paraphrases of one template. Union-find gives the
    # transitive closure of those two relations in one pass.
    _pair_parent = list(range(len(mm_texts_tr)))

    def _pair_find(index):
        while _pair_parent[index] != index:
            _pair_parent[index] = _pair_parent[_pair_parent[index]]
            index = _pair_parent[index]
        return index

    def _pair_union(left, right):
        left_root, right_root = _pair_find(left), _pair_find(right)
        if left_root != right_root:
            _pair_parent[right_root] = left_root

    _seen_pair_image, _seen_pair_template = {}, {}
    for _pair_index, (_pair_text, _pair_source) in enumerate(
        zip(mm_texts_tr, mm_image_sources_tr)
    ):
        _template_key = _text_template_group_key(_pair_text)
        if _pair_source in _seen_pair_image:
            _pair_union(_pair_index, _seen_pair_image[_pair_source])
        else:
            _seen_pair_image[_pair_source] = _pair_index
        if _template_key in _seen_pair_template:
            _pair_union(_pair_index, _seen_pair_template[_template_key])
        else:
            _seen_pair_template[_template_key] = _pair_index
    mm_pair_groups_tr = [
        f'pair_component_{_pair_find(index)}'
        for index in range(len(mm_texts_tr))
    ]
    print(
        f"  VLM paired training rows: {len(mm_texts_tr)} in "
        f"{len(set(mm_pair_groups_tr))} independent image/template components"
    )

    # Val pairing
    txt_by_lbl_v = {i: [] for i in range(len(STRESS_LABELS))}
    img_by_lbl_v = {i: [] for i in range(len(STRESS_LABELS))}
    for t, l in zip(texts_val, label_val_txt):
        li = l[0] if isinstance(l, list) else l
        txt_by_lbl_v[li].append(t)
    for img, l in zip(image_val, label_val_img):
        li = l[0] if isinstance(l, list) else l
        img_by_lbl_v[li].append(img)
    mm_texts_v, mm_images_v, mm_labels_v = [], [], []
    for li in range(len(STRESS_LABELS)):
        n = min(len(txt_by_lbl_v[li]), len(img_by_lbl_v[li]))
        mm_texts_v.extend(select_template_diverse_texts(
            txt_by_lbl_v[li], n, seed=config.seed + 7321 + li
        ))
        mm_images_v.extend(img_by_lbl_v[li][:n])
        mm_labels_v.extend([[li]] * n)

    # Test pairs are deliberately held out from model selection. These are
    # label-aligned proxy pairs, not verified text/image observations of the
    # same leaf, so VLM results must not be described as paired-field results.
    txt_by_lbl_te = {i: [] for i in range(len(STRESS_LABELS))}
    img_by_lbl_te = {i: [] for i in range(len(STRESS_LABELS))}
    for t, l in zip(texts_test, label_test_txt):
        li = l[0] if isinstance(l, list) else l
        txt_by_lbl_te[li].append(t)
    for img, l in zip(image_test, label_test_img):
        li = l[0] if isinstance(l, list) else l
        img_by_lbl_te[li].append(img)
    mm_texts_te, mm_images_te, mm_labels_te = [], [], []
    for li in range(len(STRESS_LABELS)):
        n = min(len(txt_by_lbl_te[li]), len(img_by_lbl_te[li]))
        mm_texts_te.extend(select_template_diverse_texts(
            txt_by_lbl_te[li], n, seed=config.seed + 7331 + li
        ))
        mm_images_te.extend(img_by_lbl_te[li][:n])
        mm_labels_te.extend([[li]] * n)

    if linked_pair_mode:
        mm_texts_tr, mm_images_tr, mm_labels_tr = linked_mm_train
        mm_texts_v, mm_images_v, mm_labels_v = linked_mm_val
        mm_texts_te, mm_images_te, mm_labels_te = linked_mm_test
        flat_labels_mm = [_single_label_index(label) for label in mm_labels_tr]
        # Linked rows already carry a connected source/text component id.
        mm_pair_groups_tr = list(image_split_groups_train)
        print(
            "  VLM genuine sample-linked pairs: "
            f"{len(mm_texts_tr)} train, {len(mm_texts_v)} val, "
            f"{len(mm_texts_te)} test"
        )
    else:
        print(f"  VLM proxy pairs (unique source-image support with online same-class resampling; not sample-linked): "
              f"{len(mm_texts_tr)} train, {len(mm_texts_v)} val, {len(mm_texts_te)} test")
    vlm_pairing_semantics = (
        'filename_and_box_linked_same_observation'
        if linked_pair_mode else 'label_aligned_not_sample_linked'
    )
    vlm_evaluation_scope = (
        'same held-out source-image-grouped, filename-and-box-linked observations'
        if linked_pair_mode else
        'same held-out label-aligned proxy pairs; not sample-linked observations'
    )

    results = {"llm_models": {}, "vit_models": {}, "vlm_models": {},
               "centralized": {}, "federated": {},
               "dataset_info": {
                   "source": (
                       "genuine filename-and-box-linked crop/text observations"
                       if linked_pair_mode else
                       "real image dataset + separately supplied text CSV"
                   ),
                   "image_path": str(benchmark_image_root),
                   "text_path": str(text_data_dir),
                   "annotations_csv": str(
                       linked_pair_info['annotation_csv']
                       if linked_pair_mode else text_data_dir / "annotations.csv"
                   ),
                   "text_source_kind": text_source_kind,
                   "label_schema": STRESS_SCHEMA_VERSION,
                   "text_split_audit": text_split_audit,
                   "image_split_audit": image_split_audit,
                   "evaluation_protocol": (
                       "source-image-grouped held-out validation and test"
                       if linked_pair_mode else
                       "source-photo-grouped images plus template-group-held-out "
                       "text; final model scores use test"
                   ),
                     "vlm_pairing": (
                         "text and crop are filename-and-box linked to the same source observation"
                         if linked_pair_mode else
                         "training uses independent source-image support with stochastic "
                         "same-class partners; val/test cover held-out text templates "
                         "round-robin but remain label-aligned proxy pairs, not verified "
                         "sample-linked observations"
                     ),
                    "linked_pair_mode": linked_pair_mode,
                    "source_taxonomy": (
                        sorted(set(linked_pair_info['source_diseases']))
                        if linked_pair_mode else None
                    ),
                   "image_count": len(images_all),
                   "text_count": len(text_df),
                   "image_class_counts": _img_cls_c,
                   "text_class_counts": _text_cls_c,
                   "image_file_count": _image_file_count,
                   "image_content_digest": _image_content_digest,
                   "text_content_digest": _text_content_digest,
                    "taxonomy_audit": taxonomy_audit,
                    "train_balance_fill": _train_fill_counts,
                    "train_fill_strategy": _fill_strategy,
                    "train_balance_materialized": bool(
                        _fill_strategy == 'synthetic'
                        and model_train_synthetic_count > 0
                    ),
                    "model_train_synthetic_count": model_train_synthetic_count,
                   "image_fill_target": _fill_target,
                   "val_images_all_real": True,
                   "test_images_all_real": True,
                   "fingerprint": data_fingerprint,
               }}

    # ── [4/8] LLM Training ───────────────────────────────────────────────────
    print("\n" + "=" * 70)
    print("[4/8] TRAINING 5 LLM MODELS")
    print("=" * 70)

    benchmark_tokenizer = None
    if bool(getattr(config, 'use_pretrained_backbones', True)):
        try:
            from transformers import AutoTokenizer
            benchmark_tokenizer = AutoTokenizer.from_pretrained(
                str(config.pretrained_text_tokenizer), use_fast=True
            )
            print(
                "  [Transfer learning] Tokenizer loaded: "
                f"{config.pretrained_text_tokenizer}"
            )
        except Exception as tokenizer_error:
            if not bool(getattr(config, 'allow_lightweight_fallback', False)):
                raise RuntimeError(
                    "Pretrained backbones were requested but the tokenizer "
                    "could not be loaded. Check network/cache access, or set "
                    "allow_lightweight_fallback=True explicitly."
                ) from tokenizer_error
            print(
                "  [WARN] Pretrained tokenizer unavailable; using explicit "
                f"lightweight fallback: {tokenizer_error}"
            )

    text_train_ds = TextDataset(
        text_train, benchmark_tokenizer, config.max_seq_length
    )
    text_val_ds = TextDataset(
        text_val, benchmark_tokenizer, config.max_seq_length
    )
    text_test_ds = TextDataset(
        text_test, benchmark_tokenizer, config.max_seq_length
    )
    train_loader  = create_balanced_dataloader(
        text_train_ds, flat_labels_txt, batch_size=config.batch_size,
        num_classes=config.num_labels, shuffle=True,
    )
    text_val_loader = DataLoader(text_val_ds, batch_size=config.batch_size)
    val_loader = text_val_loader
    text_test_loader = DataLoader(text_test_ds, batch_size=config.batch_size)
    text_validation_group_ids = None
    if not linked_pair_mode:
        text_validation_group_ids = effective_text_group_ids(
            text_val['text'].tolist(), text_val['labels'].tolist()
        )
        print(
            "  [Text selection] Checkpoints/models are ranked on "
            f"{len(set(text_validation_group_ids))} independent validation "
            f"template groups, aggregated from {len(text_validation_group_ids)} rows."
        )
    results['dataset_info']['text_model_selection'] = {
        'scope': (
            'independent_first_sentence_template_groups'
            if text_validation_group_ids is not None else
            'validation_rows_for_linked_observations'
        ),
        'validation_rows': int(len(text_val)),
        'independent_validation_groups': (
            int(len(set(text_validation_group_ids)))
            if text_validation_group_ids is not None else None
        ),
        'primary_metric': 'macro_f1',
        'test_used_for_selection': False,
    }

    print("  [Protocol] Validation selects checkpoints; reported LLM F1 is held-out template-group test F1.")
    using_pretrained_text = bool(
        getattr(config, 'use_pretrained_backbones', True)
        and benchmark_tokenizer is not None
    )
    print(
        "  [Model note] "
        + (
            "Loading the actual pretrained Hugging Face encoder for every named run."
            if using_pretrained_text else
            "Using the explicitly enabled lightweight scratch fallback."
        )
    )
    print(
        "  [Text memory] Activation checkpointing is "
        + (
            "explicitly enabled."
            if bool(config.pretrained_text_gradient_checkpointing) else
            "disabled (stable eager backward for short sequences)."
        )
    )

    import gc

    def _heldout_evidence(metrics):
        """Compact JSON-safe support/uncertainty fields for result tables."""
        return {
            'n_test': int(metrics['n_samples']),
            'n_correct': int(metrics['n_correct']),
            'accuracy_ci95_low': float(metrics['accuracy_ci95_low']),
            'accuracy_ci95_high': float(metrics['accuracy_ci95_high']),
            'accuracy_ci_method': metrics['accuracy_ci_method'],
            'test_class_support': {
                str(label): int(count)
                for label, count in metrics.get(
                    'label_distribution', {}
                ).items()
            },
            'test_prediction_distribution': {
                str(label): int(count)
                for label, count in metrics.get(
                    'pred_distribution', {}
                ).items()
            },
            'test_per_class_recall_ci95': {
                str(label): {
                    key: (int(value) if key in {'n', 'correct'} else value)
                    for key, value in interval.items()
                }
                for label, interval in metrics.get(
                    'per_class_recall_ci95', {}
                ).items()
            },
        }

    def _text_group_evidence(metrics):
        """Aggregate synthetic/template rows to their independent test groups."""
        from collections import Counter, defaultdict

        test_texts = text_test['text'].tolist()
        labels = np.asarray(metrics['labels'], dtype=int)
        grouped_indices = defaultdict(list)
        if linked_pair_mode:
            linked_test_groups = _linked_values('groups', linked_test_idx)
            for row_index, group in enumerate(linked_test_groups):
                grouped_indices[str(group)].append(row_index)
            interval_scope = 'source-image groups'
        else:
            grouped_metrics = aggregate_classification_metrics_by_group(
                metrics,
                effective_text_group_ids(test_texts, labels.tolist()),
            )
            return {
                'independent_test_groups': int(grouped_metrics['n_samples']),
                'independent_group_correct': int(grouped_metrics['n_correct']),
                'independent_group_accuracy': float(
                    grouped_metrics['accuracy']
                ),
                'independent_group_f1_micro': float(
                    grouped_metrics['f1_micro']
                ),
                'independent_group_f1_macro': float(
                    grouped_metrics['f1_macro']
                ),
                'independent_group_rule': (
                    'mean class probability within template group'
                ),
                'group_accuracy_ci95_low': float(
                    grouped_metrics['accuracy_ci95_low']
                ),
                'group_accuracy_ci95_high': float(
                    grouped_metrics['accuracy_ci95_high']
                ),
                'group_accuracy_ci_method': (
                    'Wilson interval over independent first-sentence '
                    'template groups'
                ),
            }
        predictions = np.asarray(metrics['predictions'], dtype=int)
        group_correct = 0
        for indices in grouped_indices.values():
            if linked_pair_mode:
                # A source photograph can contain boxes from more than one
                # class. Count the independent source group as correct only
                # when every evaluated crop from it is correct.
                group_correct += int(
                    all(predictions[index] == labels[index] for index in indices)
                )
                continue
            true_labels = {int(labels[index]) for index in indices}
            if len(true_labels) != 1:
                raise RuntimeError("A held-out text group contains conflicting labels")
            counts = Counter(int(predictions[index]) for index in indices)
            predicted_label = min(
                (-count, label) for label, count in counts.items()
            )[1]
            group_correct += int(predicted_label == next(iter(true_labels)))
        group_total = len(grouped_indices)
        low, high = wilson_score_interval(group_correct, group_total)
        return {
            'independent_test_groups': group_total,
            'independent_group_correct': group_correct,
            'independent_group_accuracy': group_correct / group_total,
            'independent_group_rule': (
                'all crops from source correct' if linked_pair_mode
                else 'majority row prediction within template group'
            ),
            'group_accuracy_ci95_low': float(low),
            'group_accuracy_ci95_high': float(high),
            'group_accuracy_ci_method': (
                f'Wilson interval over {interval_scope}'
            ),
        }

    def _new_text_benchmark(model_id):
        if using_pretrained_text:
            benchmark_model = HuggingFaceTextClassifier(
                model_id,
                num_labels=config.num_labels,
                enable_gradient_checkpointing=bool(
                    config.pretrained_text_gradient_checkpointing
                ),
            )
            benchmark_model.pretrained_learning_rate = float(
                config.pretrained_text_learning_rate
            )
            return benchmark_model.to(device)
        return LightweightTextClassifier(num_labels=config.num_labels).to(device)

    # ---- Grouped out-of-fold CV over the text training rows --------------
    # Run BEFORE the named models train, because it supplies two things they
    # need: the architecture ranking used later to pick a fusion parent, and
    # the epoch curve used to set each model's epoch budget. The validation
    # split cannot do the latter -- it collapses to ~8 independent template
    # groups and saturates at 1.0 across several architectures.
    parent_selection_protocol = str(
        getattr(config, 'parent_selection_protocol', 'validation')
    ).lower()
    if parent_selection_protocol not in {'validation', 'out_of_fold_cv'}:
        raise ValueError(
            "parent_selection_protocol must be 'validation' or 'out_of_fold_cv'"
        )
    parent_cv_folds = max(2, int(getattr(config, 'parent_selection_cv_folds', 3)))
    epoch_selection_protocol = str(
        getattr(config, 'epoch_selection_protocol', 'validation')
    ).lower()
    if epoch_selection_protocol not in {'validation', 'cross_validated'}:
        raise ValueError(
            "epoch_selection_protocol must be 'validation' or 'cross_validated'"
        )
    text_oof_scores, vision_oof_scores = {}, {}

    def _make_text_cv_dataset(features, labels, is_train):
        frame = pd.DataFrame({'text': list(features), 'labels': list(labels)})
        return TextDataset(frame, benchmark_tokenizer, config.max_seq_length)

    def _make_vision_cv_dataset(features, labels, is_train):
        return ImageDataset(
            list(features), list(labels), augment_images=bool(is_train),
            minority_augment_max_strength=getattr(
                config, 'minority_augment_max_strength', 1.0
            ),
        )

    def _cv_epoch_budget(oof_scores, model_name):
        """Epoch count and deployment mode for one model, from its CV curve."""
        if epoch_selection_protocol != 'cross_validated':
            return None, False
        entry = oof_scores.get(model_name) or {}
        best_epoch = entry.get('cv_best_epoch')
        if not best_epoch:
            return None, False
        return int(best_epoch), True

    if parent_selection_protocol == 'out_of_fold_cv':
        print("\n>>> Grouped out-of-fold CV over text training rows...")
        print(
            f"    Rationale: the validation split holds only "
            f"{len(set(text_validation_group_ids or []))} independent template "
            f"groups, which cannot rank five architectures or an epoch budget. "
            f"CV uses all {len(text_train)} training rows and never reads test."
        )
        print(f"    Cost: {parent_cv_folds} folds x {len(LLM_MODELS)} text refits.")
        text_cv_texts = text_train['text'].tolist()
        text_cv_labels = text_train['labels'].tolist()
        text_cv_groups = effective_text_group_ids(text_cv_texts, text_cv_labels)
        for _cv_name, _cv_id in LLM_MODELS.items():
            try:
                text_oof_scores[_cv_name] = out_of_fold_architecture_score(
                    lambda model_id=_cv_id: _new_text_benchmark(model_id),
                    text_cv_texts, text_cv_labels, text_cv_groups,
                    _make_text_cv_dataset, config, device, 'text',
                    n_splits=parent_cv_folds, seed=config.seed,
                    diversity_weight=0.04 if using_pretrained_text else 1.0,
                    batch_size=config.batch_size,
                )
                _entry = text_oof_scores[_cv_name]
                print(
                    f"    [text CV] {_cv_name}: out-of-fold macro-F1="
                    f"{_entry['f1_macro']:.4f} (n={_entry['n']}), "
                    f"best epoch={_entry['cv_best_epoch']} "
                    f"(curve macro-F1={_entry['cv_best_epoch_f1_macro']:.4f})"
                )
            except Exception as _cv_error:
                print(f"    [WARN] text CV failed for {_cv_name}: {_cv_error}")

    for model_name, model_id in LLM_MODELS.items():
        checkpoint_path = config.checkpoint_dir / f"llm_{model_name.lower().replace('-','_')}_best.pt"
        text_cv_epochs, text_use_final_epoch = _cv_epoch_budget(
            text_oof_scores, model_name
        )
        text_model_fingerprint = _hl.sha256(
            (
                f"{data_fingerprint}|text_transfer_v7_stable_backward|{model_id}|"
                f"pretrained:{using_pretrained_text}|"
                f"gradient_checkpointing:"
                f"{bool(config.pretrained_text_gradient_checkpointing)}|"
                f"tokenizer:{config.pretrained_text_tokenizer}|"
                f"max_length:{int(config.max_seq_length)}|"
                f"epochs:{int(config.pretrained_epochs)}|"
                f"lr:{float(config.pretrained_text_learning_rate):.12g}|"
                f"weight_decay:{float(config.weight_decay):.12g}|"
                f"batch:{int(config.batch_size)}|"
                f"accumulation:{int(config.gradient_accumulation_steps)}|"
                f"warmup:{float(config.warmup_ratio):.8g}|"
                f"patience:{int(config.early_stopping_patience)}|"
                f"mixed_precision:{bool(config.use_mixed_precision)}|"
                "scheduler:optimizer_update_cosine_v2|diversity:0.04|"
                f"selection:{'group_macro_micro_then_row_macro_micro_v2' if text_validation_group_ids is not None else 'row_macro_micro_nll_v1'}|"
                f"validation_groups:{len(set(text_validation_group_ids or []))}|"
                f"epoch_selection:{epoch_selection_protocol}|"
                f"cv_epochs:{text_cv_epochs}|"
                "sampler:epoch_scaled_v2"
            ).encode('utf-8')
        ).hexdigest()[:12]
        if checkpoint_path.exists():
            try:
                ckpt = torch.load(checkpoint_path, map_location="cpu")
                saved_f1 = ckpt.get("f1_score", 0.0)
                compatible = (
                    ckpt.get('model_fingerprint') == text_model_fingerprint
                    and ckpt.get('pretrained_model_id')
                    == (model_id if using_pretrained_text else None)
                )
                fingerprint_mismatch = not compatible
                ckpt_fingerprint = ckpt.get('model_fingerprint')
                if compatible:
                    model = _new_text_benchmark(model_id)
                    model.load_state_dict(ckpt["model_state_dict"])
                    test_metrics = evaluate(model, text_test_loader, device, "text")
                    text_group_evidence = _text_group_evidence(test_metrics)
                    validation_selection_metrics = ckpt.get(
                        'validation_selection_metrics', {}
                    ) or {}
                    selection_macro = validation_selection_metrics.get(
                        'f1_macro'
                    )
                    selection_micro = validation_selection_metrics.get(
                        'f1_micro'
                    )
                    selection_summary = (
                        f"independent-group validation macro/micro-F1="
                        f"{float(selection_macro):.4f}/{float(selection_micro):.4f}; "
                        if selection_macro is not None and selection_micro is not None
                        else "validation selection metrics unavailable; "
                    )
                    print(f"\n>>> [SKIP] {model_name}: checkpoint found ("
                          f"{selection_summary}row validation micro-F1="
                          f"{saved_f1:.4f}; headline held-out independent "
                          f"groups "
                          f"{text_group_evidence['independent_group_correct']}/"
                          f"{text_group_evidence['independent_test_groups']} "
                          f"[CI {text_group_evidence['group_accuracy_ci95_low']:.3f}-"
                          f"{text_group_evidence['group_accuracy_ci95_high']:.3f}]; "
                          f"row diagnostic {test_metrics['n_correct']}/"
                          f"{test_metrics['n_samples']}, micro/macro-F1="
                          f"{test_metrics['f1_micro']:.4f}/"
                          f"{test_metrics['f1_macro']:.4f}).")
                    results["llm_models"][model_name] = {
                        "f1": text_group_evidence.get(
                            "independent_group_f1_micro",
                            text_group_evidence["independent_group_accuracy"],
                        ),
                        "f1_macro": text_group_evidence.get(
                            "independent_group_f1_macro", test_metrics["f1_macro"]
                        ),
                        "precision": test_metrics["precision"], "recall": test_metrics["recall"],
                        "accuracy": text_group_evidence[
                            "independent_group_accuracy"
                        ],
                        "row_test_f1": test_metrics["f1_micro"],
                        "row_test_f1_macro": test_metrics["f1_macro"],
                        "row_test_accuracy": test_metrics["accuracy"],
                        "validation_f1": saved_f1,
                        "validation_f1_macro": (
                            float(ckpt['validation_f1_macro'])
                            if ckpt.get('validation_f1_macro') is not None else None
                        ),
                        "validation_selection_scope": ckpt.get(
                            'validation_selection_scope', 'validation_rows'
                        ),
                        "validation_selection_f1": validation_selection_metrics.get(
                            'f1_micro'
                        ),
                        "validation_selection_f1_macro": (
                            validation_selection_metrics.get('f1_macro')
                        ),
                        "validation_independent_groups": ckpt.get(
                            'validation_independent_groups'
                        ),
                        **_heldout_evidence(test_metrics),
                        **text_group_evidence,
                        "test_f1": test_metrics["f1_micro"],
                        "params": ckpt.get("num_params", 0),
                        "history": [], "checkpoint": str(checkpoint_path),
                        "per_class_f1": test_metrics.get("per_class_f1"),
                        "implementation": ckpt.get('implementation'),
                        "model_class": ckpt.get('model_class'),
                        "pretrained_model_id": ckpt.get('pretrained_model_id'),
                        "tokenizer_id": ckpt.get('tokenizer_id'),
                        "pretrained": bool(ckpt.get('pretrained')),
                        "gradient_checkpointing_enabled": bool(
                            ckpt.get('gradient_checkpointing_enabled', False)
                        ),
                        **(ckpt.get('resource_metrics') or {}),
                        **heldout_probability_record(test_metrics),
                    }
                    del model, ckpt
                    gc.collect()
                    continue
                if fingerprint_mismatch:
                    reason = (
                        "checkpoint/model/data fingerprint changed "
                        f"({ckpt_fingerprint} -> {text_model_fingerprint})"
                    )
                    print(f"\n>>> [STALE] {model_name}: {reason}. Retraining with current data.")
                    del ckpt
                    gc.collect()
                    checkpoint_path.unlink(missing_ok=True)
            except Exception as e:
                print(f"\n>>> [WARN] Could not load checkpoint for {model_name}: {e}. Retraining.")

        print(f"\n>>> Training {model_name}...")
        if text_use_final_epoch:
            print(
                f"    Epoch budget from cross-validation: {text_cv_epochs} "
                "epochs; the validation split is not used to pick a checkpoint."
            )
        model = _new_text_benchmark(model_id)
        _resource_probe = start_training_resource_probe(device)
        best_f1, history, final_metrics, best_state = train_model(
            model, train_loader, val_loader, config, device, "text",
            diversity_weight=0.04 if using_pretrained_text else 1.0,
            validation_group_ids=text_validation_group_ids,
            fixed_epochs=text_cv_epochs,
            use_final_epoch_state=text_use_final_epoch,
            disable_early_stopping=text_use_final_epoch,
        )
        _resource_metrics = training_resource_metrics(
            _resource_probe, device, history
        )
        if best_state is None:
            # Preserve a usable parent even if the anti-collapse checkpoint
            # rule rejected every epoch; validation still governs selection.
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            best_f1 = float(final_metrics['f1_micro'])
        if best_state is not None:
            model.load_state_dict(best_state)
            text_implementation = (
                f"Pretrained Hugging Face encoder: {model_id}"
                if using_pretrained_text else
                "LightweightTextClassifier (explicit scratch fallback)"
            )
            text_model_class = (
                "HuggingFaceTextClassifier" if using_pretrained_text
                else "LightweightTextClassifier"
            )
            torch.save({
                "model_state_dict": best_state,
                "f1_score": best_f1,
                "validation_f1_macro": float(final_metrics['f1_macro']),
                "config": checkpoint_safe_metadata(config.__dict__),
                "model_name": model_name,
                "model_type": "LLM",
                "model_class": text_model_class,
                "pretrained": using_pretrained_text,
                "pretrained_model_id": model_id if using_pretrained_text else None,
                "tokenizer_id": (
                    str(config.pretrained_text_tokenizer)
                    if using_pretrained_text else "SimpleTokenizer"
                ),
                "implementation": text_implementation,
                "gradient_checkpointing_enabled": bool(
                    getattr(model, 'gradient_checkpointing_enabled', False)
                ),
                "num_params": sum(p.numel() for p in model.parameters()),
                "data_fingerprint": data_fingerprint,
                "model_fingerprint": text_model_fingerprint,
                "validation_selection_scope": (
                    "independent_template_groups"
                    if text_validation_group_ids is not None else
                    "validation_rows"
                ),
                "validation_independent_groups": (
                    len(set(text_validation_group_ids))
                    if text_validation_group_ids is not None else None
                ),
                "validation_selection_metrics": history.get(
                    'best_selection_metrics'
                ),
                "evaluation_protocol": (
                    "template_group_heldout_v5_group_selected_transfer_learning"
                    if text_validation_group_ids is not None else
                    "source_image_grouped_linked_v5_transfer_learning"
                ),
                # Persisted so the cost plots stay populated on a later run
                # that reuses this checkpoint instead of retraining. Held-out
                # probabilities are NOT persisted -- the skip path reloads and
                # re-evaluates the model, so they are recomputed exactly.
                "resource_metrics": _resource_metrics,
            }, checkpoint_path)
            print(f"  Saved: {checkpoint_path}")
        test_metrics = evaluate(model, text_test_loader, device, "text")
        text_group_evidence = _text_group_evidence(test_metrics)
        validation_selection_metrics = history.get(
            'best_selection_metrics', {}
        ) or {}
        results["llm_models"][model_name] = {
            "f1": text_group_evidence.get(
                "independent_group_f1_micro",
                text_group_evidence["independent_group_accuracy"],
            ),
            "f1_macro": text_group_evidence.get(
                "independent_group_f1_macro", test_metrics["f1_macro"]
            ),
            "precision": test_metrics["precision"], "recall": test_metrics["recall"],
            "accuracy": text_group_evidence["independent_group_accuracy"],
            "row_test_f1": test_metrics["f1_micro"],
            "row_test_f1_macro": test_metrics["f1_macro"],
            "row_test_accuracy": test_metrics["accuracy"],
            "validation_f1": final_metrics["f1_micro"],
            "validation_f1_macro": final_metrics["f1_macro"],
            "validation_selection_scope": validation_selection_metrics.get(
                'scope', 'validation_rows'
            ),
            "validation_selection_f1": validation_selection_metrics.get(
                'f1_micro'
            ),
            "validation_selection_f1_macro": validation_selection_metrics.get(
                'f1_macro'
            ),
            "validation_independent_groups": (
                len(set(text_validation_group_ids))
                if text_validation_group_ids is not None else None
            ),
            **_heldout_evidence(test_metrics),
            **text_group_evidence,
            "test_f1": test_metrics["f1_micro"],
            "params": sum(p.numel() for p in model.parameters()),
            "history": history, "checkpoint": str(checkpoint_path),
            "per_class_f1": test_metrics.get("per_class_f1"),
            "implementation": (
                f"Pretrained Hugging Face encoder: {model_id}"
                if using_pretrained_text else
                "LightweightTextClassifier (explicit scratch fallback)"
            ),
            "model_class": (
                "HuggingFaceTextClassifier" if using_pretrained_text
                else "LightweightTextClassifier"
            ),
            "pretrained_model_id": model_id if using_pretrained_text else None,
            "tokenizer_id": (
                str(config.pretrained_text_tokenizer)
                if using_pretrained_text else "SimpleTokenizer"
            ),
            "pretrained": using_pretrained_text,
            "gradient_checkpointing_enabled": bool(
                getattr(model, 'gradient_checkpointing_enabled', False)
            ),
            **_resource_metrics,
            **heldout_probability_record(test_metrics),
        }
        print(
            f"  {model_name}: selection-validation macro/micro-F1="
            f"{float(validation_selection_metrics.get('f1_macro', final_metrics['f1_macro'])):.4f}/"
            f"{float(validation_selection_metrics.get('f1_micro', final_metrics['f1_micro'])):.4f}; "
            f"row-validation diagnostic macro/micro="
            f"{final_metrics['f1_macro']:.4f}/{final_metrics['f1_micro']:.4f}; "
            f"headline independent groups "
            f"{text_group_evidence['independent_group_correct']}/"
            f"{text_group_evidence['independent_test_groups']} "
            f"[CI {text_group_evidence['group_accuracy_ci95_low']:.3f}-"
            f"{text_group_evidence['group_accuracy_ci95_high']:.3f}]; "
            f"row diagnostic {test_metrics['n_correct']}/"
            f"{test_metrics['n_samples']}, micro/macro-F1="
            f"{test_metrics['f1_micro']:.4f}/"
            f"{test_metrics['f1_macro']:.4f}"
        )
        del model, best_state
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    # ── [5/8] ViT Training ───────────────────────────────────────────────────
    for text_result in results['llm_models'].values():
        text_result.update({
            'text_evaluation_protocol': text_split_audit['protocol'],
            'text_source_kind': text_source_kind,
        })
        if not linked_pair_mode:
            text_result['test_groups_per_class'] = {
                STRESS_LABELS[int(label)]: int(allocation['test'])
                for label, allocation in
                text_split_audit['split_groups_per_class'].items()
            }

    print("\n" + "=" * 70)
    print("[5/8] TRAINING 5 VISION BACKBONES")
    print("=" * 70)

    # Train vision benchmarks from the 139 independent real training images.
    # BalancedBatchSampler already resamples minority classes and ImageDataset
    # creates a fresh stochastic view on every access; pre-copying every class
    # to 200 tensors caused the six Hopper training leaves to be replayed far
    # more often than necessary and encouraged memorization.
    vision_train_images = list(model_real_image_train)
    vision_train_labels = list(model_real_label_train_img)
    flat_labels_vision = [
        label[0] if isinstance(label, (list, tuple)) else int(label)
        for label in vision_train_labels
    ]
    image_train_ds = ImageDataset(
        vision_train_images, vision_train_labels, augment_images=True,
        minority_augment_max_strength=getattr(
            config, 'minority_augment_max_strength', 1.0
        ),
    )
    image_val_ds   = ImageDataset(image_val,   label_val_img)
    image_test_ds  = ImageDataset(image_test,  label_test_img)
    using_pretrained_vision = bool(
        getattr(config, 'use_pretrained_backbones', True)
    )
    vision_batch_size = (
        min(int(config.batch_size), 8)
        if using_pretrained_vision else int(config.batch_size)
    )
    train_loader   = create_balanced_dataloader(
        image_train_ds, flat_labels_vision, batch_size=vision_batch_size,
        num_classes=config.num_labels, shuffle=True,
    )
    image_val_loader = DataLoader(image_val_ds, batch_size=vision_batch_size)
    val_loader = image_val_loader
    image_test_loader = DataLoader(image_test_ds, batch_size=vision_batch_size)
    image_validation_group_ids = list(image_split_groups_val)
    _image_validation_group_labels = {}
    for _group_id, _label in zip(
            image_validation_group_ids, label_val_img):
        _typed_group_id = (
            type(_group_id).__qualname__, repr(_group_id)
        )
        _image_validation_group_labels.setdefault(
            _typed_group_id, set()
        ).add(_single_label_index(_label))
    _mixed_label_validation_groups = [
        group_id for group_id, labels in _image_validation_group_labels.items()
        if len(labels) > 1
    ]
    if _mixed_label_validation_groups:
        # A source photograph with multiple ground-truth classes has no single
        # group label. Preserve every crop as a validation row rather than
        # averaging contradictory targets.
        image_validation_group_ids = None
        print(
            "  [Vision selection] Source groups contain multiple labels; "
            "checkpoints are ranked on validation crops."
        )
    else:
        print(
            "  [Vision selection] Checkpoints/models are ranked on "
            f"{len(set(image_validation_group_ids))} independent validation "
            f"source groups, aggregated from {len(image_validation_group_ids)} rows."
        )
    results['dataset_info']['vision_model_selection'] = {
        'scope': (
            'independent_source_groups'
            if image_validation_group_ids is not None else
            'validation_rows_due_to_mixed_label_source_groups'
        ),
        'validation_rows': int(len(image_val)),
        'independent_validation_groups': (
            int(len(set(image_validation_group_ids)))
            if image_validation_group_ids is not None else None
        ),
        'primary_metric': 'macro_f1',
        'test_used_for_selection': False,
    }

    print("  [Protocol] Validation selects checkpoints; reported vision F1 is real-image held-out test F1.")
    print(
        f"  [Vision train] {len(vision_train_images)} training rows from "
        f"{len(set(source_unique_real_groups_train))} independent real sources"
        + (
            f" plus {model_train_synthetic_count} synthetic ablation rows; "
            if model_train_synthetic_count else "; "
        )
        +
        "minorities are resampled online with fresh augmentation only."
    )
    print(
        "  [Model note] "
        + (
            "Loading the actual ImageNet-pretrained Hugging Face vision encoder "
            "for every named run."
            if using_pretrained_vision else
            "Using the explicitly enabled lightweight scratch fallback."
        )
    )

    def _new_vision_benchmark(model_id):
        if using_pretrained_vision:
            benchmark_model = HuggingFaceVisionClassifier(
                model_id,
                num_labels=config.num_labels,
                inference_tta=bool(config.pretrained_vision_inference_tta),
            )
            benchmark_model.pretrained_learning_rate = float(
                config.pretrained_vision_learning_rate
            )
            benchmark_model.pretrained_head_learning_rate = float(
                config.pretrained_vision_head_learning_rate
            )
            return benchmark_model.to(device)
        return LightweightVisionClassifier(num_labels=config.num_labels).to(device)

    # ---- Grouped out-of-fold CV over the image training rows -------------
    # Same purpose as the text CV above: architecture ranking plus an epoch
    # budget with training-set support instead of 29 validation images.
    if parent_selection_protocol == 'out_of_fold_cv':
        print("\n>>> Grouped out-of-fold CV over image training rows...")
        print(
            f"    Cost: {parent_cv_folds} folds x {len(VIT_MODELS)} vision refits."
        )
        for _cv_name, _cv_id in VIT_MODELS.items():
            try:
                vision_oof_scores[_cv_name] = out_of_fold_architecture_score(
                    lambda model_id=_cv_id: _new_vision_benchmark(model_id),
                    vision_train_images, vision_train_labels,
                    model_real_train_groups,
                    _make_vision_cv_dataset, config, device, 'vision',
                    n_splits=parent_cv_folds, seed=config.seed,
                    diversity_weight=0.04 if using_pretrained_vision else 1.0,
                    batch_size=vision_batch_size,
                )
                _entry = vision_oof_scores[_cv_name]
                print(
                    f"    [vision CV] {_cv_name}: out-of-fold macro-F1="
                    f"{_entry['f1_macro']:.4f} (n={_entry['n']}), "
                    f"best epoch={_entry['cv_best_epoch']} "
                    f"(curve macro-F1={_entry['cv_best_epoch_f1_macro']:.4f})"
                )
            except Exception as _cv_error:
                print(f"    [WARN] vision CV failed for {_cv_name}: {_cv_error}")

    for model_name, model_id in VIT_MODELS.items():
        checkpoint_path = config.checkpoint_dir / f"vit_{model_name.lower().replace('-','_')}_best.pt"
        vision_cv_epochs, vision_use_final_epoch = _cv_epoch_budget(
            vision_oof_scores, model_name
        )
        vision_model_fingerprint = _hl.sha256(
            (
                f"{data_fingerprint}|vision_transfer_v5_activation_aware|{model_id}|"
                f"pretrained:{using_pretrained_vision}|"
                f"epochs:{int(config.pretrained_vision_epochs)}|"
                f"lr:{float(config.pretrained_vision_learning_rate):.12g}|"
                f"head_lr:{float(config.pretrained_vision_head_learning_rate):.12g}|"
                f"weight_decay:{float(config.weight_decay):.12g}|"
                f"batch:{int(vision_batch_size)}|"
                f"image_size:{int(config.image_size)}|"
                f"accumulation:{int(config.gradient_accumulation_steps)}|"
                f"warmup:{float(config.warmup_ratio):.8g}|"
                f"patience:{int(config.early_stopping_patience)}|"
                f"mixed_precision:{bool(config.use_mixed_precision)}|"
                f"linear_probe_epochs:"
                f"{int(config.pretrained_vision_linear_probe_epochs)}|"
                f"tail_unfreeze_epochs:"
                f"{int(config.pretrained_vision_tail_unfreeze_epochs)}|"
                f"freeze_batch_norm_stats:"
                f"{bool(config.pretrained_vision_freeze_batch_norm_stats)}|"
                f"inference_tta_hflip:"
                f"{bool(config.pretrained_vision_inference_tta)}|"
                "pooling:vit_deit_pretrained_cls_v2|"
                "processor:native_norm_slow_pinned_v2|"
                # The augmentation recipe MUST be part of the checkpoint
                # identity. Changing minority_augment_max_strength without this
                # term left every cached vision checkpoint "compatible", so the
                # new augmentation never ran and the change was a silent no-op.
                "augmentation:class_aware_crop_color_orient_v4|"
                f"minority_augment_max_strength:"
                f"{float(getattr(config, 'minority_augment_max_strength', 1.0)):.6g}|"
                "tta:validation_selected_hflip_feature_mean_v2|"
                "sampler:source_unique_balanced_online_v2_epoch_scaled|"
                f"selection:{'group_macro_micro_then_row_macro_micro_v2' if image_validation_group_ids is not None else 'row_macro_micro_nll_v1'}|"
                f"validation_groups:{len(set(image_validation_group_ids or []))}|"
                f"epoch_selection:{epoch_selection_protocol}|"
                f"cv_epochs:{vision_cv_epochs}|"
                "scheduler:activation_aware_group_cosine_v3|diversity:0.04"
            ).encode('utf-8')
        ).hexdigest()[:12]
        if checkpoint_path.exists():
            try:
                ckpt = torch.load(checkpoint_path, map_location="cpu")
                saved_f1 = ckpt.get("f1_score", 0.0)
                compatible = (
                    ckpt.get('model_fingerprint') == vision_model_fingerprint
                    and ckpt.get('pretrained_model_id')
                    == (model_id if using_pretrained_vision else None)
                )
                fingerprint_mismatch = not compatible
                ckpt_fingerprint = ckpt.get('model_fingerprint')
                if compatible:
                    model = _new_vision_benchmark(model_id)
                    model.load_state_dict(ckpt["model_state_dict"])
                    if hasattr(model, 'inference_tta'):
                        model.inference_tta = checkpoint_inference_tta_enabled(
                            ckpt, default=False
                        )
                    test_metrics = evaluate(model, image_test_loader, device, "vision")
                    validation_selection_metrics = ckpt.get(
                        'validation_selection_metrics', {}
                    ) or {}
                    print(f"\n>>> [SKIP] {model_name}: checkpoint found "
                          f"(val micro-F1={saved_f1:.4f}, held-out "
                          f"{test_metrics['n_correct']}/{test_metrics['n_samples']}, "
                          f"micro-F1={test_metrics['f1_micro']:.4f}, "
                          f"macro-F1={test_metrics['f1_macro']:.4f}, "
                          f"95% CI={test_metrics['accuracy_ci95_low']:.3f}-"
                          f"{test_metrics['accuracy_ci95_high']:.3f}).")
                    results["vit_models"][model_name] = {
                        "f1": test_metrics["f1_micro"], "f1_macro": test_metrics["f1_macro"],
                        "precision": test_metrics["precision"], "recall": test_metrics["recall"],
                        "accuracy": test_metrics["accuracy"], "validation_f1": saved_f1,
                        "validation_f1_macro": (
                            float(ckpt['validation_f1_macro'])
                            if ckpt.get('validation_f1_macro') is not None else None
                        ),
                        "validation_selection_scope": ckpt.get(
                            'validation_selection_scope', 'validation_rows'
                        ),
                        "validation_selection_f1": validation_selection_metrics.get(
                            'f1_micro'
                        ),
                        "validation_selection_f1_macro": (
                            validation_selection_metrics.get('f1_macro')
                        ),
                        "validation_independent_groups": ckpt.get(
                            'validation_independent_groups'
                        ),
                        **_heldout_evidence(test_metrics),
                        "test_f1": test_metrics["f1_micro"],
                        "params": ckpt.get("num_params", 0),
                        "history": [], "checkpoint": str(checkpoint_path),
                        "per_class_f1": test_metrics.get("per_class_f1"),
                        "implementation": ckpt.get('implementation'),
                        "model_class": ckpt.get('model_class'),
                        "pretrained_model_id": ckpt.get('pretrained_model_id'),
                        "processor_id": ckpt.get('processor_id'),
                        "inference_tta_enabled": bool(
                            getattr(model, 'inference_tta', False)
                        ),
                        "pretrained": bool(ckpt.get('pretrained')),
                        **(ckpt.get('resource_metrics') or {}),
                        **heldout_probability_record(test_metrics),
                    }
                    del model, ckpt
                    gc.collect()
                    continue
                if fingerprint_mismatch:
                    reason = (
                        "checkpoint/model/data fingerprint changed "
                        f"({ckpt_fingerprint} -> {vision_model_fingerprint})"
                    )
                    print(f"\n>>> [STALE] {model_name}: {reason}. Retraining with current data.")
                    del ckpt
                    gc.collect()
                    checkpoint_path.unlink(missing_ok=True)
            except Exception as e:
                print(f"\n>>> [WARN] Could not load checkpoint for {model_name}: {e}. Retraining.")

        print(f"\n>>> Training {model_name}...")
        if vision_use_final_epoch:
            print(
                f"    Epoch budget from cross-validation: {vision_cv_epochs} "
                "epochs; the validation split is not used to pick a checkpoint."
            )
        model = _new_vision_benchmark(model_id)
        _resource_probe = start_training_resource_probe(device)
        best_f1, history, final_metrics, best_state = train_model(
            model, train_loader, val_loader, config, device, "vision",
            diversity_weight=0.04 if using_pretrained_vision else 1.0,
            validation_group_ids=image_validation_group_ids,
            fixed_epochs=vision_cv_epochs,
            use_final_epoch_state=vision_use_final_epoch,
            disable_early_stopping=vision_use_final_epoch,
        )
        _resource_metrics = training_resource_metrics(
            _resource_probe, device, history
        )
        if best_state is None:
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            best_f1 = float(final_metrics['f1_micro'])
        if best_state is not None:
            model.load_state_dict(best_state)
            vision_implementation = (
                f"ImageNet-pretrained Hugging Face encoder: {model_id}"
                if using_pretrained_vision else
                "LightweightVisionClassifier (explicit scratch fallback)"
            )
            vision_model_class = (
                "HuggingFaceVisionClassifier" if using_pretrained_vision
                else "LightweightVisionClassifier"
            )
            torch.save({
                "model_state_dict": best_state,
                "f1_score": best_f1,
                "validation_f1_macro": float(final_metrics['f1_macro']),
                "config": checkpoint_safe_metadata(config.__dict__),
                "model_name": model_name,
                "model_type": "ViT",
                "model_class": vision_model_class,
                "pretrained": using_pretrained_vision,
                "pretrained_model_id": model_id if using_pretrained_vision else None,
                "processor_id": model_id if using_pretrained_vision else "ImageNetNormalize",
                "implementation": vision_implementation,
                "vision_transfer_schedule": {
                    "epochs": int(config.pretrained_vision_epochs),
                    "head_only_epochs": int(
                        config.pretrained_vision_linear_probe_epochs
                    ),
                    "final_stage_epochs": int(
                        config.pretrained_vision_tail_unfreeze_epochs
                    ),
                    "encoder_learning_rate": float(
                        config.pretrained_vision_learning_rate
                    ),
                    "head_learning_rate": float(
                        config.pretrained_vision_head_learning_rate
                    ),
                    "freeze_batch_norm_stats": bool(
                        config.pretrained_vision_freeze_batch_norm_stats
                    ),
                    "learning_rate_scheduler": (
                        "activation_aware_group_warmup_cosine"
                    ),
                },
                "inference_tta": (
                    "horizontal_flip_feature_mean"
                    if bool(history.get(
                        'best_inference_tta',
                        getattr(model, 'inference_tta', False),
                    )) else None
                ),
                "inference_tta_enabled": bool(history.get(
                    'best_inference_tta',
                    getattr(model, 'inference_tta', False),
                )),
                "inference_tta_selection": (
                    "validation macro/micro-F1; original-only on exact tie"
                ),
                "validation_selection_scope": (
                    "independent_source_groups"
                    if image_validation_group_ids is not None else
                    "validation_rows"
                ),
                "validation_independent_groups": (
                    len(set(image_validation_group_ids))
                    if image_validation_group_ids is not None else None
                ),
                "validation_selection_metrics": history.get(
                    'best_selection_metrics'
                ),
                "num_params": sum(p.numel() for p in model.parameters()),
                "data_fingerprint": data_fingerprint,
                "model_fingerprint": vision_model_fingerprint,
                "evaluation_protocol": "real_image_heldout_v3_transfer_learning",
                "resource_metrics": _resource_metrics,
            }, checkpoint_path)
            print(f"  Saved: {checkpoint_path}")
        test_metrics = evaluate(model, image_test_loader, device, "vision")
        validation_selection_metrics = history.get(
            'best_selection_metrics', {}
        ) or {}
        results["vit_models"][model_name] = {
            "f1": test_metrics["f1_micro"], "f1_macro": test_metrics["f1_macro"],
            "precision": test_metrics["precision"], "recall": test_metrics["recall"],
            "accuracy": test_metrics["accuracy"], "validation_f1": final_metrics["f1_micro"],
            "validation_f1_macro": final_metrics["f1_macro"],
            "validation_selection_scope": validation_selection_metrics.get(
                'scope', 'validation_rows'
            ),
            "validation_selection_f1": validation_selection_metrics.get(
                'f1_micro'
            ),
            "validation_selection_f1_macro": validation_selection_metrics.get(
                'f1_macro'
            ),
            "validation_independent_groups": (
                len(set(image_validation_group_ids))
                if image_validation_group_ids is not None else None
            ),
            **_heldout_evidence(test_metrics),
            "test_f1": test_metrics["f1_micro"],
            "params": sum(p.numel() for p in model.parameters()),
            "history": history, "checkpoint": str(checkpoint_path),
            "per_class_f1": test_metrics.get("per_class_f1"),
            "implementation": (
                f"ImageNet-pretrained Hugging Face encoder: {model_id}"
                if using_pretrained_vision else
                "LightweightVisionClassifier (explicit scratch fallback)"
            ),
            "model_class": (
                "HuggingFaceVisionClassifier" if using_pretrained_vision
                else "LightweightVisionClassifier"
            ),
            "pretrained_model_id": model_id if using_pretrained_vision else None,
            "processor_id": model_id if using_pretrained_vision else "ImageNetNormalize",
            "inference_tta_enabled": bool(
                getattr(model, 'inference_tta', False)
            ),
            "pretrained": using_pretrained_vision,
            **_resource_metrics,
            **heldout_probability_record(test_metrics),
        }
        print(
            f"  {model_name}: validation macro/micro-F1="
            f"{final_metrics['f1_macro']:.4f}/"
            f"{final_metrics['f1_micro']:.4f}; "
            f"held-out {test_metrics['n_correct']}/{test_metrics['n_samples']}, "
            f"micro-F1={test_metrics['f1_micro']:.4f}, "
            f"macro-F1={test_metrics['f1_macro']:.4f}, "
            f"95% CI={test_metrics['accuracy_ci95_low']:.3f}-"
            f"{test_metrics['accuracy_ci95_high']:.3f}"
        )
        del model, best_state
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    # ── [6/8] VLM Training ───────────────────────────────────────────────────
    print("\n" + "=" * 70)
    print("[6/8] TRAINING 8 EARLY + 1 FLEXIBLE CROSS-ATTENTION + 1 LATE-FUSION VLM")
    print("=" * 70)

    mm_train_ds = MultiModalDataset(
        mm_texts_tr, mm_labels_tr, mm_images_tr, benchmark_tokenizer,
        int(config.max_seq_length),
        resample_same_label=not linked_pair_mode, augment_images=True,
        minority_augment_max_strength=getattr(
            config, 'minority_augment_max_strength', 1.0
        ),
    )
    mm_val_ds = MultiModalDataset(
        mm_texts_v, mm_labels_v, mm_images_v, benchmark_tokenizer,
        int(config.max_seq_length)
    )
    mm_test_ds = MultiModalDataset(
        mm_texts_te, mm_labels_te, mm_images_te, benchmark_tokenizer,
        int(config.max_seq_length)
    )
    train_loader = create_balanced_dataloader(
        mm_train_ds, flat_labels_mm, batch_size=config.batch_size,
        num_classes=config.num_labels, shuffle=True,
    )
    val_loader = DataLoader(mm_val_ds, batch_size=config.batch_size)
    mm_test_loader = DataLoader(mm_test_ds, batch_size=config.batch_size)

    if len(mm_test_ds) == 0:
        raise RuntimeError("No VLM test pairs available after label-aligned pairing.")
    print(
        "  [Protocol] Validation selects checkpoints; reported VLM metrics use "
        + ("the source-grouped paired test set." if linked_pair_mode else
           "the held-out proxy-pair test set.")
    )
    early_fusion_training_protocol = (
        "early_fusion_v6_source_unique_macro_selection|"
        f"epochs:{int(config.epochs)}|"
        f"lr:{float(config.learning_rate):.12g}|"
        f"weight_decay:{float(config.weight_decay):.12g}|"
        f"batch:{int(config.batch_size)}|"
        f"accumulation:{int(config.gradient_accumulation_steps)}|"
        f"warmup:{float(config.warmup_ratio):.8g}|"
        f"patience:{int(config.early_stopping_patience)}|"
        f"mixed_precision:{bool(config.use_mixed_precision)}|"
        # Early-fusion VLMs also train on the augmented MultiModalDataset, so
        # their cached checkpoints must invalidate when the recipe changes too.
        "image_aug:class_aware_crop_color_orient_v4|"
        f"minority_augment_max_strength:"
        f"{float(getattr(config, 'minority_augment_max_strength', 1.0)):.6g}|"
        "diversity_weight:1|selection:macro_micro_nll_v1"
    )

    for fusion_type in VLM_FUSION_TYPES:
        fusion_display = VLM_FUSION_DISPLAY_NAMES.get(
            fusion_type, f'{fusion_type}-style scratch fusion'
        )
        checkpoint_path = config.checkpoint_dir / f"vlm_{fusion_type.lower()}_best.pt"
        if checkpoint_path.exists():
            try:
                ckpt = torch.load(checkpoint_path, map_location="cpu")
                saved_f1 = ckpt.get("f1_score", 0.0)
                ckpt_fingerprint = ckpt.get("data_fingerprint")
                fingerprint_mismatch = (
                    ckpt_fingerprint is None
                    or ckpt_fingerprint != data_fingerprint
                    or ckpt.get('training_protocol')
                    != early_fusion_training_protocol
                )
                if not fingerprint_mismatch:
                    model = MultiModalClassifier(num_labels=config.num_labels, fusion_type=fusion_type).to(device)
                    model.load_state_dict(ckpt["model_state_dict"])
                    val_metrics = evaluate(model, val_loader, device, "multimodal")
                    test_metrics = evaluate(model, mm_test_loader, device, "multimodal")
                    print(f"\n>>> [SKIP] VLM ({fusion_display}): checkpoint found "
                          f"(val macro/micro="
                          f"{val_metrics['f1_macro']:.4f}/"
                          f"{val_metrics['f1_micro']:.4f}, held-out "
                          f"{test_metrics['n_correct']}/{test_metrics['n_samples']}, "
                          f"macro/micro={test_metrics['f1_macro']:.4f}/"
                          f"{test_metrics['f1_micro']:.4f}, CI "
                          f"{test_metrics['accuracy_ci95_low']:.3f}-"
                          f"{test_metrics['accuracy_ci95_high']:.3f}).")
                    results["vlm_models"][fusion_type] = {
                        "f1": test_metrics["f1_micro"], "f1_macro": test_metrics["f1_macro"],
                        "precision": test_metrics["precision"], "recall": test_metrics["recall"],
                        "accuracy": test_metrics["accuracy"],
                        "validation_f1": val_metrics["f1_micro"],
                        "validation_f1_macro": val_metrics["f1_macro"],
                        **_heldout_evidence(test_metrics),
                        "test_f1": test_metrics["f1_micro"],
                        "params": ckpt.get("num_params", 0),
                        "history": [], "checkpoint": str(checkpoint_path),
                        "per_class_f1": test_metrics.get("per_class_f1"),
                        "evaluation_scope": vlm_evaluation_scope,
                        "display_name": fusion_display,
                        "implementation": "Lightweight scratch fusion surrogate",
                        **(ckpt.get('resource_metrics') or {}),
                        **heldout_probability_record(test_metrics),
                    }
                    del model, ckpt
                    gc.collect()
                    continue
                if fingerprint_mismatch:
                    # Report the term that actually changed. The old message
                    # always blamed the data fingerprint, so a pure
                    # training-protocol change printed an identical digest on
                    # both sides ("a -> a") and read like a bug.
                    if ckpt_fingerprint != data_fingerprint:
                        reason = (
                            "data fingerprint changed "
                            f"({ckpt_fingerprint} -> {data_fingerprint})"
                        )
                    else:
                        reason = (
                            "training protocol changed "
                            f"({ckpt.get('training_protocol')!r} -> "
                            f"{early_fusion_training_protocol!r})"
                        )
                    print(f"\n>>> [STALE] VLM ({fusion_type}): {reason}. Retraining with current data.")
                    del ckpt
                    gc.collect()
                    checkpoint_path.unlink(missing_ok=True)
            except Exception as e:
                print(f"\n>>> [WARN] Could not load checkpoint for VLM ({fusion_type}): {e}. Retraining.")

        print(f"\n>>> Training VLM ({fusion_display})...")
        model = MultiModalClassifier(num_labels=config.num_labels, fusion_type=fusion_type).to(device)
        _resource_probe = start_training_resource_probe(device)
        best_f1, history, final_metrics, best_state = train_model(
            model, train_loader, val_loader, config, device, "multimodal", diversity_weight=1.0
        )
        _resource_metrics = training_resource_metrics(
            _resource_probe, device, history
        )
        if best_state is None:
            best_state = {
                key: value.detach().cpu().clone()
                for key, value in model.state_dict().items()
            }
            best_f1 = float(final_metrics['f1_micro'])
        model.load_state_dict(best_state)
        torch.save({"model_state_dict": best_state, "f1_score": best_f1,
                    "validation_f1_macro": float(final_metrics['f1_macro']),
                    "config": checkpoint_safe_metadata(config.__dict__), "fusion_type": fusion_type, "model_type": "VLM",
                    "num_params": sum(p.numel() for p in model.parameters()),
                    "data_fingerprint": data_fingerprint,
                    "training_protocol": early_fusion_training_protocol,
                    "resource_metrics": _resource_metrics,
                    "evaluation_protocol": (
                        "source_grouped_linked_pair_heldout_v1"
                        if linked_pair_mode else
                        "template_group_proxy_pair_heldout_v4_diverse_support"
                    )},
                   checkpoint_path)
        print(f"  Saved: {checkpoint_path}")
        test_metrics = evaluate(model, mm_test_loader, device, "multimodal")
        results["vlm_models"][fusion_type] = {
            "f1": test_metrics["f1_micro"], "f1_macro": test_metrics["f1_macro"],
            "precision": test_metrics["precision"], "recall": test_metrics["recall"],
            "accuracy": test_metrics["accuracy"], "validation_f1": final_metrics["f1_micro"],
            "validation_f1_macro": final_metrics["f1_macro"],
            **_heldout_evidence(test_metrics),
            "test_f1": test_metrics["f1_micro"],
            "params": sum(p.numel() for p in model.parameters()),
            "history": history, "checkpoint": str(checkpoint_path),
            "per_class_f1": test_metrics.get("per_class_f1"),
            "evaluation_scope": vlm_evaluation_scope,
            "display_name": fusion_display,
            "implementation": "Lightweight scratch fusion surrogate",
            **_resource_metrics,
            **heldout_probability_record(test_metrics),
        }
        print(
            f"  VLM ({fusion_display}): validation macro/micro="
            f"{final_metrics['f1_macro']:.4f}/"
            f"{final_metrics['f1_micro']:.4f}; held-out "
            f"{test_metrics['n_correct']}/{test_metrics['n_samples']}, "
            f"macro/micro={test_metrics['f1_macro']:.4f}/"
            f"{test_metrics['f1_micro']:.4f}, 95% CI="
            f"{test_metrics['accuracy_ci95_low']:.3f}-"
            f"{test_metrics['accuracy_ci95_high']:.3f}"
        )
        del model, best_state
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    # Pick one early-fusion teacher using validation metrics only. It can guide
    # the flexible single-checkpoint student and is also included in the fair
    # same-support report; test performance never participates in this choice.
    early_fusion_teacher = None
    early_fusion_info = None
    early_candidates = [
        (
            float(results['vlm_models'][name].get('validation_f1_macro', -1.0)),
            float(results['vlm_models'][name].get('validation_f1', -1.0)),
            name,
        )
        for name in VLM_FUSION_TYPES
        if name in results['vlm_models']
    ]
    if early_candidates:
        _, _, early_fusion_name = max(early_candidates)
        early_checkpoint_path = Path(
            results['vlm_models'][early_fusion_name]['checkpoint']
        )
        try:
            early_checkpoint = torch.load(early_checkpoint_path, map_location='cpu')
            if (early_checkpoint.get('data_fingerprint') != data_fingerprint
                    or early_checkpoint.get('training_protocol')
                    != early_fusion_training_protocol):
                raise ValueError('early-fusion checkpoint fingerprint mismatch')
            early_fusion_teacher = MultiModalClassifier(
                num_labels=config.num_labels, fusion_type=early_fusion_name
            ).to(device)
            early_fusion_teacher.load_state_dict(
                early_checkpoint['model_state_dict'], strict=True
            )
            early_fusion_teacher.eval()
            for parameter in early_fusion_teacher.parameters():
                parameter.requires_grad_(False)
            early_validation_metrics = evaluate(
                early_fusion_teacher, val_loader, device, 'multimodal'
            )
            early_fusion_info = {
                'name': early_fusion_name,
                'path': early_checkpoint_path,
                'f1_micro': float(early_validation_metrics['f1_micro']),
                'f1_macro': float(early_validation_metrics['f1_macro']),
            }
            print(
                f"    Validation-selected early VLM teacher: {early_fusion_name} "
                f"(micro-F1={early_fusion_info['f1_micro']:.4f}, "
                f"macro-F1={early_fusion_info['f1_macro']:.4f})"
            )
            del early_checkpoint
        except Exception as early_teacher_error:
            print(f"    [WARN] Early-fusion teacher unavailable: {early_teacher_error}")
            early_fusion_teacher = None
            early_fusion_info = None

    # ── [7/8] Federated vs Centralized ───────────────────────────────────────
    # Select the strongest unimodal checkpoints on the COMMON proxy-pair
    # validation loader. They initialize the one-model flexible VLM and also
    # serve as frozen experts for the late-fusion baseline. No test labels or
    # scores are used for either selection path.
    print("\n>>> Training one-model VLM (flexible_cross_attention)...")

    def _reconstruct_unimodal_checkpoint(checkpoint, fallback_cls, model_type):
        model_class = checkpoint.get('model_class')
        pretrained_id = checkpoint.get('pretrained_model_id')
        if model_class == 'HuggingFaceTextClassifier':
            if model_type != 'text' or not pretrained_id:
                raise ValueError('Invalid pretrained text checkpoint metadata')
            return HuggingFaceTextClassifier(
                pretrained_id, num_labels=config.num_labels
            ).to(device)
        if model_class == 'HuggingFaceVisionClassifier':
            if model_type != 'vision' or not pretrained_id:
                raise ValueError('Invalid pretrained vision checkpoint metadata')
            return HuggingFaceVisionClassifier(
                pretrained_id,
                num_labels=config.num_labels,
                inference_tta=checkpoint_inference_tta_enabled(
                    checkpoint, default=False
                ),
            ).to(device)
        return fallback_cls(num_labels=config.num_labels).to(device)

    def _select_fusion_parent(model_results, model_cls, model_type,
                              modality_val_loader,
                              selection_group_ids=None,
                              oof_scores=None):
        oof_scores = oof_scores or {}
        scored = []
        for parent_name, parent_data in model_results.items():
            parent_path = Path(parent_data.get('checkpoint', ''))
            if not parent_path.is_file():
                continue
            try:
                parent_ckpt = torch.load(parent_path, map_location='cpu')
                if parent_ckpt.get('data_fingerprint') != data_fingerprint:
                    del parent_ckpt
                    continue
                candidate = _reconstruct_unimodal_checkpoint(
                    parent_ckpt, model_cls, model_type
                )
                candidate.load_state_dict(parent_ckpt['model_state_dict'])
                selection_row_metrics = evaluate(
                    candidate, modality_val_loader, device, model_type
                )
                selection_metrics = (
                    aggregate_classification_metrics_by_group(
                        selection_row_metrics, selection_group_ids
                    )
                    if selection_group_ids is not None else
                    selection_row_metrics
                )
                common_metrics = evaluate(
                    candidate, val_loader, device, model_type
                )
                scored.append({
                    'name': parent_name,
                    'path': parent_path,
                    # Selection uses the complete validation support native to
                    # this modality. The common proxy metrics are retained for
                    # initializing/calibrating fusion on matched rows.
                    'selection_f1_micro': float(selection_metrics['f1_micro']),
                    'selection_f1_macro': float(selection_metrics['f1_macro']),
                    'selection_nll': validation_negative_log_likelihood(
                        selection_metrics
                    ),
                    'selection_scope': (
                        'independent_validation_groups'
                        if selection_group_ids is not None else
                        'validation_rows'
                    ),
                    'selection_n': int(selection_metrics['n_samples']),
                    'selection_row_f1_micro': float(
                        selection_row_metrics['f1_micro']
                    ),
                    'selection_row_f1_macro': float(
                        selection_row_metrics['f1_macro']
                    ),
                    'f1_micro': float(common_metrics['f1_micro']),
                    'f1_macro': float(common_metrics['f1_macro']),
                    'common_val_nll': validation_negative_log_likelihood(
                        common_metrics
                    ),
                    'model_class': parent_ckpt.get('model_class'),
                    'pretrained_model_id': parent_ckpt.get('pretrained_model_id'),
                    'tokenizer_id': parent_ckpt.get('tokenizer_id'),
                    'processor_id': parent_ckpt.get('processor_id'),
                    'inference_tta_enabled': (
                        checkpoint_inference_tta_enabled(
                            parent_ckpt, default=False
                        ) if model_type == 'vision' else False
                    ),
                    'oof': oof_scores.get(parent_name),
                })
                del candidate, parent_ckpt
                gc.collect()
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            except Exception as parent_error:
                print(f"    [WARN] Could not score {parent_name} for late fusion: {parent_error}")

        if not scored:
            raise RuntimeError(f"No compatible {model_type} checkpoint available for late fusion")

        def _validation_key(row):
            return (
                row['selection_f1_macro'],
                row['selection_f1_micro'],
                row['selection_row_f1_macro'],
                row['selection_row_f1_micro'],
                # F1 saturates and ties on the tiny vision validation support
                # (Swin-tiny and ConvNeXT-tiny both 0.800), which previously
                # collapsed selection onto the arbitrary alphabetical name
                # below and picked the weaker parent. Validation NLL is
                # continuous and keeps discriminating after every F1 term ties
                # -- lower NLL (negated for max) is the better-calibrated
                # parent. Both terms are validation-only; test is never read.
                -row['selection_nll'],
                -row['common_val_nll'],
                row['name'],
            )

        # Out-of-fold ranking is used only when EVERY candidate has a score, so
        # architectures are never compared across two different criteria. The
        # validation terms remain as the tie-break beneath it.
        use_oof = all(row.get('oof') for row in scored)
        if use_oof:
            selection_basis = (
                f"pooled out-of-fold CV over "
                f"{scored[0]['oof']['n']} training rows "
                f"({scored[0]['oof']['n_splits']} grouped folds)"
            )
            selected = max(
                scored,
                key=lambda row: (
                    row['oof']['f1_macro'],
                    row['oof']['f1_micro'],
                    -row['oof']['nll'],
                ) + _validation_key(row),
            )
        else:
            selection_basis = (
                f"held-out validation ({scored[0]['selection_n']} "
                f"{scored[0]['selection_scope']})"
            )
            selected = max(scored, key=_validation_key)
        selected['selection_basis'] = selection_basis
        selected['selection_protocol'] = (
            'out_of_fold_cv' if use_oof else 'validation'
        )
        selected['candidate_ranking'] = [
            {
                'name': row['name'],
                'oof_f1_macro': (
                    row['oof']['f1_macro'] if row.get('oof') else None
                ),
                'validation_f1_macro': row['selection_f1_macro'],
            }
            for row in sorted(
                scored,
                key=lambda row: (
                    (row['oof']['f1_macro'] if use_oof else 0.0),
                    row['selection_f1_macro'],
                ),
                reverse=True,
            )
        ]
        if use_oof:
            validation_pick = max(scored, key=_validation_key)['name']
            if validation_pick != selected['name']:
                print(
                    f"    [{model_type} parent] Out-of-fold CV selects "
                    f"{selected['name']}; the {scored[0]['selection_n']}-sample "
                    f"validation criterion would have selected "
                    f"{validation_pick}. CV is the prespecified criterion; "
                    "this disagreement is reported, not resolved on test."
                )
        selected_ckpt = torch.load(selected['path'], map_location='cpu')
        selected_model = _reconstruct_unimodal_checkpoint(
            selected_ckpt, model_cls, model_type
        )
        selected_model.load_state_dict(selected_ckpt['model_state_dict'])
        selected_model.eval()
        del selected_ckpt
        print(
            f"    Selected {model_type} parent {selected['name']} by "
            f"{selected['selection_basis']}"
            + (
                f": out-of-fold macro/micro-F1="
                f"{selected['oof']['f1_macro']:.4f}/"
                f"{selected['oof']['f1_micro']:.4f}, NLL="
                f"{selected['oof']['nll']:.4f}"
                if selected.get('oof') and selected['selection_protocol'] == 'out_of_fold_cv'
                else f": macro/micro-F1="
                f"{selected['selection_f1_macro']:.4f}/"
                f"{selected['selection_f1_micro']:.4f}, NLL="
                f"{selected['selection_nll']:.4f}"
            )
            + "; held-out validation macro/micro="
            f"{selected['selection_f1_macro']:.4f}/"
            f"{selected['selection_f1_micro']:.4f}"
            f"; common proxy validation macro/micro={selected['f1_macro']:.4f}/"
            f"{selected['f1_micro']:.4f}"
        )
        return selected_model, selected

    late_text_parent = None
    late_vision_parent = None
    late_model = None
    flexible_model = None
    flexible_val_modes = None
    flexible_test_modes = None
    flexible_robustness_results = None
    simple_concat_robustness_results = None

    # text_oof_scores / vision_oof_scores were computed before the parents
    # trained (stages [4/8] and [5/8]), because their epoch curves set each
    # model's epoch budget. Nothing is recomputed here; this only records them.
    if parent_selection_protocol == 'out_of_fold_cv':
        results['parent_selection_cv'] = {
            'protocol': 'grouped_stratified_out_of_fold_training_cv_v2',
            'n_splits': parent_cv_folds,
            'epoch_selection_protocol': epoch_selection_protocol,
            'text': text_oof_scores,
            'vision': vision_oof_scores,
            'text_cv_epochs': {
                name: (entry or {}).get('cv_best_epoch')
                for name, entry in text_oof_scores.items()
            },
            'vision_cv_epochs': {
                name: (entry or {}).get('cv_best_epoch')
                for name, entry in vision_oof_scores.items()
            },
            'test_used_for_selection': False,
            'note': (
                'Two distinct uses. (1) Architecture ranking: the pooled score '
                'takes each fold at its own best epoch, so it is optimistic in '
                'absolute terms and is a ranking criterion only. (2) Epoch '
                'budget: cv_best_epoch comes from the pooled per-epoch curve '
                'with early stopping disabled inside folds. Deployed parents '
                'are full-training-set fits at the CV-chosen epoch.'
            ),
        }

    try:
        late_text_parent, late_text_info = _select_fusion_parent(
            results['llm_models'], LightweightTextClassifier, 'text',
            text_val_loader,
            selection_group_ids=text_validation_group_ids,
            oof_scores=text_oof_scores,
        )
        late_vision_parent, late_vision_info = _select_fusion_parent(
            results['vit_models'], LightweightVisionClassifier, 'vision',
            image_val_loader,
            selection_group_ids=image_validation_group_ids,
            oof_scores=vision_oof_scores,
        )
        results['fusion_parent_selection'] = {
            'protocol': parent_selection_protocol,
            'cv_folds': (
                parent_cv_folds
                if parent_selection_protocol == 'out_of_fold_cv' else None
            ),
            'test_used_for_selection': False,
            'text': {
                'selected': late_text_info['name'],
                'basis': late_text_info.get('selection_basis'),
                'ranking': late_text_info.get('candidate_ranking'),
            },
            'vision': {
                'selected': late_vision_info['name'],
                'basis': late_vision_info.get('selection_basis'),
                'ranking': late_vision_info.get('candidate_ranking'),
            },
        }

        def _checkpoint_digest(checkpoint_path):
            digest = _hl.sha256()
            with Path(checkpoint_path).open('rb') as checkpoint_file:
                for chunk in iter(lambda: checkpoint_file.read(1024 * 1024), b''):
                    digest.update(chunk)
            return digest.hexdigest()[:16]

        late_text_digest = _checkpoint_digest(late_text_info['path'])
        late_vision_digest = _checkpoint_digest(late_vision_info['path'])
        early_teacher_digest = (
            _checkpoint_digest(early_fusion_info['path'])
            if early_fusion_info is not None else 'none'
        )
        text_prior = float(np.clip(
            0.5 + late_text_info['f1_micro'] - late_vision_info['f1_micro'],
            0.10, 0.90,
        ))

        # ------------------------------------------------------------------
        # One jointly trainable flexible cross-attention VLM.
        # ------------------------------------------------------------------
        try:
            pretrained_fusion = (
                isinstance(late_text_parent, HuggingFaceTextClassifier)
                and isinstance(late_vision_parent, HuggingFaceVisionClassifier)
            )
            if pretrained_fusion:
                flexible_model = PretrainedMultimodalFusionVLM(
                    text_model_name=late_text_info['pretrained_model_id'],
                    vision_model_name=late_vision_info['pretrained_model_id'],
                    num_labels=config.num_labels,
                    modality_dropout=float(config.flexible_vlm_modality_dropout),
                    text_aux_weight=float(config.flexible_vlm_text_aux_weight),
                    image_aux_weight=float(config.flexible_vlm_image_aux_weight),
                    alignment_weight=float(config.flexible_vlm_alignment_weight),
                    min_text_weight=float(config.flexible_vlm_min_text_weight),
                    max_text_weight=float(config.flexible_vlm_max_text_weight),
                    vision_inference_tta=bool(
                        late_vision_info.get(
                            'inference_tta_enabled', False
                        )
                    ),
                ).to(device)
            else:
                flexible_model = FlexibleCrossAttentionVLM(
                    num_labels=config.num_labels,
                    max_seq_length=int(config.max_seq_length),
                    modality_dropout=float(config.flexible_vlm_modality_dropout),
                    text_aux_weight=float(config.flexible_vlm_text_aux_weight),
                    image_aux_weight=float(config.flexible_vlm_image_aux_weight),
                    alignment_weight=float(config.flexible_vlm_alignment_weight),
                    min_text_weight=float(config.flexible_vlm_min_text_weight),
                    max_text_weight=float(config.flexible_vlm_max_text_weight),
                ).to(device)
            flexible_model.initialize_from_unimodal(
                late_text_parent, late_vision_parent
            )
            flexible_model.freeze_unimodal_backbones(
                bool(config.flexible_vlm_freeze_backbones)
            )
            flexible_model.set_parent_prior(text_prior)
            flexible_model_class = type(flexible_model).__name__
            flexible_kwargs = flexible_model.architecture_kwargs()
            flexible_batch_size = max(
                config.num_labels,
                min(
                    int(config.batch_size),
                    int(config.flexible_vlm_batch_size),
                ),
            )
            _gate_calibration_protocol = str(getattr(
                config, 'gate_calibration_protocol', 'validation'
            )).lower()
            flexible_protocol = (
                (
                    'pretrained_pooled_gated_residual_fusion_v8_group_parents'
                    if pretrained_fusion else
                    'active_residual_cross_attention_v12_macro_parents'
                )
                + f'|parent_selection:{parent_selection_protocol}'
                + (
                    f':{parent_cv_folds}fold'
                    if parent_selection_protocol == 'out_of_fold_cv' else ''
                )
                + f'|gate_calibration:{_gate_calibration_protocol}'
                + (
                    f':{int(getattr(config, "gate_calibration_cv_folds", 3))}fold'
                    if _gate_calibration_protocol == 'out_of_fold_cv' else ''
                )
                + f'|reliability_gate:{bool(getattr(config, "fit_reliability_gate", True))}'
                + f'|no_harm_margin:{float(getattr(config, "fusion_no_harm_margin", 0.0) or 0.0):.6g}'
            )
            flexible_identity_raw = (
                f"{data_fingerprint}|{flexible_protocol}|"
                f"text:{late_text_info['name']}:{late_text_digest}|"
                f"vision:{late_vision_info['name']}:{late_vision_digest}|"
                f"teacher:{early_fusion_info['name'] if early_fusion_info else 'none'}:"
                f"{early_teacher_digest}|"
                f"text_prior:{text_prior:.8f}|"
                f"train_batch:{int(flexible_batch_size)}|"
                f"train_batch_cap:{int(config.flexible_vlm_batch_size)}|"
                f"epochs:{int(config.epochs)}|lr:{float(config.learning_rate):.12g}|"
                f"weight_decay:{float(config.weight_decay):.12g}|"
                f"warmup:{float(config.warmup_ratio):.8g}|"
                f"patience:{int(config.early_stopping_patience)}|"
                f"mixed_precision:{bool(config.use_mixed_precision)}|"
                f"accumulation:{int(config.gradient_accumulation_steps)}|"
                f"distill_weight:{float(config.flexible_vlm_distillation_weight):.8g}|"
                f"distill_temperature:{float(config.flexible_vlm_distillation_temperature):.8g}|"
                f"diversity:{float(config.flexible_vlm_diversity_weight):.8g}|"
                f"gate_supervision:{float(config.flexible_vlm_gate_supervision_weight):.8g}|"
                f"parent_guard:{float(config.flexible_vlm_parent_guard_weight):.8g}|"
                f"parent_guard_margin:{float(config.flexible_vlm_parent_guard_margin):.8g}|"
                f"min_validation_f1_gain:{float(config.flexible_vlm_min_validation_f1_gain):.8g}|"
                f"freeze_backbones:{bool(config.flexible_vlm_freeze_backbones)}|"
                f"vision_tta:{bool(late_vision_info.get('inference_tta_enabled', False))}|"
                f"fill_strategy:{_fill_strategy}|"
                f"pairing:{vlm_pairing_semantics}|"
                f"pair_sampler:{'dynamic_same_label' if not linked_pair_mode else 'linked_fixed'}|"
                "parent_probability_calibration:learned_temperatures_v1|"
                "parent_guard_rule:best_per_sample_parent_v2|"
                "validation_tiebreak:macro_micro_f1_no_nll_only_v3|"
                "image_aug:class_aware_crop_color_orient_v4|"
                f"minority_augment_max_strength:"
                f"{float(getattr(config, 'minority_augment_max_strength', 1.0)):.6g}|"
                f"kwargs:{json.dumps(flexible_kwargs, sort_keys=True)}"
            )
            flexible_fingerprint = _hl.sha256(
                flexible_identity_raw.encode('utf-8')
            ).hexdigest()[:12]
            flexible_checkpoint_path = (
                config.checkpoint_dir / 'vlm_flexible_cross_attention_best.pt'
            )
            flexible_history = {}
            loaded_flexible_checkpoint = False

            if flexible_checkpoint_path.is_file():
                try:
                    flexible_ckpt = torch.load(
                        flexible_checkpoint_path, map_location='cpu'
                    )
                    if (flexible_ckpt.get('flexible_vlm_fingerprint')
                            == flexible_fingerprint
                            and flexible_ckpt.get('model_class')
                            == flexible_model_class):
                        flexible_model.load_state_dict(
                            flexible_ckpt['model_state_dict'], strict=True
                        )
                        flexible_history = flexible_ckpt.get('history', {})
                        flexible_val_modes = {
                            'both': evaluate(
                                flexible_model, val_loader, device, 'multimodal',
                                modality_mode='both',
                            ),
                            'text_only': evaluate(
                                flexible_model, val_loader, device, 'multimodal',
                                modality_mode='text_only',
                            ),
                            'image_only': evaluate(
                                flexible_model, val_loader, device, 'multimodal',
                                modality_mode='image_only',
                            ),
                        }
                        loaded_flexible_checkpoint = True
                        print(
                            "    [SKIP] compatible flexible-VLM checkpoint found; "
                            f"common-val both F1="
                            f"{flexible_val_modes['both']['f1_micro']:.4f}"
                        )
                    else:
                        print(
                            "    [STALE] Flexible-VLM data, parents, or protocol "
                            "changed; retraining."
                        )
                    del flexible_ckpt
                except Exception as flexible_load_error:
                    print(
                        "    [WARN] Could not load flexible-VLM checkpoint: "
                        f"{flexible_load_error}"
                    )

            if not loaded_flexible_checkpoint:
                flexible_train_ds = MultiModalDataset(
                    mm_texts_tr,
                    mm_labels_tr,
                    mm_images_tr,
                    benchmark_tokenizer,
                    int(config.max_seq_length),
                    # Proxy pairs are class-aligned, not observations of the
                    # same leaf. Re-sample a same-class image on every access
                    # so one arbitrary invented pairing cannot be memorized.
                    resample_same_label=not linked_pair_mode,
                    augment_images=True,
                    minority_augment_max_strength=getattr(
                        config, 'minority_augment_max_strength', 1.0
                    ),
                )
                print(
                    f"    Flexible VLM training batch size: {flexible_batch_size} "
                    f"(gradient accumulation={config.gradient_accumulation_steps})"
                )
                flexible_train_loader = create_balanced_dataloader(
                    flexible_train_ds,
                    flat_labels_mm,
                    batch_size=flexible_batch_size,
                    num_classes=config.num_labels,
                    shuffle=True,
                )

                # Pooled out-of-fold paired parent probabilities for gate
                # calibration. The ~30-pair validation split cannot resolve the
                # mixing weight; this refits the two SELECTED parent
                # architectures inside grouped folds over the training pairs so
                # the weight is chosen on several times the held-out support.
                mixture_support = None
                if str(getattr(
                    config, 'gate_calibration_protocol', 'validation'
                )).lower() == 'out_of_fold_cv':
                    gate_cv_folds = max(2, int(getattr(
                        config, 'gate_calibration_cv_folds', 3
                    )))
                    print(
                        "\n>>> Building out-of-fold gate-calibration support "
                        f"({gate_cv_folds} grouped folds x "
                        f"{len(mm_texts_tr)} paired rows; refits "
                        f"{late_text_info['name']} + {late_vision_info['name']})..."
                    )
                    try:
                        mixture_support = out_of_fold_parent_pair_support(
                            build_text_model=(
                                lambda model_id=late_text_info[
                                    'pretrained_model_id'
                                ]: (
                                    _new_text_benchmark(model_id)
                                    if model_id else
                                    LightweightTextClassifier(
                                        num_labels=config.num_labels
                                    ).to(device)
                                )
                            ),
                            build_vision_model=(
                                lambda model_id=late_vision_info[
                                    'pretrained_model_id'
                                ]: (
                                    _new_vision_benchmark(model_id)
                                    if model_id else
                                    LightweightVisionClassifier(
                                        num_labels=config.num_labels
                                    ).to(device)
                                )
                            ),
                            texts=mm_texts_tr,
                            images=mm_images_tr,
                            labels=mm_labels_tr,
                            groups=mm_pair_groups_tr,
                            make_text_dataset=_make_text_cv_dataset,
                            make_vision_dataset=_make_vision_cv_dataset,
                            config=config,
                            device=device,
                            n_splits=gate_cv_folds,
                            seed=int(config.seed) + 4409,
                            text_batch_size=config.batch_size,
                            vision_batch_size=vision_batch_size,
                            text_diversity_weight=(
                                0.04 if using_pretrained_text else 1.0
                            ),
                            vision_diversity_weight=(
                                0.04 if using_pretrained_vision else 1.0
                            ),
                        )
                        results['gate_calibration_support'] = {
                            key: value
                            for key, value in mixture_support.items()
                            if key not in {
                                'labels', 'text_probabilities',
                                'image_probabilities', 'fold_index',
                            }
                        }
                    except Exception as mixture_support_error:
                        # A failed calibration refit must not lose the run; fall
                        # back to the historical validation grid and say so.
                        print(
                            "    [WARN] Out-of-fold gate-calibration support "
                            f"unavailable: {mixture_support_error}. Falling back "
                            "to validation-grid calibration."
                        )
                        mixture_support = None
                (flexible_best_f1, flexible_history, flexible_val_modes,
                 flexible_state) = train_flexible_cross_attention_vlm(
                    flexible_model,
                    flexible_train_loader,
                    val_loader,
                    config,
                    device,
                    teacher_model=(
                        early_fusion_teacher
                        if (
                            early_fusion_info is not None
                            and float(config.flexible_vlm_distillation_weight) > 0.0
                            and float(early_fusion_info['f1_micro'])
                            > max(
                                float(late_text_info['f1_micro']),
                                float(late_vision_info['f1_micro']),
                            )
                            and float(early_fusion_info['f1_macro'])
                            >= max(
                                float(late_text_info['f1_macro']),
                                float(late_vision_info['f1_macro']),
                            )
                        ) else None
                    ),
                    mixture_calibration_support=mixture_support,
                )
                flexible_model.load_state_dict(flexible_state, strict=True)
                flexible_params = sum(
                    p.numel() for p in flexible_model.parameters()
                )
                torch.save({
                    'model_state_dict': flexible_state,
                    'f1_score': flexible_best_f1,
                    'config': checkpoint_safe_metadata(config.__dict__),
                    'fusion_type': 'flexible_cross_attention',
                    'model_type': 'VLM',
                    'model_class': flexible_model_class,
                    'model_kwargs': flexible_kwargs,
                    'checkpoint_version': flexible_protocol,
                    'supports_modalities': ['text', 'image', 'text+image'],
                    'pairing_semantics': vlm_pairing_semantics,
                    'token_level_cross_attention': not bool(pretrained_fusion),
                    'pretrained_feature_cross_attention': False,
                    'effective_architecture': (
                        'pretrained_pooled_feature_gated_fusion'
                        if pretrained_fusion else
                        'token_level_cross_attention_fusion'
                    ),
                    'cross_attention_alignment_supported': not bool(
                        pretrained_fusion
                    ),
                    'pretrained_backbones': bool(pretrained_fusion),
                    'active_multimodal_calibration': True,
                    'adapter_training_improved_validation': bool(
                        flexible_history.get(
                            'adapter_training_improved_validation', False
                        )
                    ),
                    'random_residual_removed': bool(
                        flexible_history.get('random_residual_removed', False)
                    ),
                    'unimodal_endpoints_allowed_as_vlm': False,
                    'backbones_frozen': bool(config.flexible_vlm_freeze_backbones),
                    'num_params': flexible_params,
                    'parent_text': late_text_info['name'],
                    'parent_vision': late_vision_info['name'],
                    'tokenizer_id': late_text_info.get('tokenizer_id'),
                    'processor_id': late_vision_info.get('processor_id'),
                    'parent_text_digest': late_text_digest,
                    'parent_vision_digest': late_vision_digest,
                    'teacher_model': (
                        early_fusion_info['name'] if early_fusion_info else None
                    ),
                    'teacher_digest': early_teacher_digest,
                    'teacher_selection_split': 'validation',
                    'initial_text_prior': text_prior,
                    'data_fingerprint': data_fingerprint,
                    'flexible_vlm_fingerprint': flexible_fingerprint,
                    'evaluation_protocol': flexible_protocol,
                    'history': checkpoint_safe_metadata(flexible_history),
                }, flexible_checkpoint_path)
                print(f"  Saved: {flexible_checkpoint_path}")
                del flexible_state, flexible_train_loader, flexible_train_ds

            # Freeze the validation-selected checkpoint before touching test.
            flexible_test_modes = {
                'both': evaluate(
                    flexible_model, mm_test_loader, device, 'multimodal',
                    modality_mode='both',
                ),
                'text_only': evaluate(
                    flexible_model, mm_test_loader, device, 'multimodal',
                    modality_mode='text_only',
                ),
                'image_only': evaluate(
                    flexible_model, mm_test_loader, device, 'multimodal',
                    modality_mode='image_only',
                ),
            }

            # Reporting-only stress tests. These are evaluated after the
            # validation-selected checkpoint is frozen and never feed back into
            # architecture, gate, epoch, or checkpoint selection.
            try:
                flexible_robustness_results = evaluate_modality_robustness(
                    flexible_model,
                    mm_test_loader,
                    device,
                    model_type='multimodal',
                    seed=int(config.seed) + 18001,
                )
                flexible_robustness_results['true_missing_modality'] = {
                    'text_missing_image_only': {
                        'n': int(len(flexible_test_modes['image_only']['labels'])),
                        'accuracy': float(flexible_test_modes['image_only']['accuracy']),
                        'f1_micro': float(flexible_test_modes['image_only']['f1_micro']),
                        'f1_macro': float(flexible_test_modes['image_only']['f1_macro']),
                    },
                    'image_missing_text_only': {
                        'n': int(len(flexible_test_modes['text_only']['labels'])),
                        'accuracy': float(flexible_test_modes['text_only']['accuracy']),
                        'f1_micro': float(flexible_test_modes['text_only']['f1_micro']),
                        'f1_macro': float(flexible_test_modes['text_only']['f1_macro']),
                    },
                }
            except Exception as robustness_error:
                flexible_robustness_results = None
                print(
                    "    [WARN] Flexible-VLM robustness diagnostics skipped: "
                    f"{robustness_error}"
                )

            def _compact_flexible_metrics(metrics):
                return {
                    'n': int(len(metrics['labels'])),
                    'correct': int((metrics['predictions'] == metrics['labels']).sum()),
                    'f1_micro': float(metrics['f1_micro']),
                    'f1_macro': float(metrics['f1_macro']),
                    'precision': float(metrics['precision']),
                    'recall': float(metrics['recall']),
                    'accuracy': float(metrics['accuracy']),
                    'accuracy_ci95_low': float(metrics['accuracy_ci95_low']),
                    'accuracy_ci95_high': float(metrics['accuracy_ci95_high']),
                    'per_class_f1': [
                        float(v) for v in metrics.get('per_class_f1', [])
                    ],
                }

            flexible_params = sum(p.numel() for p in flexible_model.parameters())
            flexible_both = flexible_test_modes['both']
            flexible_fixed_weight = float(
                flexible_model.fixed_text_weight.detach().cpu()
            )
            flexible_text_temperature = float(
                flexible_model.log_temp_text.detach().exp().clamp(0.5, 5.0).cpu()
            )
            flexible_vision_temperature = float(
                flexible_model.log_temp_vision.detach().exp().clamp(0.5, 5.0).cpu()
            )
            flexible_calibration = flexible_history.get(
                'validation_fusion_calibration', {}
            )
            flexible_effective_mode = flexible_calibration.get(
                'selected_mode',
                (
                    'fixed_gate_pooled_feature_fusion'
                    if pretrained_fusion else 'fixed_gate_cross_attention'
                ) if flexible_fixed_weight >= 0.0 else (
                    'adaptive_pooled_feature_fusion'
                    if pretrained_fusion else 'adaptive_cross_attention'
                ),
            )
            adapter_training_improved = bool(flexible_history.get(
                'adapter_training_improved_validation', False
            ))
            cross_attention_gain_observed = bool(
                not pretrained_fusion
                and adapter_training_improved
                and flexible_effective_mode in {
                    'adaptive_cross_attention',
                    'fixed_gate_cross_attention',
                }
            )
            results['vlm_models']['flexible_cross_attention'] = {
                'f1': float(flexible_both['f1_micro']),
                'f1_macro': float(flexible_both['f1_macro']),
                'precision': float(flexible_both['precision']),
                'recall': float(flexible_both['recall']),
                'accuracy': float(flexible_both['accuracy']),
                **_heldout_evidence(flexible_both),
                'validation_f1': float(
                    flexible_val_modes['both']['f1_micro']
                ),
                'validation_f1_macro': float(
                    flexible_val_modes['both']['f1_macro']
                ),
                'test_f1': float(flexible_both['f1_micro']),
                'params': flexible_params,
                'history': flexible_history,
                'checkpoint': str(flexible_checkpoint_path),
                'per_class_f1': flexible_both.get('per_class_f1'),
                'model_class': flexible_model_class,
                'model_kwargs': flexible_kwargs,
                'supports_modalities': ['text', 'image', 'text+image'],
                'token_level_cross_attention': not bool(pretrained_fusion),
                'pretrained_feature_cross_attention': False,
                'effective_architecture': (
                    'pretrained_pooled_feature_gated_fusion'
                    if pretrained_fusion else
                    'token_level_cross_attention_fusion'
                ),
                'cross_attention_alignment_supported': not bool(
                    pretrained_fusion
                ),
                'pretrained_backbones': bool(pretrained_fusion),
                'architecture_multimodal_capable': True,
                'effective_mode': flexible_effective_mode,
                'adapter_training_improved_validation': (
                    adapter_training_improved
                ),
                'cross_attention_gain_observed': (
                    cross_attention_gain_observed
                ),
                'cross_attention_active': cross_attention_gain_observed,
                'random_residual_removed': bool(
                    flexible_history.get('random_residual_removed', False)
                ),
                'uses_text': True,
                'uses_image': True,
                'active_multimodal': True,
                'unimodal_endpoint_fallback': False,
                'active_multimodal_calibration': True,
                'modality_dropout': flexible_kwargs['modality_dropout'],
                'initial_text_prior': text_prior,
                'teacher_model': (
                    early_fusion_info['name'] if early_fusion_info else None
                ),
                'teacher_selection_split': 'validation',
                'selected_fusion_calibration': flexible_calibration,
                'deployed_fixed_text_weight': flexible_fixed_weight,
                'deployed_reliability_gate': bool(
                    flexible_calibration.get('reliability_gate_deployed', False)
                ),
                'gate_calibration_support': flexible_calibration.get(
                    'calibration_support'
                ),
                'gate_calibration_support_n': flexible_calibration.get(
                    'calibration_support_n'
                ),
                'gate_selection_macro_f1': flexible_calibration.get(
                    'selection_macro_f1'
                ),
                'no_harm_fallback_applied': bool(
                    flexible_calibration.get('no_harm_fallback_applied', False)
                ),
                'deployed_text_temperature': flexible_text_temperature,
                'deployed_vision_temperature': flexible_vision_temperature,
                'pairing_semantics': vlm_pairing_semantics,
                'evaluation_scope': vlm_evaluation_scope,
                'mode_metrics': {
                    mode: _compact_flexible_metrics(metrics)
                    for mode, metrics in flexible_test_modes.items()
                },
                'implementation': (
                    'One jointly trainable text/image model with '
                    + ('pretrained pooled-feature gated residual fusion'
                       if pretrained_fusion else
                       'bidirectional token-level cross-attention')
                    + ' and exact missing-modality parent paths; '
                    + (
                        'adapter improved validation macro/micro-F1'
                        if adapter_training_improved else
                        'epoch-0 adapter did not improve validation, so the '
                        'deployed residual is zero and parents are calibrated '
                        'in probability space'
                    )
                ),
            }
            print(
                "  Flexible VLM held-out macro / accuracy(=micro-F1): "
                f"both={flexible_test_modes['both']['f1_macro']:.4f}/"
                f"{flexible_test_modes['both']['f1_micro']:.4f}, "
                f"text={flexible_test_modes['text_only']['f1_macro']:.4f}/"
                f"{flexible_test_modes['text_only']['f1_micro']:.4f}, "
                f"image={flexible_test_modes['image_only']['f1_macro']:.4f}/"
                f"{flexible_test_modes['image_only']['f1_micro']:.4f}"
            )
            del flexible_model
            flexible_model = None
            gc.collect()
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        except Exception as flexible_error:
            print(f"  [WARN] Flexible cross-attention VLM failed: {flexible_error}")
            flexible_model = None
            flexible_val_modes = None
            flexible_test_modes = None
            flexible_robustness_results = None
            gc.collect()
            if torch.cuda.is_available():
                torch.cuda.empty_cache()

        print("\n>>> Training VLM baseline (pretrained_late_fusion)...")
        # Bias the initial late-fusion gate toward the stronger validation expert.
        late_model = LateFusionClassifier(
            late_text_parent,
            late_vision_parent,
            num_labels=config.num_labels,
            text_prior=text_prior,
        ).to(device)
        late_learning_rate = min(
            2e-3, max(5e-4, float(config.learning_rate) * 5.0)
        )
        late_max_epochs = max(8, min(20, int(config.epochs) + 4))
        late_patience = min(
            6, max(3, int(getattr(config, 'early_stopping_patience', 6)))
        )
        late_protocol = (
            'pretrained_late_fusion_validation_macro_calibrated_v5|'
            f'parent_selection:{parent_selection_protocol}'
            + (
                f':{parent_cv_folds}fold|'
                if parent_selection_protocol == 'out_of_fold_cv' else '|'
            ) +
            f'lr:{late_learning_rate:.12g}|weight_decay:0.001|'
            f'max_epochs:{late_max_epochs}|patience:{late_patience}|'
            f'batch:{int(config.batch_size)}|'
            'epoch_checkpoint:macro_micro_nll_v2|'
            'epoch_patience:macro_micro_v2|calibration_tiebreak:nll_v1'
        )

        late_identity_raw = (
            f"{data_fingerprint}|{late_protocol}|"
            f"text:{late_text_info['name']}:{late_text_digest}|"
            f"vision:{late_vision_info['name']}:{late_vision_digest}"
        )
        late_fingerprint = _hl.sha256(late_identity_raw.encode('utf-8')).hexdigest()[:12]
        late_checkpoint_path = config.checkpoint_dir / 'vlm_pretrained_late_fusion_best.pt'
        late_history = {}
        late_val_metrics = None
        loaded_late_checkpoint = False

        if late_checkpoint_path.is_file():
            try:
                late_ckpt = torch.load(late_checkpoint_path, map_location='cpu')
                if (late_ckpt.get('late_fusion_fingerprint') == late_fingerprint
                        and late_ckpt.get('model_class') == 'LateFusionClassifier'):
                    late_model.load_state_dict(late_ckpt['model_state_dict'])
                    late_history = late_ckpt.get('history', {})
                    late_val_metrics = evaluate(late_model, val_loader, device, 'multimodal')
                    loaded_late_checkpoint = True
                    print(f"    [SKIP] compatible late-fusion checkpoint found; "
                          f"common-val F1={late_val_metrics['f1_micro']:.4f}")
                else:
                    print("    [STALE] Late-fusion parents/protocol changed; retraining calibrator.")
                del late_ckpt
            except Exception as late_load_error:
                print(f"    [WARN] Could not load late-fusion checkpoint: {late_load_error}")

        if not loaded_late_checkpoint:
            late_best_f1, late_history, late_val_metrics, late_state = train_late_fusion_model(
                late_model, train_loader, val_loader, config, device
            )
            late_model.load_state_dict(late_state)
            total_parameters = sum(p.numel() for p in late_model.parameters())
            trainable_parameters = sum(p.numel() for p in late_model.parameters()
                                       if p.requires_grad)
            torch.save({
                'model_state_dict': late_state,
                'f1_score': late_best_f1,
                'config': checkpoint_safe_metadata(config.__dict__),
                'fusion_type': 'pretrained_late_fusion',
                'model_type': 'VLM',
                'model_class': 'LateFusionClassifier',
                'num_params': total_parameters,
                'trainable_params': trainable_parameters,
                'text_prior': text_prior,
                'parent_text': late_text_info['name'],
                'parent_vision': late_vision_info['name'],
                'parent_text_digest': late_text_digest,
                'parent_vision_digest': late_vision_digest,
                'data_fingerprint': data_fingerprint,
                'late_fusion_fingerprint': late_fingerprint,
                'evaluation_protocol': late_protocol,
                'history': checkpoint_safe_metadata(late_history),
            }, late_checkpoint_path)
            print(f"  Saved: {late_checkpoint_path}")

        # One common held-out evaluation for all fixed comparison conditions.
        # This is the only apples-to-apples claim: every score below uses the
        # exact same label-aligned proxy pairs.
        common_text_test = evaluate(late_model.text_model, mm_test_loader, device, 'text')
        common_vision_test = evaluate(late_model.vision_model, mm_test_loader, device, 'vision')
        late_test_metrics = evaluate(late_model, mm_test_loader, device, 'multimodal')
        early_test_metrics = (
            evaluate(early_fusion_teacher, mm_test_loader, device, 'multimodal')
            if early_fusion_teacher is not None and early_fusion_info is not None
            else None
        )
        # Prespecified simple text+image baseline for the four-way modality
        # comparison. This is always the concat architecture; it is not picked
        # after seeing test scores. Reuse the validation-selected teacher when
        # it happens to be concat, otherwise reconstruct the saved concat model.
        simple_concat_test_metrics = None
        if (early_test_metrics is not None and early_fusion_info is not None
                and early_fusion_info['name'] == 'concat'):
            simple_concat_test_metrics = early_test_metrics
            try:
                simple_concat_robustness_results = evaluate_modality_robustness(
                    early_fusion_teacher,
                    mm_test_loader,
                    device,
                    model_type='multimodal',
                    seed=int(config.seed) + 18001,
                )
            except Exception as robustness_error:
                print(
                    "    [WARN] Concat robustness diagnostics skipped: "
                    f"{robustness_error}"
                )
        elif 'concat' in results.get('vlm_models', {}):
            simple_concat_model = None
            simple_concat_checkpoint = None
            try:
                simple_concat_path = Path(
                    results['vlm_models']['concat']['checkpoint']
                )
                simple_concat_checkpoint = torch.load(
                    simple_concat_path, map_location='cpu'
                )
                if simple_concat_checkpoint.get('data_fingerprint') != data_fingerprint:
                    raise ValueError('concat checkpoint fingerprint mismatch')
                simple_concat_model = MultiModalClassifier(
                    num_labels=config.num_labels, fusion_type='concat'
                ).to(device)
                simple_concat_model.load_state_dict(
                    simple_concat_checkpoint['model_state_dict'], strict=True
                )
                simple_concat_test_metrics = evaluate(
                    simple_concat_model, mm_test_loader, device, 'multimodal'
                )
                try:
                    simple_concat_robustness_results = evaluate_modality_robustness(
                        simple_concat_model,
                        mm_test_loader,
                        device,
                        model_type='multimodal',
                        seed=int(config.seed) + 18001,
                    )
                except Exception as robustness_error:
                    print(
                        "    [WARN] Concat robustness diagnostics skipped: "
                        f"{robustness_error}"
                    )
            except Exception as concat_comparison_error:
                print(
                    "    [WARN] Simple concat comparison unavailable: "
                    f"{concat_comparison_error}"
                )
                simple_concat_test_metrics = None
            finally:
                if simple_concat_model is not None:
                    del simple_concat_model
                if simple_concat_checkpoint is not None:
                    del simple_concat_checkpoint
                gc.collect()
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
        common_label_reference = np.asarray(common_text_test['labels'])
        common_metric_sets = {
            'vision_parent': common_vision_test,
            'pretrained_late_fusion': late_test_metrics,
        }
        if simple_concat_test_metrics is not None:
            common_metric_sets['concat_baseline'] = simple_concat_test_metrics
        if early_test_metrics is not None:
            common_metric_sets['validation_selected_early_fusion'] = early_test_metrics
        if flexible_test_modes is not None:
            common_metric_sets['flexible_cross_attention'] = flexible_test_modes['both']
        for common_name, common_metrics in common_metric_sets.items():
            if not np.array_equal(
                common_label_reference, np.asarray(common_metrics['labels'])
            ):
                raise RuntimeError(
                    f"Common-test label/order mismatch for {common_name}; refusing comparison"
                )

        def _common_metric_summary(metrics):
            labels_array = np.asarray(metrics['labels'])
            predictions_array = np.asarray(metrics['predictions'])
            probabilities_array = np.asarray(metrics['probabilities'], dtype=float)
            correct_count = int((predictions_array == labels_array).sum())
            ci_low, ci_high = wilson_score_interval(
                correct_count, int(len(labels_array))
            )
            per_class_values = metrics.get('per_class_f1')
            if per_class_values is None:
                per_class_values = []
            summary = {
                'n': int(len(labels_array)),
                'correct': correct_count,
                'f1_micro': float(metrics['f1_micro']),
                'f1_macro': float(metrics['f1_macro']),
                'f1_weighted': float(metrics['f1_weighted']),
                'precision': float(metrics['precision']),
                'recall': float(metrics['recall']),
                'accuracy': float(metrics['accuracy']),
                'accuracy_ci95_low': float(ci_low),
                'accuracy_ci95_high': float(ci_high),
                'accuracy_ci_method': (
                    'Wilson score interval; sample-level, conditional on one fit'
                ),
                'class_support': {
                    STRESS_LABELS[class_id]: int(
                        np.sum(labels_array == class_id)
                    )
                    for class_id in range(len(STRESS_LABELS))
                },
                'per_class_f1': [float(v) for v in per_class_values],
                # Small held-out arrays are intentionally retained as JSON-safe
                # lists. They enable paired uncertainty, significance,
                # complementarity, and calibration analysis without retraining.
                'labels': labels_array.astype(int).tolist(),
                'predictions': predictions_array.astype(int).tolist(),
                'probabilities': probabilities_array.astype(float).tolist(),
            }
            if metrics.get('fusion_gate') is not None:
                gate = np.asarray(metrics['fusion_gate'], dtype=float).reshape(-1)
                if len(gate) == len(labels_array):
                    summary['effective_text_weight'] = gate.tolist()
            return summary

        common_test = {
            'evaluation_scope': vlm_evaluation_scope,
            'selection': ('parents, epochs, early/flexible/late architecture, gate mode, '
                          'and alpha selected using validation only'),
            'test_used_for_selection': False,
            'text_parent_name': late_text_info['name'],
            'vision_parent_name': late_vision_info['name'],
            'text_parent': _common_metric_summary(common_text_test),
            'vision_parent': _common_metric_summary(common_vision_test),
            'pretrained_late_fusion': _common_metric_summary(late_test_metrics),
        }
        late_alpha_for_selection = float(late_model.fixed_alpha.detach().cpu())
        late_is_active_multimodal = (
            late_alpha_for_selection < 0.0
            or 1e-12 < late_alpha_for_selection < 1.0 - 1e-12
        )
        common_test['pretrained_late_fusion'].update({
            'uses_text': bool(late_is_active_multimodal or late_alpha_for_selection >= 1.0 - 1e-12),
            'uses_image': bool(late_is_active_multimodal or late_alpha_for_selection <= 1e-12),
            'active_multimodal': bool(late_is_active_multimodal),
            'effective_mode': (
                'adaptive_late_fusion' if late_alpha_for_selection < 0.0
                else 'fixed_late_fusion' if late_is_active_multimodal
                else 'image_parent_fallback' if late_alpha_for_selection <= 1e-12
                else 'text_parent_fallback'
            ),
        })
        if simple_concat_test_metrics is not None:
            common_test['concat_baseline'] = _common_metric_summary(
                simple_concat_test_metrics
            )
            common_test['concat_baseline']['source_model_name'] = 'concat'
            common_test['concat_baseline']['role'] = (
                'prespecified simple text+image multimodal baseline'
            )
        multimodal_validation_candidates = []
        if ('concat_baseline' in common_test
                and 'concat' in results.get('vlm_models', {})):
            concat_result = results['vlm_models']['concat']
            multimodal_validation_candidates.append((
                float(concat_result.get('validation_f1_macro', 0.0)),
                float(concat_result.get('validation_f1', 0.0)),
                -1,
                'concat_baseline',
            ))
        if late_is_active_multimodal:
            multimodal_validation_candidates.append((
                float(late_val_metrics['f1_macro']),
                float(late_val_metrics['f1_micro']),
                0,
                'pretrained_late_fusion',
            ))
        if early_test_metrics is not None and early_fusion_info is not None:
            common_test['validation_selected_early_fusion'] = _common_metric_summary(
                early_test_metrics
            )
            common_test['validation_selected_early_fusion']['source_model_name'] = (
                early_fusion_info['name']
            )
            multimodal_validation_candidates.append((
                float(early_fusion_info['f1_macro']),
                float(early_fusion_info['f1_micro']),
                1,
                'validation_selected_early_fusion',
            ))
        if flexible_test_modes is not None and flexible_val_modes is not None:
            common_test['flexible_cross_attention'] = _common_metric_summary(
                flexible_test_modes['both']
            )
            multimodal_validation_candidates.append((
                float(flexible_val_modes['both']['f1_macro']),
                float(flexible_val_modes['both']['f1_micro']),
                2,
                'flexible_cross_attention',
            ))
        audited_common_keys = [
            key for key in (
                'vision_parent', 'concat_baseline',
                'validation_selected_early_fusion',
                'pretrained_late_fusion', 'flexible_cross_attention',
            )
            if key in common_test
        ]
        for common_key in audited_common_keys:
            common_test[common_key]['prediction_audit_vs_text_parent'] = (
                paired_prediction_change_audit(
                    common_test['text_parent'], common_test[common_key]
                )
            )

        signature_groups = {}
        for common_key in ['text_parent', *audited_common_keys]:
            signature = tuple(common_test[common_key]['predictions'])
            signature_groups.setdefault(signature, []).append(common_key)
        common_test['hard_prediction_equivalence_groups'] = [
            {
                'members': members,
                'n': int(common_test[members[0]]['n']),
                'identical_hard_predictions': True,
            }
            for members in signature_groups.values()
            if len(members) > 1
        ]
        # The held-out test values above are reporting only. This choice is made
        # solely from validation macro/micro F1; priority only resolves exact ties
        # in favour of the deployable flexible model.
        selected_multimodal_key = max(multimodal_validation_candidates)[-1]
        common_test['selected_multimodal_key'] = selected_multimodal_key
        common_test['selected_multimodal'] = dict(common_test[selected_multimodal_key])
        common_test['selected_multimodal']['name'] = selected_multimodal_key
        common_n = int(common_test['selected_multimodal']['n'])
        common_test['single_prediction_score_step'] = (
            1.0 / common_n if common_n else None
        )
        # Four requested conditions for modality ablation. The fourth starts as
        # a flexible cross-attention architecture, but its validation-selected
        # deployment may be a fixed two-parent mixture or a unimodal endpoint;
        # the effective label and modality flags below must reflect that choice.
        if ('concat_baseline' in common_test
                and 'flexible_cross_attention' in common_test):
            four_way_specs = [
                ('unimodal_image', 'Image only (unimodal)', 'vision_parent'),
                ('unimodal_text', 'Text only (unimodal)', 'text_parent'),
                ('standard_vlm_fusion',
                 'Standard VLM fusion (text + image concat)',
                 'concat_baseline'),
                ('proposed_multimodal_vlm',
                 'Proposed multimodal VLM (cross-attention)',
                 'flexible_cross_attention'),
            ]
            four_way_comparison = {}
            for comparison_key, display_name, metric_key in four_way_specs:
                comparison_row = dict(common_test[metric_key])
                comparison_row.update({
                    'display_name': display_name,
                    'metric_source': metric_key,
                    'uses_text': comparison_key != 'unimodal_image',
                    'uses_image': comparison_key != 'unimodal_text',
                    'is_multimodal': comparison_key in {
                        'standard_vlm_fusion', 'proposed_multimodal_vlm'
                    },
                })
                if comparison_key == 'proposed_multimodal_vlm':
                    calibration = results['vlm_models'][
                        'flexible_cross_attention'
                    ].get('selected_fusion_calibration', {})
                    deployed_fixed_weight = results['vlm_models'][
                        'flexible_cross_attention'
                    ].get('deployed_fixed_text_weight', -1.0)
                    token_cross_attention = bool(results['vlm_models'][
                        'flexible_cross_attention'
                    ].get('token_level_cross_attention', False))
                    selected_fusion_mode = calibration.get('selected_mode')
                    if not selected_fusion_mode:
                        selected_fusion_mode = (
                            (
                                'fixed_gate_cross_attention'
                                if token_cross_attention else
                                'fixed_gate_pooled_feature_fusion'
                            )
                            if float(deployed_fixed_weight) >= 0.0
                            else (
                                'adaptive_cross_attention'
                                if token_cross_attention else
                                'adaptive_pooled_feature_fusion'
                            )
                        )
                    selected_text_weight = calibration.get(
                        'selected_text_weight',
                        deployed_fixed_weight
                        if float(deployed_fixed_weight) >= 0.0 else None,
                    )
                    cross_attention_active = (
                        selected_fusion_mode in {
                            'adaptive_cross_attention',
                            'fixed_gate_cross_attention',
                        }
                    )
                    reliability_gate_active = (
                        selected_fusion_mode == 'reliability_gated_parent_mixture'
                    )
                    learned_fusion_active = selected_fusion_mode in {
                        'adaptive_cross_attention',
                        'fixed_gate_cross_attention',
                        'adaptive_pooled_feature_fusion',
                        'fixed_gate_pooled_feature_fusion',
                        # A per-sample reliability gate mixes both parents on
                        # every row; it is as multimodal as the learned adapters.
                        'reliability_gated_parent_mixture',
                    }
                    if learned_fusion_active:
                        effective_uses_text = True
                        effective_uses_image = True
                        effective_is_multimodal = True
                        effective_mode = selected_fusion_mode
                        if reliability_gate_active:
                            gate_mean = (calibration.get(
                                'reliability_gate_fit'
                            ) or {}).get('per_sample_text_weight_mean')
                            effective_display = (
                                'Proposed flexible VLM (per-sample '
                                'reliability-gated fusion'
                                + (
                                    f'; mean text weight={float(gate_mean):.2f})'
                                    if gate_mean is not None else ')'
                                )
                            )
                            plot_label = 'Proposed reliability-gated VLM'
                        elif selected_fusion_mode in {
                            'adaptive_cross_attention',
                            'adaptive_pooled_feature_fusion',
                        }:
                            effective_display = (
                                'Proposed flexible VLM ('
                                + (
                                    'adaptive cross-attention'
                                    if cross_attention_active else
                                    'adaptive pooled-feature fusion'
                                )
                                + ')'
                            )
                            plot_label = 'Proposed adaptive VLM'
                        else:
                            effective_display = (
                                'Proposed flexible VLM (validated interior gate; '
                                f'text weight={float(selected_text_weight):.2f})'
                            )
                            plot_label = (
                                'Proposed active VLM '
                                f'(w_text={float(selected_text_weight):.2f})'
                            )
                    else:
                        try:
                            selected_text_weight = float(selected_text_weight)
                        except (TypeError, ValueError):
                            selected_text_weight = None
                        effective_uses_text = (
                            selected_text_weight is not None
                            and selected_text_weight > 1e-12
                        )
                        effective_uses_image = (
                            selected_text_weight is not None
                            and selected_text_weight < 1.0 - 1e-12
                        )
                        effective_is_multimodal = (
                            effective_uses_text and effective_uses_image
                        )
                        if effective_is_multimodal:
                            effective_mode = 'fixed_parent_mixture'
                            effective_display = (
                                'Validation-selected fixed parent mixture '
                                f'(text weight={selected_text_weight:.2f})'
                            )
                            plot_label = (
                                f'Fixed parent mixture (w_text={selected_text_weight:.2f})'
                            )
                        elif effective_uses_text:
                            effective_mode = 'text_parent_fallback'
                            effective_display = (
                                'Validation-selected text-parent fallback '
                                '(cross-attention inactive)'
                            )
                            plot_label = 'Text-parent fallback'
                        elif effective_uses_image:
                            effective_mode = 'image_parent_fallback'
                            effective_display = (
                                'Validation-selected image-parent fallback '
                                '(cross-attention inactive)'
                            )
                            plot_label = 'Image-parent fallback'
                        else:
                            effective_mode = 'unknown_fixed_fallback'
                            effective_display = (
                                'Validation-selected fixed fallback '
                                '(weight unavailable)'
                            )
                            plot_label = 'Fixed fallback'
                    comparison_row.update({
                        'validation_selected_fusion_mode': selected_fusion_mode,
                        'validation_selected_text_weight': selected_text_weight,
                        'cross_attention_active': cross_attention_active,
                        'learned_fusion_active': learned_fusion_active,
                        'effective_mode': effective_mode,
                        'display_name': effective_display,
                        'plot_label': plot_label,
                        'uses_text': effective_uses_text,
                        'uses_image': effective_uses_image,
                        'is_multimodal': effective_is_multimodal,
                    })
                four_way_comparison[comparison_key] = comparison_row
            common_test['four_way_modality_comparison'] = four_way_comparison
            common_test['four_way_metadata'] = {
                'order': [spec[0] for spec in four_way_specs],
                'metric_sources': [spec[2] for spec in four_way_specs],
                'architectures_pre_specified': True,
                'identical_test_support_asserted': True,
                'test_used_for_selection': False,
                'note': (
                    'concat is multimodal; the proposed condition is labelled '
                    'by its validation-selected effective mode, including any '
                    'fixed-parent or unimodal endpoint fallback'
                ),
            }
            common_test['four_way_metadata']['proposed_effective_mode'] = (
                four_way_comparison['proposed_multimodal_vlm'].get(
                    'effective_mode'
                )
            )
            common_test['four_way_metadata'][
                'proposed_effective_is_multimodal'
            ] = bool(
                four_way_comparison['proposed_multimodal_vlm'].get(
                    'is_multimodal'
                )
            )
            observed_best_f1_micro = max(
                row['f1_micro'] for row in four_way_comparison.values()
            )
            observed_best_f1_macro = max(
                row['f1_macro'] for row in four_way_comparison.values()
            )
            common_test['four_way_metadata']['observed_micro_leaders'] = [
                key for key, row in four_way_comparison.items()
                if abs(row['f1_micro'] - observed_best_f1_micro) < 1e-12
            ]
            # Macro-F1 is the prespecified primary comparison because common
            # image support is severely imbalanced. Micro-F1 equals accuracy
            # in this single-label task and remains reported as a secondary
            # descriptive metric.
            common_test['four_way_metadata']['primary_metric'] = 'f1_macro'
            common_test['four_way_metadata']['observed_common_test_leaders'] = [
                key for key, row in four_way_comparison.items()
                if abs(row['f1_macro'] - observed_best_f1_macro) < 1e-12
            ]
            common_test['four_way_metadata'][
                'proposed_is_observed_common_test_leader'
            ] = (
                'proposed_multimodal_vlm'
                in common_test['four_way_metadata'][
                    'observed_common_test_leaders'
                ]
            )
            common_test['four_way_metadata']['observed_best_f1_micro'] = (
                observed_best_f1_micro
            )
            common_test['four_way_metadata']['observed_best_f1_macro'] = (
                observed_best_f1_macro
            )
            proposed_f1_micro = float(
                four_way_comparison['proposed_multimodal_vlm']['f1_micro']
            )
            proposed_f1_macro = float(
                four_way_comparison['proposed_multimodal_vlm']['f1_macro']
            )
            proposed_accuracy = float(
                four_way_comparison['proposed_multimodal_vlm']['accuracy']
            )
            proposed_accuracy_target = float(
                getattr(config, 'proposed_accuracy_target', 0.90)
            )
            proposed_target_evidence = accuracy_target_evidence(
                int(four_way_comparison['proposed_multimodal_vlm']['correct']),
                int(four_way_comparison['proposed_multimodal_vlm']['n']),
                proposed_accuracy_target,
            )
            proposed_accuracy_target_statistically_supported = bool(
                proposed_target_evidence['target_supported']
            )
            claim_baselines = {
                key: row for key, row in four_way_comparison.items()
                if key != 'proposed_multimodal_vlm'
            }
            # The four-way ablation intentionally uses concat as its standard
            # VLM condition, but any "best" claim must also include the
            # separately reported validation-selected late-fusion baseline.
            claim_baselines['pretrained_late_fusion'] = common_test[
                'pretrained_late_fusion'
            ]
            strongest_baseline_f1_macro = max(
                float(row['f1_macro']) for row in claim_baselines.values()
            )
            strongest_baseline_f1_micro = max(
                float(row['f1_micro']) for row in claim_baselines.values()
            )
            proposed_gain = (
                proposed_f1_macro - strongest_baseline_f1_macro
            )
            proposed_is_active_multimodal = bool(
                four_way_comparison['proposed_multimodal_vlm'].get(
                    'is_multimodal'
                )
            )
            taxonomy_claim_eligible = bool(
                taxonomy_audit.get('claim_eligible', False)
            )
            paired_observation_claim_eligible = bool(linked_pair_mode)
            proposed_accuracy_target_met = bool(
                proposed_accuracy_target_statistically_supported
                and taxonomy_claim_eligible
                and paired_observation_claim_eligible
            )
            proposed_strictly_best = proposed_gain > 1e-12
            proposed_row = four_way_comparison['proposed_multimodal_vlm']
            paired_superiority_tests = []
            for baseline_key, baseline_row in claim_baselines.items():
                paired_superiority_tests.append({
                    'baseline': baseline_key,
                    'gain_accuracy': (
                        float(proposed_row['accuracy'])
                        - float(baseline_row['accuracy'])
                    ),
                    'p_exact': exact_mcnemar_pvalue(
                        proposed_row['labels'],
                        proposed_row['predictions'],
                        baseline_row['predictions'],
                    ),
                })
            ranked_test_indices = sorted(
                range(len(paired_superiority_tests)),
                key=lambda index: paired_superiority_tests[index]['p_exact'],
            )
            running_adjusted_p = 0.0
            for rank, test_index in enumerate(ranked_test_indices):
                adjusted_p = min(
                    1.0,
                    (len(paired_superiority_tests) - rank)
                    * paired_superiority_tests[test_index]['p_exact'],
                )
                running_adjusted_p = max(running_adjusted_p, adjusted_p)
                paired_superiority_tests[test_index]['p_holm'] = float(
                    running_adjusted_p
                )
            paired_accuracy_superiority_supported = bool(
                paired_superiority_tests
                and all(
                    row['gain_accuracy'] > 0.0 and row['p_holm'] < 0.05
                    for row in paired_superiority_tests
                )
            )
            macro_leader_with_paired_accuracy_support = bool(
                proposed_strictly_best
                and proposed_is_active_multimodal
                and taxonomy_claim_eligible
                and paired_observation_claim_eligible
                and paired_accuracy_superiority_supported
            )
            # Backward-compatible aliases. The scoped fields below make clear
            # that exact McNemar tests evaluate paired accuracy, not macro-F1.
            statistical_superiority_supported = (
                paired_accuracy_superiority_supported
            )
            best_claim_supported = macro_leader_with_paired_accuracy_support
            common_test['four_way_metadata'].update({
                'strongest_non_proposed_f1_micro': strongest_baseline_f1_micro,
                'strongest_non_proposed_f1_macro': strongest_baseline_f1_macro,
                'proposed_gain_over_strongest_baseline': proposed_gain,
                'proposed_gain_metric': 'f1_macro',
                'proposed_is_strictly_best': proposed_strictly_best,
                'proposed_is_active_multimodal': proposed_is_active_multimodal,
                'taxonomy_claim_eligible': taxonomy_claim_eligible,
                'paired_observation_claim_eligible': (
                    paired_observation_claim_eligible
                ),
                'paired_accuracy_superiority_tests': paired_superiority_tests,
                'paired_superiority_tests': paired_superiority_tests,
                'paired_test_metric': 'accuracy',
                'paired_test_method': (
                    'two-sided exact McNemar with Holm correction'
                ),
                'paired_accuracy_superiority_supported': (
                    paired_accuracy_superiority_supported
                ),
                'statistical_superiority_supported': (
                    statistical_superiority_supported
                ),
                'proposed_accuracy': proposed_accuracy,
                'proposed_accuracy_target': proposed_accuracy_target,
                'proposed_accuracy_target_met': proposed_accuracy_target_met,
                'proposed_accuracy_target_statistically_supported': (
                    proposed_accuracy_target_statistically_supported
                ),
                'proposed_accuracy_target_requires_verified_taxonomy': True,
                'proposed_accuracy_target_requires_linked_observations': True,
                'proposed_accuracy_point_target_met': (
                    proposed_target_evidence['point_target_met']
                ),
                'proposed_accuracy_target_evidence': proposed_target_evidence,
                'macro_leader_with_paired_accuracy_support': (
                    macro_leader_with_paired_accuracy_support
                ),
                'best_claim_supported': best_claim_supported,
            })
            results['four_way_modality_comparison'] = four_way_comparison
            results['four_way_modality_comparison_metadata'] = dict(
                common_test['four_way_metadata']
            )

            # Headline baseline-vs-proposed figure (plot 35). The comparator is
            # the STRONGEST baseline on this identical support, never a weak one
            # chosen to flatter the proposed model, so the figure shows a loss
            # whenever the proposed model actually loses.
            _summary_baselines = {
                key: row for key, row in four_way_comparison.items()
                if key != 'proposed_multimodal_vlm'
            }
            _summary_baselines['pretrained_late_fusion'] = dict(
                common_test['pretrained_late_fusion'],
                display_name='Late fusion (validation-calibrated)',
            )
            _summary_baseline_key = max(
                _summary_baselines,
                key=lambda key: (
                    float(_summary_baselines[key]['f1_macro']),
                    float(_summary_baselines[key]['f1_micro']),
                    key,
                ),
            )
            _summary_baseline = _summary_baselines[_summary_baseline_key]
            _summary_proposed = four_way_comparison['proposed_multimodal_vlm']

            def _summary_metrics(row):
                return {
                    'f1': float(row['f1_macro']),
                    'precision': float(row['precision']),
                    'recall': float(row['recall']),
                    'accuracy': float(row['accuracy']),
                    'correct': int(row['correct']),
                    'n': int(row['n']),
                }

            results['summary_comparison'] = {
                'same_test_support': True,
                'n': int(_summary_proposed['n']),
                'primary_metric': 'f1_macro',
                'metric_note': (
                    "'f1' is macro-F1; accuracy equals micro-F1 for this "
                    'single-label multiclass task'
                ),
                'baseline_key': _summary_baseline_key,
                'baseline_name': str(
                    _summary_baseline.get('display_name', _summary_baseline_key)
                ),
                'baseline_selection_rule': (
                    'strongest baseline by macro-F1 on the identical common '
                    'held-out support'
                ),
                'proposed_name': str(
                    _summary_proposed.get('display_name',
                                          'Proposed multimodal VLM')
                ),
                'baseline': _summary_metrics(_summary_baseline),
                'proposed': _summary_metrics(_summary_proposed),
                'proposed_minus_baseline_f1_macro': float(
                    _summary_proposed['f1_macro']
                    - _summary_baseline['f1_macro']
                ),
                'proposed_beats_strongest_baseline': bool(
                    float(_summary_proposed['f1_macro'])
                    > float(_summary_baseline['f1_macro'])
                ),
                'all_baselines': {
                    key: _summary_metrics(row)
                    for key, row in _summary_baselines.items()
                },
                'test_used_for_selection': False,
            }

            # Mutually exclusive account of every proposed-model error on the
            # common test, categorised by what the two parents got right. This
            # is a measured partition of the errors, not an interpretation.
            _err_labels = np.asarray(_summary_proposed['labels'], dtype=int)
            _err_proposed = np.asarray(
                _summary_proposed['predictions'], dtype=int
            ) == _err_labels
            _err_image = np.asarray(
                four_way_comparison['unimodal_image']['predictions'], dtype=int
            ) == _err_labels
            _err_text = np.asarray(
                four_way_comparison['unimodal_text']['predictions'], dtype=int
            ) == _err_labels
            _err_wrong = ~_err_proposed
            results['error_analysis'] = {
                'measured': True,
                'scope': (
                    'proposed-model errors on the common held-out support, '
                    'partitioned by parent correctness'
                ),
                'n': int(len(_err_labels)),
                'partition_is_exhaustive_and_exclusive': True,
                'counts': {
                    'Both parents correct': int(
                        np.sum(_err_wrong & _err_image & _err_text)
                    ),
                    'Only image correct': int(
                        np.sum(_err_wrong & _err_image & ~_err_text)
                    ),
                    'Only text correct': int(
                        np.sum(_err_wrong & ~_err_image & _err_text)
                    ),
                    'Neither parent correct': int(
                        np.sum(_err_wrong & ~_err_image & ~_err_text)
                    ),
                },
            }
            results['our_multimodal_model_claim'] = {
                'model': 'flexible_cross_attention',
                'active_multimodal': bool(
                    four_way_comparison['proposed_multimodal_vlm'][
                        'is_multimodal'
                    ]
                ),
                'common_test_f1_micro': proposed_f1_micro,
                'common_test_f1_macro': proposed_f1_macro,
                'common_test_accuracy': proposed_accuracy,
                'accuracy_target': proposed_accuracy_target,
                'accuracy_target_met': proposed_accuracy_target_met,
                'accuracy_target_statistically_supported': (
                    proposed_accuracy_target_statistically_supported
                ),
                'accuracy_target_requires_verified_taxonomy': True,
                'accuracy_target_requires_linked_observations': True,
                'taxonomy_claim_eligible': taxonomy_claim_eligible,
                'paired_observation_claim_eligible': (
                    paired_observation_claim_eligible
                ),
                'accuracy_point_target_met': (
                    proposed_target_evidence['point_target_met']
                ),
                'accuracy_target_evidence': proposed_target_evidence,
                'strongest_baseline_f1_micro': strongest_baseline_f1_micro,
                'strongest_baseline_f1_macro': strongest_baseline_f1_macro,
                'gain': proposed_gain,
                'gain_metric': 'f1_macro',
                'macro_leader_with_paired_accuracy_support': (
                    macro_leader_with_paired_accuracy_support
                ),
                'paired_accuracy_superiority_supported': (
                    paired_accuracy_superiority_supported
                ),
                'paired_test_metric': 'accuracy',
                'paired_test_method': (
                    'two-sided exact McNemar with Holm correction'
                ),
                'claim_scope': (
                    'descriptive macro-F1 lead plus paired accuracy superiority'
                ),
                'claim_supported': best_claim_supported,
                'wording': (
                    'The proposed active multimodal model has the highest measured '
                    'macro-F1 on the common held-out test. Separately, its paired '
                    'accuracy advantage over every baseline is significant under '
                    'Holm-corrected two-sided exact McNemar tests.'
                    if best_claim_supported else
                    (
                        'The proposed model has the highest measured held-out macro-F1, '
                        'but the configured disease taxonomy is not verified; no '
                        'scientific superiority claim is emitted.'
                        if proposed_strictly_best and not taxonomy_claim_eligible else
                        (
                            'The proposed model has the highest measured proxy-pair '
                            'macro-F1, but text and image are not linked observations; '
                            'no multimodal superiority claim is emitted.'
                            if proposed_strictly_best
                            and not paired_observation_claim_eligible else
                            (
                            'The proposed model has the highest measured held-out '
                            'macro-F1, but Holm-corrected two-sided exact McNemar '
                            'tests do not support an accuracy advantage over every '
                            'baseline; no statistical superiority claim is emitted.'
                            if proposed_strictly_best else
                        'The held-out test does not support claiming that our '
                        'active multimodal model is best.'
                            )
                        )
                    )
                ),
                'test_used_for_selection': False,
                'taxonomy_audit_status': taxonomy_audit.get('status'),
            }
            if best_claim_supported:
                results['active_multimodal_winner'] = {
                    'name': 'flexible_cross_attention',
                    'f1_micro': proposed_f1_micro,
                    'f1_macro': proposed_f1_macro,
                    'gain_over_strongest_baseline': proposed_gain,
                    'primary_metric': 'f1_macro',
                    'macro_f1_evidence': 'descriptive point estimate',
                    'paired_significance_metric': 'accuracy',
                    'paired_accuracy_superiority_supported': True,
                    'evaluation_scope': common_test['evaluation_scope'],
                }
            try:
                four_way_csv_path = (
                    config.output_dir / 'four_way_modality_comparison.csv'
                )
                pd.DataFrame([
                    {
                        'condition': key,
                        'display_name': row['display_name'],
                        'uses_text': row['uses_text'],
                        'uses_image': row['uses_image'],
                        'is_multimodal': row['is_multimodal'],
                        'n': row['n'],
                        'correct': row['correct'],
                        'accuracy': row['accuracy'],
                        'accuracy_ci95_low': row['accuracy_ci95_low'],
                        'accuracy_ci95_high': row['accuracy_ci95_high'],
                        'f1_micro': row['f1_micro'],
                        'f1_macro': row['f1_macro'],
                        'precision': row['precision'],
                        'recall': row['recall'],
                    }
                    for key, row in four_way_comparison.items()
                ]).to_csv(four_way_csv_path, index=False)
                results['four_way_modality_comparison_csv'] = str(
                    four_way_csv_path
                )
            except Exception as comparison_csv_error:
                print(
                    "    [WARN] Could not save four-way comparison CSV: "
                    f"{comparison_csv_error}"
                )
        if (flexible_robustness_results is not None
                or simple_concat_robustness_results is not None):
            results['modality_robustness'] = {
                'evaluation_scope': vlm_evaluation_scope + '; reporting only',
                'test_used_for_selection': False,
                'models': {},
            }
            if simple_concat_robustness_results is not None:
                results['modality_robustness']['models'][
                    'standard_vlm_fusion'
                ] = simple_concat_robustness_results
            if flexible_robustness_results is not None:
                results['modality_robustness']['models'][
                    'proposed_multimodal_vlm'
                ] = flexible_robustness_results
        results['fusion_common_test'] = common_test

        total_parameters = sum(p.numel() for p in late_model.parameters())
        trainable_parameters = sum(p.numel() for p in late_model.parameters() if p.requires_grad)
        selected_alpha = float(late_model.fixed_alpha.detach().cpu())
        if selected_alpha < 0.0:
            late_effective_mode = 'adaptive_late_fusion'
            late_uses_text = True
            late_uses_image = True
        elif selected_alpha <= 1e-12:
            late_effective_mode = 'image_parent_fallback'
            late_uses_text = False
            late_uses_image = True
        elif selected_alpha >= 1.0 - 1e-12:
            late_effective_mode = 'text_parent_fallback'
            late_uses_text = True
            late_uses_image = False
        else:
            late_effective_mode = 'fixed_late_fusion'
            late_uses_text = True
            late_uses_image = True
        results['vlm_models']['pretrained_late_fusion'] = {
            'f1': float(late_test_metrics['f1_micro']),
            'f1_macro': float(late_test_metrics['f1_macro']),
            'precision': float(late_test_metrics['precision']),
            'recall': float(late_test_metrics['recall']),
            'accuracy': float(late_test_metrics['accuracy']),
            'validation_f1': float(late_val_metrics['f1_micro']),
            'validation_f1_macro': float(late_val_metrics['f1_macro']),
            'test_f1': float(late_test_metrics['f1_micro']),
            'params': total_parameters,
            'trainable_params': trainable_parameters,
            'history': late_history,
            'checkpoint': str(late_checkpoint_path),
            'per_class_f1': late_test_metrics.get('per_class_f1'),
            'model_class': 'LateFusionClassifier',
            'parent_text': late_text_info['name'],
            'parent_vision': late_vision_info['name'],
            'parent_text_digest': late_text_digest,
            'parent_vision_digest': late_vision_digest,
            'implementation': 'Frozen text/vision experts + validation-calibrated adaptive/convex late fusion',
            'selected_mode': 'adaptive' if selected_alpha < 0 else 'fixed_alpha',
            'selected_alpha': None if selected_alpha < 0 else selected_alpha,
            'architecture_multimodal_capable': True,
            'effective_mode': late_effective_mode,
            'uses_text': late_uses_text,
            'uses_image': late_uses_image,
            'active_multimodal': bool(late_uses_text and late_uses_image),
            'unimodal_endpoint_fallback': not bool(
                late_uses_text and late_uses_image
            ),
            'evaluation_scope': vlm_evaluation_scope,
        }
        selected_result_key = (
            early_fusion_info['name']
            if (selected_multimodal_key == 'validation_selected_early_fusion'
                and early_fusion_info is not None)
            else 'concat'
            if selected_multimodal_key == 'concat_baseline'
            else selected_multimodal_key
        )
        results['validation_selected_multimodal_model'] = {
            'name': selected_multimodal_key,
            'source_model_name': selected_result_key,
            'selection_split': 'validation',
            'test_used_for_selection': False,
            'checkpoint': results['vlm_models'][selected_result_key]['checkpoint'],
        }
        production_multimodal_key = (
            'flexible_cross_attention'
            if 'flexible_cross_attention' in results['vlm_models']
            else selected_result_key
        )
        results['final_multimodal_model'] = {
            'name': production_multimodal_key,
            'selection_reason': (
                'required single-checkpoint text-only/image-only/both interface'
                if production_multimodal_key == 'flexible_cross_attention'
                else 'best available validation-selected multimodal model'
            ),
            'validation_leader': selected_multimodal_key,
            'test_used_for_selection': False,
            'checkpoint': results['vlm_models'][production_multimodal_key]['checkpoint'],
        }

        n_common = common_test['pretrained_late_fusion']['n']
        print("\n  COMMON HELD-OUT PROXY-PAIR COMPARISON")
        print(
            f"    N={n_common}; one changed prediction moves accuracy/micro-F1 by "
            f"{1.0 / n_common:.4f}."
        )
        print(
            "    Metric identity: for this single-label multiclass task, "
            "accuracy and micro-F1 are mathematically identical; macro-F1 is "
            "the primary class-balanced score."
        )
        print(
            "    Intervals below are 95% sample-level Wilson intervals; they "
            "apply to accuracy/micro-F1, not macro-F1, retraining, or "
            "template-cluster uncertainty."
        )

        def _print_common_metric(label, key, source_note=''):
            row = common_test[key]
            print(
                f"    {label:<16}: {row['correct']}/{n_common}; "
                f"macro-F1={row['f1_macro']:.4f}, "
                f"accuracy/micro-F1={row['f1_micro']:.4f}, "
                f"95% accuracy CI={row['accuracy_ci95_low']:.3f}-"
                f"{row['accuracy_ci95_high']:.3f}{source_note}"
            )

        _print_common_metric('Text parent', 'text_parent')
        _print_common_metric('Vision parent', 'vision_parent')
        if 'validation_selected_early_fusion' in common_test:
            early_common = common_test['validation_selected_early_fusion']
            _print_common_metric(
                'Early VLM', 'validation_selected_early_fusion',
                f"; source={early_common['source_model_name']}",
            )
        _print_common_metric('Late fusion', 'pretrained_late_fusion')
        if 'flexible_cross_attention' in common_test:
            _print_common_metric(
                'Flexible VLM', 'flexible_cross_attention',
                '; report key retained for checkpoint compatibility',
            )

        print("    Paired hard-decision audit versus text parent:")
        for common_key in audited_common_keys:
            audit = common_test[common_key][
                'prediction_audit_vs_text_parent'
            ]
            probability_note = ""
            if audit['identical_hard_predictions']:
                probability_mae = audit.get(
                    'probability_mean_absolute_difference'
                )
                probability_max = audit.get(
                    'probability_max_absolute_difference'
                )
                if probability_mae is None:
                    probability_note = "; same hard decisions"
                elif probability_mae <= 1e-12:
                    probability_note = "; hard decisions and probabilities identical"
                else:
                    probability_note = (
                        "; same hard decisions, probability MAE="
                        f"{probability_mae:.6f}, max delta={probability_max:.6f}"
                    )
            print(
                f"      {common_key}: changed={audit['changed_prediction_count']}/"
                f"{audit['n']}, fusion/model-only wins="
                f"{audit['candidate_only_correct']}, text-only wins="
                f"{audit['reference_only_correct']}, net correct gain="
                f"{audit['net_correct_gain']}, McNemar p="
                f"{audit['mcnemar_exact_p']:.4f}"
                + probability_note
            )
        equivalence_groups = common_test.get(
            'hard_prediction_equivalence_groups', []
        )
        if equivalence_groups:
            print(
                "    Prediction-equivalent groups (one empirical decision "
                "result per group): "
                + "; ".join(
                    " = ".join(group['members'])
                    for group in equivalence_groups
                )
            )
        common_leader_candidates = {
            key: common_test[key]['f1_macro']
            for key in (
                'text_parent', 'vision_parent', 'concat_baseline',
                'validation_selected_early_fusion',
                'pretrained_late_fusion', 'flexible_cross_attention',
            )
            if key in common_test
        }
        common_best_macro = max(common_leader_candidates.values())
        common_observed_leaders = [
            key for key, score in common_leader_candidates.items()
            if abs(score - common_best_macro) <= 1e-12
        ]
        common_test['observed_all_common_test_leaders'] = (
            common_observed_leaders
        )
        leader_signatures = {}
        for key in common_observed_leaders:
            signature = tuple(common_test[key]['predictions'])
            leader_signatures.setdefault(signature, []).append(key)
        common_test['observed_leader_equivalence_groups'] = list(
            leader_signatures.values()
        )
        print(
            "    Observed macro-F1 leader decision group(s), reporting only: "
            + "; ".join(
                " = ".join(group)
                for group in common_test['observed_leader_equivalence_groups']
            )
        )
        if 'four_way_modality_comparison' in common_test:
            print("\n  FOUR-WAY MODALITY COMPARISON (identical held-out support)")
            for comparison_row in common_test['four_way_modality_comparison'].values():
                print(
                    f"    {comparison_row['display_name']:<46} "
                    f"{comparison_row['correct']}/{comparison_row['n']} "
                    f"accuracy/micro-F1={comparison_row['accuracy']:.4f}, "
                    f"95% CI={comparison_row['accuracy_ci95_low']:.3f}-"
                    f"{comparison_row['accuracy_ci95_high']:.3f}, "
                    f"macro-F1={comparison_row['f1_macro']:.4f}"
                )
            observed_leaders = common_test['four_way_metadata'][
                'observed_common_test_leaders'
            ]
            print(
                "    Four-way observed macro-F1 leader(s), reporting only: "
                + ", ".join(observed_leaders)
            )
            proposed_row = common_test['four_way_modality_comparison'][
                'proposed_multimodal_vlm'
            ]
            print(
                "    Proposed VLM validation-selected fusion mode: "
                f"{proposed_row['validation_selected_fusion_mode']}"
            )
        print(
            "    Validation-selected active multimodal condition: "
            f"{selected_multimodal_key}"
        )
        parent_best = max(common_test['text_parent']['f1_macro'],
                          common_test['vision_parent']['f1_macro'])
        selected_observed_f1 = common_test['selected_multimodal']['f1_macro']
        if selected_observed_f1 > parent_best:
            print(
                "    Result: the validation-selected active multimodal condition has the "
                f"highest observed macro-F1 on this N={n_common} common proxy test."
            )
        elif selected_observed_f1 == parent_best:
            print(
                "    Result: the selected active multimodal condition ties the "
                "strongest parent in macro-F1."
            )
        else:
            print(
                "    Result: the selected active multimodal condition did not beat the strongest "
                "parent in macro-F1 on this held-out test."
            )
        model_claim = results.get('our_multimodal_model_claim')
        if model_claim:
            print(f"    Claim check: {model_claim['wording']}")
            target_state = 'MET' if model_claim['accuracy_target_met'] else 'NOT MET'
            print(
                "    Proposed-model accuracy target evidence: "
                f"{model_claim['common_test_accuracy']:.2%} / "
                f"{model_claim['accuracy_target']:.0%}; 95% lower bound="
                f"{model_claim['accuracy_target_evidence']['accuracy_ci95_low']:.2%} "
                f"({target_state})"
            )
            if (model_claim['accuracy_target_statistically_supported']
                    and not model_claim['accuracy_target_met']):
                target_blockers = []
                if not model_claim['taxonomy_claim_eligible']:
                    target_blockers.append('taxonomy is not independently verified')
                if not model_claim['paired_observation_claim_eligible']:
                    target_blockers.append('text/image observations are not linked')
                print(
                    "    Numerical target evidence is not accepted as verified "
                    "disease accuracy: " + '; '.join(target_blockers)
                )

        del late_model, late_text_parent, late_vision_parent
        if early_fusion_teacher is not None:
            del early_fusion_teacher
            early_fusion_teacher = None
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception as late_fusion_error:
        print(f"  [WARN] Pretrained late fusion could not be completed: {late_fusion_error}")
        if 'flexible_cross_attention' in results.get('vlm_models', {}):
            results['final_multimodal_model'] = {
                'name': 'flexible_cross_attention',
                'selection_reason': (
                    'required single-checkpoint text-only/image-only/both interface'
                ),
                'validation_leader': 'flexible_cross_attention',
                'test_used_for_selection': False,
                'checkpoint': results['vlm_models']['flexible_cross_attention']['checkpoint'],
            }
        late_model = None
        late_text_parent = None
        late_vision_parent = None
        if early_fusion_teacher is not None:
            del early_fusion_teacher
            early_fusion_teacher = None
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    print("\n" + "=" * 70)
    print("[7/8] FEDERATED VS CENTRALIZED COMPARISON")
    print("=" * 70)

    # Build a source-aware proxy-pair pool for the FL study. Unlinked exports use
    # one image row per source and keep each authored text-template family on one
    # client. Genuine linked rows retain every lesion crop, while the connected
    # source/text component remains indivisible during client partitioning. This
    # is a simulated label-skew experiment, not true farm/site ownership data.
    fed_pair_texts, fed_pair_images, fed_pair_labels = [], [], []
    fed_pair_image_groups = []
    fed_pair_text_groups = []
    fed_pair_counts = {}
    fed_pair_rng = random.Random(config.seed + 9106)
    if linked_pair_mode:
        fed_pair_texts = list(texts_train)
        fed_pair_images = list(real_image_train)
        fed_pair_labels = list(real_label_train_img)
        fed_pair_image_groups = [
            str(group) for group in image_split_groups_train
        ]
        # The connected component already unites repeated text and source-photo
        # rows, so it is the correct ownership unit for both modalities.
        fed_pair_text_groups = list(fed_pair_image_groups)
        fed_pair_counts = _image_split_counts(fed_pair_labels)
    else:
        for class_id in range(config.num_labels):
            class_texts = select_template_diverse_texts(
                list(txt_by_lbl[class_id]),
                len(txt_by_lbl[class_id]),
                seed=config.seed + 9116 + class_id,
            )
            class_image_rows = [
                (image, source_group)
                for image, label, source_group in zip(
                    source_unique_real_image_train,
                    source_unique_real_label_train_img,
                    source_unique_real_groups_train,
                )
                if _single_label_index(label) == class_id
            ]
            fed_pair_rng.shuffle(class_image_rows)
            pair_count = min(len(class_texts), len(class_image_rows))
            if pair_count < 1:
                raise ValueError(
                    "Four-way FL comparison needs at least one unique source pair "
                    f"for {STRESS_LABELS[class_id]}"
                )
            selected_texts = class_texts[:pair_count]
            fed_pair_texts.extend(selected_texts)
            fed_pair_text_groups.extend(
                _text_template_group_key(text) for text in selected_texts
            )
            fed_pair_images.extend(
                image for image, _ in class_image_rows[:pair_count]
            )
            fed_pair_image_groups.extend(
                source_group for _, source_group in class_image_rows[:pair_count]
            )
            fed_pair_labels.extend([[class_id]] * pair_count)
            fed_pair_counts[STRESS_LABELS[class_id]] = pair_count

    fed_pair_sequences = (
        fed_pair_texts, fed_pair_images, fed_pair_labels,
        fed_pair_image_groups, fed_pair_text_groups,
    )
    fed_pair_lengths = [len(sequence) for sequence in fed_pair_sequences]
    if not fed_pair_lengths[0] or len(set(fed_pair_lengths)) != 1:
        raise RuntimeError(
            "Federated modality rows are empty or misaligned before tuple "
            f"shuffling: lengths={fed_pair_lengths}"
        )
    fed_pair_rows = list(zip(*fed_pair_sequences))
    fed_pair_rng.shuffle(fed_pair_rows)
    (fed_pair_texts, fed_pair_images, fed_pair_labels,
     fed_pair_image_groups, fed_pair_text_groups) = map(
        list, zip(*fed_pair_rows)
    )
    fed_text_source_keys = [
        _normalise_text_for_split(text) for text in fed_pair_texts
    ]
    fed_image_source_keys = list(fed_pair_image_groups)
    if (not linked_pair_mode
            and len(set(fed_text_source_keys)) != len(fed_text_source_keys)):
        raise RuntimeError(
            "Federated training pool contains a repeated text source record"
        )
    if (not linked_pair_mode
            and len(set(fed_image_source_keys)) != len(fed_image_source_keys)):
        raise RuntimeError(
            "Federated training pool contains a repeated image source group"
        )

    # Use this one fixed aligned dataset for every condition. Text/image models
    # simply ignore the unused input. Runtime same-label resampling is disabled
    # so no data can be drawn from outside the owning client subset.
    fed_comparison_train_ds = MultiModalDataset(
        fed_pair_texts,
        fed_pair_labels,
        fed_pair_images,
        None,
        int(config.max_seq_length),
        resample_same_label=False,
        augment_images=True,
        minority_augment_max_strength=getattr(
            config, 'minority_augment_max_strength', 1.0
        ),
    )
    fed_compare_batch_size = max(
        1,
        min(int(config.batch_size), int(config.flexible_vlm_batch_size)),
    )
    fed_common_val_loader = DataLoader(
        mm_val_ds, batch_size=fed_compare_batch_size, shuffle=False
    )
    fed_common_test_loader = DataLoader(
        mm_test_ds, batch_size=fed_compare_batch_size, shuffle=False
    )
    fed_compare_labels = [
        _single_label_index(label) for label in fed_pair_labels
    ]
    print(
        "  Non-replicated FL training "
        + ("linked observation rows: " if linked_pair_mode else "proxy pairs: ")
        +
        f"{len(fed_comparison_train_ds)} {fed_pair_counts}; "
        f"matched batch size={fed_compare_batch_size}"
    )
    shared_client_indices = split_data_non_iid(
        fed_comparison_train_ds,
        config.num_clients,
        config.dirichlet_alpha,
        labels=fed_compare_labels,
        seed=config.seed + 9107,
        groups=fed_pair_text_groups,
    )
    client_source_group_sets = [
        {fed_image_source_keys[index] for index in client_indices}
        for client_indices in shared_client_indices
    ]
    client_text_group_sets = [
        {fed_pair_text_groups[index] for index in client_indices}
        for client_indices in shared_client_indices
    ]
    for left_client in range(len(client_source_group_sets)):
        for right_client in range(left_client + 1, len(client_source_group_sets)):
            overlap = (
                client_source_group_sets[left_client]
                & client_source_group_sets[right_client]
            )
            if overlap:
                raise RuntimeError(
                    "Federated client partition leaked source-photo groups: "
                    f"clients {left_client}/{right_client}, groups={sorted(overlap)}"
                )
            text_overlap = (
                client_text_group_sets[left_client]
                & client_text_group_sets[right_client]
            )
            if text_overlap:
                raise RuntimeError(
                    "Federated client partition leaked text/source groups: "
                    f"clients {left_client}/{right_client}, "
                    f"groups={sorted(text_overlap)}"
                )
    import hashlib as _fed_hashlib
    shared_partition_digest = _fed_hashlib.sha256(
        json.dumps(shared_client_indices, separators=(',', ':')).encode('utf-8')
    ).hexdigest()[:12]
    client_source_group_assignment_digest = _fed_hashlib.sha256(
        "\n".join(sorted(
            f"{client_id}\t{group}"
            for client_id, groups in enumerate(client_source_group_sets)
            for group in groups
        )).encode('utf-8')
    ).hexdigest()[:12]
    client_text_group_assignment_digest = _fed_hashlib.sha256(
        "\n".join(sorted(
            f"{client_id}\t{group}"
            for client_id, groups in enumerate(client_text_group_sets)
            for group in groups
        )).encode('utf-8')
    ).hexdigest()[:12]

    flexible_fed_kwargs = {
        'num_labels': config.num_labels,
        'max_seq_length': int(config.max_seq_length),
        'modality_dropout': float(config.flexible_vlm_modality_dropout),
        'text_aux_weight': float(config.flexible_vlm_text_aux_weight),
        'image_aux_weight': float(config.flexible_vlm_image_aux_weight),
        'alignment_weight': float(config.flexible_vlm_alignment_weight),
    }
    _modal_cfg = {
        'ViT': (LightweightVisionClassifier,
                {'num_labels': config.num_labels}, 'vision'),
        'LLM': (LightweightTextClassifier,
                {'num_labels': config.num_labels}, 'text'),
        'VLM': (MultiModalClassifier,
                {'num_labels': config.num_labels, 'fusion_type': 'concat'},
                'multimodal'),
        'FlexibleVLM': (FlexibleCrossAttentionVLM, flexible_fed_kwargs,
                        'multimodal'),
    }
    _condition_keys = {
        'ViT': 'unimodal_image',
        'LLM': 'unimodal_text',
        'VLM': 'standard_vlm_fusion',
        'FlexibleVLM': 'flexible_multimodal_vlm_matched_scratch',
    }
    fed_evaluation_scope = (
        'same held-out filename-and-box-linked observations, grouped by '
        'connected source/text component, for all centralized and federated '
        'conditions'
        if linked_pair_mode else
        'same held-out label-aligned proxy pairs for all centralized and '
        'federated conditions'
    )
    fed_training_pairing_semantics = (
        'filename-and-box-linked lesion rows; repeated genuine lesion rows are '
        'retained and each connected source/text component stays on one client'
        if linked_pair_mode else
        'label-aligned proxy pairs; one independent image-source row per pair '
        'and each authored text-template family stays on one client'
    )
    four_way_fed = {
        'evaluation_scope': fed_evaluation_scope,
        'federation_scope': (
            'simulated class-label-skew clients; source data has no farm/site '
            'ownership field'
        ),
        'training_pairing_semantics': fed_training_pairing_semantics,
        'training_pair_count': int(len(fed_comparison_train_ds)),
        'training_pairs_per_class': dict(fed_pair_counts),
        'normalized_text_record_unique_asserted': bool(not linked_pair_mode),
        'source_image_group_disjoint_asserted': True,
        'text_or_component_group_disjoint_asserted': True,
        'group_partition_mode': (
            'connected_source_text_component'
            if linked_pair_mode else 'text_template_family'
        ),
        'group_assignment_class_rule': (
            'dominant row label; lowest class id on an exact tie'
        ),
        'independent_training_image_group_count': int(
            len(set(fed_pair_image_groups))
        ),
        'independent_training_text_or_component_group_count': int(
            len(set(fed_pair_text_groups))
        ),
        'client_row_counts': [
            int(len(indices)) for indices in shared_client_indices
        ],
        'client_source_group_counts': [
            int(len(groups)) for groups in client_source_group_sets
        ],
        'client_text_or_component_group_counts': [
            int(len(groups)) for groups in client_text_group_sets
        ],
        'client_source_group_assignment_digest': (
            client_source_group_assignment_digest
        ),
        'client_text_or_component_group_assignment_digest': (
            client_text_group_assignment_digest
        ),
        'selection_split': 'common multimodal validation support',
        'test_used_for_selection': False,
        'architectures_pre_specified': True,
        'identical_training_support': True,
        'shared_client_partition': True,
        'validation_selected_checkpoints': True,
        'training_protocol': (
            'shared initialization per condition, fixed aligned training rows, '
            'same AdamW LR/batch and architecture-defined objective within each '
            'centralized/FedAvg pair, same total data passes, validation macro-F1 '
            'then micro-F1 then NLL checkpoint selection'
        ),
        'fed_rounds': int(config.fed_rounds),
        'local_epochs': int(config.local_epochs),
        'total_passes': int(config.fed_rounds * config.local_epochs),
        'batch_size': fed_compare_batch_size,
        'num_clients': int(config.num_clients),
        'dirichlet_alpha': float(config.dirichlet_alpha),
        'client_partition_digest': shared_partition_digest,
        'conditions': {},
    }
    common_test_label_arrays = {}

    def _fed_metric_summary(metrics):
        labels_array = np.asarray(metrics['labels'])
        predictions_array = np.asarray(metrics['predictions'])
        probabilities_array = np.asarray(metrics['probabilities'], dtype=float)
        summary = {
            'n': int(len(labels_array)),
            'correct': int((predictions_array == labels_array).sum()),
            'accuracy': float(metrics['accuracy']),
            'f1_micro': float(metrics['f1_micro']),
            'f1_macro': float(metrics['f1_macro']),
            'f1_weighted': float(metrics['f1_weighted']),
            'precision': float(metrics['precision']),
            'recall': float(metrics['recall']),
            'per_class_f1': [float(value) for value in metrics['per_class_f1']],
            'labels': labels_array.astype(int).tolist(),
            'predictions': predictions_array.astype(int).tolist(),
            'probabilities': probabilities_array.astype(float).tolist(),
        }
        if metrics.get('fusion_gate') is not None:
            gate = np.asarray(metrics['fusion_gate'], dtype=float).reshape(-1)
            if len(gate) == len(labels_array):
                summary['effective_text_weight'] = gate.tolist()
        return summary

    for condition_index, (model_type, (cls, kw, mtype)) in enumerate(
        _modal_cfg.items()
    ):
        display_name = FEDERATED_CONDITION_DISPLAY[model_type]
        print(f"\n>>> Comparing {display_name}...")

        # Predeclare one architecture-specific initialization before either arm
        # trains. Validation/test values never influence these weights.
        initialization_seed = config.seed + 12000 + condition_index
        random.seed(initialization_seed)
        np.random.seed(initialization_seed)
        torch.manual_seed(initialization_seed)
        initialization_model = cls(**kw)
        initial_state = {
            key: value.detach().cpu().clone()
            for key, value in initialization_model.state_dict().items()
        }
        model_params = sum(
            parameter.numel() for parameter in initialization_model.parameters()
        )
        del initialization_model

        print(f"  Training matched centralized control: {display_name}...")
        # Reset both arms to the same training RNG seed. Their sampling paths
        # necessarily diverge (global shuffle versus per-client shuffles), but
        # neither arm receives an arbitrary seed advantage.
        centralized_training_seed = config.seed + 13000 + condition_index
        random.seed(centralized_training_seed)
        np.random.seed(centralized_training_seed)
        torch.manual_seed(centralized_training_seed)
        cent_val_f1, cent_history, cent_state = centralized_train_fedavg_matched(
            cls,
            kw,
            fed_comparison_train_ds,
            fed_common_val_loader,
            config,
            device,
            mtype,
            initial_state=initial_state,
            batch_size=fed_compare_batch_size,
        )
        cent_model = cls(**kw).to(device)
        cent_model.load_state_dict(cent_state, strict=True)
        cent_test_metrics = evaluate(
            cent_model, fed_common_test_loader, device, mtype
        )
        del cent_model

        print(f"  Training FedAvg: {display_name}...")
        federated_training_seed = centralized_training_seed
        random.seed(federated_training_seed)
        np.random.seed(federated_training_seed)
        torch.manual_seed(federated_training_seed)
        fed_val_f1, fed_history, fed_state = federated_train(
            cls,
            kw,
            fed_comparison_train_ds,
            fed_common_val_loader,
            config,
            device,
            mtype,
            initial_state=initial_state,
            client_indices=shared_client_indices,
            batch_size=fed_compare_batch_size,
        )
        fed_model = cls(**kw).to(device)
        fed_model.load_state_dict(fed_state, strict=True)
        fed_test_metrics = evaluate(
            fed_model, fed_common_test_loader, device, mtype
        )
        del fed_model

        cent_labels = np.asarray(cent_test_metrics['labels'])
        fed_labels = np.asarray(fed_test_metrics['labels'])
        if not np.array_equal(cent_labels, fed_labels):
            raise RuntimeError(
                f"Centralized/FedAvg test label mismatch for {model_type}"
            )
        common_test_label_arrays[f'{model_type}_centralized'] = cent_labels
        common_test_label_arrays[f'{model_type}_federated'] = fed_labels

        cent_summary = _fed_metric_summary(cent_test_metrics)
        fed_summary = _fed_metric_summary(fed_test_metrics)
        cent_selected_validation = cent_history['selected_validation']
        fed_selected_validation = fed_history['selected_validation']
        condition_key = _condition_keys[model_type]
        condition_record = {
            'display_name': display_name,
            'model_key': model_type,
            'model_class': cls.__name__,
            'model_kwargs': dict(kw),
            'training_variant': (
                'matched scratch-training architecture study; distinct from the '
                'parent-warm-started/distilled deployment checkpoint'
                if model_type == 'FlexibleVLM'
                else 'matched scratch-training architecture study'
            ),
            'initialization_seed': int(initialization_seed),
            'centralized_training_seed': int(centralized_training_seed),
            'federated_training_seed': int(federated_training_seed),
            'uses_text': model_type != 'ViT',
            'uses_image': model_type != 'LLM',
            'is_multimodal': model_type in {'VLM', 'FlexibleVLM'},
            'centralized': {
                **cent_summary,
                'validation_f1': float(cent_val_f1),
                'validation_f1_macro': float(
                    cent_selected_validation['f1_macro']
                ),
            },
            'federated': {
                **fed_summary,
                'validation_f1': float(fed_val_f1),
                'validation_f1_macro': float(
                    fed_selected_validation['f1_macro']
                ),
            },
            'federated_minus_centralized_f1': (
                fed_summary['f1_micro'] - cent_summary['f1_micro']
            ),
        }
        four_way_fed['conditions'][condition_key] = condition_record

        cent_ckpt = (
            config.checkpoint_dir
            / f"centralized_{condition_key}_fedmatched_best.pt"
        )
        fed_ckpt = (
            config.checkpoint_dir
            / f"federated_{condition_key}_fedavg_best.pt"
        )
        condition_record['centralized']['checkpoint'] = str(cent_ckpt)
        condition_record['centralized']['history_result_key'] = (
            f"centralized.{model_type}.history"
        )
        condition_record['federated']['checkpoint'] = str(fed_ckpt)
        condition_record['federated']['history_result_key'] = (
            f"federated.{model_type}.history"
        )
        checkpoint_common = {
            'config': checkpoint_safe_metadata(config.__dict__),
            'condition_key': condition_key,
            'display_name': display_name,
            'model_type': model_type,
            'model_class': cls.__name__,
            'model_kwargs': dict(kw),
            'num_params': model_params,
            'initialization_seed': int(initialization_seed),
            'centralized_training_seed': int(centralized_training_seed),
            'federated_training_seed': int(federated_training_seed),
            'data_fingerprint': data_fingerprint,
            'client_partition_digest': shared_partition_digest,
            'client_source_group_assignment_digest': (
                client_source_group_assignment_digest
            ),
            'client_text_or_component_group_assignment_digest': (
                client_text_group_assignment_digest
            ),
            'evaluation_protocol': (
                'four_way_fed_vs_centralized_common_test_v2_macro_selection'
            ),
            'validation_selection_metric': (
                'macro-F1, then micro-F1, then negative log-likelihood'
            ),
            'test_used_for_selection': False,
        }
        torch.save({
            **checkpoint_common,
            'model_state_dict': cent_state,
            'training_mode': 'centralized_fedavg_matched',
            'validation_f1': float(cent_val_f1),
            'validation_f1_macro': float(
                cent_selected_validation['f1_macro']
            ),
            'common_test_metrics': cent_summary,
            'history': checkpoint_safe_metadata(cent_history),
        }, cent_ckpt)
        torch.save({
            **checkpoint_common,
            'model_state_dict': fed_state,
            'training_mode': 'federated_fedavg',
            'validation_f1': float(fed_val_f1),
            'validation_f1_macro': float(
                fed_selected_validation['f1_macro']
            ),
            'common_test_metrics': fed_summary,
            'history': checkpoint_safe_metadata(fed_history),
        }, fed_ckpt)

        results['centralized'][model_type] = {
            'f1': cent_summary['f1_micro'],
            'f1_macro': cent_summary['f1_macro'],
            'f1_weighted': cent_summary['f1_weighted'],
            'accuracy': cent_summary['accuracy'],
            'validation_f1': float(cent_val_f1),
            'validation_f1_macro': float(
                cent_selected_validation['f1_macro']
            ),
            'checkpoint': str(cent_ckpt),
            'history': cent_history,
            'per_class_f1': cent_summary['per_class_f1'],
            'params': model_params,
            'n': cent_summary['n'],
            'correct': cent_summary['correct'],
            'display_name': display_name,
            'evaluation_scope': fed_evaluation_scope,
        }
        results['federated'][model_type] = {
            'f1': fed_summary['f1_micro'],
            'f1_macro': fed_summary['f1_macro'],
            'f1_weighted': fed_summary['f1_weighted'],
            'accuracy': fed_summary['accuracy'],
            'validation_f1': float(fed_val_f1),
            'validation_f1_macro': float(
                fed_selected_validation['f1_macro']
            ),
            'checkpoint': str(fed_ckpt),
            'history': fed_history,
            'per_class_f1': fed_summary['per_class_f1'],
            'params': model_params,
            'n': fed_summary['n'],
            'correct': fed_summary['correct'],
            'display_name': display_name,
            'evaluation_scope': fed_evaluation_scope,
        }
        results.setdefault('federated_history', {})[model_type] = fed_history
        results.setdefault('fed_client_stats', {})[model_type] = {
            'num_clients': config.num_clients,
            'alpha': config.dirichlet_alpha,
            'partition_digest': shared_partition_digest,
            'client_sizes': [len(indices) for indices in shared_client_indices],
            'client_label_counts': [
                [
                    sum(
                        1 for index in indices
                        if fed_compare_labels[index] == class_id
                    )
                    for class_id in range(config.num_labels)
                ]
                for indices in shared_client_indices
            ],
        }
        print(
            f"  {display_name}: centralized test F1="
            f"{cent_summary['f1_micro']:.4f}, FedAvg test F1="
            f"{fed_summary['f1_micro']:.4f} (N={cent_summary['n']})"
        )

        del cent_state, fed_state, initial_state
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

        # Expensive federated sweeps remain opt-in and preserve the existing
        # three model-family defaults. FlexibleVLM is not swept unless added to
        # config.fed_sweep_model_types explicitly.
        if (getattr(config, 'run_fed_sweep', False)
                and model_type in getattr(config, 'fed_sweep_model_types', [])):
            print(f"  Federated sweep for {display_name}...")
            try:
                results.setdefault('fed_sweep', {})[model_type] = (
                    run_federated_sweep(
                        cls,
                        kw,
                        fed_comparison_train_ds,
                        fed_common_val_loader,
                        config,
                        device,
                        mtype,
                        labels=fed_compare_labels,
                        batch_size=fed_compare_batch_size,
                        groups=fed_pair_text_groups,
                    )
                )
            except Exception as sweep_error:
                print(f"  [WARN] Federated sweep failed for {model_type}: {sweep_error}")
            gc.collect()
            if torch.cuda.is_available():
                torch.cuda.empty_cache()

    common_label_reference = next(iter(common_test_label_arrays.values()))
    for label_name, label_values in common_test_label_arrays.items():
        if not np.array_equal(common_label_reference, label_values):
            raise RuntimeError(
                f"Four-way centralized/FedAvg label-order mismatch: {label_name}"
            )
    four_way_fed['identical_test_support_asserted'] = True
    four_way_fed['n'] = int(len(common_label_reference))
    four_way_fed['accuracy_resolution'] = (
        1.0 / len(common_label_reference)
        if len(common_label_reference) else None
    )
    results['four_way_federated_comparison'] = four_way_fed
    try:
        fed_comparison_csv = (
            config.output_dir / 'four_way_federated_vs_centralized.csv'
        )
        fed_rows = []
        for condition_key, condition_record in four_way_fed['conditions'].items():
            for training_mode in ('centralized', 'federated'):
                metric_row = condition_record[training_mode]
                fed_rows.append({
                    'condition': condition_key,
                    'display_name': condition_record['display_name'],
                    'training_mode': training_mode,
                    'n': metric_row['n'],
                    'correct': metric_row['correct'],
                    'accuracy': metric_row['accuracy'],
                    'f1_micro': metric_row['f1_micro'],
                    'f1_macro': metric_row['f1_macro'],
                    'f1_weighted': metric_row['f1_weighted'],
                    'precision': metric_row['precision'],
                    'recall': metric_row['recall'],
                    'validation_f1': metric_row['validation_f1'],
                    'checkpoint': metric_row['checkpoint'],
                })
        pd.DataFrame(fed_rows).to_csv(fed_comparison_csv, index=False)
        results['four_way_federated_comparison_csv'] = str(fed_comparison_csv)
    except Exception as fed_csv_error:
        print(f"  [WARN] Could not save federated comparison CSV: {fed_csv_error}")

    # ── [8/8] Results, plots, comparison ────────────────────────────────────
    print("\n" + "=" * 70)
    print("[8/8] GENERATING PLOTS & SAVING RESULTS")
    print("=" * 70)

    # Generate the production API from the one-checkpoint flexible VLM when it
    # is available. This also makes direct run_training_real_data() executions
    # serveable; run_colab() may regenerate the same file harmlessly.
    final_multimodal = results.get('final_multimodal_model', {})
    final_checkpoint = final_multimodal.get('checkpoint')
    if final_checkpoint:
        try:
            api_server_path = create_api_server(
                best_checkpoint_path=final_checkpoint,
                config=config,
                port=8000,
                start=False,
            )
            results['api_server'] = {
                'path': str(api_server_path),
                'checkpoint': str(final_checkpoint),
                'model': final_multimodal.get('name'),
                'supports_modalities': ['text', 'image', 'text+image'],
            }
        except Exception as api_error:
            print(f"  [WARN] API generation failed: {api_error}")

    # Inter-model comparison
    inter_model_results = run_inter_model_comparison(results)
    results["inter_model"] = inter_model_results

    # Plots
    generate_all_plots(results, config)

    # Save JSON
    results_file = config.output_dir / "complete_results.json"
    with open(results_file, "w") as f:
        json.dump(results, f, indent=2, default=str)
    print(f"  Results saved: {results_file}")

    # Comparison tables
    print_comprehensive_model_comparison(results)

    # Centralized vs Federated summary
    print("\n" + "=" * 90)
    print("FOUR-WAY CENTRALIZED vs FEDERATED COMPARISON (COMMON HELD-OUT TEST)")
    print("=" * 90)
    print(
        f"{'Condition':<42} {'Central Macro':<14} {'Fed Macro':<11} "
        f"{'Macro diff':<11} {'Central Acc':<12} {'Fed Acc':<10} {'Observed higher'}"
    )
    print("-" * 125)
    for mt in MODEL_TYPE_ORDER:
        if mt not in results['centralized'] or mt not in results['federated']:
            continue
        c_row = results["centralized"][mt]
        f_row = results["federated"][mt]
        c = float(c_row.get('f1_macro', c_row['f1']))
        f = float(f_row.get('f1_macro', f_row['f1']))
        c_accuracy = float(c_row.get('accuracy', c_row['f1']))
        f_accuracy = float(f_row.get('accuracy', f_row['f1']))
        d = f - c
        w = "Federated" if d > 0 else ("Centralized" if d < 0 else "Tie")
        display_name = FEDERATED_CONDITION_DISPLAY.get(mt, mt)
        print(
            f"{display_name:<42} {c:<14.4f} {f:<11.4f} "
            f"{d:<+11.4f} {c_accuracy:<12.4f} {f_accuracy:<10.4f} {w}"
        )

    print_research_paper_comparison(results)
    compare_architectures_with_literature(results, config)

    # Final summary
    print("\n" + "=" * 90)
    print("TRAINING COMPLETE — REAL DATA PIPELINE")
    print("=" * 90)
    print(f"  Text data:   per-class text.csv files ({text_data_dir})")
    print(f"  Image data:  per-class images/ folders ({data_dir})")
    print(f"  Results:     {results_file}")
    print(f"  Plots:       {config.plots_dir}/")
    print(f"  Checkpoints: {config.checkpoint_dir}/")
    print("\n  Models trained:")
    for mn, md in results["llm_models"].items():
        print(f"    LLM {mn}: macro-F1={md.get('f1_macro', md['f1']):.4f}, "
              f"accuracy/micro-F1={md['f1']:.4f}")
    for mn, md in results["vit_models"].items():
        print(f"    Vision {mn}: macro-F1={md.get('f1_macro', md['f1']):.4f}, "
              f"accuracy/micro-F1={md['f1']:.4f}")
    for ft, md in results["vlm_models"].items():
        display_name = md.get('display_name', ft)
        print(f"    VLM {display_name}: "
              f"macro-F1={md.get('f1_macro', md['f1']):.4f}, "
              f"accuracy/micro-F1={md['f1']:.4f}")

    # ── Disease Bounding Box Visualiser ─────────────────────────────────────
    # Annotates a sample of Real Dataset images with OBB disease boxes and
    # saves the grid overview so the user can inspect detections immediately.
    try:
        run_disease_box_visualizer(config=config, max_images=40)
    except Exception as _e_vis:
        print(f"  [VIS] Visualizer skipped: {_e_vis}")

    # ── RAG Diagnosis Evaluation Plots ───────────────────────────────────────
    # Generates rag_01..rag_07 (retrieval scores, score heatmap, type
    # distribution, confidence, KB distribution, score boxplot, VLM probs) —
    # backs paper Fig. 5 / Fig. 7a / Fig. 8a. Not produced by any other step.
    try:
        rag_results = run_rag_diagnosis(data_dir=text_data_dir)
        results["rag_diagnosis"] = rag_results
        generate_rag_diagnosis_plots(rag_results, config.plots_dir)
        with open(results_file, "w") as f:
            json.dump(results, f, indent=2, default=str)
        print(f"  RAG results updated: {results_file}")
    except Exception as _e_rag:
        print(f"  [RAG] Diagnosis evaluation skipped: {_e_rag}")

    # ── Save to GDrive (already routed there by setup_gdrive_output_dirs) ────
    # ── Then package everything into a ZIP and download it ───────────────────
    # (Runs last so the zip picks up the visualizer + RAG plots above too.)
    summarize_generated_plots(config)

    print("\n" + "=" * 70)
    print("SAVING & DOWNLOADING RESULTS")
    print("=" * 70)
    try:
        # Package from the exact configured directories. In Colab this also
        # triggers the browser download; locally it leaves the ZIP in cwd.
        results_zip = _download_results_with_config(config)
        results["download_package"] = str(results_zip)
    except Exception as _e_dl:
        print(f"⚠️  Download packaging failed: {_e_dl}")
        print(f"   Checkpoints : {config.checkpoint_dir}/")
        print(f"   Plots       : {config.plots_dir}/")
        print(f"   Results JSON: {config.output_dir}/")

    return results



# ============================================================================
# DISEASE BOUNDING BOX VISUALIZER  (YOLO OBB → annotated images)
# ============================================================================
#
#  Draws coloured oriented-bounding-box polygons + disease name labels on
#  every image in the Real Dataset and/or on images uploaded by the user.
#
#  Public API
#  ----------
#  visualize_dataset_boxes(out_dir, max_images, cols, thumb_size)
#      → annotates all Real Dataset images, saves grid overview
#
#  visualize_user_images(image_paths_or_uploads, out_dir)
#      → Colab users call files.upload() first, then pass the dict;
#        also accepts a list of file-path strings for non-Colab use
#
#  Both functions return a list of Path objects to the saved annotated images.
# ============================================================================

# Class colours (R,G,B), keyed by NAME so a colour stays attached to its class
# no matter how the indices renumber when a class is excluded.
_BOX_COLORS_BY_NAME = {
    'LEAF_BLIGHT':         (120, 200, 255),   # sky-blue
    'LEAF_HOPPERS':        (255, 160,  60),   # orange
    'LEAF_RUST':           ( 80, 225, 100),   # green
    'LOOPER_CATERPILLARS': (220,  90,  90),   # coral-red
    'MOSQUITO_BUG':        (210,  80, 220),   # magenta
}

# Index-keyed views built from the ACTIVE schema. Previously these were literal
# dicts keyed 0-4 in the old class order, so excluding a class silently drew
# every box with the wrong name and colour.
_BOX_COLORS = {
    index: _BOX_COLORS_BY_NAME.get(name, (200, 200, 200))
    for index, name in enumerate(STRESS_LABELS)
}
_DISPLAY_NAMES = {index: name for index, name in enumerate(STRESS_LABELS)}

_BOX_LINE_WIDTH  = 3     # polygon outline thickness  (px)
_LABEL_FONT_SIZE = 15    # target font size (fits LOOPER_CATERPILLARS etc.)
_LABEL_PAD       = 4     # text-pill padding           (px)
_FILL_ALPHA      = 55    # polygon fill opacity (0-255)


def _load_vis_font(size: int = 18):
    """Load a TrueType font from common system paths; fall back to PIL default."""
    from PIL import ImageFont
    candidates = [
        # Windows
        "C:/Windows/Fonts/arialbd.ttf",
        "C:/Windows/Fonts/arial.ttf",
        "C:/Windows/Fonts/calibrib.ttf",
        "C:/Windows/Fonts/segoeui.ttf",
        # Linux / Colab
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
        # macOS
        "/System/Library/Fonts/Helvetica.ttc",
        "/Library/Fonts/Arial Bold.ttf",
    ]
    import os as _os
    for p in candidates:
        if _os.path.exists(p):
            try:
                return ImageFont.truetype(p, size)
            except Exception:
                pass
    return ImageFont.load_default()


def _parse_obb_label_file(label_path) -> list:
    """
    Parse one YOLO-OBB label file.
    Line format: class_id  x1 y1  x2 y2  x3 y3  x4 y4   (normalised 0-1)
    Returns canonical class ids plus the original raw id:
    {class_id: int, raw_class_id: int, pts: [(x,y), ...] x4}
    """
    from pathlib import Path as _P
    boxes = []
    try:
        for raw in _P(label_path).read_text(encoding="utf-8", errors="replace").splitlines():
            parts = raw.strip().split()
            if len(parts) < 9:
                continue
            raw_cid = int(parts[0])
            canonical_name = RAW_YOLO_ID_TO_STRESS.get(raw_cid)
            if canonical_name is None:
                continue
            cid = LABEL_TO_IDX[canonical_name]
            coords = [float(v) for v in parts[1:9]]
            pts = [(coords[i], coords[i + 1]) for i in range(0, 8, 2)]
            boxes.append({"class_id": cid, "raw_class_id": raw_cid, "pts": pts})
    except Exception:
        pass
    return boxes


def _draw_boxes(img_pil, boxes: list, font) -> "PIL.Image.Image":
    """
    Draw oriented bounding boxes with disease-name labels on *img_pil*.
    Returns a new annotated RGB PIL image.
    """
    from PIL import Image as _Img, ImageDraw as _Draw
    img = img_pil.convert("RGB").copy()
    W, H = img.size

    # Overlay for semi-transparent polygon fills
    overlay = _Img.new("RGBA", (W, H), (0, 0, 0, 0))
    ov_draw = _Draw.Draw(overlay)

    # Main canvas for solid outlines + text
    canvas = img.convert("RGBA")
    draw   = _Draw.Draw(canvas)

    for box in boxes:
        cid   = box["class_id"]
        color = _BOX_COLORS.get(cid, (200, 200, 200))
        name  = _DISPLAY_NAMES.get(cid, f"Class {cid}")

        # Convert normalised coords → pixel coords (clamped)
        def _to_px(nx, ny):
            return (max(0, min(W - 1, int(nx * W))),
                    max(0, min(H - 1, int(ny * H))))

        pixel_pts = [_to_px(x, y) for x, y in box["pts"]]

        # Semi-transparent fill
        ov_draw.polygon(pixel_pts, fill=(*color, _FILL_ALPHA))

        # Solid outline
        draw.line(pixel_pts + [pixel_pts[0]], fill=(*color, 255),
                  width=_BOX_LINE_WIDTH)

        # Corner dots for clarity
        for px, py in pixel_pts:
            r = 4
            draw.ellipse([px - r, py - r, px + r, py + r],
                         fill=(*color, 255), outline=(255, 255, 255, 200))

        # Label pill — placed just above the top-most point
        xs = [p[0] for p in pixel_pts]
        ys = [p[1] for p in pixel_pts]
        tx, ty = max(0, min(xs)), max(0, min(ys))

        try:
            bb = font.getbbox(name)
            tw, th = bb[2] - bb[0], bb[3] - bb[1]
        except AttributeError:
            tw, th = font.getsize(name)

        rx0 = tx
        ry0 = max(0, ty - th - 2 * _LABEL_PAD)
        rx1 = min(W, tx + tw + 2 * _LABEL_PAD)
        ry1 = max(0, ty)

        draw.rectangle([rx0, ry0, rx1, ry1], fill=(*color, 220))
        draw.text((rx0 + _LABEL_PAD, ry0 + _LABEL_PAD // 2),
                  name, fill=(255, 255, 255, 255), font=font)

    # Merge transparent fill overlay
    canvas = _Img.alpha_composite(canvas, overlay)
    return canvas.convert("RGB")


def _make_legend_image(font) -> "PIL.Image.Image":
    """Create a colour-coded legend image for all 5 disease classes."""
    from PIL import Image as _Img, ImageDraw as _Draw
    lw, lh = 420, 50 + len(_DISPLAY_NAMES) * 40
    leg = _Img.new("RGB", (lw, lh), (18, 18, 18))
    d = _Draw.Draw(leg)
    # Title
    try:
        tf = font.font_variant(size=_LABEL_FONT_SIZE + 4)  # type: ignore
    except Exception:
        tf = font
    d.text((12, 8), "TEA DISEASE LEGEND", fill=(255, 255, 255), font=tf)
    for i, (cid, name) in enumerate(_DISPLAY_NAMES.items()):
        y = 46 + i * 40
        color = _BOX_COLORS[cid]
        d.rectangle([12, y, 38, y + 26], fill=color)
        d.rectangle([12, y, 38, y + 26], outline=(200, 200, 200))
        d.text((48, y + 4), name, fill=(230, 230, 230), font=font)
    return leg


def _build_grid(img_paths: list, cols: int = 5, thumb_size: int = 320) -> "PIL.Image.Image":
    """Stitch annotated thumbnails into a grid overview image."""
    from PIL import Image as _Img
    thumbs = []
    for p in img_paths:
        try:
            im = _Img.open(p).convert("RGB")
            im.thumbnail((thumb_size, thumb_size))
            thumbs.append(im)
        except Exception:
            pass
    if not thumbs:
        return _Img.new("RGB", (thumb_size, thumb_size), (30, 30, 30))
    rows = (len(thumbs) + cols - 1) // cols
    grid = _Img.new("RGB", (cols * thumb_size, rows * thumb_size), (30, 30, 30))
    for idx, im in enumerate(thumbs):
        r, c = divmod(idx, cols)
        xo = c * thumb_size + (thumb_size - im.width) // 2
        yo = r * thumb_size + (thumb_size - im.height) // 2
        grid.paste(im, (xo, yo))
    return grid



def visualize_dataset_boxes(
    out_dir=None,
    max_images: int = None,
    cols: int = 5,
    thumb_size: int = 320,
    dataset_dir=None,
) -> list:
    """Annotate every image in the Real Dataset with disease bounding boxes.

    Reads YOLO OBB label files, draws coloured polygon boxes and disease-name
    labels on each image, then saves them to *out_dir*.  Also produces:
      - ``_legend.png``      — colour-coded disease legend
      - ``_grid_overview.jpg`` — montage of all annotated images

    Args:
        out_dir:      Output directory (auto: <project>/annotated_images/).
        max_images:   Process only this many images (default: all 200).
        cols:         Columns in the grid overview (default: 5).
        thumb_size:   Thumbnail size for the grid (default: 320 px).
        dataset_dir:  Override the auto-detected Real Dataset directory.

    Returns:
        List of ``Path`` objects to the saved annotated image files.
    """
    from pathlib import Path as _P
    from PIL import Image as _Img

    # ── Resolve dataset directory ──────────────────────────────────────────────
    if dataset_dir is None:
        _candidates = [
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset"),
            _P("/content/drive/MyDrive/FarmFederate/Real Dataset"),
            _P("/content/FarmFederate/Real Dataset"),
            _P("Real Dataset"),
            _P("../Real Dataset"),
        ]
        dataset_dir = next((p for p in _candidates if p.exists()), None)
    if dataset_dir is None:
        print("[VIS] SKIP: raw YOLO OBB dataset directory was not supplied.")
        return []
    dataset_dir = _P(dataset_dir)
    img_dir = dataset_dir / "images"
    lbl_dir = dataset_dir / "labels"

    if not img_dir.exists() or not lbl_dir.exists():
        if _is_usable_sorted_dataset(dataset_dir):
            print(
                "[VIS] SKIP: the portable class-sorted benchmark has image "
                "labels but does not contain raw YOLO OBB coordinates; a "
                "bounding-box preview would be misleading."
            )
        else:
            print(
                f"[VIS] SKIP: images/ and labels/ OBB folders are missing in "
                f"{dataset_dir}"
            )
        return []

    # ── Resolve output directory ───────────────────────────────────────────────
    if out_dir is None:
        _root = _P("C:/Users/USER_HP/Desktop/FarmFederate")
        if not _root.exists():
            _root = _P("/content")
        out_dir = _root / "annotated_images"
    out_dir = _P(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    font = _load_vis_font(_LABEL_FONT_SIZE)
    label_files = sorted(lbl_dir.glob("*.txt"))
    if max_images:
        label_files = label_files[:max_images]

    print(f"\n{'='*70}")
    print("DISEASE BOUNDING BOX VISUALIZER")
    print(f"{'='*70}")
    print(f"  Dataset : {dataset_dir}")
    print(f"  Images  : {len(label_files)} to annotate")
    print(f"  Output  : {out_dir}")
    print()

    annotated_paths = []
    class_counts = {i: 0 for i in _DISPLAY_NAMES}
    skipped = 0

    for lf in label_files:
        img_path = img_dir / (lf.stem + ".jpg")
        if not img_path.exists():
            # Try .png / .jpeg
            for ext in (".png", ".jpeg", ".JPG", ".PNG"):
                alt = img_dir / (lf.stem + ext)
                if alt.exists():
                    img_path = alt
                    break
            else:
                skipped += 1
                continue

        boxes = _parse_obb_label_file(lf)
        if not boxes:
            skipped += 1
            continue

        for b in boxes:
            cid = b["class_id"]
            if cid in class_counts:
                class_counts[cid] += 1

        try:
            img = _Img.open(img_path).convert("RGB")
        except Exception as exc:
            print(f"  [WARN] Cannot open {img_path.name}: {exc}")
            skipped += 1
            continue

        annotated = _draw_boxes(img, boxes, font)
        out_path  = out_dir / img_path.name
        annotated.save(out_path, quality=92)
        annotated_paths.append(out_path)

    # ── Statistics ─────────────────────────────────────────────────────────────
    print(f"[VIS] Annotated {len(annotated_paths)} images  "
          f"(skipped {skipped})")
    print("\n  Disease Box Counts:")
    for cid, name in _DISPLAY_NAMES.items():
        bar = "#" * (class_counts[cid] // 3)
        print(f"    {name:<22}: {class_counts[cid]:4d}  {bar}")

    # ── Legend ─────────────────────────────────────────────────────────────────
    legend = _make_legend_image(font)
    legend_path = out_dir / "_legend.png"
    legend.save(legend_path)
    print(f"\n  Legend   -> {legend_path}")

    # ── Grid overview ─────────────────────────────────────────────────────────
    if annotated_paths:
        print(f"  Building grid overview ({cols} cols, {thumb_size}px) ...")
        grid = _build_grid(annotated_paths, cols=cols, thumb_size=thumb_size)
        grid_path = out_dir / "_grid_overview.jpg"
        grid.save(grid_path, quality=85)
        print(f"  Grid     -> {grid_path}")

        # Show inline in Colab / Jupyter
        try:
            from IPython.display import display as _disp, Image as _IpyImg
            _disp(_IpyImg(filename=str(grid_path), width=min(1200, cols * thumb_size)))
        except Exception:
            pass

    print(f"\n[VIS] Done. All annotated images saved to:\n  {out_dir}\n")
    return annotated_paths


def visualize_user_images(
    images_input=None,
    out_dir=None,
    show_inline: bool = True,
) -> list:
    """Annotate user-supplied images using OBB labels (if available) or
    prompt the user to upload images in Colab.

    This function supports two modes:

    **Mode A — Colab upload (recommended in Colab):**
        Upload images that already have matching label files in the Real Dataset.
        The function pairs each uploaded image with its label (if found) and
        draws the disease boxes.

        .. code-block:: python

            from google.colab import files
            uploaded = files.upload()          # pick one or more .jpg files
            visualize_user_images(uploaded)

    **Mode B — file paths:**
        Pass a list of absolute paths to images.  Each image is paired with a
        label file of the same stem in the Real Dataset labels/ directory.

        .. code-block:: python

            visualize_user_images([
                "C:/path/to/image1.jpg",
                "C:/path/to/image2.jpg",
            ])

    If no matching YOLO label file is found for an image, the image is saved
    as-is with a "No annotation found" watermark.

    Args:
        images_input:  ``dict`` from ``files.upload()`` **or** list of path
                       strings / Path objects.  Pass ``None`` to trigger Colab
                       upload automatically.
        out_dir:       Output directory (default: <project>/user_annotated/).
        show_inline:   Display annotated images inline in Colab/Jupyter.

    Returns:
        List of ``Path`` objects to the saved annotated image files.
    """
    from pathlib import Path as _P
    from PIL import Image as _Img, ImageDraw as _Draw

    # ── Auto-trigger Colab upload when nothing is provided ────────────────────
    if images_input is None:
        try:
            from google.colab import files as _cf
            print("[VIS] Please select image(s) to upload ...")
            images_input = _cf.upload()
        except ImportError:
            print("[VIS] Not running in Colab. Pass image paths as a list.")
            return []

    # ── Resolve output directory ───────────────────────────────────────────────
    if out_dir is None:
        _root = _P("C:/Users/USER_HP/Desktop/FarmFederate")
        if not _root.exists():
            _root = _P("/content")
        out_dir = _root / "user_annotated"
    out_dir = _P(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    # ── Resolve Real Dataset labels directory ──────────────────────────────────
    _lbl_candidates = [
        _P("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset/labels"),
        _P("/content/drive/MyDrive/FarmFederate/Real Dataset/labels"),
        _P("/content/FarmFederate/Real Dataset/labels"),
        _P("Real Dataset/labels"),
    ]
    lbl_dir = next((p for p in _lbl_candidates if p.exists()), None)

    font = _load_vis_font(_LABEL_FONT_SIZE)

    print(f"\n{'='*70}")
    print("USER IMAGE DISEASE BOX VISUALIZER")
    print(f"{'='*70}")
    print(f"  Output dir   : {out_dir}")
    print(f"  Labels source: {lbl_dir or 'NOT FOUND — images will have watermark'}")

    # ── Normalise input to list of (filename, bytes_or_path) ──────────────────
    work_items: list = []   # (display_name, PIL.Image)

    if isinstance(images_input, dict):
        # Colab files.upload() → {filename: bytes, ...}
        import io as _io
        for fname, raw in images_input.items():
            try:
                pil = _Img.open(_io.BytesIO(raw)).convert("RGB")
                work_items.append((fname, pil))
            except Exception as exc:
                print(f"  [WARN] Cannot decode {fname}: {exc}")
    else:
        # list of paths
        for p in images_input:
            try:
                pil = _Img.open(_P(p)).convert("RGB")
                work_items.append((_P(p).name, pil))
            except Exception as exc:
                print(f"  [WARN] Cannot open {p}: {exc}")

    if not work_items:
        print("[VIS] No valid images to process.")
        return []

    print(f"  Images to annotate: {len(work_items)}\n")

    annotated_paths = []

    for fname, pil_img in work_items:
        stem = _P(fname).stem
        boxes = []

        # ── Try to find a matching label file ─────────────────────────────────
        if lbl_dir:
            lbl_path = lbl_dir / (stem + ".txt")
            if lbl_path.exists():
                boxes = _parse_obb_label_file(lbl_path)

        if boxes:
            annotated = _draw_boxes(pil_img, boxes, font)
            n_boxes   = len(boxes)
            disease_names = list({
                _DISPLAY_NAMES.get(b["class_id"], f"Class {b['class_id']}")
                for b in boxes
            })
            status   = f"Annotated  |  {n_boxes} box(es): {', '.join(disease_names)}"
        else:
            # No label → watermark the image
            annotated = pil_img.copy()
            d = _Draw.Draw(annotated)
            msg = "No annotation found"
            try:
                bb = font.getbbox(msg)
                tw, th = bb[2] - bb[0], bb[3] - bb[1]
            except AttributeError:
                tw, th = font.getsize(msg)
            W, H = annotated.size
            d.rectangle([4, 4, tw + 14, th + 14], fill=(60, 60, 60, 180))
            d.text((8, 6), msg, fill=(255, 220, 80), font=font)
            status = "No matching label — saved as-is"

        out_name = stem + "_annotated.jpg"
        out_path = out_dir / out_name
        annotated.save(out_path, quality=92)
        annotated_paths.append(out_path)
        print(f"  {fname:<45} -> {status}")

        # Show inline (Colab / Jupyter)
        if show_inline:
            try:
                from IPython.display import display as _disp, Image as _IpyImg
                _disp(_IpyImg(filename=str(out_path), width=640))
            except Exception:
                pass

    # ── Save a side-by-side comparison grid ───────────────────────────────────
    if len(annotated_paths) > 1:
        grid = _build_grid(annotated_paths, cols=min(3, len(annotated_paths)),
                           thumb_size=400)
        grid_path = out_dir / "_user_grid.jpg"
        grid.save(grid_path, quality=85)
        print(f"\n  Grid overview -> {grid_path}")
        if show_inline:
            try:
                from IPython.display import display as _disp, Image as _IpyImg
                _disp(_IpyImg(filename=str(grid_path), width=min(1200, 400 * 3)))
            except Exception:
                pass

    print(f"\n[VIS] Done. Annotated images saved to:\n  {out_dir}\n")

    # ── Quick-start reminder printed to the Colab cell ────────────────────────
    print("  Quick-start in Colab:")
    print("    from google.colab import files")
    print("    uploaded = files.upload()     # select your tea-leaf images")
    print("    visualize_user_images(uploaded)")
    return annotated_paths


# ── Convenience wrapper called during training pipeline ──────────────────────
def run_disease_box_visualizer(config=None, max_images: int = 40):
    """Visualize disease bounding boxes on the Real Dataset as part of the
    training pipeline.  Called automatically after [8/8] plots are generated.

    Args:
        config:      FarmFederate Config object (uses output_dir for saving).
        max_images:  How many images to annotate in the pipeline run
                     (default 40 to keep it fast; pass None for all 200).
    """
    from pathlib import Path as _P
    out = (_P(config.output_dir) / "disease_annotated") if config else None
    print("\n" + "=" * 70)
    print("DISEASE BOX VISUALIZER — Real Dataset Preview")
    print("=" * 70)
    paths = visualize_dataset_boxes(out_dir=out, max_images=max_images,
                                    cols=5, thumb_size=300,
                                    dataset_dir=(
                                        _P(config.data_dir)
                                        if config is not None else None
                                    ))
    if paths:
        print(f"  {len(paths)} annotated images ready.")
        print("  To annotate YOUR images in Colab, run:")
        print("    from google.colab import files")
        print("    uploaded = files.upload()")
        print("    visualize_user_images(uploaded)")
    return paths


