def _classify_text_to_disease(text: str) -> tuple:
    """Match a text prompt to a disease class using keyword scoring.

    Returns (class_name: str, class_idx: int, confidence: float, matched_kws: list).
    Falls back to the class with the most keyword hits.
    """
    text_lower = text.lower()

    scores = {}
    matched = {}
    for cls_name, keywords in _TEXT_DISEASE_KEYWORDS.items():
        hits = [kw for kw in keywords if kw in text_lower]
        scores[cls_name] = len(hits)
        matched[cls_name] = hits

    # Pick the best class
    best_cls = max(scores, key=scores.get)
    total_hits = sum(scores.values())
    if total_hits == 0:
        # No keyword matched — return first class with low confidence
        return (best_cls, STRESS_LABELS.index(best_cls), 0.0, [])

    confidence = scores[best_cls] / max(total_hits, 1)
    cls_idx = STRESS_LABELS.index(best_cls)
    return (best_cls, cls_idx, confidence, matched[best_cls])


# The legacy tea_data folders use a different disease taxonomy. There is no
# valid positional one-to-one mapping to the FarmFederate stress schema, so
# they are deliberately excluded from stress-class example lookup.
_STRESS_TO_TEA_DATA_FOLDER = {}
_TEA_DATA_FOLDER_TO_STRESS = {v: k for k, v in _STRESS_TO_TEA_DATA_FOLDER.items()}


def _find_example_images_for_class(class_idx: int, max_examples: int = 3,
                                    dataset_dir=None) -> list:
    """Find images for the given class from all available dataset sources.

    Search order:
      1. Real Dataset  (images/ + labels/) — returns OBB boxes
      2. data/real_dataset_sorted/{CLASS}/  — class-sorted real images (no OBB)
      3. tea_data/{old_name}/images/        — synth + augmented training images

    Returns list of (image_path, label_path_or_None, boxes_or_empty, source_tag) tuples.
    source_tag is one of: 'real_obb', 'real_sorted', 'tea_data_synth'.
    """
    from pathlib import Path as _P
    import random as _rnd

    results = []

    # ── Source 1: Real Dataset with OBB labels ────────────────────────────────
    if dataset_dir is None:
        _candidates = [
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset"),
            _P("/content/drive/MyDrive/FarmFederate/Real Dataset"),
            _P("/content/FarmFederate/Real Dataset"),
            _P("Real Dataset"),
            _P("../Real Dataset"),
        ]
        obb_dir = next((p for p in _candidates if p.exists()), None)
    else:
        obb_dir = _P(dataset_dir) if _P(dataset_dir).exists() else None

    if obb_dir is not None:
        img_dir = obb_dir / "images"
        lbl_dir = obb_dir / "labels"
        if img_dir.exists() and lbl_dir.exists():
            for lf in sorted(lbl_dir.glob("*.txt")):
                boxes = _parse_obb_label_file(lf)
                matching = [b for b in boxes if b["class_id"] == class_idx]
                if not matching:
                    continue
                img_path = img_dir / (lf.stem + ".jpg")
                if not img_path.exists():
                    for ext in (".png", ".jpeg", ".JPG"):
                        alt = img_dir / (lf.stem + ext)
                        if alt.exists():
                            img_path = alt
                            break
                    else:
                        continue
                results.append((img_path, lf, boxes, "real_obb"))
                if len(results) >= max_examples:
                    return results

    remaining = max_examples - len(results)
    if remaining <= 0:
        return results

    # ── Source 2: data/real_dataset_sorted/{CLASS}/ ───────────────────────────
    cls_name = STRESS_LABELS[class_idx]
    _sorted_candidates = [
        _P("C:/Users/USER_HP/Desktop/FarmFederate/real_dataset_sorted") / cls_name,
        _P("/content/real_dataset_sorted") / cls_name,
        _P("/content/drive/MyDrive/FarmFederate/real_dataset_sorted") / cls_name,
        _P("C:/Users/USER_HP/Desktop/FarmFederate/data/real_dataset_sorted") / cls_name,
        _P("/content/drive/MyDrive/FarmFederate/data/real_dataset_sorted") / cls_name,
        _P("data/real_dataset_sorted") / cls_name,
    ]
    sorted_dir = next((p for p in _sorted_candidates if p.exists()), None)

    if sorted_dir is not None:
        imgs = sorted(sorted_dir.glob("*.jpg")) + sorted(sorted_dir.glob("*.png"))
        _rnd.shuffle(imgs)
        for ip in imgs[:remaining]:
            results.append((ip, None, [], "real_sorted"))
        remaining = max_examples - len(results)
        if remaining <= 0:
            return results

    # ── Source 3: farmfederate_results dataset/tea_data/{CLASS}/images/ ─────────
    # New layout from trained Colab output — uses STRESS_LABELS names directly
    _results_candidates = [
        _P("C:/Users/USER_HP/Desktop/FarmFederate/farmfederate_results (1)/dataset/tea_data") / cls_name / "images",
        _P("/content/drive/MyDrive/FarmFederate/farmfederate_results/dataset/tea_data") / cls_name / "images",
        _P("/content/farmfederate_results/dataset/tea_data") / cls_name / "images",
        _P("farmfederate_results/dataset/tea_data") / cls_name / "images",
    ]
    results_img_dir = next((p for p in _results_candidates if p.exists()), None)
    if results_img_dir is not None:
        imgs = sorted(results_img_dir.glob("*.jpg")) + sorted(results_img_dir.glob("*.png"))
        _rnd.shuffle(imgs)
        for ip in imgs[:remaining]:
            results.append((ip, None, [], "tea_data_trained"))
        remaining = max_examples - len(results)
        if remaining <= 0:
            return results

    # ── Source 4: tea_data/{old_folder_name}/images/ (legacy synth layout) ──────
    _tea_folder = _STRESS_TO_TEA_DATA_FOLDER.get(cls_name)
    if _tea_folder:
        _tea_candidates = [
            _P("C:/Users/USER_HP/Desktop/FarmFederate/tea_data") / _tea_folder / "images",
            _P("/content/tea_data") / _tea_folder / "images",
            _P("/content/drive/MyDrive/tea_data") / _tea_folder / "images",
            _P("/content/drive/MyDrive/FarmFederate/tea_data") / _tea_folder / "images",
            _P("tea_data") / _tea_folder / "images",
            _P("C:/Users/USER_HP/Desktop/FarmFederate/tea_data") / cls_name / "images",
            _P("/content/tea_data") / cls_name / "images",
        ]
        tea_img_dir = next((p for p in _tea_candidates if p.exists()), None)

        if tea_img_dir is not None:
            imgs = sorted(tea_img_dir.glob("*.jpg")) + sorted(tea_img_dir.glob("*.png"))
            _rnd.shuffle(imgs)
            for ip in imgs[:remaining]:
                results.append((ip, None, [], "tea_data_synth"))

    return results



def diagnose_from_text(
    text_prompt: str,
    max_examples: int = 3,
    out_dir=None,
    show_inline: bool = True,
    dataset_dir=None,
) -> dict:
    """Classify a text symptom description and show annotated example images.

    When a user provides only a text prompt (no image), this function:
      1. Classifies the text into one of the 5 tea disease/pest classes
      2. Finds real example images from the dataset that have that disease
      3. Draws bounding boxes on the examples highlighting the disease areas
      4. Displays the annotated examples inline (Colab / Jupyter)
      5. Returns a diagnosis dict with class, confidence, paths, etc.

    Usage in Colab
    --------------
    >>> diagnose_from_text("I see orange rust-coloured pustules on the leaf underside")
    >>> diagnose_from_text("Small holes and ragged edges on leaves, frass visible")
    >>> diagnose_from_text("Brown necrotic patches spreading from leaf margin")

    Args:
        text_prompt:   Natural-language symptom description.
        max_examples:  How many example images to show (default 3).
        out_dir:       Output directory for saved annotated examples.
        show_inline:   Display images inline in Colab/Jupyter (default True).
        dataset_dir:   Override Real Dataset path (auto-detected if None).

    Returns:
        dict with keys: class_name, class_idx, display_name, confidence,
                        matched_keywords, example_images, recommendation.
    """
    from pathlib import Path as _P
    from PIL import Image as _Img, ImageDraw as _Draw

    # ── Resolve output directory ──────────────────────────────────────────────
    if out_dir is None:
        _root = _P("C:/Users/USER_HP/Desktop/FarmFederate")
        if not _root.exists():
            _root = _P("/content")
        out_dir = _root / "text_diagnosis_examples"
    out_dir = _P(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    font = _load_vis_font(_LABEL_FONT_SIZE)
    font_large = _load_vis_font(24)

    # ── Step 1: Classify text ────────────────────────────────────────────────
    cls_name, cls_idx, confidence, matched_kws = _classify_text_to_disease(text_prompt)
    display_name = _DISPLAY_NAMES.get(cls_idx, cls_name)
    color = _BOX_COLORS.get(cls_idx, (200, 200, 200))

    print(f"\n{'='*70}")
    print("TEXT-TO-IMAGE DISEASE DIAGNOSIS")
    print(f"{'='*70}")
    print(f"  Prompt     : \"{text_prompt[:120]}{'...' if len(text_prompt)>120 else ''}\"")
    print(f"  Diagnosed  : {display_name}  (class {cls_idx}: {cls_name})")
    print(f"  Confidence : {confidence:.0%}")
    if matched_kws:
        print(f"  Keywords   : {', '.join(matched_kws[:8])}")
    print()

    # ── Step 2: Find example images ──────────────────────────────────────────
    examples = _find_example_images_for_class(
        cls_idx, max_examples=max_examples, dataset_dir=dataset_dir
    )

    if not examples:
        print(f"  [INFO] No example images found for class '{cls_name}' in the dataset.")
        print(f"         The Real Dataset may not be available at the expected path.")
        return {
            "class_name": cls_name,
            "class_idx": cls_idx,
            "display_name": display_name,
            "confidence": confidence,
            "matched_keywords": matched_kws,
            "example_images": [],
            "recommendation": f"Disease matched: {display_name}. "
                              f"No example images available in the current dataset.",
        }

    # Count by source
    n_obb   = sum(1 for e in examples if e[3] == "real_obb")
    n_sort  = sum(1 for e in examples if e[3] == "real_sorted")
    n_synth = sum(1 for e in examples if e[3] == "tea_data_synth")
    parts = []
    if n_obb:   parts.append(f"{n_obb} OBB-annotated (Real Dataset)")
    if n_sort:  parts.append(f"{n_sort} class-sorted (real)")
    if n_synth: parts.append(f"{n_synth} training (synthetic/augmented)")
    print(f"  Found {len(examples)} example(s): {', '.join(parts)}\n")

    # ── Step 3: Annotate and save examples ───────────────────────────────────
    _SOURCE_LABELS = {
        "real_obb":         "Real + OBB Boxes",
        "real_sorted":      "Real (class-sorted)",
        "tea_data_trained": "Training Data (FarmFederate results)",
        "tea_data_synth":   "Training Data (synth/augmented)",
    }

    annotated_paths = []

    for idx, (img_path, lbl_path, all_boxes, source_tag) in enumerate(examples):
        try:
            img = _Img.open(img_path).convert("RGB")
        except Exception as exc:
            print(f"  [WARN] Cannot open {img_path.name}: {exc}")
            continue

        if all_boxes:
            # OBB-annotated: draw all boxes
            annotated = _draw_boxes(img, all_boxes, font)
        else:
            # No OBB labels — show with a class-label overlay
            annotated = img.copy()
            W, H = annotated.size
            d = _Draw.Draw(annotated)

            # Semi-transparent colour bar at the bottom
            bar_h = 42
            bar_overlay = _Img.new("RGBA", (W, bar_h), (*color, 180))
            annotated_rgba = annotated.convert("RGBA")
            annotated_rgba.paste(bar_overlay, (0, H - bar_h), bar_overlay)
            annotated = annotated_rgba.convert("RGB")

            d = _Draw.Draw(annotated)
            label_text = f"{display_name}  [{_SOURCE_LABELS.get(source_tag, source_tag)}]"
            d.text((10, H - bar_h + 10), label_text,
                   fill=(255, 255, 255), font=font)

        # ── Add a header banner with diagnosis info ──────────────────────────
        W, H = annotated.size
        banner_h = 48
        banner = _Img.new("RGB", (W, banner_h), (25, 25, 25))
        bd = _Draw.Draw(banner)

        # Colour pill for disease class
        pill_w = 16
        bd.rectangle([8, 10, 8 + pill_w, banner_h - 10], fill=color)

        # Title text
        src_short = {"real_obb": "Real+OBB", "real_sorted": "Real",
                     "tea_data_synth": "Synth"}
        title = (f"  {display_name}  |  Ex {idx + 1}/{len(examples)}"
                 f"  |  {src_short.get(source_tag, '?')}"
                 f"  |  Conf: {confidence:.0%}")
        bd.text((8 + pill_w + 8, 12), title,
                fill=(240, 240, 240), font=font)

        # Compose: banner on top + annotated below
        composite = _Img.new("RGB", (W, H + banner_h), (25, 25, 25))
        composite.paste(banner, (0, 0))
        composite.paste(annotated, (0, banner_h))

        # ── Save ─────────────────────────────────────────────────────────────
        out_name = f"example_{cls_name.lower()}_{idx + 1}.jpg"
        out_path = out_dir / out_name
        composite.save(out_path, quality=92)
        annotated_paths.append(out_path)

        # Print details
        if all_boxes:
            n_matched = sum(1 for b in all_boxes if b["class_id"] == cls_idx)
            n_total   = len(all_boxes)
            diseases_in_img = list({
                _DISPLAY_NAMES.get(b["class_id"], f"Class {b['class_id']}")
                for b in all_boxes
            })
            print(f"  [{idx+1}] {img_path.name}  [{source_tag}]")
            print(f"      {n_matched} {display_name} box(es)  |  "
                  f"{n_total} total  |  Diseases: {', '.join(diseases_in_img)}")
        else:
            print(f"  [{idx+1}] {img_path.name}  [{source_tag}]")
            print(f"      Class: {display_name}  (no OBB labels)")
        print(f"      Saved: {out_path}")

        # Show inline in Colab / Jupyter
        if show_inline:
            try:
                from IPython.display import display as _disp, Image as _IpyImg
                _disp(_IpyImg(filename=str(out_path), width=min(720, W)))
            except Exception:
                pass

    # ── Step 4: Build a comparison strip if multiple examples ────────────────
    if len(annotated_paths) > 1:
        grid = _build_grid(annotated_paths,
                           cols=min(3, len(annotated_paths)),
                           thumb_size=400)
        grid_path = out_dir / f"examples_{cls_name.lower()}_grid.jpg"
        grid.save(grid_path, quality=85)
        print(f"\n  Grid overview: {grid_path}")
        if show_inline:
            try:
                from IPython.display import display as _disp, Image as _IpyImg
                _disp(_IpyImg(filename=str(grid_path),
                              width=min(1200, 400 * len(annotated_paths))))
            except Exception:
                pass

    # ── Step 5: Build recommendation text ────────────────────────────────────
    _REMEDIES = {
        'LEAF_BLIGHT':          "Prune affected branches. Apply copper-based fungicides (Copper Oxychloride). Maintain good drainage and reduce shade.",
        'LEAF_HOPPERS':         "Apply systemic insecticides (Thiamethoxam, Imidacloprid). Remove alternate hosts. Use light traps for monitoring.",
        'LEAF_RUST':            "Improve air circulation via pruning. Apply Bordeaux mixture or copper formulations. Ensure balanced NPK fertilization.",
        'LOOPER_CATERPILLARS':  "Hand-pick visible larvae. Apply Bacillus thuringiensis (Bt) spray. Use pheromone traps. Maintain bush hygiene.",
        'MOSQUITO_BUG':         "Apply contact insecticides (Quinalphos). Prune and destroy affected shoots. Monitor young flush regularly.",
    }

    remedy = _REMEDIES.get(cls_name, "Consult a plant pathologist for specific treatment.")

    print(f"\n  {'-'*60}")
    print(f"  RECOMMENDATION")
    print(f"  {'-'*60}")
    print(f"  Disease  : {display_name}")
    print(f"  Remedy   : {remedy}")
    print(f"  {'-'*60}\n")

    result = {
        "class_name": cls_name,
        "class_idx": cls_idx,
        "display_name": display_name,
        "confidence": confidence,
        "matched_keywords": matched_kws,
        "example_images": [str(p) for p in annotated_paths],
        "recommendation": f"{display_name}: {remedy}",
        "num_examples": len(annotated_paths),
    }

    print(f"[VIS] Done. {len(annotated_paths)} example(s) saved to: {out_dir}\n")
    print("  Usage examples:")
    print('    diagnose_from_text("orange rust pustules on leaf underside")')
    print('    diagnose_from_text("holes and ragged edges, caterpillar frass visible")')
    print('    diagnose_from_text("brown water-soaked lesions on leaf margin")')
    print('    diagnose_from_text("white stippling on leaf, tip burn and curling")')
    print('    diagnose_from_text("corky raised spots on young shoots, tip dieback")')

    return result


