def annotate_image_with_obb(pil_img, cls_name: str, confidence: float) -> "PIL.Image.Image":
    """Draw OBB polygon + disease label on a PIL image using OpenCV leaf masking.

    Uses HSV green-channel masking to auto-detect leaf regions, then fits
    oriented bounding boxes (minAreaRect) around each region.  Falls back to a
    full-image border when no leaf region is found.

    Args:
        pil_img:    PIL.Image in RGB mode.
        cls_name:   One of the 5 STRESS_LABELS strings.
        confidence: Predicted confidence (0-1) to show in the label.

    Returns:
        Annotated PIL.Image (RGB).
    """
    try:
        import cv2
        import numpy as np
        from PIL import Image as _Img
    except ImportError:
        print("[annotate_image_with_obb] cv2/numpy not available — returning original.")
        return pil_img

    img = cv2.cvtColor(np.array(pil_img.convert("RGB")), cv2.COLOR_RGB2BGR)
    H, W = img.shape[:2]

    color  = _DISEASE_BGR.get(cls_name, (100, 200, 100))
    font_s = max(0.45, min(W, H) / 600)
    thick  = max(1, int(min(W, H) / 300))

    # HSV leaf masking
    hsv  = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv, (25, 30, 40), (95, 255, 255))
    k    = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (15, 15))
    mask = cv2.morphologyEx(cv2.morphologyEx(mask, cv2.MORPH_CLOSE, k), cv2.MORPH_OPEN, k)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    boxes = [cv2.boxPoints(cv2.minAreaRect(c)).tolist()
             for c in contours if cv2.contourArea(c) > 0.01 * W * H]
    if not boxes:
        m = 15
        boxes = [[(m, m), (W - m, m), (W - m, H - m), (m, H - m)]]

    display = cls_name.replace("_", " ").title()
    label   = f"{display}  {confidence * 100:.0f}%"
    for pts in boxes:
        arr = np.array(pts, dtype=np.int32)
        cv2.polylines(img, [arr], True, color, thick)
        (tw, th), bl = cv2.getTextSize(label, cv2.FONT_HERSHEY_SIMPLEX, font_s, thick)
        x0, y0 = arr[0]
        rx, ry = max(0, int(x0) - 2), max(0, int(y0) - th - bl - 6)
        cv2.rectangle(img, (rx, ry), (rx + tw + 6, ry + th + bl + 6), color, -1)
        cv2.putText(img, label, (rx + 3, ry + th + 3),
                    cv2.FONT_HERSHEY_SIMPLEX, font_s, (255, 255, 255), thick, cv2.LINE_AA)

    return _Img.fromarray(cv2.cvtColor(img, cv2.COLOR_BGR2RGB))


# Checkpoints preference order for image diagnosis
_VIT_CKPT_PREFERENCE = [
    "federated_vit_best.pt",
    "vit_vit_base_best.pt",
    "centralized_vit_best.pt",
    "vit_efficientnet_best.pt",
    "vit_deit_tiny_best.pt",
    "vit_swin_tiny_best.pt",
]


def _find_vit_checkpoint(ckpt_dir=None) -> "Path | None":
    """Locate the best available ViT checkpoint across common paths."""
    from pathlib import Path as _P
    _dirs = []
    if ckpt_dir:
        _dirs.append(_P(ckpt_dir))
    _dirs += [
        _P("C:/Users/USER_HP/Desktop/FarmFederate/farmfederate_results (1)/drive/checkpoints"),
        _P("/content/drive/MyDrive/FarmFederate/checkpoints"),
        _P("/content/checkpoints"),
        _P("checkpoints"),
    ]
    for d in _dirs:
        if not d.exists():
            continue
        for name in _VIT_CKPT_PREFERENCE:
            p = d / name
            if p.exists():
                return p
    return None


def diagnose_from_image(
    image,
    ckpt_dir=None,
    show_inline: bool = True,
    out_dir=None,
) -> dict:
    """Classify a leaf image using the trained FarmFederate ViT model.

    Loads the best available ``LightweightVisionClassifier`` checkpoint
    (prefers ``federated_vit_best.pt``), runs inference, annotates the image
    with an OBB polygon, and optionally displays it inline in Colab/Jupyter.

    Args:
        image:       PIL.Image, file path (str/Path), or bytes (JPEG/PNG).
        ckpt_dir:    Override checkpoint directory (auto-detected if None).
        show_inline: Display annotated image in Colab/Jupyter (default True).
        out_dir:     Directory to save the annotated image (None = temp dir).

    Returns:
        dict with keys: class_name, display_name, confidence, all_scores,
                        remedies, annotated_image (PIL), annotated_path (str).

    Usage in Colab
    --------------
    >>> from PIL import Image
    >>> result = diagnose_from_image(Image.open("my_leaf.jpg"))
    >>> print(result['display_name'], f"{result['confidence']:.0%}")

    >>> # from URL
    >>> import requests, io
    >>> r = requests.get("https://example.com/leaf.jpg")
    >>> result = diagnose_from_image(io.BytesIO(r.content))
    """
    import io as _io
    from pathlib import Path as _P
    from PIL import Image as _Img

    # ── Normalise input to PIL image ─────────────────────────────────────────
    if isinstance(image, (_P, str)):
        pil = _Img.open(str(image)).convert("RGB")
    elif isinstance(image, bytes):
        pil = _Img.open(_io.BytesIO(image)).convert("RGB")
    elif hasattr(image, 'read'):
        pil = _Img.open(image).convert("RGB")
    elif hasattr(image, 'convert'):
        pil = image.convert("RGB")
    else:
        raise TypeError(f"Unsupported image type: {type(image)}")

    # ── Locate checkpoint ─────────────────────────────────────────────────────
    ckpt_path = _find_vit_checkpoint(ckpt_dir)
    if ckpt_path is None:
        print("[diagnose_from_image] No ViT checkpoint found — run Colab training first.")
        return {}

    # ── Load model ────────────────────────────────────────────────────────────
    try:
        import torch
        import torch.nn.functional as F
        import torchvision.transforms as T
    except ImportError:
        print("[diagnose_from_image] torch/torchvision not available.")
        return {}

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    ckpt   = torch.load(str(ckpt_path), map_location="cpu", weights_only=False)
    state  = ckpt.get("model_state_dict", ckpt)

    model = LightweightVisionClassifier(num_labels=5)
    model.load_state_dict(state, strict=False)
    model.eval().to(device)

    tfm = T.Compose([
        T.Resize((224, 224)),
        T.ToTensor(),
        T.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),
    ])

    # ── Inference ─────────────────────────────────────────────────────────────
    x = tfm(pil).unsqueeze(0).to(device)
    with torch.no_grad():
        out    = model(x)
        logits = out["logits"] if isinstance(out, dict) else out
        probs  = F.softmax(logits, dim=-1)[0].cpu()

    cls_idx    = int(probs.argmax())
    cls_name   = STRESS_LABELS[cls_idx]
    confidence = float(probs[cls_idx])
    all_scores = {STRESS_LABELS[i]: round(float(probs[i]), 4)
                  for i in range(len(STRESS_LABELS))}

    # ── Annotate ──────────────────────────────────────────────────────────────
    annotated = annotate_image_with_obb(pil, cls_name, confidence)

    # ── Save ──────────────────────────────────────────────────────────────────
    if out_dir is None:
        _root = _P("/content") if _P("/content").exists() else _P(".")
        out_dir = _root / "image_diagnosis"
    out_dir = _P(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    import time as _time
    out_name = f"diagnosis_{cls_name.lower()}_{int(_time.time())}.jpg"
    out_path = out_dir / out_name
    annotated.save(out_path, quality=92)

    display_name = cls_name.replace("_", " ").title()
    remedies     = _DISEASE_REMEDIES_FULL.get(cls_name, [])

    # ── Console report ────────────────────────────────────────────────────────
    print(f"\n{'='*60}")
    print("IMAGE DISEASE DIAGNOSIS  (FarmFederate federated ViT)")
    print(f"{'='*60}")
    print(f"  Model      : {ckpt_path.name}")
    print(f"  Diagnosed  : {display_name}")
    print(f"  Confidence : {confidence:.1%}")
    print(f"  All scores :")
    for cls, sc in sorted(all_scores.items(), key=lambda x: -x[1]):
        bar = "█" * int(sc * 20)
        print(f"    {cls:<22} {sc:.3f}  {bar}")
    print(f"\n  Saved      : {out_path}")
    print(f"\n  Remedies:")
    for i, r in enumerate(remedies, 1):
        print(f"    {i}. {r}")

    if show_inline:
        try:
            from IPython.display import display as _disp, Image as _IpyImg
            _disp(_IpyImg(filename=str(out_path), width=640))
        except Exception:
            pass

    return {
        "class_name":      cls_name,
        "display_name":    display_name,
        "class_idx":       cls_idx,
        "confidence":      confidence,
        "all_scores":      all_scores,
        "remedies":        remedies,
        "model":           ckpt_path.stem,
        "checkpoint":      str(ckpt_path),
        "annotated_image": annotated,
        "annotated_path":  str(out_path),
    }


# ============================================================================
# GRADIO DISEASE DEMO (Colab-friendly)
# ============================================================================

def run_gradio_disease_demo(ckpt_dir=None, share: bool = True):
    """Launch a Gradio web demo for tea leaf disease detection.

    Two tabs:
      • Image — upload any leaf photo → annotated image + disease + confidence bars + remedies
      • Text  — describe symptoms → reference annotated image from training data + remedies

    Args:
        ckpt_dir: Override checkpoint directory (auto-detected if None).
        share:    Create a public Gradio link (default True for Colab).

    Usage in Colab
    --------------
    >>> run_gradio_disease_demo()
    """
    try:
        import gradio as gr
    except ImportError:
        print("[Gradio] Install with: pip install gradio")
        return

    from PIL import Image as _Img
    import io as _io, random as _rnd

    ckpt_path = _find_vit_checkpoint(ckpt_dir)

    def _image_infer(pil_img):
        if pil_img is None:
            return None, "Upload a leaf image."
        result = diagnose_from_image(pil_img, ckpt_dir=ckpt_dir,
                                     show_inline=False, out_dir="/tmp/gradio_disease")
        if not result:
            return None, "Model not available — run training first."
        ann   = result["annotated_image"]
        lines = [f"**{result['display_name']}** — {result['confidence']:.1%}\n"]
        lines.append("**All scores:**")
        for cls, sc in sorted(result["all_scores"].items(), key=lambda x: -x[1]):
            bar = "█" * int(sc * 25)
            lines.append(f"`{cls:<22}` {sc:.3f}  {bar}")
        lines.append("\n**Remedies:**")
        for i, r in enumerate(result["remedies"], 1):
            lines.append(f"{i}. {r}")
        return ann, "\n".join(lines)

    def _text_infer(query):
        if not query or not query.strip():
            return None, "Enter a disease name or symptom description."
        cls_name, cls_idx, conf, kws = _classify_text_to_disease(query)
        # Find reference image
        examples = _find_example_images_for_class(cls_idx, max_examples=1)
        ref_img = None
        if examples:
            img_path, _, boxes, _ = examples[0]
            try:
                pil = _Img.open(img_path).convert("RGB")
                ref_img = annotate_image_with_obb(pil, cls_name, 1.0)
            except Exception:
                pass
        display_name = cls_name.replace("_", " ").title()
        remedies     = _DISEASE_REMEDIES_FULL.get(cls_name, [])
        lines = [f"**{display_name}**"]
        if kws:
            lines.append(f"Matched keywords: {', '.join(kws[:6])}")
        lines.append("\n**Remedies:**")
        for i, r in enumerate(remedies, 1):
            lines.append(f"{i}. {r}")
        return ref_img, "\n".join(lines)

    model_label = ckpt_path.name if ckpt_path else "no checkpoint"
    with gr.Blocks(title="FarmFederate Tea Disease Detector") as demo:
        gr.Markdown(f"## FarmFederate Tea Leaf Disease Detector\n"
                    f"Model: `{model_label}` &nbsp;|&nbsp; "
                    f"5 classes: Leaf Blight · Leaf Hoppers · Leaf Rust · Looper Caterpillars · Mosquito Bug")
        with gr.Tabs():
            with gr.Tab("Image Detection"):
                with gr.Row():
                    img_in  = gr.Image(type="pil", label="Upload leaf image")
                    img_out = gr.Image(type="pil", label="Annotated result")
                info_out = gr.Markdown()
                gr.Button("Detect Disease").click(
                    _image_infer, inputs=img_in, outputs=[img_out, info_out])

            with gr.Tab("Text Lookup"):
                with gr.Row():
                    txt_in  = gr.Textbox(label="Disease name or symptom",
                                         placeholder="e.g. orange rust pustules on leaf")
                    ref_out = gr.Image(type="pil", label="Reference image")
                txt_info = gr.Markdown()
                examples_list = [["leaf blight"], ["leaf rust"], ["leaf hoppers"],
                                  ["looper caterpillar"], ["mosquito bug"]]
                gr.Examples(examples_list, inputs=txt_in)
                gr.Button("Look Up").click(
                    _text_infer, inputs=txt_in, outputs=[ref_out, txt_info])

    demo.launch(share=share)


