def sort_real_dataset_into_classes(
    src_dir: str = None,
    dst_dir: str = None,
) -> dict:
    """Sort the flat YOLO OBB Real Dataset into per-class subfolders.

    Parses labels/{stem}.txt for each image, finds the dominant YOLO class ID,
    then copies the image to dst_dir/{CLASS_NAME}/ using the ground-truth mapping:
      YOLO 0 -> LEAF_BLIGHT          (Leaf Blight)
      YOLO 1 -> LEAF_HOPPERS         (Leaf-Hopper)
      YOLO 2 -> LEAF_RUST            (Leaf Rust)
      YOLO 3 -> LOOPER_CATERPILLARS  (Looper Caterpillar)
      YOLO 4 -> MOSQUITO_BUG         (Mosquito bug)

    Works both locally (Windows) and on Colab. Auto-detects common paths.

    Args:
        src_dir: Root of the raw YOLO OBB dataset (contains images/ and labels/).
                 Auto-detected if None.
        dst_dir: Destination root for sorted per-class folders.
                 Defaults to /content/real_dataset_sorted (Colab) or
                 src_dir/../real_dataset_sorted (local).
    Returns:
        dict mapping class name to image count.
    """
    import shutil as _shu
    from pathlib import Path as _P
    from collections import Counter as _Ctr

    # Reuse the one canonical raw-ID mapping used by the direct loader.
    _YOLO_TO_CLASS = RAW_YOLO_ID_TO_STRESS

    # Auto-detect source (raw YOLO OBB dataset)
    if src_dir is None:
        _src_candidates = [
            _P("/content/real_dataset"),
            _P("/content/Real_Dataset"),
            _P("/content/drive/MyDrive/FarmFederate/Real Dataset"),
            _P("/content/drive/My Drive/FarmFederate/Real Dataset"),
            _P("/content/drive/MyDrive/FarmFederate/Real_Dataset"),
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset"),
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real_Dataset"),
            _P("Real Dataset"),
            _P("Real_Dataset"),
        ]
        src_dir = next(
            (p for p in _src_candidates if p.exists() and (p / "images").exists()),
            None,
        )
    if src_dir is None:
        print("[sort_real_dataset] Raw YOLO OBB dataset not found — provide src_dir.")
        return {}
    src_path = _P(src_dir)

    # Auto-detect destination
    if dst_dir is None:
        dst_dir = (
            "/content/real_dataset_sorted"
            if IN_COLAB
            else str(src_path.parent / "real_dataset_sorted")
        )
    dst_path = _P(dst_dir)

    img_dir = src_path / "images"
    lbl_dir = src_path / "labels"
    if not img_dir.exists() or not lbl_dir.exists():
        print(f"[sort_real_dataset] images/ or labels/ not found in {src_path}")
        return {}

    # Create per-class subdirectories
    for cls_name in _YOLO_TO_CLASS.values():
        (dst_path / cls_name).mkdir(parents=True, exist_ok=True)

    print(f"\n{'='*60}")
    print("Sorting Real Dataset into per-class folders (YOLO OBB labels)")
    print(f"  Source : {src_path}")
    print(f"  Dest   : {dst_path}")
    print(f"{'='*60}")

    counts = {cls: 0 for cls in _YOLO_TO_CLASS.values()}
    skipped = 0

    img_paths = (
        sorted(img_dir.glob("*.jpg")) + sorted(img_dir.glob("*.jpeg")) +
        sorted(img_dir.glob("*.png")) + sorted(img_dir.glob("*.JPG")) +
        sorted(img_dir.glob("*.PNG"))
    )

    for img_path in img_paths:
        lbl_path = lbl_dir / (img_path.stem + ".txt")
        if not lbl_path.exists():
            skipped += 1
            continue
        try:
            cls_ids = []
            with open(lbl_path) as f:
                for line in f:
                    parts = line.strip().split()
                    if parts:
                        cls_ids.append(int(parts[0]))
            if not cls_ids:
                skipped += 1
                continue
            dominant = _Ctr(cls_ids).most_common(1)[0][0]
            cls_name = _YOLO_TO_CLASS.get(dominant)
            if cls_name is None:
                skipped += 1
                continue
            dst_file = dst_path / cls_name / img_path.name
            if not dst_file.exists():
                _shu.copy2(img_path, dst_file)
            counts[cls_name] += 1
        except Exception:
            skipped += 1
            continue

    total = sum(counts.values())
    print(f"\nSorted {total} images (skipped {skipped}):")
    for cls_name, n in counts.items():
        bar = "#" * (n // 3)
        print(f"  {cls_name:<25} {n:>4}  {bar}")
    print(f"\nSorted dataset at: {dst_path}")
    return counts


def setup_colab_data(
    out_dir: str = "/content/tea_data",
    real_dataset_sorted_dir: str = None,
    n_text_per_class: int = 600,
    max_img_per_class: int = 800,
    cross_class_prob: float = 0.60,
    skip_if_exists: bool = True,
):
    """Merge real sorted images, fill with synthetic, generate text CSVs.

    All images come from the real OBB dataset; classes with too few images are
    filled up to max_img_per_class using PIL augmentation (real images) or
    class-specific synthetic tea-leaf generation (zero-image classes).
    No external dataset downloads are performed.

    Steps:
      0. Copy images from real_dataset_sorted_dir/{CLS}/ -> out_dir/{CLS}/images/
      1. Balance all classes to max_img_per_class:
           - Too many: randomly cap to max_img_per_class
           - Too few:  PIL augmentation from available real images
           - Zero:     class-specific synthetic tea-leaf generation
      2. Generate neutral per-class text CSVs -> out_dir/{cls}/text.csv
      3. Write combined annotations.csv -> out_dir/annotations.csv

    Real dataset setup on Colab (run once):
      # Option A — Google Drive (recommended, persists across sessions):
      from google.colab import drive
      drive.mount('/content/drive')
      # Upload data/real_dataset_sorted/ to MyDrive/FarmFederate/ on Drive.
      # Auto-detected at: /content/drive/MyDrive/FarmFederate/data/real_dataset_sorted

      # Option B — direct zip upload (one session):
      from google.colab import files
      files.upload()   # upload real_dataset_sorted.zip
      !unzip -q real_dataset_sorted.zip -d /content/

    Args:
        out_dir:                  Output directory (default /content/tea_data)
        real_dataset_sorted_dir:  Path to pre-sorted real dataset with class subfolders.
                                  Auto-detects common Drive/Colab/local paths if None.
        n_text_per_class:         Text samples per class
        max_img_per_class:        Target images per class (cap + synthetic fill)
        cross_class_prob:         Probability of cross-class suffix in text samples
        skip_if_exists:           Skip augmentation/balancing if images already at target
    """
    import csv as _csv, shutil as _shutil, os as _os_setup
    from pathlib import Path as _P

    _classes = ['LEAF_BLIGHT', 'LEAF_HOPPERS', 'LEAF_RUST', 'LOOPER_CATERPILLARS', 'MOSQUITO_BUG']
    out_path = _P(out_dir)

    print(f"\n{'='*60}")
    print("FarmFederate — Colab Data Setup")
    print(f"  Output dir : {out_dir}")
    print(f"  Text/class : {n_text_per_class}")
    print(f"{'='*60}")

    # ── Pre-Step: Auto-sort raw YOLO OBB dataset if sorted dir missing ────────
    # If real_dataset_sorted_dir is not given (or doesn't exist), check if the
    # raw YOLO OBB dataset is available and auto-sort it into per-class folders.
    _sorted_default = (
        "/content/real_dataset_sorted" if IN_COLAB
        else str(_P("data/real_dataset_sorted").resolve())
    )
    _sorted_check_path = _P(real_dataset_sorted_dir) if real_dataset_sorted_dir else _P(_sorted_default)
    _sorted_has_classes = any((_sorted_check_path / c).exists() for c in _classes)
    if not _sorted_has_classes:
        print("\n[Pre-Step] Sorted per-class folder not found — attempting auto-sort from raw YOLO OBB dataset ...")
        _raw_candidates = [
            _P("/content/real_dataset"),
            _P("/content/Real_Dataset"),
            _P("/content/drive/MyDrive/FarmFederate/Real Dataset"),
            _P("/content/drive/My Drive/FarmFederate/Real Dataset"),
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real Dataset"),
            _P("C:/Users/USER_HP/Desktop/FarmFederate/Real_Dataset"),
        ]
        _raw_src = next((p for p in _raw_candidates if p.exists() and (p / "images").exists()), None)
        if _raw_src:
            _sort_counts = sort_real_dataset_into_classes(
                src_dir=str(_raw_src),
                dst_dir=str(_sorted_check_path),
            )
            if sum(_sort_counts.values()) > 0:
                real_dataset_sorted_dir = str(_sorted_check_path)
                print(f"  Auto-sorted {sum(_sort_counts.values())} images -> {_sorted_check_path}")
        else:
            print("  Raw YOLO OBB dataset not found either — will use synthetic images only.")

    # ── Step 0: Merge real sorted dataset images ──────────────────────────────
    # Auto-detect real_dataset_sorted_dir across Colab / Drive / local paths
    if real_dataset_sorted_dir is None:
        _real_candidates = [
            _P("/content/real_dataset_sorted"),                                                      # gdown download target (sorted Drive folder)
            _P("/content/drive/MyDrive/FarmFederate/real_dataset_sorted"),
            _P("/content/drive/My Drive/FarmFederate/real_dataset_sorted"),
            _P("/content/drive/MyDrive/FarmFederate/data/real_dataset_sorted"),
            _P("/content/drive/My Drive/FarmFederate/data/real_dataset_sorted"),
            _P("/content/drive/MyDrive/real_dataset_sorted"),
            _P("C:/Users/USER_HP/Desktop/FarmFederate/farmfederate_results (1)/dataset/tea_data"),  # real augmented dataset
            _P("C:/Users/USER_HP/Desktop/FarmFederate/data/real_dataset_sorted"),
            _P("data/real_dataset_sorted"),
            _P("../data/real_dataset_sorted"),
        ]
        _found = next((p for p in _real_candidates if p.exists()), None)
        if _found:
            real_dataset_sorted_dir = str(_found)

    if real_dataset_sorted_dir and _P(real_dataset_sorted_dir).exists():
        real_sorted_path = _P(real_dataset_sorted_dir)
        print(f"\n[0/3] Merging real dataset from: {real_sorted_path}")
        real_copied = 0
        for cls in _classes:
            src_cls_dir = real_sorted_path / cls
            if not src_cls_dir.exists():
                continue
            # Support both flat (cls/*.jpg) and nested (cls/images/*.jpg) layouts
            _nested = src_cls_dir / 'images'
            src_img_dir = _nested if _nested.exists() else src_cls_dir
            dst_cls_dir = out_path / cls / 'images'
            dst_cls_dir.mkdir(parents=True, exist_ok=True)
            for img_file in (list(src_img_dir.glob('*.jpg')) + list(src_img_dir.glob('*.jpeg')) +
                             list(src_img_dir.glob('*.png')) + list(src_img_dir.glob('*.JPG'))):
                dst_file = dst_cls_dir / f"real_{img_file.name}"
                if not dst_file.exists():
                    _shutil.copy2(img_file, dst_file)
                    real_copied += 1
        print(f"  Copied {real_copied} real images into {out_dir}")
        for cls in _classes:
            dst_cls_dir = out_path / cls / 'images'
            n = len(list(dst_cls_dir.glob('*.jpg')) + list(dst_cls_dir.glob('*.jpeg')) + list(dst_cls_dir.glob('*.png'))) if dst_cls_dir.exists() else 0
            print(f"    {cls}: {n}")
    else:
        print(f"\n[0/3] Real dataset sorted dir not found — skipping real data merge.")
        print(f"      To include: upload data/real_dataset_sorted/ to Google Drive at")
        print(f"      MyDrive/FarmFederate/data/real_dataset_sorted/")

    # ── Step 1: Balance all classes to max_img_per_class ─────────────────────
    # Cap majority classes (random sample) and augment minority classes (PIL
    # transforms) so every class has exactly max_img_per_class images on disk.
    # Classes with 0 real images get class-specific synthetic tea-leaf images.
    import random as _rnd
    import numpy as _np_syn
    try:
        from PIL import Image as _PILImg, ImageEnhance as _PILEnh, ImageOps as _PILOps
        _pil_ok = True
    except ImportError:
        _pil_ok = False
        print("  [balance] PIL not available — skipping augmentation")

    def _make_synthetic_leaf_pil(cls_name: str, n: int, img_dir, img_size: int = 224):
        """Generate n PIL-based synthetic tea-leaf images for cls_name into img_dir."""
        if not _pil_ok:
            return 0
        _cidx = _classes.index(cls_name) if cls_name in _classes else 0
        # Base RGB (0-255) per class — subtle green offsets
        _base = [(55,110,35),(50,110,38),(48,110,40),(47,110,35),(45,110,35)]
        br, bg, bb = _base[_cidx]
        _y, _x = _np_syn.ogrid[:img_size, :img_size]
        for i in range(n):
            ro = _rnd.randint(-15, 15); go = _rnd.randint(-10, 10); bo = _rnd.randint(-10, 10)
            arr = _np_syn.zeros((img_size, img_size, 3), dtype=_np_syn.float32)
            arr[:,:,0] = (br + ro) / 255.0
            arr[:,:,1] = (bg + go) / 255.0
            arr[:,:,2] = (bb + bo) / 255.0
            arr += _np_syn.random.randn(img_size, img_size, 3).astype(_np_syn.float32) * 0.04
            if cls_name == 'LEAF_HOPPERS':
                # Stippling: yellowish-bronze diffuse patches (sap-sucking damage)
                for _ in range(_rnd.randint(3, 8)):
                    cx, cy = _rnd.randint(20, img_size-20), _rnd.randint(20, img_size-20)
                    r = _rnd.randint(10, 30)
                    mask = ((_x-cx)**2 + (_y-cy)**2) < r**2
                    alpha = _rnd.uniform(0.25, 0.50)
                    arr[mask,0] = arr[mask,0]*(1-alpha) + 0.62*alpha
                    arr[mask,1] = arr[mask,1]*(1-alpha) + 0.58*alpha
                    arr[mask,2] = arr[mask,2]*(1-alpha) + 0.18*alpha
                # Fine stipple dots
                for _ in range(_rnd.randint(20, 60)):
                    px, py = _rnd.randint(0, img_size-1), _rnd.randint(0, img_size-1)
                    arr[max(0,py-1):py+2, max(0,px-1):px+2, 0] = _rnd.uniform(0.55, 0.70)
                    arr[max(0,py-1):py+2, max(0,px-1):px+2, 1] = _rnd.uniform(0.45, 0.60)
                    arr[max(0,py-1):py+2, max(0,px-1):px+2, 2] = _rnd.uniform(0.10, 0.25)
            elif cls_name == 'LOOPER_CATERPILLARS':
                # Holes: dark brown ring + tan centre (caterpillar bite marks)
                for _ in range(_rnd.randint(5, 14)):
                    cx, cy = _rnd.randint(15, img_size-15), _rnd.randint(15, img_size-15)
                    r_out = _rnd.randint(6, 16); r_in = max(2, r_out//2)
                    outer = ((_x-cx)**2 + (_y-cy)**2) < r_out**2
                    inner = ((_x-cx)**2 + (_y-cy)**2) < r_in**2
                    ring  = outer & ~inner
                    alpha = _rnd.uniform(0.40, 0.65)
                    arr[ring,0]  = arr[ring,0]*(1-alpha)  + 0.28*alpha
                    arr[ring,1]  = arr[ring,1]*(1-alpha)  + 0.14*alpha
                    arr[inner,0] = arr[inner,0]*(1-alpha) + 0.50*alpha
                    arr[inner,1] = arr[inner,1]*(1-alpha) + 0.38*alpha
                    arr[inner,2] = arr[inner,2]*(1-alpha) + 0.20*alpha
                # Ragged edge nibble marks
                for _ in range(_rnd.randint(3, 8)):
                    ex = _rnd.randint(0, img_size-1)
                    ey = _rnd.randint(0, 10) if _rnd.random() < 0.5 else _rnd.randint(img_size-10, img_size-1)
                    r  = _rnd.randint(4, 10)
                    m  = ((_x-ex)**2 + (_y-ey)**2) < r**2
                    arr[m, 0] = _rnd.uniform(0.40, 0.55)
                    arr[m, 1] = _rnd.uniform(0.25, 0.38)
                    arr[m, 2] = _rnd.uniform(0.10, 0.22)
            elif cls_name == 'LEAF_BLIGHT':
                # Large irregular necrotic patches (water-soaked dark brown)
                n_patches = _rnd.randint(1, 3)
                for _ in range(n_patches):
                    cx, cy = _rnd.randint(30, img_size-30), _rnd.randint(30, img_size-30)
                    rx = _rnd.randint(20, 55); ry = _rnd.randint(15, 45)
                    inner_mask = ((_x-cx)**2/rx**2 + (_y-cy)**2/ry**2) < 1.0
                    # Dark necrotic centre
                    alpha_c = _rnd.uniform(0.60, 0.80)
                    arr[inner_mask, 0] = arr[inner_mask,0]*(1-alpha_c) + 0.18*alpha_c
                    arr[inner_mask, 1] = arr[inner_mask,1]*(1-alpha_c) + 0.10*alpha_c
                    arr[inner_mask, 2] = arr[inner_mask,2]*(1-alpha_c) + 0.05*alpha_c
                    # Yellow halo around patch
                    halo_rx, halo_ry = rx+12, ry+12
                    halo_mask = (((_x-cx)**2/halo_rx**2 + (_y-cy)**2/halo_ry**2) < 1.0) & ~inner_mask
                    alpha_h = _rnd.uniform(0.30, 0.50)
                    arr[halo_mask, 0] = arr[halo_mask,0]*(1-alpha_h) + 0.72*alpha_h
                    arr[halo_mask, 1] = arr[halo_mask,1]*(1-alpha_h) + 0.65*alpha_h
                    arr[halo_mask, 2] = arr[halo_mask,2]*(1-alpha_h) + 0.12*alpha_h
            elif cls_name == 'LEAF_RUST':
                # Orange-red rust pustule clusters (Hemileia vastatrix)
                n_clusters = _rnd.randint(3, 8)
                for _ in range(n_clusters):
                    cx, cy = _rnd.randint(20, img_size-20), _rnd.randint(20, img_size-20)
                    # Multiple tiny pustules per cluster
                    for _ in range(_rnd.randint(4, 10)):
                        px = cx + _rnd.randint(-14, 14)
                        py = cy + _rnd.randint(-14, 14)
                        r  = _rnd.randint(2, 6)
                        pm = ((_x-px)**2 + (_y-py)**2) < r**2
                        alpha = _rnd.uniform(0.45, 0.70)
                        arr[pm, 0] = arr[pm,0]*(1-alpha) + 0.78*alpha  # orange-red
                        arr[pm, 1] = arr[pm,1]*(1-alpha) + 0.32*alpha
                        arr[pm, 2] = arr[pm,2]*(1-alpha) + 0.05*alpha
                # Surrounding yellowing
                for _ in range(_rnd.randint(2, 5)):
                    cx, cy = _rnd.randint(25, img_size-25), _rnd.randint(25, img_size-25)
                    r = _rnd.randint(12, 25)
                    ym = ((_x-cx)**2 + (_y-cy)**2) < r**2
                    alpha = _rnd.uniform(0.15, 0.30)
                    arr[ym, 0] = arr[ym,0]*(1-alpha) + 0.68*alpha
                    arr[ym, 1] = arr[ym,1]*(1-alpha) + 0.62*alpha
                    arr[ym, 2] = arr[ym,2]*(1-alpha) + 0.08*alpha
            elif cls_name == 'MOSQUITO_BUG':
                # Angular corky lesions bounded by veins (Helopeltis antonii)
                n_lesions = _rnd.randint(3, 9)
                for _ in range(n_lesions):
                    cx, cy = _rnd.randint(20, img_size-20), _rnd.randint(20, img_size-20)
                    # Angular (rectangular-ish) lesion shape
                    hw = _rnd.randint(6, 18); hh = _rnd.randint(5, 14)
                    ang = _rnd.uniform(0, _np_syn.pi)
                    cos_a, sin_a = _np_syn.cos(ang), _np_syn.sin(ang)
                    dx = (_x - cx) * cos_a + (_y - cy) * sin_a
                    dy = -(_x - cx) * sin_a + (_y - cy) * cos_a
                    am = (abs(dx) < hw) & (abs(dy) < hh)
                    alpha = _rnd.uniform(0.50, 0.70)
                    arr[am, 0] = arr[am,0]*(1-alpha) + 0.35*alpha  # dark reddish-brown
                    arr[am, 1] = arr[am,1]*(1-alpha) + 0.12*alpha
                    arr[am, 2] = arr[am,2]*(1-alpha) + 0.06*alpha
                # Corky surface texture (fine dark speckling)
                for _ in range(_rnd.randint(30, 80)):
                    px, py = _rnd.randint(0, img_size-1), _rnd.randint(0, img_size-1)
                    arr[py:py+2, px:px+2, 0] *= _rnd.uniform(0.55, 0.80)
                    arr[py:py+2, px:px+2, 1] *= _rnd.uniform(0.55, 0.80)
            else:
                # Fallback blotch
                for _ in range(_rnd.randint(2, 5)):
                    cx, cy = _rnd.randint(20, img_size-20), _rnd.randint(20, img_size-20)
                    r = _rnd.randint(8, 20)
                    mask = ((_x-cx)**2 + (_y-cy)**2) < r**2
                    alpha = _rnd.uniform(0.20, 0.40)
                    arr[mask,0] = arr[mask,0]*(1-alpha) + 0.45*alpha
                    arr[mask,1] = arr[mask,1]*(1-alpha) + 0.22*alpha
            arr = _np_syn.clip(arr, 0, 1)
            pil_img = _PILImg.fromarray((arr*255).astype(_np_syn.uint8), 'RGB')
            pil_img.save(img_dir / f"syn_{i:05d}.jpg", 'JPEG', quality=85)
        return n

    _already_balanced = all(
        (out_path / cls / 'images').exists() and
        len(list((out_path / cls / 'images').glob('*.jpg'))) >= max_img_per_class
        for cls in _classes)
    if skip_if_exists and _already_balanced:
        print(f"\n[1/3] Images already balanced at {max_img_per_class}/class — skipping")
    else:
        print(f"\n[1/3] Balancing classes to {max_img_per_class} images each ...")

        _aug_ops = [
            lambda img: img.transpose(_PILImg.FLIP_LEFT_RIGHT),
            lambda img: img.transpose(_PILImg.FLIP_TOP_BOTTOM),
            lambda img: img.rotate(90,  expand=True),
            lambda img: img.rotate(180, expand=True),
            lambda img: img.rotate(270, expand=True),
            lambda img: _PILEnh.Brightness(img).enhance(_rnd.uniform(0.7, 1.3)),
            lambda img: _PILEnh.Contrast(img).enhance(_rnd.uniform(0.7, 1.3)),
            lambda img: _PILEnh.Color(img).enhance(_rnd.uniform(0.6, 1.4)),
            lambda img: _PILOps.autocontrast(img),
            lambda img: img.transpose(_PILImg.FLIP_LEFT_RIGHT).rotate(90, expand=True),
            lambda img: _PILEnh.Sharpness(img).enhance(_rnd.uniform(0.5, 2.0)),
            lambda img: img.rotate(_rnd.uniform(-20, 20)),
        ]

        for cls in _classes:
            img_dir = out_path / cls / 'images'
            img_dir.mkdir(parents=True, exist_ok=True)
            all_imgs = (list(img_dir.glob('*.jpg')) +
                        list(img_dir.glob('*.jpeg')) +
                        list(img_dir.glob('*.png')))
            n = len(all_imgs)

            if n == 0:
                print(f"  {cls:<25}  0 real images — generating {max_img_per_class} synthetic tea-leaf ...")
                _make_synthetic_leaf_pil(cls, max_img_per_class, img_dir)
                print(f"  {cls:<25}  generated {max_img_per_class} synthetic images")
                continue

            if n > max_img_per_class:
                _rnd.shuffle(all_imgs)
                to_delete = all_imgs[max_img_per_class:]
                for f in to_delete:
                    try: f.unlink()
                    except Exception: pass
                print(f"  {cls:<25}  capped  {n} -> {max_img_per_class}")

            elif n < max_img_per_class and _pil_ok:
                needed = max_img_per_class - n
                source = all_imgs[:]
                generated = 0
                aug_idx = 0
                while generated < needed:
                    src_path = source[generated % len(source)]
                    op = _aug_ops[aug_idx % len(_aug_ops)]
                    aug_idx += 1
                    try:
                        img = _PILImg.open(src_path).convert('RGB')
                        img = op(img)
                        aug_name = f"aug_{generated:05d}_{src_path.stem}.jpg"
                        img.save(img_dir / aug_name, 'JPEG', quality=90)
                        generated += 1
                    except Exception:
                        pass
                print(f"  {cls:<25}  augmented {n} -> {n + generated}  (+{generated} synthetic)")
            else:
                print(f"  {cls:<25}  ok  ({n})")

        print("\n  Final per-class counts:")
        for cls in _classes:
            img_dir = out_path / cls / 'images'
            n = len(list(img_dir.glob('*.jpg')) + list(img_dir.glob('*.jpeg')) + list(img_dir.glob('*.png'))) if img_dir.exists() else 0
            bar = '#' * (n // 50)
            print(f"    {cls:<25} {n:>5}  {bar}")

    # ── Step 2: Generate neutral text CSVs ───────────────────────────────────
    # Use the difficulty-tiered generator: 8% clear / 22% slightly mixed / 70% heavily mixed.
    # These are synthetic templates, not field-linked observations. The training
    # path deduplicates and template-group-splits them before evaluation.
    print(f"\n[2/3] Generating text CSVs ({n_text_per_class} samples/class, difficulty-tiered) ...")
    _text_df = generate_synthetic_text_data(n_samples=n_text_per_class * len(_classes))
    all_rows = []
    for cls_idx, cls_name in enumerate(_classes):
        cls_df = _text_df[_text_df['label_name'] == cls_name].head(n_text_per_class)
        rows = [{'text': r['text'], 'class_id': cls_idx, 'class_name': cls_name,
                 'source': 'synthetic_template'}
                for _, r in cls_df.iterrows()]
        random.shuffle(rows)
        csv_path = out_path / cls_name / 'text.csv'
        csv_path.parent.mkdir(parents=True, exist_ok=True)
        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = _csv.DictWriter(f, fieldnames=['text', 'class_id', 'class_name', 'source'])
            writer.writeheader()
            writer.writerows(rows)
        all_rows.extend(rows)
        print(f"  {cls_name}: {len(rows)} samples")

    # ── Step 3: Write combined annotations.csv ───────────────────────────────
    print(f"\n[3/3] Writing annotations.csv ({len(all_rows)} rows)...")
    random.shuffle(all_rows)
    ann_path = out_path / 'annotations.csv'
    with open(ann_path, 'w', newline='', encoding='utf-8') as f:
        writer = _csv.DictWriter(f, fieldnames=['text', 'class_id', 'class_name', 'source'])
        writer.writeheader()
        writer.writerows(all_rows)

    # ── Set global DATA_DIR ───────────────────────────────────────────────────
    import builtins as _b
    _b.DATA_DIR = str(out_path)
    try:
        globals()['DATA_DIR'] = str(out_path)
    except Exception:
        pass

    # Final summary
    print(f"\nData setup complete!")
    print(f"  DATA_DIR = {out_dir}")
    total_imgs = 0
    for cls in _classes:
        img_dir = out_path / cls / 'images'
        n = len(list(img_dir.glob('*.jpg')) + list(img_dir.glob('*.jpeg')) + list(img_dir.glob('*.png'))) if img_dir.exists() else 0
        total_imgs += n
        print(f"  {cls:20s}  images={n:4d}  text={n_text_per_class}")
    print(f"  Total images : {total_imgs}")
    print(f"  annotations  : {len(all_rows)} rows")
    print(f"\nNow call: run_training_real_data()  or  run_colab()")


def download_results(output_zip: str = "/content/farmfederate_results.zip"):
    """Zip all trained models, plots, and result JSONs and download to browser.

    Collects from:
      - checkpoints/   (.pt model files)
      - plots/         (.png figures)
      - outputs/       (complete_results.json, metrics, etc.)
      - figs_publication/
      - training_results/

    Safe to call manually at any time:
        download_results()
    """
    import zipfile as _zf
    import os as _os
    from pathlib import Path as _P

    if not IN_COLAB:
        print("[download_results] Not in Colab — skipping browser download.")
        print(f"  Results are in: checkpoints/  plots/  outputs/")
        return

    try:
        from google.colab import files as _colab_files
    except ImportError:
        print("[download_results] google.colab not available.")
        return

    zip_path = _P(output_zip)

    # Directories and file patterns to collect
    # Each entry: (base_dir, glob_pattern, arcname_prefix)
    # arcname_prefix overrides the path inside the zip (keeps it clean)
    COLLECT = [
        # ── Trained model weights ─────────────────────────────────────────
        ("/content/checkpoints",               "**/*.pt",   "checkpoints"),
        ("/content/checkpoints",               "**/*.pth",  "checkpoints"),
        ("/content/checkpoints_paper",         "**/*.pt",   "checkpoints_paper"),
        (str((_P.cwd() / "checkpoints").resolve()), "**/*.pt",  "checkpoints"),
        (str((_P.cwd() / "checkpoints").resolve()), "**/*.pth", "checkpoints"),
        # ── Metrics / results JSON ────────────────────────────────────────
        ("/content/outputs",                   "**/*",      "outputs"),
        ("/content/outputs_federated_complete","**/*",      "outputs_federated_complete"),
        ("/content/training_results",          "**/*",      "training_results"),
        (str((_P.cwd() / "results").resolve()),"**/*",      "outputs"),
        # ── Plots / figures ───────────────────────────────────────────────
        ("/content/plots",                     "**/*.png",  "plots"),
        (str((_P.cwd() / "plots").resolve()),  "**/*.png",  "plots"),
        (str((_P.cwd() / "plots").resolve()),  "**/*.jpg",  "plots"),
        (str((_P.cwd() / "plots").resolve()),  "**/*.jpeg", "plots"),
        (str((_P.cwd() / "plots").resolve()),  "**/*.pdf",  "plots"),
        (str((_P.cwd() / "plots").resolve()),  "**/*.csv",  "plots"),
        ("/content/figs_publication",          "**/*.png",  "figs_publication"),
        # ── Sorted real dataset (200 images in 5 class folders) ─────────────
        ("/content/real_dataset_sorted",       "**/*.jpg",  "dataset/real_dataset_sorted"),
        ("/content/real_dataset_sorted",       "**/*.jpeg", "dataset/real_dataset_sorted"),
        ("/content/real_dataset_sorted",       "**/*.png",  "dataset/real_dataset_sorted"),
        # ── Balanced dataset (tea_data: real + augmented synthetic) ──────────
        # Includes all 5 class image folders + text CSVs + annotations.csv
        ("/content/tea_data",                  "**/*.jpg",  "dataset/tea_data"),
        ("/content/tea_data",                  "**/*.jpeg", "dataset/tea_data"),
        ("/content/tea_data",                  "**/*.png",  "dataset/tea_data"),
        ("/content/tea_data",                  "**/*.csv",  "dataset/tea_data"),
        ("/content/tea_data",                  "**/*.json", "dataset/tea_data"),
        # ── Drive mirrors (if mounted) ────────────────────────────────────
        ("/content/drive/MyDrive/FarmFederate/outputs",     "**/*",    "drive/outputs"),
        ("/content/drive/MyDrive/FarmFederate/checkpoints", "**/*.pt", "drive/checkpoints"),
        ("/content/drive/MyDrive/FarmFederate/plots",       "**/*.png","drive/plots"),
    ]

    print(f"\n{'='*60}")
    print("Packing results + dataset for download ...")
    seen = set()   # deduplicate files that appear in both local and Drive mirrors
    total = 0
    with _zf.ZipFile(zip_path, 'w', _zf.ZIP_DEFLATED) as zf:
        for base_dir, pattern, arc_prefix in COLLECT:
            base = _P(base_dir)
            if not base.exists():
                continue
            for fpath in sorted(base.glob(pattern)):
                if not fpath.is_file():
                    continue
                # skip zip files and the output zip itself
                if fpath.suffix.lower() == '.zip':
                    continue
                # skip kaggle_tmp scratch folder
                if 'kaggle_tmp' in str(fpath):
                    continue
                rel = fpath.relative_to(base)
                arcname = f"{arc_prefix}/{rel}"
                if arcname in seen:
                    continue
                seen.add(arcname)
                try:
                    zf.write(fpath, arcname)
                    total += 1
                except Exception:
                    pass

    size_mb = zip_path.stat().st_size / 1e6
    print(f"  Packed {total} files  ({size_mb:.1f} MB)  ->  {zip_path}")
    print("  Starting browser download ...")
    _colab_files.download(str(zip_path))
    print("  Done — check your browser Downloads folder.")
    print(f"\n  Zip contents:")
    print(f"    checkpoints/                   <- trained model weights (.pt)")
    print(f"    outputs/                       <- complete_results.json + metrics")
    print(f"    plots/                         <- training curves + comparison charts")
    print(f"    figs_publication/              <- publication-ready figures")
    print(f"    dataset/real_dataset_sorted/   <- 200 real images sorted by class")
